export default {"1":{"html":"<p>ایک واحد چارٹ کی تصویر بنائیں جو صرف ایک سوال کا جواب دیتا ہے جو آپ کو ایک روپیہ کا خطرہ مول لینے سے پہلے اہم ہے۔ اگر NIFTY یہاں اونچا، یا بیچ میں فلیٹ، یا نیچے بہت نیچے، تو آپ اصل میں کیا بناتے ہیں یا کھوتے ہیں؟ وہ ایک چارٹ ہے <strong>ادائیگی کا خاکہ</strong>، اور اسے پڑھنا سیکھنا اس کورس میں ہر نام کی حکمت عملی کے پیچھے اصل ہنر ہے۔ حکمت عملی آپشن ٹانگوں کے ایک سیٹ سے زیادہ کچھ نہیں ہے، اور اس کی ادائیگی کا خاکہ اس بات کی دیانت دار تصویر ہے کہ وہ اسٹیک کیسے برتاؤ کرتا ہے۔ تصویر میں مہارت حاصل کریں اور فینسی ناموں سے فرق پڑتا ہے۔ آپ کسی بھی امتزاج کو دیکھیں گے اور سیکنڈوں میں کہیں گے، یہ کہاں سے کماتا ہے، کہاں سے خون بہہ رہا ہے، اور لائن پر کتنا ہے۔ OpenAlgo <strong>حکمت عملی بنانے والا</strong> آپ کے لیے یہ تصویر کھینچتا ہے، اور اس کورس میں ہر چارٹ سیدھے اس سے آتا ہے، جو 26 جون 2026 کو کیپچر کی گئی حقیقی NIFTY آپشن قیمتوں پر بنایا گیا ہے۔</p>\n<h2 id=\"a-payoff-diagram-is-a-picture-of-your-money\">ادائیگی کا خاکہ آپ کے پیسے کی تصویر ہے۔</h2>\n<p>اس کورس میں ہر ادائیگی کا چارٹ ایک ہی دو محوروں کا اشتراک کرتا ہے، لہذا ایک بار جب آپ ایک پڑھ لیں تو آپ ان سب کو پڑھ سکتے ہیں۔</p>\n<ul>\n<li>افقی محور ہے <strong>NIFTY کی قیمت ختم ہونے پر</strong>. NIFTY انڈیکس ہے، ان حکمت عملیوں کا قدرتی گھر، کیونکہ اس کے اختیارات ملک میں سب سے زیادہ مائع ہیں۔ 26 جون 2026 کو انڈیکس ایک جگہ پر بیٹھ گیا۔ <strong>24,056</strong>پر پیسے کی ہڑتال کے ساتھ <strong>24,050</strong>. ہر چارٹ کے لیے تیار کیا گیا ہے۔ <strong>28 جولائی 2026</strong> ماہانہ ایکسپائری، NSE ماہانہ جو تقریباً 32 دن بعد منگل کو آتا ہے۔ جیسے ہی آپ کی آنکھ بائیں سفر کرتی ہے NIFTY گر گئی ہے، اور جیسے ہی یہ دائیں سفر کرتی ہے NIFTY بلند ہو گئی ہے۔</li>\n<li>عمودی محور آپ کا ہے۔ <strong>نفع یا نقصان؟</strong> پوری پوزیشن پر، روپے میں ایک لاٹ کے لیے <strong>65</strong>. زیرو لائن کے اوپر آپ منافع میں ہیں، اس کے نیچے آپ نقصان میں ہیں۔</li>\n</ul>\n<p>واحد سب سے اہم خصوصیت ہے <strong>صفر لائن</strong>، وہ سطح جہاں نفع اور نقصان بالکل کچھ نہیں ہے۔ جہاں بھی حکمت عملی اس کے اوپر بیٹھی ہے آپ پیسہ کما رہے ہیں، اور جہاں بھی یہ اس کے نیچے بیٹھی ہے آپ کو نقصان ہو رہا ہے۔ پورا کھیل پڑھ رہا ہے جہاں لائن ہر ممکنہ اختتامی قیمت پر رہتی ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ادائیگی کا خاکہ آپ کے نفع یا نقصان (عمودی) کو ایکسپائری (افقی) پر NIFTY کی قیمت کے مقابلے میں 65 کے ایک لاٹ میں روپے میں پیش کرتا ہے۔ صفر کی لکیر کے اوپر منافع ہے، اس کے نیچے نقصان ہے۔ پڑھیں کہ لائن کہاں بیٹھتی ہے اور آپ کسی بھی قیمت پر اپنا نتیجہ جانتے ہیں۔</p>\n</div></div>\n<h2 id=\"the-two-lines-at-expiry-and-today\">دو لائنیں: میعاد ختم ہونے پر اور آج</h2>\n<p>کسی بھی بلڈر چارٹ کو قریب سے دیکھیں اور آپ کو ایک نہیں بلکہ دو لائنیں نظر آئیں گی۔ وہ مختلف کہانیاں سناتے ہیں اور آپ کو دونوں کی ضرورت ہے۔</p>\n<ul>\n<li>دی <strong>نارنجی \"ایکسپائری پر\" لائن</strong> آخری دن، 28 جولائی 2026 کو آپ کی پوزیشن کی قدر ہے، جب تمام وقت کی قدر ختم ہو چکی ہے اور صرف اندرونی قدر باقی ہے۔ یہ صاف ستھری، کنک شکل ہے جس کا مطلب زیادہ تر لوگ ادائیگی سے کرتے ہیں۔ اگر آپ آخری گھنٹی کو پکڑتے ہیں تو یہ وہی ہے جو آپ کے پاس ہے یا واجب الادا ہے۔</li>\n<li>دی <strong>نیلی ڈیش والی \"T+0\" لائن</strong> آج آپ کی پوزیشن کی قدر ہے، ابھی، صفر دن گزرنے کے ساتھ، جس کا مطلب ہے T+0۔ یہ ہموار اور گول ہے کیونکہ اختیارات اب بھی وقت کی قدر رکھتے ہیں۔</li>\n</ul>\n<p>دونوں میں وقت کی وجہ سے فرق ہے۔ NIFTY کی اسی قیمت کے لیے میعاد ختم ہونے سے پہلے ایک آپشن زیادہ قابل قدر ہے، کیونکہ انڈیکس کے لیے آپ کے راستے کو منتقل کرنے کے لیے ابھی بھی وقت ہے۔ وہ اضافی قیمت ہے۔ <strong>وقت کی قدر</strong>، اور یہ ختم ہونے کے قریب آتے ہی پگھل جاتا ہے۔ آخری دن تک بلیو ٹوڈے لائن اورنج ایکسپائری لائن پر ٹوٹ چکی ہے۔ لہذا نیلی ڈیشڈ لائن تقریباً وہی ہے جو آپ کی اسکرین اب دکھاتی ہے، اور اورنج لائن دکھاتی ہے کہ اگر آپ کچھ بھی جلد بند نہیں کرتے ہیں تو آپ کہاں جارہے ہیں۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>اورنج ایٹ ایکسپائری لائن آپ کی منزل ہے۔ نیلی ڈیش والی T+0 لائن وہیں ہے جہاں آپ آج کھڑے ہیں۔ جیسے جیسے دن گزرتے ہیں، نیلی لکیر نارنجی کی طرف بڑھ جاتی ہے، کیونکہ ہر آپشن میں پکائی گئی وقت کی قدر ختم ہونے کے ساتھ صفر پر آ جاتی ہے۔</p>\n</div></div>\n<h2 id=\"profit-zones-loss-zones-and-the-breakeven\">منافع کے زون، نقصان کے زون، اور بریک ایون</h2>\n<p>ایک بار جب آپ کو صفر کی لکیر مل جاتی ہے، چارٹ دو سایہ دار خطوں میں تقسیم ہو جاتا ہے۔</p>\n<ul>\n<li>دی <strong>منافع زون</strong> ہر بند ہونے والی قیمت ہے جہاں اورنج ایکسپائری لائن صفر سے اوپر بیٹھتی ہے۔ بلڈر اس سبز کو سایہ دیتا ہے۔</li>\n<li>دی <strong>نقصان زون</strong> ہر بند ہونے والی قیمت ہے جہاں اورنج لائن صفر سے نیچے، سایہ دار سرخ ہوتی ہے۔</li>\n</ul>\n<p>صحیح قیمت جہاں اورنج لائن صفر کو عبور کرتی ہے a ہے۔ <strong>breakeven</strong>، وہ قریب جس پر آپ نہ تو بناتے ہیں اور نہ ہی کھوتے ہیں۔ کچھ حکمت عملیوں میں ایک بریک ایون ہوتا ہے، کئی میں دو، کچھ میں چار ہوتے ہیں۔ بلڈر گرا دیتا ہے۔ <strong>امبر بریک ایون ڈاٹ</strong> ہر کراسنگ پر تاکہ آپ کی نظر اس پر پڑے۔ اس نقطے کے ایک طرف ہر چیز نفع ہے، دوسری طرف ہر چیز نقصان ہے، لہذا بریک ایون سبز اور سرخ کے درمیان باؤنڈری فینس ہے۔</p>\n<p>دو فلیٹ نشانات اس منظر کو ختم کرتے ہیں۔ دی <strong>زیادہ سے زیادہ منافع</strong> اورنج لائن اب تک پہنچنے والی سب سے زیادہ ہے، اور <strong>زیادہ سے زیادہ نقصان</strong> یہ اب تک کا سب سے کم ڈوبتا ہے۔ خطرے کی متعین حکمت عملی کے لیے دونوں فلیٹ، محدود شیلف ہیں، اس لیے آپ آرڈر دینے سے پہلے اپنے بہترین اور بدترین حالات کو جانتے ہیں۔</p>\n<h2 id=\"the-sigma-bands-and-the-spot-line\">سگما بینڈز اور اسپاٹ لائن</h2>\n<p>ہر بلڈر چارٹ پر دو مزید خصوصیات آپ کو بتاتی ہیں کہ مارکیٹ خود کیا توقع رکھتی ہے۔</p>\n<ul>\n<li>ایک روشن <strong>گلابی عمودی لائن</strong> کرنٹ کو نشان زد کرتا ہے۔ <strong>24,056 پر جگہ</strong>، لہذا آپ ایک نظر میں دیکھ سکتے ہیں کہ ہر ایک بریک ایون کتنی دور بیٹھا ہے جہاں سے آج NIFTY تجارت کرتا ہے۔</li>\n<li>ادائیگی کے پیچھے بیہوش سایہ دار بیٹھیں۔ <strong>سگما بینڈ</strong>، جسے معیاری انحراف بینڈ بھی کہا جاتا ہے۔ اندرونی جوڑا ایک معیاری انحراف کی حرکت کو نشان زد کرتا ہے اور بیرونی جوڑا دو معیاری انحراف کی حرکت کو نشان زد کرتا ہے، جس کی پیمائش تقریباً رقم کے مضمر اتار چڑھاؤ سے ہوتی ہے۔ <strong>12.7 فیصد</strong> اور دن ختم ہونے میں رہ گئے ہیں۔ صاف لفظوں میں، وہ اس حد کو ظاہر کرتے ہیں کہ آپشن مارکیٹ کی قیمتوں کا تعین کیا جا رہا ہے۔ NIFTY کے اندرونی بینڈ کے اندر تقریباً دو بار تین میں، اور بیرونی بینڈ کے اندر تقریباً ہمیشہ ختم ہونے کی توقع ہے۔</li>\n</ul>\n<p>وہ بینڈ ایک حقیقت کی جانچ ہیں۔ اگر کوئی حکمت عملی صرف اس وقت فائدہ مند ہوتی ہے جب NIFTY بیرونی بینڈ سے بہت باہر اترتا ہے، تو مارکیٹ آپ کو بتا رہی ہے کہ نتیجہ کا امکان نہیں ہے۔ اگر اس کا منافع بخش علاقہ آرام سے اندرونی بینڈ کا احاطہ کرتا ہے، تو مشکلات دوستانہ ہوتی ہیں۔ آپ تجارت کو اس اقدام کے خلاف پڑھ رہے ہیں جس کی مارکیٹ درحقیقت توقع کرتی ہے، خواہش مندانہ سوچ کے خلاف نہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>کسی بھی حکمت عملی کا فیصلہ کرنے سے پہلے، اس پر نظر ڈالیں کہ اس کا سبز منافع کا زون کہاں بیہوش سگما بینڈ کے خلاف بیٹھا ہے۔ ایک منافع بخش زون جو اندرونی ایک معیاری انحراف بینڈ کا احاطہ کرتا ہے ممکنہ نتائج پر شرط لگا رہا ہے۔ ایک جس کو بیرونی بینڈ سے آگے NIFTY کی ضرورت ہے وہ نایاب پر شرط لگا رہا ہے۔ بینڈ ایک اندازہ کو باخبر پڑھنے میں بدل دیتے ہیں۔</p>\n</div></div>\n<h2 id=\"legs-the-pieces-you-stack\">ٹانگیں: وہ ٹکڑے جو آپ اسٹیک کرتے ہیں۔</h2>\n<p>اے <strong>ٹانگ</strong> آپ کی پوزیشن میں ایک واحد آپشن ہے۔ آپ پہلے سے ہی آپشنز کی بنیادی باتوں سے چار ٹانگوں کو جانتے ہیں، چار ایٹم جن سے ہر حکمت عملی بنائی جاتی ہے۔</p>\n<ul>\n<li>کال خریدیں، خریدنے کا حق، اس وقت کے لیے جب آپ اضافہ کی توقع کرتے ہیں۔</li>\n<li>کال فروخت کریں، خریدار کے منافع کی ادائیگی کی ذمہ داری اگر تفویض کی گئی ہے، جب آپ توقع کرتے ہیں کہ NIFTY ایک سطح سے نیچے رہے گا۔</li>\n<li>ایک پوٹ خریدیں، بیچنے کا حق، جب آپ گرنے کی توقع کرتے ہیں۔</li>\n<li>ایک پوٹ بیچیں، اگر تفویض کیا گیا ہو تو خریدار کے منافع کی ادائیگی کی ذمہ داری، جب آپ توقع کرتے ہیں کہ NIFTY ایک سطح سے اوپر رہے گا۔</li>\n</ul>\n<p>NIFTY انڈیکس آپشنز کے لیے، اسائنمنٹ کیش سیٹلڈ ہے: میعاد ختم ہونے پر بیچنے والے آپشن کی اندرونی قیمت ادا کرتا ہے، بغیر کسی حصص کے ہاتھ بدلے۔ (سنگل سٹاک کے اختیارات اس کے بجائے فزیکل ڈیلیوری کے ذریعے طے کر سکتے ہیں، جو کہ ایک اور وجہ ہے کہ تاجر عام طور پر کسی پوزیشن کو سیٹلمنٹ میں لے جانے کی بجائے ختم ہونے سے پہلے بند کر دیتے ہیں۔)</p>\n<p>اے <strong>حکمت عملی</strong> صرف دو یا دو سے زیادہ ٹانگیں ایک ساتھ پکڑی جاتی ہیں، ایک ہی بنیادی اور ایکسپائری پر، اس لیے منتخب کیا جاتا ہے کہ ان کی مشترکہ ادائیگی میں وہ شکل ہو جو آپ چاہتے ہیں۔ جب آپ ایک ٹانگ بیچتے ہیں، تو آپ جو پریمیم جمع کرتے ہیں وہ آپ کی خریدی ہوئی ٹانگ کی ادائیگی میں مدد کرتا ہے۔ تقریباً ہر پھیلاؤ کے پیچھے یہی خاموش انجن ہے۔ ایک ٹانگ دوسرے کو فنڈ دیتی ہے، آپ کی لاگت کو کم کرتی ہے یا آپ کے انعام کو محدود کرنے کے بدلے آپ کے خطرے کو کم کرتی ہے۔ مشترکہ ادائیگی صرف ٹانگوں کا مجموعہ ہے، جس میں ہر قیمت پر روپے کے حساب سے اضافہ کیا جاتا ہے، اور یہ اضافہ بالکل وہی ہے جو بلڈر آپ کے لیے کرتا ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>حکمت عملی بنانے والا آپ کی ٹانگوں کی حقیقی NIFTY آپشن کی قیمتوں سے حاصل کرتا ہے، جو مصنوعی مستقبل سے ہٹ کر Black-76 کے ساتھ ماڈل بنایا گیا ہے، جو ہندوستانی اختیارات کے لیے صحیح طریقہ ہے۔ اسی انجن نے اس کورس میں ہر چارٹ تیار کیا۔ سپاٹ 24,056، ATM اسٹرائیک 24,050، لاٹ 65، 50 پوائنٹ گرڈ پر سٹرائیکس، 28 جولائی 2026 کو ختم ہو رہی ہے۔</p>\n</div></div>\n<h2 id=\"reading-one-real-example-end-to-end\">ایک حقیقی مثال کو آخر تک پڑھنا</h2>\n<p>آئیے ایک ساتھ مل کر ایک حقیقی حکمت عملی پڑھیں، <strong>بیل کال پھیل گئی</strong>، تو پوری تصویر کلک کرتی ہے۔ یہ 28 جولائی 2026 کی میعاد ختم ہونے پر دو ٹانگوں، دونوں کالوں کے ساتھ ہلکی سی تیزی کی تجارت ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>قسم</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>خریدیں۔</td>\n<td>24,050</td>\n<td>کال کریں۔</td>\n</tr>\n<tr>\n<td>2</td>\n<td>بیچنا</td>\n<td>24,150</td>\n<td>کال کریں۔</td>\n</tr>\n</tbody></table>\n<p>آپ 24,050 کال خریدتے ہیں اور 24,150 کال بیچتے ہیں۔ آپ جو کال بیچتے ہیں وہ پریمیم لاتا ہے جو آپ کی خریدی ہوئی کال کی قیمت کا زیادہ تر حصہ ادا کرتا ہے، اس لیے پوزیشن کی لاگت تنہا کال سے کہیں کم ہے۔ وہ خالص لاگت، <strong>خالص ڈیبٹ</strong> 3,624 روپے، آپ سب سے زیادہ کھو سکتے ہیں۔ یہاں بلڈر کی رپورٹ کیا ہے.</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>قدر</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>بریک ایون</td>\n<td>24,106</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>2,876 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>3,624 روپے</td>\n</tr>\n</tbody></table>\n<p>اب چارٹ پڑھیں۔ بائیں طرف، 24,050 سے نیچے، دونوں کالیں بیکار ختم ہو جاتی ہیں اور آپ پورا نیٹ ڈیبٹ، 3,624 روپے کھو دیتے ہیں۔ وہ فلیٹ سرخ فرش آپ کا زیادہ سے زیادہ نقصان ہے۔ جیسا کہ NIFTY 24,050 سے آگے بڑھتا ہے، خریدی ہوئی کال کی قیمت بڑھ جاتی ہے اور نقصان سکڑ جاتا ہے، یہاں تک کہ <strong>24,106 کا وقفہ</strong>امبر ڈاٹ سے نشان زد، اورنج لائن صفر کو سبز میں کراس کرتی ہے۔ 24,150 سے اوپر کی دونوں کالیں پیسے میں گہری ہیں، اسپریڈ مکمل طور پر کھلا ہے، اور آپ کا منافع اپنی حد سے بڑھنا بند ہو جاتا ہے۔ <strong>2,876 روپے</strong>، ایک فلیٹ سبز چھت۔ نیلی ڈیشڈ T+0 لائن اسی سفر کو مکمل طور پر دکھاتی ہے، کیونکہ وقت کی قدر آج بھی موجود ہے اور 28 جولائی تک ختم ہو جائے گی۔ نوٹ کریں کہ 24,106 کا بریک ایون صرف اندرونی سگما بینڈ کے اندر بیٹھتا ہے، لہذا یہ تجارت ایک معمولی، قابل اعتماد اضافہ پر شرط لگا رہی ہے، نہ کہ چاند کی تصویر۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bull-call-spread.png\" alt=\"ایک حقیقی NIFTY بل کال اسپریڈ، 24,050 کال خریدنا اور 24,150 کال بیچنا، 24,106 پر امبر بریک ایون ڈاٹ کے ساتھ، 24,050 سے نیچے 3,624 روپے کا سرخ زیادہ سے زیادہ نقصان کا فلور، اور 2,84760 روپے کی سبز زیادہ سے زیادہ منافع کی حد۔ گلابی لائن اسپاٹ 24,056 کو نشان زد کرتی ہے اور بیہوش سگما بینڈ اس حرکت کو ظاہر کرتے ہیں جس کی مارکیٹ کی توقع ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>ایک حقیقی NIFTY بل کال اسپریڈ، 24,050 کال خریدنا اور 24,150 کال بیچنا، 24,106 پر امبر بریک ایون ڈاٹ کے ساتھ، 24,050 سے نیچے 3,624 روپے کا سرخ زیادہ سے زیادہ نقصان کا فلور، اور 2,84760 روپے سے اوپر سبز زیادہ سے زیادہ منافع کی حد۔ گلابی لائن اسپاٹ 24,056 کو نشان زد کرتی ہے اور بیہوش سگما بینڈ اس حرکت کو ظاہر کرتے ہیں جس کی مارکیٹ کی توقع ہے۔</figcaption></figure>\n<p>یہ پورا طریقہ ہے۔ زیرو لائن، امبر بریک ایون ڈاٹس، گرین اور ریڈ زونز، دو فلیٹ چھتیں، گلابی اسپاٹ لائن، اور دھندلے سگما بینڈز تلاش کریں۔ اسے کسی بھی چارٹ پر کریں اور آپ نے حکمت عملی پڑھ لی ہے۔ OpenAlgo میں ہر چارٹ ایک ہی صاف ستھرا openalgo.in نظر پہنتا ہے، لہذا مہارت ہر اس ادائیگی میں منتقل ہوتی ہے جسے آپ کبھی بھی بنائیں گے۔ حقیقی رقم کا خطرہ مول لینے سے پہلے آپ آرڈر میکینکس کی مشق بھی کر سکتے ہیں۔ <strong>سینڈ باکس ٹریڈنگ ( OpenAlgo میں تجزیہ کار موڈ)</strong>، لہذا جب حقیقی سرمایہ شامل ہوتا ہے تو کچھ بھی عجیب محسوس نہیں ہوتا ہے۔ اگلے باب میں ہم آہستہ کرتے ہیں اور نو نمبروں کے پورے پینل کا مطالعہ کرتے ہیں جو ان چارٹ میں سے ہر ایک کے ساتھ بیٹھا ہے۔</p>\n","toc":[{"level":2,"text":"ادائیگی کا خاکہ آپ کے پیسے کی تصویر ہے۔","id":"a-payoff-diagram-is-a-picture-of-your-money"},{"level":2,"text":"دو لائنیں: میعاد ختم ہونے پر اور آج","id":"the-two-lines-at-expiry-and-today"},{"level":2,"text":"منافع کے زون، نقصان کے زون، اور بریک ایون","id":"profit-zones-loss-zones-and-the-breakeven"},{"level":2,"text":"سگما بینڈز اور اسپاٹ لائن","id":"the-sigma-bands-and-the-spot-line"},{"level":2,"text":"ٹانگیں: وہ ٹکڑے جو آپ اسٹیک کرتے ہیں۔","id":"legs-the-pieces-you-stack"},{"level":2,"text":"ایک حقیقی مثال کو آخر تک پڑھنا","id":"reading-one-real-example-end-to-end"}],"imgCount":1,"hasContent":true},"2":{"html":"<p>اس کورس میں تقریباً ہر حکمت عملی اپنے چارٹ کے ساتھ نمبروں کے پینل کے ساتھ آتی ہے۔ OpenAlgo بلڈر رپورٹ کرتا ہے۔ <strong>نو</strong> ان میں سے، اور وہ ایک ساتھ تجارت کا مکمل سکور کارڈ ہیں۔ چارٹ آپ کو شکل دکھاتا ہے۔ یہ نو نمبر اس پر صحیح اعداد و شمار ڈالتے ہیں۔ تمام نو کو پڑھنا سیکھیں اور آپ ایک پوزیشن کا سائز لے سکتے ہیں، اس کی مشکلات کا اندازہ لگا سکتے ہیں، اور یہ جان سکتے ہیں کہ اس میں کتنی رقم ملتی ہے، یہ سب کچھ ایک آرڈر دینے سے پہلے۔ یہ باب ان میں سے ہر ایک کو سکھاتا ہے، ایک حقیقی NIFTY تجارت کا استعمال کرتے ہوئے آپ بعد میں دوبارہ ملیں گے، <strong>بیل ڈال پھیل گیا</strong>، اور پھر اسے ایک بہت ہی مختلف تجارت کے ساتھ لگاتا ہے تاکہ سب سے اہم سبق مل جائے۔</p>\n<h2 id=\"the-nine-numbers-on-the-panel\">پینل پر نو نمبر</h2>\n<p>یہ مکمل پینل ہے جو بلڈر کسی بھی حکمت عملی کے لیے دکھاتا ہے۔ ہم ہر ایک کی وضاحت کریں گے، پھر انہیں حقیقی تجارت سے پڑھیں گے۔</p>\n<ul>\n<li><strong>زیادہ سے زیادہ منافع</strong>: فی لاٹ، ایکسپائری پر بہترین پوزیشن کر سکتی ہے۔</li>\n<li><strong>زیادہ سے زیادہ نقصان</strong>: فی لاٹ، ایکسپائری پر یہ سب سے برا کام کر سکتا ہے۔ \"لامحدود\" کا مطلب ہے کہ نقصان بڑھتا ہی جاتا ہے کیونکہ بنیادی چیز آپ کے خلاف حرکت کرتی رہتی ہے۔ سخت معنوں میں یہ صرف ایک ننگی مختصر کال یا مختصر مستقبل کا الٹا ہے، کیونکہ قیمت کی اوپر کوئی حد نہیں ہے۔ ایک شارٹ پوٹ یا لمبا مستقبل منفی پہلو سے ہار جاتا ہے، لیکن یہ نقصان محدود ہے، چونکہ قیمت صفر سے نیچے نہیں آسکتی ہے، اس لیے یہ واقعی لامحدود ہونے کی بجائے بہت بڑی ہے۔ خریدا ہوا آپشن، کال کریں یا ڈالیں، کبھی بھی اس پریمیم سے زیادہ نہیں کھو سکتے جو آپ نے اس کے لیے ادا کیے تھے۔ جب بلڈر \"لامحدود\" پرنٹ کرتا ہے، تو اسے \"اس طرف کوئی چھت نہیں\" کے طور پر پڑھیں، اور اسے ہمیشہ اس حقیقت پسندانہ حرکت کے ساتھ جوڑیں جو درحقیقت نقصان پہنچائے۔</li>\n<li><strong>Breakevens</strong>: قیمت یا قیمتیں جہاں اورنج ایکسپائری لائن صفر کو عبور کرتی ہے۔</li>\n<li><strong>منافع کا امکان (POP)</strong>: منڈی سے منسلک مشکلات تجارت کا اختتام منافع میں ہوتا ہے۔</li>\n<li><strong>انعام کا خطرہ</strong>: زیادہ سے زیادہ نقصان کے مقابلے میں زیادہ سے زیادہ منافع سیٹ، کسی چیز کو 1 کے طور پر دکھایا گیا ہے۔</li>\n<li><strong>نیٹ کریڈٹ یا نیٹ ڈیبٹ</strong>: چاہے آپ پریمیم اپ فرنٹ (کریڈٹ) وصول کریں یا اسے ادا کریں (ڈیبٹ)۔</li>\n<li><strong>تخمینہ پریمیم</strong>: تمام ٹانگوں کا مجموعی پریمیم ایک ساتھ جوڑا گیا، ایک ٹرن اوور کا اعداد و شمار۔</li>\n<li><strong>کل P&amp;L</strong>: اس وقت کھلا منافع یا نقصان، آپ کے داخل ہوتے وقت تقریباً صفر۔</li>\n<li><strong>مارجن کی درخواست</strong>: مارجن (نقدی یا گرویدہ ضمانت میں) پوزیشن رکھنے کے لیے ایکسچینج بلاکس۔</li>\n</ul>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>نو نمبر مکمل طور پر تجارت کی وضاحت کرتے ہیں: زیادہ سے زیادہ منافع، زیادہ سے زیادہ نقصان، بریک ایونز، منافع کا امکان، انعام کا خطرہ، خالص کریڈٹ یا ڈیبٹ، تخمینہ شدہ پریمیم، لائیو کل P&amp;L، اور مارجن درکار ہے۔ چارٹ تصویر ہے؛ یہ نو اس کے پیچھے صحیح اعداد و شمار ہیں۔</p>\n</div></div>\n<h2 id=\"the-bull-put-spread-in-numbers\">بیل تعداد میں پھیل گیا</h2>\n<p>دی <strong>بیل ڈال پھیل گیا</strong> 28 جولائی 2026 کی میعاد ختم ہونے پر دو ٹانگوں کے ساتھ ایک ہلکی سی تیزی، متعین خطرے والی کریڈٹ ٹریڈ ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>قسم</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>بیچنا</td>\n<td>24,050</td>\n<td>ڈالو</td>\n</tr>\n<tr>\n<td>2</td>\n<td>خریدیں۔</td>\n<td>23,950</td>\n<td>ڈالو</td>\n</tr>\n</tbody></table>\n<p>آپ 24,050 کا پوٹ بیچتے ہیں، جو آپ کو اس وقت تک ادائیگی کرتا ہے جب تک کہ NIFTY برقرار رہتا ہے، اور اس کے نیچے 23,950 کو بطور تحفظ خریدیں۔ فروخت شدہ پوٹ خریدے گئے پوٹ کی لاگت سے زیادہ لاتا ہے، لہذا آپ خالص کریڈٹ کے ساتھ چلے جاتے ہیں۔ یہاں مکمل نو نمبر والا پینل ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>میٹرک</th>\n<th>قدر</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>بریک ایون</td>\n<td>24,011</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>2,506 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>3,994 روپے</td>\n</tr>\n<tr>\n<td>منافع کا امکان</td>\n<td>51 فیصد</td>\n</tr>\n<tr>\n<td>انعام کا خطرہ</td>\n<td>1 : 0.63</td>\n</tr>\n<tr>\n<td>نیٹ کریڈٹ</td>\n<td>2,506 روپے</td>\n</tr>\n<tr>\n<td>تخمینہ پریمیم</td>\n<td>دونوں پوٹس کا مجموعی پریمیم</td>\n</tr>\n<tr>\n<td>کل P&amp;L</td>\n<td>داخلے پر تقریباً 0 روپے</td>\n</tr>\n<tr>\n<td>مارجن کی درخواست</td>\n<td>35,358 روپے</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bull-put-spread.png\" alt=\"NIFTY بیل پوٹ اسپریڈ، 24,050 کا پوٹ بیچا اور 23,950 کا پوٹ خریدا، امبر بریک ایون ڈاٹ کے ساتھ 24,011 پر، 2,506 روپے کا پورا کریڈٹ 24,050 سے اوپر رکھا گیا، اور نقصان 23,950 سے نیچے 3,994 روپے تک محدود ہوگیا۔ گلابی لائن اسپاٹ 24,056 کو نشان زد کرتی ہے اور دائیں طرف کا پینل تمام نو نمبر دکھاتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY بیل پوٹ اسپریڈ، 24,050 کا پوٹ بیچا اور 23,950 کا پوٹ خریدا، امبر بریک ایون ڈاٹ کے ساتھ 24,011 پر، 2,506 روپے کا مکمل کریڈٹ 24,050 سے اوپر رکھا گیا، اور نقصان 23,950 سے نیچے 3,994 روپے تک محدود ہوگیا۔ گلابی لائن اسپاٹ 24,056 کو نشان زد کرتی ہے اور دائیں طرف کا پینل تمام نو نمبر دکھاتا ہے۔</figcaption></figure>\n<h2 id=\"walking-the-numbers-one-by-one\">نمبروں کو ایک ایک کرکے چلنا</h2>\n<p><strong>زیادہ سے زیادہ منافع، 2,506 روپے۔</strong> یہ بالکل وہی خالص کریڈٹ ہے جو آپ نے جمع کیا ہے، اور اگر آپ NIFTY 24,050 پر یا اس سے اوپر بند ہو جاتا ہے تو آپ یہ سب اپنے پاس رکھتے ہیں، جہاں دونوں کی میعاد ختم ہوجاتی ہے۔ کریڈٹ انعام ہے، اور آپ اسے صرف NIFTY کے ذریعے بینک کرتے ہیں۔</p>\n<p><strong>زیادہ سے زیادہ نقصان، 3,994 روپے۔</strong> یہ نقصان ہوتا ہے اگر NIFTY 23,950 پر یا اس سے نیچے بند ہوتا ہے، جہاں خریدا ہوا نقصان کو پورا کرتا ہے۔ دونوں سٹرائیکس میں 100 پوائنٹس کا فرق ہے، جس کی قیمت 65 کے لاٹ کے لیے 6,500 روپے ہے۔ آپ نے 2,506 روپے کریڈٹ کے طور پر رکھے ہیں، لہذا آپ سب سے زیادہ کھو سکتے ہیں باقی، 6,500 روپے مائنس 2,506 روپے، جو کہ 3,994 روپے ہے۔ کریڈٹ پلس زیادہ سے زیادہ نقصان ہمیشہ پوری ہڑتال کی چوڑائی کے برابر ہوتا ہے۔</p>\n<p><strong>بریک ایون، 24,011۔</strong> NIFTY 24,011 تک تھوڑا سا نیچے کی طرف بڑھ سکتا ہے، اور آپ اب بھی باہر آتے ہیں، کیونکہ کریڈٹ کسی بھی زوال کے پہلے حصے کو متاثر کرتا ہے۔ یہ 24,050 سٹرائیک مائنس تقریباً 39 پوائنٹس فی شیئر کا کریڈٹ ہے۔ 24,011 سے اوپر آپ کم از کم کچھ منافع رکھتے ہیں، اس کے نیچے آپ کو نقصان ہونا شروع ہو جاتا ہے۔</p>\n<p><strong>خالص کریڈٹ، 2,506 روپے۔</strong> پوزیشن آپ کو پہلے دن ادا کرتی ہے۔ اے <strong>کریڈٹ</strong> اس کا مطلب ہے کہ آپ کے اکاؤنٹ میں پریمیم زمینیں، ایک خالص فروخت کنندہ کا نشان۔ اے <strong>ڈیبٹ</strong> اس کا مطلب یہ ہے کہ آپ نے سامنے ادائیگی کی، خالص خریدار کا نشان۔ یہاں کریڈٹ اور زیادہ سے زیادہ منافع ایک ہی اعداد و شمار ہیں، جو ہر سادہ کریڈٹ اسپریڈ کے لیے درست ہے۔</p>\n<p><strong>انعام کا خطرہ، 1 سے 0.63۔</strong> ہر روپے کے لیے جو آپ خطرے میں ہیں آپ تقریباً 63 پیسے کما سکتے ہیں۔ آپ 2,506 روپے کمانے کے لیے 3,994 روپے کا خطرہ مول لے رہے ہیں، اس لیے آپ اپنی کمائی سے زیادہ خطرہ مول لیتے ہیں۔ یہ کوئی خامی نہیں ہے، یہ وہ تجارت ہے جسے آپ جیتنے کے زیادہ مواقع کے بدلے میں قبول کرتے ہیں، جس کی اگلی نمبر وضاحت کرتی ہے۔</p>\n<p><strong>تخمینہ پریمیم</strong> یہ دونوں پوٹس کا مجموعی پریمیم ہے جو ایک ساتھ شامل کیا گیا ہے، ٹرن اوور کا اعداد و شمار، آپ کا خطرہ نہیں۔ اسے زیادہ سے زیادہ نقصان کے ساتھ الجھاؤ نہیں۔ آپ کا اصل خطرہ 3,994 روپے کا زیادہ سے زیادہ نقصان ہے، مجموعی پریمیم کبھی نہیں۔</p>\n<p><strong>کل P&amp;L، تقریباً صفر۔</strong> جس لمحے آپ داخل ہوتے ہیں، پوزیشن تقریباً وہی ہے جو آپ نے ادا کی یا وصول کی، اس لیے کھلا منافع یا نقصان صفر کے قریب ہے۔ یہ NIFTY کے سفر کے دوران اور وقت کے زوال کے ساتھ سبز یا سرخ میں منتقل ہوتا ہے۔</p>\n<p><strong>مارجن درکار ہے، 35,358 روپے۔</strong> یہ مارجن (نقد یا گرویدہ ضمانت میں) ایکسچینج بلاکس ہے جو آپ کو تجارت کو برقرار رکھنے کی اجازت دیتا ہے، OpenAlgo مارجن کیلکولیٹر سے SPAN علاوہ ایکسپوزر مارجن۔ چونکہ یہ خریدے گئے حفاظتی پوٹ کے ساتھ ایک طے شدہ خطرہ ہے، مارجن معمولی ہے۔ ایک ہی نظریہ کے ساتھ ایک ننگا شارٹ پٹ کئی گنا زیادہ بلاک کردے گا۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>اس بیل پوٹ اسپریڈ کے لیے سٹرائیکس 100 پوائنٹس کے علاوہ ہیں، 65 کے لاٹ کی قیمت 6,500 روپے ہے۔ 2,506 روپے کا کریڈٹ آپ کا انعام ہے، اور بقیہ 3,994 روپے آپ کا رسک ہے۔ کریڈٹ پلس زیادہ سے زیادہ نقصان ہمیشہ پوری ہڑتال کی چوڑائی کے برابر ہوتا ہے۔ پینل پر ہر اعداد و شمار فی ایک لاٹ ہے۔</p>\n</div></div>\n<h2 id=\"probability-of-profit-and-the-trade-it-implies\">منافع کا امکان، اور اس کا مطلب تجارت</h2>\n<p>وہ نمبر جو ایک ابتدائی شخص اکثر غلط پڑھتا ہے۔ <strong>منافع کا امکان</strong>, the <strong>POP</strong>. یہ مارکیٹ سے منسلک موقع ہے کہ تجارت منافع میں ختم ہو جائے، اس ماڈل سے کام کیا گیا ہے جہاں 28 جولائی تک 28 جولائی تک لینڈ ہو سکتا ہے، تقریباً 12.7 فیصد کی ایٹ-دی-منی مضمر اتار چڑھاؤ کا استعمال کرتے ہوئے اور مدت ختم ہونے کے دن۔ آپ کو فارمولے کی ضرورت نہیں ہے۔ اسے اس طرح پڑھیں کہ تجارت ایک فاتح کو ختم کرتی ہے۔</p>\n<p>بیل پوٹ اسپریڈ کے لیے POP ہے۔ <strong>51 فیصد</strong>. NIFTY کو صرف 24,011 کے قریب یا اس سے اوپر رکھنا ہوتا ہے، آج کے 24,056 سے تھوڑا نیچے، اس لیے تجارت آدھے وقت سے تھوڑا زیادہ جیت جاتی ہے۔ اسے 1 سے 0.63 کے انعام کے خطرے کے ساتھ جوڑیں اور پوری تصویر نظر آئے: جیتنے کا تقریباً ایک موقع، انعام کے ساتھ خطرہ سے تھوڑا چھوٹا۔ یہ ایک متوازن، ایماندارانہ تجارت ہے، یہی وجہ ہے کہ یہ ایک اچھا پہلا کریڈٹ اسپریڈ بناتی ہے۔</p>\n<p>یہ وہ اصول ہے جو آپ کو ملنے والی تقریباً ہر حکمت عملی کو کنٹرول کرتا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>منافع کا ایک اعلی امکان عام طور پر ایک چھوٹے انعام کے ساتھ آتا ہے، اور ایک بڑا انعام عام طور پر منافع کے کم امکان کے ساتھ آتا ہے۔ مارکیٹ کی قیمتیں یہ ہیں تاکہ کوئی شکل مفت پیسہ نہ ہو۔ جب تجارت اکثر جیت جاتی ہے تو ہر جیت چھوٹی ہوتی ہے۔ جب کوئی تجارت بڑی قیمت ادا کرتی ہے تو یہ شاذ و نادر ہی جیتتا ہے۔</p>\n</div></div>\n<h2 id=\"a-high-pop-trade-the-short-iron-condor\">ایک اعلی POP تجارت: مختصر لوہے کا کنڈور</h2>\n<p>اس تجارت کو محسوس کرنے کے لیے، چار ٹانگوں والے متعین خطرے والے ڈھانچے کے ساتھ بیل ڈال دیں جس سے آپ بعد میں ملیں گے، <strong>مختصر لوہے کا کنڈور</strong>. ابھی کے لیے اس کی تعمیر کو نظر انداز کریں اور اس پھیلاؤ کے خلاف صرف اس کے نمبر پڑھیں جو آپ پہلے سے جانتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>میٹرک</th>\n<th>بیل ڈال اسپریڈ</th>\n<th>مختصر آئرن کنڈور</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>2,506 روپے</td>\n<td>884 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>3,994 روپے</td>\n<td>5,616 روپے</td>\n</tr>\n<tr>\n<td>منافع کا امکان</td>\n<td>51 فیصد</td>\n<td>83 فیصد</td>\n</tr>\n<tr>\n<td>انعام کا خطرہ</td>\n<td>1 : 0.63</td>\n<td>1 : 0.16</td>\n</tr>\n<tr>\n<td>Breakevens</td>\n<td>24,011</td>\n<td>23,864 / 24,236</td>\n</tr>\n<tr>\n<td>مارجن کی درخواست</td>\n<td>35,358 روپے</td>\n<td>68,864 روپے</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-short-iron-condor.png\" alt=\"NIFTY مختصر آئرن کنڈور، ایک چار ٹانگوں والا ڈیفائنڈ رسک ڈھانچہ جس میں 23,864 اور 24,236 پر امبر بریک ایون ڈاٹس ہیں۔ اس کا پینل 884 روپے کے چھوٹے زیادہ سے زیادہ منافع اور 5,616 روپے کے زیادہ سے زیادہ نقصان کے ساتھ 83 فیصد کے منافع کے اعلی امکان کو ظاہر کرتا ہے، کلاسک ہائی اوڈز، کم انعام والا سودا۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY مختصر آئرن کنڈور، ایک چار ٹانگوں والا ڈیفائنڈ رسک ڈھانچہ جس میں 23,864 اور 24,236 پر امبر بریک ایون ڈاٹس ہیں۔ اس کا پینل 884 روپے کے چھوٹے زیادہ سے زیادہ منافع اور 5,616 روپے کے زیادہ سے زیادہ نقصان کے ساتھ 83 فیصد کے منافع کے اعلی امکان کو ظاہر کرتا ہے، کلاسک ہائی اوڈز، کم انعام والا سودا۔</figcaption></figure>\n<p>مختصر لوہے کا کنڈور جیت گیا۔ <strong>83 فیصد</strong> وقت کے، کہیں زیادہ کثرت سے بیل ڈال پھیل گیا. جب تک آپ باقی پینل کو نہیں پڑھتے تب تک یہ بہت اچھا لگتا ہے۔ ہر جیت صرف ہوتی ہے۔ <strong>884 روپے</strong>، جبکہ ہر ایک نقصان ہو سکتا ہے <strong>5,616 روپے</strong>، صرف 1 سے 0.16 کے انعام کا خطرہ۔ آپ ایک بنانے کے لیے چھ روپے سے زیادہ کا خطرہ مول لے رہے ہیں۔ زیادہ جیت کی شرح اور چھوٹا انعام ایک ہی سکے کے دو رخ ہیں: مارکیٹ آپ کو بار بار جیتتی ہے صرف اس وجہ سے کہ یہ ہر ایک کو چھوٹا اور نایاب نقصان کو بڑا بناتا ہے۔</p>\n<p>پینل کو پڑھنے میں یہ واحد سب سے اہم سبق ہے۔ ایک اعلی POP اچھی تجارت کے مترادف نہیں ہے، اور انعام کے لیے کم خطرہ بری تجارت جیسا نہیں ہے۔ دونوں نمبروں کو ہمیشہ ایک ساتھ پڑھنا چاہیے، آپ کے اپنے ایماندارانہ نظریہ کے ساتھ کہ NIFTY کے کہاں جانے کا امکان ہے۔ یا تو تجارت صحیح حالات میں سمجھدار ہوسکتی ہے، اور یا تو آپ کو نقصان پہنچ سکتی ہے اگر آپ اسے لاپرواہی سے سائز دیتے ہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>کبھی بھی کسی حکمت عملی کو اس کے اکیلے POP یا اس کے اکیلے انعام دینے کے خطرے سے نہ پرکھیں۔ انہیں ایک جوڑے کے طور پر پڑھیں۔ 1 سے 0.16 انعام کے ساتھ 83 فیصد POP اور 1 سے 0.63 انعام کے ساتھ 51 فیصد POP صرف دو مختلف سودے ہیں، نہ کہ ایک بہتر اور ایک بدتر۔ NIFTY پر آپ کا نظریہ فیصلہ کرتا ہے کہ کون سا سودا فٹ بیٹھتا ہے۔</p>\n</div></div>\n<h2 id=\"margin-and-defined-risk-for-beginners\">ابتدائیوں کے لیے مارجن اور متعین خطرہ</h2>\n<p>نو نمبروں میں سے دو آپ کی باقیوں سے زیادہ حفاظت کرتے ہیں۔ <strong>زیادہ سے زیادہ نقصان</strong> اور <strong>مارجن کی ضرورت ہے</strong>. وہ مل کر آپ کو بتاتے ہیں کہ تجارت پر کیا لاگت آسکتی ہے اور یہ کھلے رہنے کے دوران کیا منسلک ہوتا ہے۔</p>\n<p>یہ دونوں مثالیں ہیں۔ <strong>طے شدہ خطرہ</strong>. زیادہ سے زیادہ نقصان چارٹ پر چھپی ہوئی ایک فلیٹ، محدود منزل ہے، بیل پٹ اسپریڈ کے لیے 3,994 روپے اور شارٹ آئرن کنڈور کے لیے 5,616 روپے، کیونکہ خریدی گئی ٹانگ ہر طرف سے ہونے والے نقصان کو پورا کرتی ہے۔ ان کے مارجن، 35,358 روپے اور 68,864 روپے، اسی وجہ سے معمولی ہیں۔ اس کا موازنہ کورس کے بعد کی ننگی مختصر پوزیشنوں سے کریں، جہاں نقصان لامحدود ہے اور مارجن ڈیڑھ لاکھ سے زیادہ ہے۔ ایک مبتدی کے طور پر آپ وہ تجارت چاہتے ہیں جن کی سب سے خراب صورت ایک معلوم نمبر ہے جس میں آپ زندہ رہ سکتے ہیں، اور جس کا مارجن آپ آرام سے الگ کر سکتے ہیں۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ہمیشہ ایک پوزیشن کو اس کے زیادہ سے زیادہ نقصان سے سائز کریں، کبھی بھی اس کے کریڈٹ یا اس کے تخمینہ شدہ پریمیم سے نہیں۔ بیل نے 2,506 روپے بنانے کے لیے 3,994 روپے کا اسپریڈ رسک لگایا، اور جیت کا سلسلہ اگلے نقصان کو کم نہیں کرتا۔ اپنی لاٹ گنتی کا فیصلہ کریں کہ برے دن آپ کا اکاؤنٹ کیا جذب کر سکتا ہے، ہر حفاظتی ٹانگ کو اپنی جگہ پر رکھیں، اور مارجن کے اعداد و شمار کو حقیقی نقد سمجھیں جو تجارت کے کھلنے کے دوران بند کر دیا جاتا ہے۔</p>\n</div></div>\n<p>اب آپ مکمل سکور کارڈ کے مالک ہیں۔ یہاں سے، ہر باب اپنی شکل اور اس کے نو نمبروں کے لحاظ سے ایک حکمت عملی متعارف کراتا ہے، اور آپ ان سب کو پڑھنا پہلے ہی جانتے ہیں۔ اس کے بعد ہم نے انہیں سب سے آسان تجارت، سنگل ٹانگ لانگ کال اور شارٹ پٹ پر کام کرنے کے لیے رکھا۔</p>\n","toc":[{"level":2,"text":"پینل پر نو نمبر","id":"the-nine-numbers-on-the-panel"},{"level":2,"text":"بیل تعداد میں پھیل گیا","id":"the-bull-put-spread-in-numbers"},{"level":2,"text":"نمبروں کو ایک ایک کرکے چلنا","id":"walking-the-numbers-one-by-one"},{"level":2,"text":"منافع کا امکان، اور اس کا مطلب تجارت","id":"probability-of-profit-and-the-trade-it-implies"},{"level":2,"text":"ایک اعلی POP تجارت: مختصر لوہے کا کنڈور","id":"a-high-pop-trade-the-short-iron-condor"},{"level":2,"text":"ابتدائیوں کے لیے مارجن اور متعین خطرہ","id":"margin-and-defined-risk-for-beginners"}],"imgCount":2,"hasContent":true},"3":{"html":"<p>آپ کی ایک واضح رائے ہے: NIFTY آنے والے مہینے میں اوپر کی طرف بڑھ رہا ہے۔ ایک واحد آپشن کے ساتھ اس واحد نقطہ نظر کی پشت پناہی کرنے کے دو سادہ طریقے ہیں، اور وہ اسی تجارت کے مخالف سمتوں پر بیٹھتے ہیں۔ آپ کر سکتے ہیں۔ <strong>ایک کال خریدیں</strong>, اضافہ کی سواری کے حق کے لیے ابھی پریمیم ادا کرنا۔ یا آپ کر سکتے ہیں۔ <strong>ایک ڈال فروخت</strong>، ابھی ایک پریمیم جمع کرنا اور اگر یہ آپ کی ہڑتال پر آتا ہے تو NIFTY خریدنے کا وعدہ کرنا۔ آپ میں سے ایک خریدار، امید مند اور صبر کرنے والا ہے، جس کی تھوڑی سی مقررہ قیمت ہے۔ دوسرا بیچنے والا ہے، جو پہلے سے ادا کیا جاتا ہے لیکن حقیقی ذمہ داری کو پورا کرتا ہے۔ یہ باب 26 جون 2026 کو کیپچر کیے گئے حقیقی NIFTY آپشن ڈیٹا دونوں پر بناتا ہے، جس میں انڈیکس 24,056، 24,050 پر پیسے کی ہڑتال، 65 یونٹس کا ایک لاٹ، اور 28 جولائی 2026 کی میعاد ختم ہونے میں تقریباً 32 دن باقی ہیں۔</p>\n<h2 id=\"the-one-line-idea\">ایک لائن کا خیال</h2>\n<p>اے <strong>لمبی کال</strong> لامحدود اوپر کی طرف ایک چھوٹا سا پریمیم ادا کرتا ہے۔ اے <strong>مختصر پوٹ</strong> ایک چھوٹا پریمیم اکٹھا کرتا ہے اور ایک بڑے چھپے ہوئے منفی پہلو کو قبول کرتا ہے۔ دونوں ایک ہی تیزی کے نقطہ نظر کا اظہار کرتے ہیں، لیکن وہ پورے سودے کو تبدیل کرتے ہیں: خریدار ایک کھلی جیت کے بدلے میں کم مشکلات اور ایک محدود، معلوم نقصان لیتا ہے، جب کہ فروخت کنندہ ایک محدود جیت اور خطرناک دم کے بدلے میں زیادہ مشکلات اور دوستانہ گھڑی لیتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>اسی تیزی کے نظارے اور اسی 24,050 سٹرائیک پر، لانگ کال کم مشکلات پر لامحدود فائدہ کے لیے مقررہ 27,677 روپے کا خطرہ رکھتی ہے، جب کہ شارٹ پٹ زیادہ مشکلات پر ایک مقررہ 19,182 روپے کماتا ہے لیکن اگر NIFTY ٹوٹ جاتا ہے تو بڑے، ڈھیلے نقصان کا خطرہ ہوتا ہے۔ خریدار ایک بڑی جیت کے لیے ادائیگی کرتے ہیں جسے وہ شاذ و نادر ہی حاصل کرتے ہیں۔ بیچنے والے اکثر ادائیگی کرتے ہیں، لیکن غیر معمولی نقصان بھاری ہے.</p>\n</div></div>\n<h2 id=\"the-long-call-rupee-by-rupee\">لمبی کال، روپیہ بہ روپیہ</h2>\n<p>آپ ایک ایٹ دی منی کال خریدتے ہیں۔ وہ ایک ٹانگ پوری پوزیشن ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>کال خریدیں۔</td>\n<td>24,050</td>\n<td>425.8 ادا کیا گیا۔</td>\n<td>27,677 روپے باہر</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>خالص ڈیبٹ</strong></td>\n<td><strong>27,677 روپے باہر</strong></td>\n</tr>\n</tbody></table>\n<p>24,050 کال کی قیمت 425.8 فی شیئر ہے، جو 425.8 گنا 65 ہے، یا <strong>27,677 روپے</strong> ایک بہت کے لئے. جب آپ خریدتے ہیں تو وہ رقم آپ کے اکاؤنٹ سے نکل جاتی ہے، اور آپ سے کبھی ایک روپیہ بھی نہیں مانگا جا سکتا۔ یہ ایک حقیقت ایک اختیار خریدنے کا پورا سکون ہے۔ آپ کا زیادہ سے زیادہ نقصان پریمیم، فل سٹاپ ہے، اور اسٹرائیک کے اوپر آپ کے اوپری حصے کی کوئی حد نہیں ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-long-call.png\" alt=\"NIFTY پر لمبی کال، 24,050 کال کو 27,677 روپے میں خریدنا۔ اورنج ایٹ-ایکسپائری لائن اسٹرائیک کے نیچے فلیٹ نقصان کے فرش پر ٹکی ہوئی ہے، 24,476 کے بریک ایون پر صفر کو عبور کرتی ہے، پھر گرین پرافٹ زون میں بغیر کسی حد کے چڑھ جاتی ہے۔ نیلی ڈیشڈ T+0 لائن اس کے اوپر بیٹھی ہے، اس وقت کی قدر رکھتی ہے جو زوال پذیر ہو جائے گی۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY پر طویل کال، 24,050 کال کو 27,677 روپے میں خریدنا۔ اورنج ایٹ-ایکسپائری لائن اسٹرائیک کے نیچے فلیٹ نقصان کے فرش پر ٹکی ہوئی ہے، 24,476 کے بریک ایون پر صفر کو عبور کرتی ہے، پھر گرین پرافٹ زون میں بغیر کسی حد کے چڑھ جاتی ہے۔ نیلی ڈیشڈ T+0 لائن اس کے اوپر بیٹھی ہے، اس وقت کی قدر رکھتی ہے جو زوال پذیر ہو جائے گی۔</figcaption></figure>\n<h2 id=\"the-long-call-s-three-numbers\">لمبی کال کے تین نمبر</h2>\n<p>ہر نمبر براہ راست تجارت سے باہر آتا ہے۔ ایک بار جب آپ منطق کو دیکھ لیں تو یاد کرنے کے لیے کچھ بھی نہیں۔</p>\n<p><strong>زیادہ سے زیادہ نقصان پریمیم ہے، 27,677 روپے۔</strong> اگر NIFTY 24,050 پر یا اس سے نیچے ختم ہوجاتا ہے، تو 24,050 پر خریدنے کا حق بیکار ہے اور آپ کا پورا خرچ ختم ہوجاتا ہے۔ یہ چارٹ کے بائیں جانب فلیٹ فلور ہے۔</p>\n<p><strong>زیادہ سے زیادہ منافع لامحدود ہے۔</strong> ہر نقطہ NIFTY اسٹرائیک کے اوپر چڑھنے سے کال کی قدر میں اضافہ ہوتا ہے، اور اسے کوئی چیز نہیں روکتی، اس لیے لائن ہمیشہ کے لیے بڑھ جاتی ہے۔</p>\n<p><strong>Breakeven اسٹرائیک کے علاوہ پریمیم فی شیئر، 24,476 ہے۔</strong> آپ نے پریمیم کے 425.8 پوائنٹس ادا کیے ہیں، لہذا NIFTY کو اسٹرائیک کو کلیئر کرنا ہوگا اور پھر ایک روپیہ بنانے سے پہلے وہ 425.8 واپس حاصل کرنا ہوگا۔ یہ جگہ سے تقریباً 420 پوائنٹ اوپر 24,050 پلس 425.8 یا 24,476 پر اترتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>پریمیم جو آپ نے ادا کیا۔</td>\n<td>27,677 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>ہڑتال کے اوپر کوئی حد نہیں ہے۔</td>\n<td>لا محدود</td>\n</tr>\n<tr>\n<td>بریک ایون</td>\n<td>ہڑتال پلس پریمیم فی شیئر</td>\n<td>24,050 جمع 425.8 برابر 24,476</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-long-call-to-expiry\">ایکسپائر ہونے کے لیے لمبی کال چلنا</h2>\n<p>کال کو مٹھی بھر بند قیمتوں پر طے کریں اور شکل خود ہی ظاہر ہوجائے گی۔ کال کی قیمت اس کی داخلی قدر ہے، زیادہ سے زیادہ(NIFTY مائنس 24,050, 0)، اور آپ کا منافع وہ قیمت ہے جو آپ نے ادا کی ہے مائنس 425.8، ہر بار 65۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>24,050 کال آپ نے خریدی۔</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,800</td>\n<td>مالیت 0</td>\n<td>مائنس 27,677 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>مالیت 0</td>\n<td>مائنس 27,677 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>24,476</td>\n<td>مالیت 426</td>\n<td>تقریباً 0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>24,800</td>\n<td>مالیت 750</td>\n<td>علاوہ 21,073 روپے</td>\n</tr>\n<tr>\n<td>25,300</td>\n<td>مالیت 1,250</td>\n<td>علاوہ 53,573 روپے (اور چڑھنا)</td>\n</tr>\n</tbody></table>\n<p>24,050 پر یا اس سے کم کہیں بھی آپ پورا پریمیم کھو دیتے ہیں۔ ہڑتال اور 24,476 کے درمیان نقصان سکڑ جاتا ہے لیکن آپ اب بھی سرخ ہیں۔ 24,476 کے بعد آپ سبز ہو جاتے ہیں، اور وہاں سے ہر اضافی نقطہ خالص فائدہ ہے جس کی کوئی حد نہیں ہے۔ یہ پوری ادائیگی ہے، اور یہ اورنج لائن سے بالکل میل کھاتا ہے۔</p>\n<h2 id=\"the-short-put-rupee-by-rupee\">شارٹ پٹ، روپیہ بہ روپیہ</h2>\n<p>اب دوسری طرف کراس کریں۔ کال کے لیے ادائیگی کرنے کے بجائے، آپ ایک پیسے کی قیمت فروخت کرتے ہیں اور پریمیم اپ فرنٹ میں لیتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>ڈال فروخت</td>\n<td>24,050</td>\n<td>295.1 موصول ہوا۔</td>\n<td>علاوہ 19,182 روپے میں</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>نیٹ کریڈٹ</strong></td>\n<td><strong>علاوہ 19,182 روپے میں</strong></td>\n</tr>\n</tbody></table>\n<p>آپ فی شیئر 295.1 جمع کرتے ہیں، جو کہ ہے۔ <strong>19,182 روپے</strong> لاٹ کے لیے، فوری طور پر آپ بیچتے ہیں۔ یہ کریڈٹ سب سے زیادہ ہے جو آپ کبھی بنا سکتے ہیں۔ اگر NIFTY 24,050 پر یا اس سے اوپر بند ہوتا ہے تو آپ یہ سب اپنے پاس رکھتے ہیں، کیونکہ آپ نے جو پوٹ بیچا ہے اس کی میعاد ختم ہوجاتی ہے اور خریدار چلا جاتا ہے۔ درحقیقت آپ کو 24,050 میں NIFTY خریدنے کا وعدہ کرنے پر کرایہ ادا کیا جاتا ہے اگر یہ وہاں ڈوب جاتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-short-put.png\" alt=\"NIFTY پر شارٹ پٹ، 24,050 کا پوٹ 19,182 روپے کے کریڈٹ پر فروخت ہوا۔ اورنج لائن سٹرائیک کے اوپر زیادہ سے زیادہ منافع پر فلیٹ ہے، 23,755 کے بریک ایون پر صفر کو عبور کرتی ہے، پھر نقصان کے علاقے میں ایک بہت بڑے نشیب کی طرف پھسل جاتی ہے جس میں کوئی منزل نہیں ہوتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY پر شارٹ پٹ، 24,050 کا پوٹ 19,182 روپے کے کریڈٹ پر فروخت ہوا۔ اورنج لائن سٹرائیک کے اوپر زیادہ سے زیادہ منافع پر فلیٹ ہے، 23,755 کے بریک ایون پر صفر کو عبور کرتی ہے، پھر نقصان کے علاقے میں ایک بہت بڑے نشیب کی طرف پھسل جاتی ہے جس میں کوئی منزل نہیں ہوتی ہے۔</figcaption></figure>\n<h2 id=\"the-short-put-s-three-numbers\">شارٹ پٹ کے تین نمبر</h2>\n<p><strong>زیادہ سے زیادہ منافع کریڈٹ ہے، 19,182 روپے۔</strong> 24,050 سے اوپر کا پٹ بیکار ہو جاتا ہے اور آپ کرایہ اپنے پاس رکھتے ہیں۔ یہ دائیں طرف فلیٹ شیلف ہے۔</p>\n<p><strong>زیادہ سے زیادہ نقصان صفر کی طرف جاتا ہے، تقریباً 1,544,068 روپے۔</strong> اسٹرائیک کے نیچے پوٹ آپ کے مقابلے میں روپے کے بدلے بڑھتا ہے، بالکل اسی طرح جیسے آپ کے پاس 24,050 سے نیچے NIFTY ہے۔ تقریباً ٹوٹل گرنے میں نظریاتی منزل 1,544,068 روپے ہے، جو کریڈٹ کو کم کر دیتی ہے۔ یہ ایک حقیقت پسندانہ واحد سیشن نہیں ہے، لیکن یہ ایماندارانہ بدترین معاملہ ہے۔</p>\n<p><strong>Breakeven اسٹرائیک مائنس کریڈٹ فی شیئر، 23,755 ہے۔</strong> NIFTY اسٹرائیک سے 295.1 پوائنٹس نیچے، 23,755 تک گر سکتا ہے، اس سے پہلے کہ پوٹ پر ہونے والا نقصان پورا کریڈٹ کھا جائے۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>پریمیم جو آپ نے جمع کیا۔</td>\n<td>19,182 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>اسٹرائیک ویلیو صفر کی طرف لے گئی۔</td>\n<td>تقریباً 1,544,068 روپے</td>\n</tr>\n<tr>\n<td>بریک ایون</td>\n<td>ہڑتال مائنس کریڈٹ فی شیئر</td>\n<td>24,050 مائنس 295.1 برابر 23,755</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-short-put-to-expiry\">ایکسپائری کے لیے شارٹ پٹ پر چلنا</h2>\n<p>یہاں پوٹ کی قیمت زیادہ سے زیادہ ہے (24,050 مائنس NIFTY، 0)، اور آپ کا نتیجہ 295.1 کریڈٹ مائنس ہے اس قدر، گنا 65۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>24,050 میں آپ نے فروخت کیا۔</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>24,300</td>\n<td>مالیت 0</td>\n<td>جمع 19,182 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>مالیت 0</td>\n<td>جمع 19,182 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>23,755</td>\n<td>مالیت 295</td>\n<td>تقریباً 0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>23,500</td>\n<td>مالیت 550</td>\n<td>مائنس 16,569 روپے</td>\n</tr>\n<tr>\n<td>23,000</td>\n<td>مالیت 1,050</td>\n<td>مائنس 49,069 روپے (اور گرتا ہوا)</td>\n</tr>\n</tbody></table>\n<p>23,755 پر یا اس سے اوپر کی ہر چیز آپ کو منافع میں رکھتی ہے، ایک وسیع محفوظ زون۔ اس کے نیچے نقصان کھلتا ہے اور گہرا ہوتا رہتا ہے، جب تک کہ NIFTY صفر کے قریب نہ ہو کوئی فلیٹ فلور نہیں ہوتا ہے۔ شکل لمبی کال کی آئینہ دار تصویر ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>شارٹ پٹ ایک ننگی چھوٹی ٹانگ ہے۔ اس کا منافع 19,182 روپے ہے جو آپ اکٹھا کرتے ہیں، لیکن اس کا نقصان تقریباً 1,544,068 روپے تک پہنچ جاتا ہے، اور ایکسچینج اسے رکھنے کے لیے 165,042 روپے کے قریب بھاری مارجن کو روکتا ہے۔ 1 سے 0.01 کے انعام کا خطرہ واضح طور پر کہتا ہے: بڑے گانٹھ والے خطرے کے خلاف ایک چھوٹا سا مقررہ انعام۔ اسے صرف اس وقت فروخت کریں جب آپ حقیقی طور پر 23,755 کے قریب NIFTY کے مالک ہونے پر راضی ہوں گے اور مارجن کو فنڈ دے سکتے ہیں اور دم کا مکمل احترام کر سکتے ہیں۔</p>\n</div></div>\n<h2 id=\"your-odds\">آپ کی مشکلات</h2>\n<p>آپ جتنا جیت سکتے ہیں یا ہار سکتے ہیں وہ صرف آدھی کہانی ہے۔ دوسرا نصف یہ ہے کہ ہر نتیجہ کا کتنا امکان ہے، اور وہ ہے۔ <strong>منافع کا امکان</strong>, مارکیٹ میں مضمر موقع تجارت کے ختم ہونے کا سبز رنگ۔</p>\n<p>دی <strong>لانگ کال کی POP تقریباً 31 فیصد ہے۔</strong>. اس کا 24,476 کا بریک ایون چارٹ پر پلس ون سگما بینڈ کے اوپر بیٹھتا ہے، اس لیے آپشن مارکیٹ کا مطلب یہ ہے کہ تین میں سے صرف ایک موقع NIFTY ختم ہونے پر اس حد کو ختم کرتا ہے۔ دی <strong>شارٹ پٹ کا POP تقریباً 62 فیصد ہے۔</strong>کیونکہ اس کا 23,755 کا بریک ایون جگہ کے نیچے، محفوظ زون کے اندر آرام سے بیٹھا ہے۔ ایک ہی تیزی کا نظارہ، دو بالکل مختلف مشکلات، کیونکہ خریدار کو ایک حقیقی اقدام کی ضرورت ہوتی ہے جبکہ بیچنے والے کو صرف مارکیٹ کی ضرورت ہوتی ہے کہ وہ کریش نہ ہو۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>ہمیشہ POP کو زیادہ سے زیادہ نقصان کے ساتھ پڑھیں، کبھی اکیلے نہیں۔ شارٹ پٹ کا 62 فیصد اس وقت تک پرکشش نظر آتا ہے جب تک کہ آپ اسے اس کے 1,544,068 روپے کے ساتھ نہ لگا دیں۔ لانگ کال کا 31 فیصد اس وقت تک خراب نظر آتا ہے جب تک کہ آپ اسے اس کے چھوٹے، فکسڈ 27,677 روپے کے خطرے کے ساتھ نہیں لگاتے۔ تجارت کسی نتیجہ کو اس کی مشکلات کے ساتھ جوڑنا ہے، نہ کہ خود ایک۔</p>\n</div></div>\n<h2 id=\"margin-and-return\">مارجن اور واپسی</h2>\n<p>طویل کال کے لئے <strong>مارجن ڈیبٹ کے برابر ہے، 27,677 روپے</strong>. چونکہ آپ اپنی ادائیگی سے زیادہ نہیں کھو سکتے ہیں، اس لیے ایکسچینج صرف پریمیم کو روکتا ہے اور کچھ بھی اضافی نہیں۔ یہ کورس میں سب سے صاف مارجن ہے۔ شارٹ پٹ اس کے برعکس ہے: یہ اس کے بارے میں جوڑتا ہے۔ <strong>165,042 روپے</strong>, تقریبا چھ گنا کریڈٹ، کیونکہ ایکسچینج کو ایک ننگے شارٹ پر کھلے منفی پہلو کا احاطہ کرنا ضروری ہے.</p>\n<p>یہ فرق واپسی کو دوبارہ ترتیب دیتا ہے۔ شارٹ پٹ 165,042 بلاک شدہ روپے پر 19,182 روپے کماتا ہے، اگر یہ کام کرتا ہے تو کیپیٹل پر تقریباً 12 فیصد، لیکن ایک دم کے ساتھ جو اس طرح کی کئی جیت کو ایک ساتھ مٹا سکتا ہے۔ لمبی کال اس کے پورے 27,677 روپے کو خطرے میں ڈالتی ہے لیکن اس سے زیادہ نہیں، اور ایک مضبوط ریلی اس سے کئی گنا زیادہ واپس آ سکتی ہے۔ ایک تجارت بڑے اقدام پر ایک چھوٹی شرط ہے، دوسری غیر معمولی تباہی کے ساتھ مستقل کرایہ۔</p>\n<h2 id=\"time-decay\">وقت کا زوال</h2>\n<p>کو دیکھو <strong>نیلی ڈیشڈ T+0 لائن</strong> جگہ کے قریب ٹھوس اورنج ایکسپائری لائن کے خلاف۔ لمبی کال کے لیے نیلی لکیر نارنجی لائن کے اوپر بیٹھتی ہے اور 28 جولائی کے قریب آتے ہی اس کی طرف ڈوب جاتی ہے۔ وہ گرتا ہوا خلا ہے۔ <strong>وقت کا زوال خریدار کو ختم کر رہا ہے۔</strong>: یہاں تک کہ اگر NIFTY ایک طرف بہتی ہے، کال ہر پرسکون دن کی قدر کرتی ہے، لہذا ایک طویل کال کو حقیقت میں اور معقول طور پر جلد ہونے کے لیے اقدام کی ضرورت ہے۔</p>\n<p>شارٹ کے لیے وہی کشی دوسری طرف چلتی ہے۔ وہاں نیلی T+0 لائن نارنجی شیلف کے نیچے بیٹھتی ہے اور دن گزرنے کے ساتھ ساتھ اس کی طرف بڑھ جاتی ہے، کیونکہ آپ نے جو پریمیم بیچا ہے وہ حقیقی منافع میں پگھل جاتا ہے۔ خریدار گھڑی سے لڑتا ہے۔ بیچنے والے کو اس سے ادائیگی کی جاتی ہے۔ یہ واحد فرق اس بات کا دل ہے کہ آخر کیوں بہت سارے تاجر اپنی طرف سے وقت کے بدلے دم کو قبول کرتے ہوئے خرید سے فروخت کی طرف بڑھتے ہیں۔</p>\n<h2 id=\"buyer-against-seller-both-bullish\">بیچنے والے کے خلاف خریدار، دونوں تیزی</h2>\n<p>دونوں تجارتوں کو ساتھ ساتھ رکھنا اس پورے کورس کا مرکزی سودا سکھاتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>لمبی کال</th>\n<th>شارٹ پٹ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>آپ ادائیگی کریں یا وصول کریں۔</td>\n<td>27,677 روپے ادا کریں۔</td>\n<td>19,182 روپے وصول کریں۔</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>27,677 روپے</td>\n<td>تقریباً 1,544,068 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>لا محدود</td>\n<td>19,182 روپے</td>\n</tr>\n<tr>\n<td>بریک ایون</td>\n<td>24,476</td>\n<td>23,755</td>\n</tr>\n<tr>\n<td>منافع کا امکان</td>\n<td>تقریبا 31 فیصد</td>\n<td>تقریبا 62 فیصد</td>\n</tr>\n<tr>\n<td>مارجن</td>\n<td>27,677 روپے</td>\n<td>165,042 روپے</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>آگے کی تقریباً ہر حکمت عملی ان دو جبلتوں کو ملا کر بنائی جاتی ہے۔ اگلے ابواب میں متعین خطرے کے پھیلاؤ ایک ہی وقت میں لمبی کال کی لاگت اور شارٹ پوٹ کی دم کو کم کرتے ہیں، دوسری ٹانگ جوڑ کر جو ایک کی ادائیگی کرتا ہے اور دوسرے کی حفاظت کرتا ہے۔ یہاں واحد ٹانگیں خام اجزاء ہیں۔</p>\n</div></div>\n<p>ایک ابتدائی کے لیے طے شدہ خطرے والی لمبی کال، یا اس سے بھی بہتر اسپریڈز بالکل آگے، شروع کرنے کے لیے محفوظ جگہ ہے۔ شارٹ پٹ کا بغور مطالعہ کرنے اور صرف منفی پہلو کے لیے پورے احترام کے ساتھ فروخت کرنے کے قابل ہے، اس کے ساتھ آگے نہیں۔</p>\n<h2 id=\"key-takeaways\">اہم نکات</h2>\n<ul>\n<li>اے <strong>لمبی کال</strong> ایک مقررہ پریمیم (27,677 روپے یہاں) ادا کرتا ہے جو کہ اس کا زیادہ سے زیادہ نقصان بھی ہے، اس کے بدلے میں 24,476 کے بریک ایون سے اوپر لامحدود اضافہ ہوتا ہے۔</li>\n<li>اے <strong>مختصر پوٹ</strong> اپنے زیادہ سے زیادہ منافع کے طور پر ایک فکسڈ کریڈٹ (19,182 روپے) اکٹھا کرتا ہے، لیکن 23,755 کے بریک ایون سے نیچے 1,544,068 روپے کی طرف بڑا نقصان اٹھاتا ہے، اور بھاری مارجن کا مطالبہ کرتا ہے۔</li>\n<li>لمبی کال میں کم مشکلات ہیں، تقریباً 31 فیصد، اور <strong>وقت کا زوال اس کے خلاف کام کرتا ہے۔</strong>. شارٹ پٹ میں زیادہ مشکلات ہیں، تقریباً 62 فیصد، اور <strong>وقت کا زوال اس کے لیے کام کرتا ہے۔</strong>.</li>\n<li>لمبی کال ہے۔ <strong>مارجن اس کے ڈیبٹ کے برابر ہے۔</strong>، کورس میں سب سے صاف۔ شارٹ پٹ ایک ننگے نیچے کے لئے تقریباً 165,042 روپے کا بنتا ہے۔</li>\n<li>ہر پڑھیں <strong>POP اس کے زیادہ سے زیادہ نقصان کے ساتھ</strong>: بھاری دم کے ساتھ زیادہ مشکلات اور چھوٹے خطرے کے ساتھ کم مشکلات ایک ہی قسم کی شرط نہیں ہیں۔</li>\n<li>خریدار ایک بڑی جیت کے موقع کے لیے ادائیگی کرتے ہیں جسے وہ شاذ و نادر ہی حاصل کرتے ہیں۔ بیچنے والے اکثر چھوٹی جیت اور ایک غیر معمولی بڑا نقصان اٹھاتے ہیں۔ نہ ہی غلط ہے، لیکن شروع کی وضاحت کی گئی ہے۔</li>\n</ul>\n","toc":[{"level":2,"text":"ایک لائن کا خیال","id":"the-one-line-idea"},{"level":2,"text":"لمبی کال، روپیہ بہ روپیہ","id":"the-long-call-rupee-by-rupee"},{"level":2,"text":"لمبی کال کے تین نمبر","id":"the-long-call-s-three-numbers"},{"level":2,"text":"ایکسپائر ہونے کے لیے لمبی کال چلنا","id":"walking-the-long-call-to-expiry"},{"level":2,"text":"شارٹ پٹ، روپیہ بہ روپیہ","id":"the-short-put-rupee-by-rupee"},{"level":2,"text":"شارٹ پٹ کے تین نمبر","id":"the-short-put-s-three-numbers"},{"level":2,"text":"ایکسپائری کے لیے شارٹ پٹ پر چلنا","id":"walking-the-short-put-to-expiry"},{"level":2,"text":"آپ کی مشکلات","id":"your-odds"},{"level":2,"text":"مارجن اور واپسی","id":"margin-and-return"},{"level":2,"text":"وقت کا زوال","id":"time-decay"},{"level":2,"text":"بیچنے والے کے خلاف خریدار، دونوں تیزی","id":"buyer-against-seller-both-bullish"},{"level":2,"text":"اہم نکات","id":"key-takeaways"}],"imgCount":2,"hasContent":true},"4":{"html":"<p>آخری باب کی لمبی کال میں مسئلہ تھا۔ 24,050 کال خریدنے کے لیے آپ نے تقریباً 27,677 روپے ادا کیے، اور NIFTY کو ایک روپیہ کمانے سے پہلے 24,476 تک پہنچنا پڑا، وہاں پہنچنے کے تین میں سے صرف ایک موقع کے ساتھ۔ یہ بہت کچھ ادا کرنا ہے، اور سفر کرنے کا ایک طویل راستہ ہے، اس نقطہ نظر کے لیے جو شاید ہلکی سی تیزی کا ہو۔ اگر آپ کو راکٹ دور کرنے کے بجائے NIFTY 24,150 کی طرف بڑھنے کی توقع ہے، تو اس رائے کو درست کرنے کا ایک سستا، بہتر طریقہ ہے۔ آپ نے جو خریدا ہے اس کے مقابلے میں آپ ایک اعلی کال فروخت کرتے ہیں، اور مارکیٹ کو اپنی زیادہ تر شرط کو فنڈ دینے دیتے ہیں۔ یہ ہے <strong>بیل کال پھیل گئی</strong>, پہلی حقیقی دو ٹانگوں والی حکمت عملی ہر آپشن کے تاجر کو سیکھنی چاہیے، اور متعین خطرے کی سب سے صاف مثال موجود ہے۔ تمام اعداد و شمار 26 جون 2026، اسپاٹ 24,056، لاٹ 65، 28 جولائی 2026 کی میعاد ختم ہونے میں تقریباً 32 دن بعد حاصل کیے گئے حقیقی NIFTY ڈیٹا کا استعمال کرتے ہیں۔</p>\n<h2 id=\"the-one-line-idea\">ایک لائن کا خیال</h2>\n<p>اے <strong>بیل کال پھیل گئی</strong> ایک ہی میعاد ختم ہونے پر دو کالیں ہیں۔ آپ <strong>لوئر سٹرائیک کال خریدیں۔</strong> عروج پر قبضہ کرنے کے لیے، اور آپ <strong>ایک اعلی ہڑتال کال فروخت</strong> پریمیم واپس لانے کے لیے۔ فروخت شدہ کال سے جو نقد آپ جمع کرتے ہیں وہ خریدی ہوئی کال کی زیادہ تر قیمت ادا کرتا ہے، اس لیے پوری پوزیشن پر تنہا کال کا ایک حصہ خرچ ہوتا ہے۔ وہ چھوٹی لاگت، <strong>خالص ڈیبٹ</strong>، یہ بھی سب سے زیادہ ہے جسے آپ کبھی کھو سکتے ہیں۔</p>\n<p>آپ اسے استعمال کرتے ہیں جب آپ کا نقطہ نظر ہے <strong>اعتدال پسند تیزی</strong>: آپ توقع کرتے ہیں کہ NIFTY ایک سطح کی طرف بڑھے گا، اس سے بہت دور نہیں جائے گا۔ آپ بہت کم قیمت ادا کرنے کے بدلے میں لامحدود اوپری کے خواب کو دور کرتے ہیں اور ایک بہت چھوٹی حرکت پر بھی ٹوٹ جاتے ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>بیل کال اسپریڈ کم کال خریدتا ہے اور خالص ڈیبٹ کے لیے زیادہ کال فروخت کرتا ہے۔ فروخت شدہ کال زیادہ تر خریدی ہوئی کال کو فنڈ دیتی ہے، اس لیے تجارت پر بہت کم لاگت آتی ہے۔ وہ خالص ڈیبٹ، یہاں 3,624 روپے، آپ کی کل لاگت اور آپ کا زیادہ سے زیادہ نقصان دونوں ہے۔ آپ کبھی بھی اس سے زیادہ نہیں کھو سکتے ہیں جو آپ ڈالتے ہیں، اور آپ ایک تنہا کال کی ضرورت سے کہیں زیادہ چھوٹے اقدام پر منافع تک پہنچ جاتے ہیں۔</p>\n</div></div>\n<h2 id=\"the-real-trade-rupee-by-rupee\">اصل تجارت، روپیہ بہ روپیہ</h2>\n<p>یہاں حقیقی NIFTY قیمتوں پر درست تجارت ہے، انڈیکس 24,056 پر ہے۔ ہم ایٹ دی منی 24,050 کال خریدتے ہیں اور 24,150 کال کو ایک سٹرائیک زیادہ فروخت کرتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>کال خریدیں۔</td>\n<td>24,050</td>\n<td>425.8 ادا کیا گیا۔</td>\n<td>27,677 روپے باہر</td>\n</tr>\n<tr>\n<td>2</td>\n<td>کال فروخت کریں۔</td>\n<td>24,150</td>\n<td>370.1 موصول ہوا۔</td>\n<td>علاوہ 24,053 روپے میں</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>خالص ڈیبٹ</strong></td>\n<td><strong>3,624 روپے باہر</strong></td>\n</tr>\n</tbody></table>\n<p>تنہا کال کے لیے آپ پر 27,677 روپے واجب الادا ہیں۔ فروخت شدہ 24,150 کال اس میں سے تقریباً 24,053 روپے کی واپسی کرتی ہے، اس لیے آپ کا حقیقی خرچ کم ہو کر ایک ہو جاتا ہے۔ <strong>3,624 روپے کا خالص ڈیبٹ</strong> ایک بہت کے لئے. چونکہ آپ نے وہ رقم پیشگی ادا کر دی ہے اور اس سے زیادہ کے لیے کبھی نہیں کہا جا سکتا ہے، اس لیے خالص ڈیبٹ بھی سب سے زیادہ ہے جسے آپ کھو سکتے ہیں۔ یہی وجہ ہے کہ بیل کال پھیل جاتی ہے۔ <strong>طے شدہ خطرہ</strong> تجارت</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bull-call-spread.png\" alt=\"NIFTY بل کال پھیل گئی، 24,050 کال خریدی اور 24,150 کال فروخت کی۔ اورنج ایٹ ایکسپائری لائن 24,050 سے نیچے 3,624 روپے کے فلیٹ نقصان کے فلور پر ہے، 24,106 کے بریک ایون پر صفر کو عبور کرتی ہے، اور 24,150 کے اوپر 2,876 روپے کے محدود منافع پر چپٹی ہے۔ نیلے رنگ کے ڈیشڈ T+0 لائن اس کے بالکل اوپر جگہ کے قریب بیٹھتی ہے، وقت گزرنے کے ساتھ ساتھ بیٹھ جاتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY بل کال پھیل گئی، 24,050 کال خریدی اور 24,150 کال فروخت کی۔ اورنج ایٹ ایکسپائری لائن 24,050 سے نیچے 3,624 روپے کے فلیٹ نقصان کے فلور پر ہے، 24,106 کے بریک ایون پر صفر کو عبور کرتی ہے، اور 24,150 کے اوپر 2,876 روپے کے محدود منافع پر چپٹی ہے۔ نیلے رنگ کے ڈیشڈ T+0 لائن اس کے بالکل اوپر جگہ کے قریب بیٹھتی ہے، وقت گزرنے کے ساتھ ساتھ بیٹھ جاتی ہے۔</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">تین نمبر، اور وہ کہاں سے آتے ہیں۔</h2>\n<p>ہر بیل کال اسپریڈ کو تین نمبروں سے بیان کیا جاتا ہے، اور ہر ایک براہ راست اوپر کی تجارت سے باہر آتا ہے۔</p>\n<p><strong>زیادہ سے زیادہ نقصان خالص ڈیبٹ ہے، 3,624 روپے۔</strong> اگر NIFTY 24,050 پر یا اس سے نیچے بند ہو جاتا ہے، تو دونوں کالیں بیکار ختم ہو جاتی ہیں اور آپ کا پورا خرچ ختم ہو جاتا ہے۔ یہ چارٹ کے بائیں جانب فلیٹ فلور ہے۔</p>\n<p><strong>زیادہ سے زیادہ منافع سٹرائیک چوڑائی مائنس ڈیبٹ، 2,876 روپے ہے۔</strong> ہڑتالوں کے درمیان فرق 100 پوائنٹس ہے، جس کی قیمت 100 گنا 65، یا 6,500 روپے ہے۔ ایک بار جب NIFTY 24,150 پر یا اس سے اوپر بند ہوتا ہے، خریدی گئی کال کو پورے 100 پوائنٹس حاصل ہوتے ہیں جب کہ فروخت شدہ کال اس سے آگے کی کوئی بھی چیز منسوخ کر دیتی ہے، اس لیے آپ اس 6,500 روپے کو کم رکھیں جو آپ نے 3,624 روپے ادا کیا، جو کہ 2,876 روپے ہے۔</p>\n<p><strong>Breakeven کم سٹرائیک کے علاوہ ڈیبٹ فی شیئر، 24,106 ہے۔</strong> آپ نے فی شیئر خالص ڈیبٹ کے 55.75 پوائنٹس کی ادائیگی کی، لہذا منافع میں جانے سے پہلے NIFTY کو خریدی گئی اسٹرائیک سے بہت اوپر جانا چاہیے۔ یہ 24,050 پلس 55.75، یا 24,106 پر اترتا ہے، جو لون کال کے 24،476 سے کہیں زیادہ قریب ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>خالص ڈیبٹ</td>\n<td>3,624 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>اسٹرائیک چوڑائی مائنس خالص ڈیبٹ</td>\n<td>6,500 روپے مائنس 3,624 روپے 2,876 روپے کے برابر ہے۔</td>\n</tr>\n<tr>\n<td>بریک ایون</td>\n<td>کم ہڑتال پلس ڈیبٹ فی شیئر</td>\n<td>24,050 جمع 55.75 برابر 24,106</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>زیادہ سے زیادہ منافع 2,876 روپے اور زیادہ سے زیادہ نقصان 3,624 روپے ہمیشہ 6,500 روپے کی مکمل اسٹرائیک چوڑائی میں اضافہ کرتے ہیں۔ پھیلاؤ آسانی سے اس چوڑائی کو آپ اور مارکیٹ کے درمیان تقسیم کرتا ہے۔ سٹرائیکس کو منتقل کریں اور دو نمبر تبدیل ہو جائیں، لیکن ان کا مجموعہ چوڑائی پر ہی رہتا ہے۔</p>\n</div></div>\n<h2 id=\"walking-the-outcomes-at-expiry\">میعاد ختم ہونے پر نتائج پر چلنا</h2>\n<p>مٹھی بھر بند قیمتوں پر پھیلاؤ کو طے کریں اور شکل ظاہر ہوتی ہے۔ خریدی گئی کال کی قیمت زیادہ سے زیادہ ہے (NIFTYمائنس 24,050, 0) فروخت شدہ کال کی قیمت زیادہ سے زیادہ ہے ( NIFTY مائنس 24,150, 0) آپ کا منافع خریدی ہوئی قیمت مائنس بیچی ہوئی قیمت، 65 گنا، 3,624 روپے ڈیبٹ سے کم ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>24,050 کال آپ نے خریدی۔</th>\n<th>24,150 کال آپ نے فروخت کی۔</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,900</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مائنس 3,624 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مائنس 3,624 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>24,106</td>\n<td>مالیت 56</td>\n<td>مالیت 0</td>\n<td>تقریباً 0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>24,150</td>\n<td>100 کی مالیت</td>\n<td>مالیت 0</td>\n<td>جمع 2,876 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,300</td>\n<td>مالیت 250</td>\n<td>150 کی مالیت</td>\n<td>جمع 2,876 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n</tbody></table>\n<p>ٹیبل کو پڑھیں اور تجارت خود ہی وضاحت کرتی ہے۔ کہیں بھی 24,050 پر یا اس سے نیچے آپ مکمل 3,624 روپے کھو دیتے ہیں۔ 24,150 یا اس سے اوپر کہیں بھی آپ پورے 2,876 روپے رکھیں۔ سٹرائیکس کے درمیان نتیجہ 24,106 پر صفر سے گزر کر ایک شیلف سے دوسرے شیلف میں پھسل جاتا ہے۔ نیچے کی قطار پر توجہ دیں: 24,300 پر خریدی گئی کال کی قیمت 250 ہے اور فروخت شدہ کال کی قیمت 150 ہے، خالص 100 پوائنٹس، وہی 6,500 روپے کی چوڑائی، اس لیے منافع کی حد ہوتی ہے اس سے کوئی فرق نہیں پڑتا ہے کہNIFTYکتنی ہی زیادہ چلتی ہے۔</p>\n<h2 id=\"your-odds\">آپ کی مشکلات</h2>\n<p>زیادہ سے زیادہ جاننا کہ آپ جیت سکتے ہیں اور ہار سکتے ہیں آدھی کہانی ہے۔ دوسرا نصف ہے <strong>منافع کا امکان</strong>, مارکیٹ میں مضمر موقع تجارت کے ختم ہونے کا سبز رنگ۔</p>\n<p>اس کے لیے پھیلاؤ <strong>POP تقریباً 47 فیصد ہے۔</strong>. 24,106 کا بریک ایون چارٹ پر موجود پلس ون سگما بینڈ کے بالکل اندر بیٹھتا ہے، آپشن مارکیٹ کی قیمتوں کا تعین کیا جاتا ہے، اس لیے NIFTY کو ادائیگی کے لیے صرف ایک چھوٹا سا دھکا دینے کی ضرورت ہے۔ یہ لون کال کے 31 فیصد سے کہیں زیادہ صحت مند ہے، کیونکہ بریک ایون کو 24,476 سے کم کر کے 24,106 کرنے کا مطلب ہے کہ بہت چھوٹا اقدام جیت کے طور پر شمار ہوتا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>انعام کے خطرے کے آگے POP پڑھیں، یہاں 1 سے 0.79۔ آپ 2,876 روپے کمانے کے لیے 3,624 روپے کا خطرہ مول لیتے ہیں، جو کہ پیسے سے بھی تھوڑا کم ہے، لیکن آپ تقریباً نصف وقت اور صرف ایک چھوٹی سی حرکت پر جیت جاتے ہیں۔ اکیلی کال ایک بڑی رن پر زیادہ ادائیگی کرتی ہے، پھر بھی یہ بہت کم منافع میں جاتی ہے۔ اسپریڈ مادی طور پر بہتر مشکلات کے لیے اوپر کا ایک ٹکڑا تجارت کرتا ہے۔</p>\n</div></div>\n<h2 id=\"margin\">مارجن</h2>\n<p>یہاں بلڈر بلاکس کے مارجن کے بارے میں ہے۔ <strong>35,378 روپے</strong>3,624 روپے سے بڑا جو آپ اصل میں کھو سکتے ہیں۔ یہ اس وقت تک عجیب لگتا ہے جب تک کہ آپ کو یاد نہ ہو کہ ایکسچینج فروخت شدہ کال لیگ پر ایکسپوزر رقم وصول کرتا ہے، حالانکہ خریدی گئی کال اسے مکمل طور پر کیپ کرتی ہے۔ واقعی خطرے میں موجود نقدی اب بھی صرف خالص ڈیبٹ ہے، لیکن تجارت کے کھلے ہونے کے دوران بڑی رقم کو الگ کرنے کے لیے تیار رہیں۔</p>\n<p>یہ مارجن آپ کو اس کے ذریعہ تجارت کا فیصلہ کرنے دیتا ہے۔ <strong>مارجن پر واپسی</strong>تقریباً ایک ماہ کے لیے بلاک شدہ 35,378 روپے کے مقابلے میں 2,876 روپے کا منافع تقریباً ہے۔ <strong>8 فیصد</strong> اگر یہ کام کرتا ہے. تمام خیالات کا موازنہ کرنے کے لیے یہی اصل پیداوار ہے، نہ کہ خام منافع کا اعداد و شمار۔</p>\n<h2 id=\"time-decay\">وقت کا زوال</h2>\n<p>کو دیکھو <strong>نیلی ڈیشڈ T+0 لائن</strong> جگہ کے قریب ٹھوس اورنج ایکسپائری لائن کے خلاف۔ وہ ایک دوسرے کے قریب بیٹھتے ہیں، کیونکہ اسپریڈ میں کسی ایک آپشن سے کہیں کم خام وقت کی قیمت ہوتی ہے: آپ کی خریدی ہوئی کال سے نکلنے والی ویلیو کو آپ کی بیچی ہوئی کال سے نکلنے والی ویلیو سے کافی حد تک پورا کیا جاتا ہے۔ ایک بیل کال اسپریڈ ہے a <strong>ڈیبٹ</strong> تجارت، تو توازن کا وقت آپ کے خلاف نرمی سے کام کرتا ہے، لیکن مستحکم ڈرین جیسی کوئی چیز تنہا کال کا شکار نہیں ہوتی۔ پوزیشن گھڑی کے مقابلے میں سمت کی زیادہ پرواہ کرتی ہے۔</p>\n<h2 id=\"choosing-your-strikes\">اپنی ہڑتالوں کا انتخاب کرنا</h2>\n<p>100 نکاتی پھیلاؤ بہت سے لوگوں کے درمیان ایک انتخاب ہے۔ اسٹرائیک کو اسپاٹ کے قریب بیچیں اور آپ زیادہ پریمیم اکٹھا کرتے ہیں، لاگت اور بریک ایون کو کم کرتے ہیں بلکہ منافع کو جلد ختم کرتے ہیں۔ اسٹرائیک کو مزید فروخت کریں اور اگر اقدام بڑا ہے تو آپ زیادہ سے زیادہ منافع کے بدلے، بریک ایون کو بڑھاتے ہوئے زیادہ ادائیگی کرتے ہیں۔ انگوٹھے کا اصول سادہ ہے۔</p>\n<p>اپنی فروخت کردہ اسٹرائیک کو اس قیمت پر چنیں جس کی آپ حقیقی طور پر توقع کرتے ہیں کہ NIFTY تک پہنچنے کی، یہاں 24,150، امید میں زیادہ نہیں۔ زیادہ سے زیادہ منافع اس سٹرائیک پر بیٹھتا ہے، اس لیے ایک NIFTY کو فروخت کرنے سے چھونے کا امکان نہیں ہے، صرف پریمیم کو پھینک دیتا ہے اور آپ کی لاگت کو بغیر کسی قیمت کے بڑھاتا ہے، جبکہ ایک بہت قریب فروخت کرنے سے اس اقدام سے پہلے ہی فائدہ ہوتا ہے۔</p>\n<h2 id=\"bull-call-spread-or-bull-put-spread\">بیل کال اسپریڈ یا بیل ڈال اسپریڈ؟</h2>\n<p>اگلا باب تعمیر کرتا ہے۔ <strong>بیل ڈال پھیل گیا</strong>، جو قریب قریب ایک جیسی ادائیگی کی شکل کے ساتھ ایک ہی اعتدال پسند تیزی کے نقطہ نظر کا اظہار کرتا ہے۔ تو آپ کون سا چنتے ہیں؟ یہ اس بات پر منحصر ہے کہ مارکیٹ آپ کو کیا ادا کر رہی ہے۔</p>\n<ul>\n<li>دی <strong>بیل کال پھیل گئی</strong> ایک ہے <strong>ڈیبٹ</strong> تجارت آپ پیشگی ادائیگی کرتے ہیں اور صحیح ہونے کی امید کرتے ہیں۔ جب NIFTY بڑھتا ہے تو آپ کو فائدہ ہوتا ہے۔</li>\n<li>دی <strong>بیل ڈال پھیل گیا</strong> ایک ہے <strong>کریڈٹ</strong> تجارت آپ کو پہلے سے ادائیگی کی جاتی ہے اور امید ہے کہ آپ کو تنہا چھوڑ دیا جائے گا۔ آپ کو اس وقت فائدہ ہوتا ہے جب NIFTY صرف گرتا ہی نہیں ہے۔</li>\n</ul>\n<p>جب مارکیٹیں گر گئی ہیں اور خوف نے پوٹ پریمیم کو موٹا کر دیا ہے، اس مہنگی انشورنس کو بیل پوٹ اسپریڈ کے ذریعے بیچنا زیادہ امیر سودا ہے۔ جب پریمیم سستے ہوں اور مارکیٹ پرسکون ہو، بیل کال اسپریڈ خریدنا بہتر قیمت ہو سکتی ہے۔ وہ ایک ہی پہاڑی کے دو راستے ہیں۔ کریڈٹ ورژن وقت کی کمی کو آپ کی طرف رکھتا ہے، ڈیبٹ ورژن مارکیٹ سے آپ کے راستے کو منتقل کرنے کے لئے کہتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>متعین خطرے کا مطلب چھوٹا خطرہ نہیں ہے۔ 3,624 روپے فی لاٹ اصلی رقم ہے، اور اگر آپ NIFTY ختم ہونے پر 24,050 پر یا اس سے نیچے بند ہو جاتا ہے تو آپ یہ سب کھو دیتے ہیں، جو آج کل 24,056 کے قریب بیٹھا ہوا انڈیکس کے ساتھ مکمل طور پر ممکن ہے۔ ہمیشہ زیادہ سے زیادہ نقصان کے حساب سے سائز کریں، زیادہ سے زیادہ منافع سے کبھی نہیں، اور یاد رکھیں کہ اس دوران بڑا مارجن جڑا رہتا ہے۔ دو لاٹ رسک 7,248 روپے، تین رسک 10,872 روپے، وغیرہ۔</p>\n</div></div>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>بغیر کسی خطرے کے پیسے کے اس کی مشق کریں۔ OpenAlgo اسٹریٹجی بلڈر کو کھولیں، NIFTY پر بل کال اسپریڈ ٹیمپلیٹ کو چنیں، اور فروخت شدہ اسٹرائیک کو سلائیڈ کرتے وقت نو میٹرک پینل اپ ڈیٹ دیکھیں۔ نیٹ ڈیبٹ اور بریک ایون کو ایک ساتھ دیکھیں، پھر سینڈ باکس ٹریڈنگ میں پوری تجارت کی تصدیق کریں ( OpenAlgo میں تجزیہ کار وضع) اس سے پہلے کہ آپ اسے کبھی بھی فنڈ دیں۔ انہی نمبروں کو دیکھ کر جو اس باب کا حوالہ دیا گیا ہے آپ کے اپنے ہاتھوں سے ظاہر ہوتا ہے جو ایک ترکیب کو سمجھنے میں بدل جاتا ہے۔</p>\n</div></div>\n<h2 id=\"key-takeaways\">اہم نکات</h2>\n<ul>\n<li>اے <strong>بیل کال پھیل گئی</strong> کم کال خریدتا ہے اور خالص ڈیبٹ کے لیے زیادہ کال فروخت کرتا ہے، جب NIFTY اوپری ہڑتال کی طرف بڑھتا ہے تو منافع ہوتا ہے۔</li>\n<li><strong>زیادہ سے زیادہ نقصان خالص ڈیبٹ ہے۔</strong> (یہاں 3,624 روپے) <strong>زیادہ سے زیادہ منافع اسٹرائیک کی چوڑائی مائنس ڈیبٹ ہے۔</strong> (2,876 روپے)، اور دونوں ہمیشہ 6,500 روپے کی پوری چوڑائی کے برابر ہوتے ہیں۔</li>\n<li><strong>Breakeven کم سٹرائیک کے علاوہ ڈیبٹ فی شیئر ہے۔</strong> (24,106)، لون کال کے 24,476 سے کہیں زیادہ قریب ہے، لہذا آپ کو بہت چھوٹی حرکت پر فائدہ ہوگا۔</li>\n<li>تنہا کال سے بہتر مشکلات، کے بارے میں <strong>47 فیصد بمقابلہ 31 فیصد</strong>، فروخت شدہ ہڑتال کے اوپر لامحدود الٹا دینے کے بدلے میں۔</li>\n<li>یہ بلاک کرتا ہے۔ <strong>35,378 روپے</strong> مارجن اور واپسی کا تقریباً <strong>8 فیصد</strong> اس سرمائے پر اگر یہ کام کرتا ہے۔ زیادہ سے زیادہ نقصان کے حساب سے سائز، زیادہ سے زیادہ منافع نہیں۔</li>\n<li>اس پر ترجیح دیں۔ <strong>بیل ڈال پھیل گیا</strong> جب پریمیم سستے ہوتے ہیں اور مارکیٹ پرسکون ہوتی ہے، تو اس اقدام کو خریدنا اسے بیچنے سے بہتر قیمت ہے۔</li>\n</ul>\n","toc":[{"level":2,"text":"ایک لائن کا خیال","id":"the-one-line-idea"},{"level":2,"text":"اصل تجارت، روپیہ بہ روپیہ","id":"the-real-trade-rupee-by-rupee"},{"level":2,"text":"تین نمبر، اور وہ کہاں سے آتے ہیں۔","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"میعاد ختم ہونے پر نتائج پر چلنا","id":"walking-the-outcomes-at-expiry"},{"level":2,"text":"آپ کی مشکلات","id":"your-odds"},{"level":2,"text":"مارجن","id":"margin"},{"level":2,"text":"وقت کا زوال","id":"time-decay"},{"level":2,"text":"اپنی ہڑتالوں کا انتخاب کرنا","id":"choosing-your-strikes"},{"level":2,"text":"بیل کال اسپریڈ یا بیل ڈال اسپریڈ؟","id":"bull-call-spread-or-bull-put-spread"},{"level":2,"text":"اہم نکات","id":"key-takeaways"}],"imgCount":1,"hasContent":true},"5":{"html":"<p>زیادہ تر ابتدائی افراد لاٹری ٹکٹ کے طور پر اختیارات سے ملتے ہیں۔ آپ ایک چھوٹا پریمیم ادا کرتے ہیں، آپ بڑے اقدام کے لیے دعا کرتے ہیں، اور زیادہ تر دنوں میں ٹکٹ کی میعاد ختم ہوجاتی ہے۔ بیل نے اس اسکرپٹ کو پوری طرح سے پلٹا دیا۔ یہاں آپ وہ ہیں جو ٹکٹ بیچ رہے ہیں، پریمیم جمع کر رہے ہیں، اور اسے خاموشی سے اس وقت تک رکھتے ہیں جب تک کہ NIFTY گر نہ جائے۔ آپ ریلی پر شرط نہیں لگا رہے ہیں۔ آپ کریش کے خلاف شرط لگا رہے ہیں، جو جیتنے کے لیے بہت مختلف اور اکثر آسان شرط ہے۔ یہ باب حقیقی NIFTY قیمتوں پر تجارت کی تشکیل کرتا ہے، آپ کو ظاہر کرتا ہے کہ ہر روپیہ کہاں سے آتا ہے، اور آپ کو وہ تین جہتیں فراہم کرتا ہے جنہیں زیادہ تر وضاحت کرنے والے چھوڑ دیتے ہیں: مشکلات، مارجن، اور وقت خود آپ کے حق میں کام کرنے کا طریقہ۔</p>\n<h2 id=\"the-one-line-idea\">ایک لائن کا خیال</h2>\n<p>اے <strong>بیل ڈال پھیل گیا</strong> ایک ہی ایکسپائری پر دو پوٹ آپشنز ہیں۔ آپ <strong>ایک اعلی ہڑتال ڈال فروخت</strong> ایک چربی پریمیم جمع کرنے کے لئے، اور آپ <strong>لوئر سٹرائیک پوٹ خریدیں۔</strong> ایک حقیقی حادثے کے خلاف سستی انشورنس کے طور پر. آپ فرق کو ایک کے طور پر رکھیں <strong>خالص کریڈٹ</strong>اور یہ کریڈٹ سب سے زیادہ ہے جو آپ بنا سکتے ہیں۔ چونکہ خریدا ہوا پوٹ آپ کے منفی پہلو کو ختم کر دیتا ہے، اس لیے آپ جو زیادہ سے زیادہ کھو سکتے ہیں وہ بٹن پر کلک کرنے سے پہلے ہی طے شدہ اور جانا جاتا ہے۔</p>\n<p>آپ اسے استعمال کرتے ہیں جب آپ کا نقطہ نظر ہے <strong>اعتدال پسند تیزی</strong>، یعنی آپ کو لگتا ہے کہ NIFTY اٹھے گا، فلیٹ رہے گا، یا بدترین طور پر صرف تھوڑا سا گرے گا۔ آپ کو ریلی کی ضرورت نہیں ہے۔ سخت گرنے سے بچنے کے لیے آپ کو صرف NIFTY کی ضرورت ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>بیل پوٹ اسپریڈ زیادہ پوٹ بیچتا ہے اور خالص کریڈٹ کے لیے کم پوٹ خریدتا ہے۔ آپ کو فائدہ ہوتا ہے اگر NIFTY آپ کی اونچی سٹرائیک سے اوپر رہتا ہے، آپ کو نقصان صرف اس صورت میں ہوتا ہے جب یہ آپ کی نچلی سٹرائیک سے نیچے آتا ہے، اور نفع اور نقصان دونوں کی حد ہوتی ہے۔ یہ شرط ہے کہ مارکیٹ کریش نہیں ہوگی، یہ شرط نہیں ہے کہ یہ بڑھ جائے گا۔</p>\n</div></div>\n<h2 id=\"the-real-trade-rupee-by-rupee\">اصل تجارت، روپیہ بہ روپیہ</h2>\n<p>26 جون 2026 کو انڈیکس کے ساتھ حاصل کی گئی حقیقی NIFTY قیمتوں پر درست تجارت یہ ہے۔ <strong>24,056</strong> اور 28 جولائی 2026 کو ختم ہونے میں تقریباً 32 دن باقی ہیں۔ ہم 24,050 پوٹ پر پیسے بیچتے ہیں اور نیچے 23,950 پوٹ ون سٹرائیک خریدتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>ڈال فروخت</td>\n<td>24,050</td>\n<td>295 موصول ہوئے۔</td>\n<td>علاوہ 19,175 روپے میں</td>\n</tr>\n<tr>\n<td>2</td>\n<td>ڈال خریدیں</td>\n<td>23,950</td>\n<td>257 ادا کیے۔</td>\n<td>16,669 روپے باہر</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>نیٹ کریڈٹ</strong></td>\n<td><strong>علاوہ 2,506 روپے میں</strong></td>\n</tr>\n</tbody></table>\n<p>24,050 پوٹ کے لیے جو پریمیم آپ وصول کرتے ہیں وہ اس پریمیم سے بڑا ہے جو آپ 23,950 پٹ کے لیے ادا کرتے ہیں، کیونکہ زیادہ ہڑتال کی قیمت زیادہ ہے۔ وہ خلا آپ کا ہے۔ <strong>2,506 روپے کا خالص کریڈٹ</strong>اور جب آپ تجارت کھولتے ہیں تو یہ آپ کے اکاؤنٹ میں آتا ہے۔ اسی لیے بیل ڈال اسپریڈ کو کہا جاتا ہے۔ <strong>کریڈٹ پھیلاؤ</strong>.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bull-put-spread.png\" alt=\"اصلی NIFTY بیل اسپریڈ: 24,050 سے اوپر 2,506 روپے کا فلیٹ پرافٹ شیلف، 23,950 سے نیچے 3,994 روپے کا فلیٹ نقصان کا شیلف، 24,011 پر سنگل بریک ایون، اور اورنج ایٹ-ایکسپائری لائن اسپاٹ کے بالکل نیچے منافع میں داخل ہوتی ہے۔ نیلی ڈیشڈ لائن آج ہے، اورنج لائن کے اوپر بیٹھی ہے کیونکہ وقت نے ابھی تک اپنا کام نہیں کیا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>اصلی NIFTY بیل اسپریڈ: 24,050 سے اوپر 2,506 روپے کا فلیٹ پرافٹ شیلف، 23,950 سے نیچے 3,994 روپے کا فلیٹ نقصان کا شیلف، 24,011 پر سنگل بریک ایون، اور اورنج ایٹ-ایکسپائری لائن اسپاٹ کے بالکل نیچے منافع میں داخل ہوتی ہے۔ نیلی ڈیشڈ لائن آج ہے، اورنج لائن کے اوپر بیٹھی ہے کیونکہ وقت نے ابھی تک اپنا کام نہیں کیا ہے۔</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">تین نمبر، اور وہ کہاں سے آتے ہیں۔</h2>\n<p>ہر بیل پوٹ اسپریڈ کو تین نمبروں سے بیان کیا جاتا ہے، اور ہر ایک اوپر کی تجارت سے سیدھا باہر آتا ہے۔ ایک بار جب آپ منطق کو دیکھیں گے تو حفظ کرنے کی ضرورت نہیں ہے۔</p>\n<p><strong>زیادہ سے زیادہ منافع خالص کریڈٹ ہے، 2,506 روپے۔</strong> اگر NIFTY 24,050 اسٹرائیک پر یا اس سے اوپر کہیں بھی ختم ہوجاتا ہے، تو دونوں پوٹس بیکار ختم ہوجاتے ہیں۔ جب انڈیکس سٹرائیک سے اوپر ہوتا ہے تو کوئی بھی پٹ کی مشق نہیں کرتا۔ آپ پر کچھ واجب الادا نہیں ہے، آپ پورا کریڈٹ اپنے پاس رکھتے ہیں، اور یہ سب سے بہتر ہے جو تجارت کر سکتی ہے۔</p>\n<p><strong>زیادہ سے زیادہ نقصان اسپریڈ مائنس کریڈٹ، 3,994 روپے ہے۔</strong> اسپریڈ دو سٹرائیکس کے درمیان فرق ہے، 100 پوائنٹس، مالیت کا 100 گنا 65، جو کہ 6,500 روپے ہے۔ اگر NIFTY 23,950 سے نیچے گر جاتا ہے، تو دونوں پوٹس پیسے میں گہرے ہیں اور ان کے درمیان مکمل 100 پوائنٹ کا فرق آپ کے خلاف بند ہے۔ آپ وہ 6,500 روپے کھو دیتے ہیں، لیکن آپ پہلے ہی 2,506 روپے جیب میں ڈال چکے ہیں، لہذا آپ کا اصل نقصان 6,500 مائنس 2,506 ہے، جو <strong>3,994 روپے</strong>. خریدا ہوا پوٹ وہی ہے جو اس سے پہلے بڑھتے ہوئے نقصان کو روکتا ہے۔ اس کے بغیر آپ لاکھوں کی کمی کا سامنا کرنے والے ننگے بیچنے والے ہوں گے۔</p>\n<p><strong>Breakeven زیادہ سٹرائیک مائنس کریڈٹ فی شیئر، 24,011 ہے۔</strong> آپ نے فی شیئر 38.55 پوائنٹس کریڈٹ اکٹھا کیا۔ NIFTY 24,050 سٹرائیک سے 38.55 پوائنٹ نیچے جا سکتا ہے، <strong>24,011</strong>اس سے پہلے کہ آپ کے شارٹ پٹ پر ہونے والا نقصان پورا کریڈٹ کھا جائے۔ 24,011 سے اوپر آپ منافع میں ختم کرتے ہیں۔ اس کے نیچے آپ نقصان میں ختم کرتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>خالص کریڈٹ</td>\n<td>2,506 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>پھیلاؤ مائنس نیٹ کریڈٹ</td>\n<td>6,500 روپے مائنس 2,506 روپے = 3,994 روپے</td>\n</tr>\n<tr>\n<td>بریک ایون</td>\n<td>زیادہ ہڑتال مائنس کریڈٹ فی شیئر</td>\n<td>24,050 منفی 38.55 = 24,011</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-outcomes-at-expiry\">میعاد ختم ہونے پر نتائج پر چلنا</h2>\n<p>کسی حکمت عملی پر بھروسہ کرنے کا سب سے صاف طریقہ یہ ہے کہ اسے مٹھی بھر بند قیمتوں پر طے کریں اور رقم کو دیکھیں۔ یہاں ایکسپائری ڈے پر NIFTY کی پانچ سطحوں پر بیل پوٹ اسپریڈ ہے، فی لاٹ 65۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>24,050 میں آپ نے فروخت کیا۔</th>\n<th>23,950 آپ نے خریدا۔</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,800</td>\n<td>مالیت 250</td>\n<td>150 کی مالیت</td>\n<td>مائنس 3,994 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>23,950</td>\n<td>100 کی مالیت</td>\n<td>مالیت 0</td>\n<td>مائنس 3,994 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>24,011</td>\n<td>مالیت 39</td>\n<td>مالیت 0</td>\n<td>0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>علاوہ 2,506 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,300</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>علاوہ 2,506 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n</tbody></table>\n<p>میز کو پڑھیں اور تجارت کی شکل خود ہی ظاہر ہوتی ہے۔ کہیں بھی 24,050 سے اوپر کی طرف آپ پورے 2,506 روپے جمع کرتے ہیں۔ 23,950 نیچے سے کہیں بھی آپ پورے 3,994 روپے کھو دیتے ہیں۔ دونوں سٹرائیکس کے درمیان نتیجہ 24,011 پر صفر سے گزر کر ایک شیلف سے دوسرے شیلف پر آسانی سے پھسل جاتا ہے۔ یہ پوری ادائیگی ہے، اور یہ چارٹ پر موجود اورنج لائن سے بالکل مماثل ہے۔</p>\n<h2 id=\"the-dimension-most-explainers-skip-your-odds\">زیادہ تر وضاحت کرنے والے جس جہت کو چھوڑ دیتے ہیں: آپ کی مشکلات</h2>\n<p>زیادہ سے زیادہ جاننا کہ آپ جیت سکتے ہیں اور ہار سکتے ہیں صرف آدھی کہانی ہے۔ سوال جو اصل میں یہ فیصلہ کرتا ہے کہ آیا تجارت ہوشیار ہے، ہر ایک نتیجہ کا کتنا امکان ہے؟ وہ ہے <strong>منافع کا امکان</strong>، یا POP، اور بلڈر اسے صحیح پینل پر رکھتا ہے۔</p>\n<p>اس کے لیے پھیلاؤ <strong>POP تقریباً 51 فیصد ہے۔</strong>. یہ نمبر آپشن مارکیٹ سے ہی آتا ہے۔ NIFTY اختیارات میں قیمت کے اتار چڑھاؤ کا استعمال کرتے ہوئے، تقریباً 12.7 فیصد، اور 32 دن باقی ہیں، مارکیٹ کا مطلب یہ ہے کہ 51 فیصد امکان ہے کہ NIFTY ختم ہونے کے بعد 24,011 بریک ایون سے اوپر ہوجائے۔ چارٹ کو دوبارہ دیکھیں۔ بیہوش سایہ دار <strong>سگما بینڈ</strong> اس حرکت کو دکھائیں جس کی مارکیٹ کی توقع ہے، اور 24,011 پر بریک ایون اسپاٹ کے بالکل نیچے بیٹھا ہے، آرام سے اندرونی بینڈ کے اندر۔ NIFTY کو کچھ خاص کرنے کی ضرورت نہیں ہے۔ اسے صرف اس جگہ پر رکھنے کی ضرورت ہے جہاں یہ پہلے سے موجود ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>ہمیشہ POP کے آگے زیادہ سے زیادہ نقصان پڑھیں، کبھی اکیلے نہیں۔ اس پھیلاؤ سے 2,506 روپے بنانے کے لیے 3,994 روپے کا خطرہ ہے، جو کہ ون ٹو ون ادائیگی سے بدتر ہے، پھر بھی یہ سمجھ میں آتا ہے کیونکہ مشکلات، 51 فیصد، آپ کے راستے پر جھکاؤ اور وقت آپ کی مدد کرتا ہے۔ کریڈٹ اسپریڈ ایک ڈیل ہے جہاں آپ زیادہ بار جیتنے کے بدلے ایک چھوٹا انعام قبول کرتے ہیں۔ POP یہ ہے کہ آپ کس طرح جانچتے ہیں کہ تجارتی بند حقیقی طور پر آپ کے حق میں ہے۔</p>\n</div></div>\n<h2 id=\"the-other-dimension-most-explainers-skip-margin\">دوسری جہت جسے زیادہ تر وضاحت کرنے والے چھوڑ دیتے ہیں: مارجن</h2>\n<p>چونکہ آپ خالص فروخت کنندہ ہیں، ایکسچینج بلاک ہو جاتا ہے۔ <strong>مارجن</strong> سیکورٹی کے طور پر، یہاں کے بارے میں <strong>35,358 روپے</strong>، SPAN جزو کے علاوہ ایک نمائش بفر سے بنا ہے۔ خریدا گیا 23,950 پوٹ اس نمبر کو چھوٹا رکھتا ہے۔ اس کے بغیر ننگا شارٹ پٹ 1.6 لاکھ روپے سے زیادہ کا معاہدہ کرے گا۔ حفاظتی ٹانگ نہ صرف آپ کے نقصان کو پورا کرتی ہے، بلکہ یہ تجارت کی ضرورت کے سرمائے کو کم کرتی ہے۔</p>\n<p>یہ مارجن آپ کو تجارت کا ایمانداری سے فیصلہ کرنے دیتا ہے۔ <strong>مارجن پر واپسی</strong>. آپ تقریباً ایک ماہ کے لیے بلاک کیے گئے 35,358 روپے کے مقابلے میں 2,506 روپے جمع کرتے ہیں، جو کہ تقریباً ہے۔ <strong>خطرے میں دارالحکومت پر 7 فیصد</strong> اگر تجارت کام کرتی ہے۔ یہ پوزیشن کی حقیقی پیداوار ہے، اور یہ وہ نمبر ہے جس کا موازنہ ایک سنجیدہ تاجر تمام خیالات سے کرتا ہے، نہ کہ خام پریمیم سے۔</p>\n<h2 id=\"time-is-on-your-side\">وقت آپ کی طرف ہے۔</h2>\n<p>چارٹ پر ایک بار پھر دیکھیں <strong>نیلی ڈیشڈ T+0 لائن</strong> موجودہ قیمت کے قریب ٹھوس اورنج ایٹ ایکسپائری لائن کے اوپر بیٹھا ہے۔ وہ خلا ہے۔ <strong>وقت کی قدر</strong>، اور ایک خالص بیچنے والے کے لیے یہ ایک تحفہ ہے۔ ہر پرسکون دن آپ کے اختیارات میں سے تھوڑا سا پریمیم پگھل جاتا ہے، اور نیلی لائن نارنجی کی طرف ڈوب جاتی ہے۔ آپ نے سامنے کریڈٹ جمع کیا، اور وقت خاموشی سے اسے حقیقی منافع میں بدل دیتا ہے جب تک کہ NIFTY برتاؤ کرتا ہے۔ ایک طویل آپشن خریدار ہر ایک دن اس کشی سے لڑتا ہے۔ کریڈٹ اسپریڈ بیچنے والے کے طور پر، آپ کو اس کے ذریعے ادائیگی کی جاتی ہے۔</p>\n<h2 id=\"choosing-your-strikes\">اپنی ہڑتالوں کا انتخاب کرنا</h2>\n<p>اوپر 100 نکاتی پھیلاؤ بہت سے لوگوں میں سے ایک انتخاب ہے۔ ہڑتالوں کے درمیان فرق کو وسیع یا تنگ کریں اور آپ پوری تجارت کو نئی شکل دیں۔ یہاں ایک ہی NIFTY، ایک ہی ایکسپائری پر چار اصلی بیل پوٹ اسپریڈز ہیں، تاکہ آپ تجارت کو صاف طور پر دیکھ سکیں۔</p>\n<table>\n<thead>\n<tr>\n<th>پھیلاؤ</th>\n<th>بیچنا/خریدنا</th>\n<th>کریڈٹ (زیادہ سے زیادہ منافع)</th>\n<th>زیادہ سے زیادہ نقصان</th>\n<th>بریک ایون</th>\n<th>POP</th>\n<th>مارجن</th>\n<th>مارجن پر واپس جائیں۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>50 پوائنٹس</td>\n<td>24,050 فروخت کریں / 24,000 خریدیں۔</td>\n<td>1,173 روپے</td>\n<td>2,077 روپے</td>\n<td>24,032</td>\n<td>50%</td>\n<td>33,633 روپے</td>\n<td>3.5%</td>\n</tr>\n<tr>\n<td>100 پوائنٹس</td>\n<td>24,050 بیچیں / 23,950 خریدیں۔</td>\n<td>2,506 روپے</td>\n<td>3,994 روپے</td>\n<td>24,011</td>\n<td>51%</td>\n<td>35,358 روپے</td>\n<td>7.1%</td>\n</tr>\n<tr>\n<td>200 پوائنٹس</td>\n<td>24,050 بیچیں / 23,850 خریدیں۔</td>\n<td>4,618 روپے</td>\n<td>8,382 روپے</td>\n<td>23,979</td>\n<td>53%</td>\n<td>39,246 روپے</td>\n<td>11.8%</td>\n</tr>\n<tr>\n<td>200 پوائنٹس، گہرا</td>\n<td>24,150 بیچیں / 23,950 خریدیں۔</td>\n<td>5,372 روپے</td>\n<td>7,628 روپے</td>\n<td>24,067</td>\n<td>48%</td>\n<td>38,553 روپے</td>\n<td>13.9%</td>\n</tr>\n</tbody></table>\n<p>پیٹرن واضح ہے۔ اے <strong>وسیع تر پھیلاؤ</strong> زیادہ کریڈٹ جمع کرتا ہے اور مارجن پر زیادہ منافع کماتا ہے، لیکن اگر آپ غلط ہیں تو اس سے زیادہ روپے کا خطرہ بھی ہوتا ہے۔ ایک اعلی، اندرونِ رقم کی ہڑتال، آخری قطار کو فروخت کرنا، سب سے زیادہ کریڈٹ اکٹھا کرتا ہے، لیکن یہ بریک ایون کو موجودہ جگہ سے 24,067 تک دھکیل دیتا ہے، اس لیے اب آپ کو تھوڑا سا اوپر جانے کے لیے NIFTY کی ضرورت ہے، نہ کہ محض پکڑنے کے لیے۔ ٹیبل میں کوئی مفت لنچ نہیں ہے، صرف ایک ڈائل جو آپ نے اپنے یقین سے مطابقت رکھنے کے لیے سیٹ کیا ہے۔ مضبوط اعتدال پسند تیزی کے نقطہ نظر، پھیلاؤ کو وسیع کریں. ہوشیار، اسے تنگ رکھیں۔</p>\n<h2 id=\"bull-put-spread-or-bull-call-spread\">بیل ڈال اسپریڈ یا بیل کال اسپریڈ؟</h2>\n<p>آپ بیل کال اسپریڈ پچھلے باب سے ملے ہیں، اور یہ بالکل ایک ہی اعتدال پسند تیزی کے نقطہ نظر کو ظاہر کرتا ہے جس کی ادائیگی قریب قریب ایک جیسی ہے۔ تو آپ کون سا انتخاب کرتے ہیں؟ ایماندارانہ جواب ہے، یہ اس بات پر منحصر ہے کہ مارکیٹ آپ کو کیا ادا کر رہی ہے۔</p>\n<ul>\n<li>دی <strong>بیل کال پھیل گئی</strong> ایک ہے <strong>ڈیبٹ</strong> تجارت آپ سامنے ادائیگی کرتے ہیں اور صحیح ہونے کی امید کرتے ہیں۔</li>\n<li>دی <strong>بیل ڈال پھیل گیا</strong> ایک ہے <strong>کریڈٹ</strong> تجارت آپ کو سامنے ادائیگی کی جاتی ہے اور امید ہے کہ آپ اکیلے رہ جائیں گے۔</li>\n</ul>\n<p>جب مارکیٹیں گر جاتی ہیں، خوف زیادہ ہوتا ہے، اور پوٹ پریمیم سوج جاتے ہیں، اس مہنگے بیمہ کو بیل پوٹ اسپریڈ کے ذریعے بیچنا زیادہ امیر سودا ہے۔ جب پریمیم سستے ہوں اور بازار پرسکون ہو تو بیل کال اسپریڈ بہتر خرید ہو سکتی ہے۔ بہت سے تجربہ کار تاجر صرف کریڈٹ ورژن کو ترجیح دیتے ہیں، کیونکہ انتظار کرنے کے لیے ادائیگی کی جاتی ہے، ان کی طرف وقت کی کمی کے ساتھ، ادائیگی کرنے اور گھڑی کو ان کے خلاف چلتی دیکھنے کے بجائے پوزیشن پر فائز رہنے کا ایک زیادہ آرام دہ طریقہ ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>بیل پوٹ اسپریڈ ڈیفائنڈ رسک ہے، لیکن خطرہ حقیقی ہے اور یہ انعام سے بڑا ہے۔ یہاں آپ 2,506 روپے کمانے کے لیے 3,994 روپے کا خطرہ مول لیتے ہیں۔ جیتنے والے مہینوں کی خاموشی آپ کو اوورسائز کرنے میں مدد دے سکتی ہے، اور پھر آپ کے نچلے سٹرائیک کے ذریعے ایک تیز کریش آپ کے کئی مہینوں کے کریڈٹ کو بیک وقت واپس لے سکتا ہے۔ ہر کریڈٹ کو اس کے زیادہ سے زیادہ نقصان سے پھیلائیں، کبھی بھی اس کریڈٹ کے حساب سے جو آپ جمع کرتے ہیں، اور کبھی بھی کسی پوٹ اسپریڈ کو اس سطح کے نیچے نہ بیچیں جس کو دیکھ کر آپ حقیقی طور پر گھبرا جائیں۔</p>\n</div></div>\n<h2 id=\"when-it-shines-and-when-to-stay-out\">یہ کب چمکتا ہے، اور کب باہر رہنا ہے۔</h2>\n<p>ایک بیل پوٹ اسپریڈ اس وقت بہترین ہوتا ہے جب کئی چیزیں قطار میں لگ جاتی ہیں۔</p>\n<ul>\n<li>آپ کا نظریہ ہے۔ <strong>معتدل تیزی سے غیر جانبدار</strong>. آپ توقع کرتے ہیں کہ NIFTY کو پکڑے یا بڑھے گا، نہ کہ بلند ہونے کی۔</li>\n<li><strong>رکھو پریمیم امیر ہیں</strong>، عام طور پر زوال کے بعد، جب خوف نے ان اختیارات کو موٹا کر دیا ہے جو آپ بیچنا چاہتے ہیں۔</li>\n<li><strong>مضمر اتار چڑھاؤ بلند ہے۔</strong>، لہذا آپ کو گھبراہٹ کا دوسرا رخ لینے کے لئے زیادہ ادائیگی کی جاتی ہے۔</li>\n<li>ہے <strong>ختم ہونے کے لئے کافی وقت</strong> کام کرنے کے لئے زوال کے لئے، لیکن اتنا نہیں کہ پوزیشن ہفتوں تک غیر منظم ہو جاتی ہے۔</li>\n</ul>\n<p>جب آپ حقیقی طور پر خرابی کے بارے میں فکر مند ہوں، جب پریمیم پتلے ہوں اور جمع کرنے کے لیے بہت کم کریڈٹ ہو، یا جب کوئی بڑا واقعہ آپ کی نچلی ہڑتال کے ذریعے رات بھر میں براہ راست NIFTY کا فرق کر سکتا ہے، کیونکہ متعین خطرہ صرف آپ کی میعاد ختم ہونے پر حفاظت کرتا ہے، نہ کہ پرتشدد فرق سے جو انٹرا ڈے مارجن کال کو متحرک کرتا ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>بغیر کسی خطرے کے اس کی مشق کرنے کا ایک صاف طریقہ: OpenAlgo اسٹریٹجی بلڈر کو کھولیں، NIFTY پر بیل پوٹ اسپریڈ ٹیمپلیٹ کو چنیں، اور سٹرائیکس کو الگ کرتے ہوئے نو میٹرک پینل اپ ڈیٹ دیکھیں۔ کریڈٹ اور مارجن میں اضافہ کو ایک ساتھ دیکھیں، بریک ایون شفٹ دیکھیں، اور سینڈ باکس ٹریڈنگ میں تجارت کی تصدیق کریں ( OpenAlgo میں تجزیہ کار وضع) اس سے پہلے کہ آپ اسے کبھی بھی فنڈ دیں۔ تجارت کو اپنے ہاتھوں سے بنانا، اور انہی نمبروں کو دیکھنا جن کا اس باب میں حوالہ دیا گیا ہے، وہی ہے جو ایک نسخہ کو حقیقی سمجھ میں بدل دیتا ہے۔</p>\n</div></div>\n<h2 id=\"key-takeaways\">اہم نکات</h2>\n<ul>\n<li>ایک بیل پوٹ اسپریڈ ایک اونچی پوٹ فروخت کرتا ہے اور a کے لئے کم پوٹ خریدتا ہے۔ <strong>خالص کریڈٹ</strong>اگر NIFTY اعلی اسٹرائیک سے اوپر رکھتا ہے تو منافع۔</li>\n<li><strong>زیادہ سے زیادہ منافع خالص کریڈٹ ہے۔</strong> (2506 روپے یہاں) <strong>زیادہ سے زیادہ نقصان اسپریڈ مائنس کریڈٹ ہے۔</strong> (3,994 روپے)، اور <strong>بریک ایون اعلی ہڑتال مائنس کریڈٹ ہے۔</strong> (24,011).</li>\n<li>انعام خطرے سے چھوٹا ہے، لہذا تجارت اپنی جگہ a کے ذریعے کماتی ہے۔ <strong>منافع کا سازگار امکان</strong> (51 فیصد) اور <strong>وقت کا زوال آپ کے لیے کام کر رہا ہے۔</strong>.</li>\n<li>یہ بلاک کرتا ہے۔ <strong>مارجن</strong> (تقریباً 35,358 روپے)، اور خریدا ہوا پوٹ وہ ہے جو مارجن اور نقصان دونوں کو چھوٹا رکھتا ہے۔ تجارت کو اس سے پرکھیں۔ <strong>مارجن پر واپسی</strong>یہاں تقریباً 7 فیصد۔</li>\n<li><strong>وسیع تر پھیلاؤ</strong> مزید خطرے کے لیے زیادہ کریڈٹ اور زیادہ واپسی جمع کریں۔ چوڑائی کو اپنے یقین سے ملا دیں۔</li>\n<li>بیل کال پھیلنے پر اسے منتخب کریں جب <strong>پریمیم امیر ہیں اور اتار چڑھاؤ زیادہ ہے۔</strong>، لہذا آپ کو انتظار کرنے کے لئے اچھی ادائیگی کی جاتی ہے۔</li>\n</ul>\n","toc":[{"level":2,"text":"ایک لائن کا خیال","id":"the-one-line-idea"},{"level":2,"text":"اصل تجارت، روپیہ بہ روپیہ","id":"the-real-trade-rupee-by-rupee"},{"level":2,"text":"تین نمبر، اور وہ کہاں سے آتے ہیں۔","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"میعاد ختم ہونے پر نتائج پر چلنا","id":"walking-the-outcomes-at-expiry"},{"level":2,"text":"زیادہ تر وضاحت کرنے والے جس جہت کو چھوڑ دیتے ہیں: آپ کی مشکلات","id":"the-dimension-most-explainers-skip-your-odds"},{"level":2,"text":"دوسری جہت جسے زیادہ تر وضاحت کرنے والے چھوڑ دیتے ہیں: مارجن","id":"the-other-dimension-most-explainers-skip-margin"},{"level":2,"text":"وقت آپ کی طرف ہے۔","id":"time-is-on-your-side"},{"level":2,"text":"اپنی ہڑتالوں کا انتخاب کرنا","id":"choosing-your-strikes"},{"level":2,"text":"بیل ڈال اسپریڈ یا بیل کال اسپریڈ؟","id":"bull-put-spread-or-bull-call-spread"},{"level":2,"text":"یہ کب چمکتا ہے، اور کب باہر رہنا ہے۔","id":"when-it-shines-and-when-to-stay-out"},{"level":2,"text":"اہم نکات","id":"key-takeaways"}],"imgCount":1,"hasContent":true},"6":{"html":"<p>اب تک ہر تیزی کی تجارت کی ایک صاف، محدود شکل رہی ہے۔ اب ہم تین ڈھانچے کے ساتھ عزائم میں آگے بڑھتے ہیں جو ان صاف ٹوپیوں کو کسی بڑی اور زیادہ کھلی چیز کے لیے تجارت کرتے ہیں، اور دو صورتوں میں کہیں زیادہ خطرناک۔ وہ سب تیز ہیں، لیکن ہر ایک مختلف انداز میں اظہار خیال کرتا ہے۔ دی <strong>کال ریشو بیک اسپریڈ</strong> الٹا کھلا چھوڑتے ہوئے آپ کے منفی پہلو کو چھوٹا رکھتا ہے۔ دی <strong>طویل مصنوعی مستقبل</strong> دو آپشنز کو ایک سیدھی لائن میں بدل دیتا ہے جو بالکل ایسے ہی برتاؤ کرتا ہے جیسا کہ مستقبل میں خریدنا۔ دی <strong>آگے کی حد</strong> ایک بلش کالر ہے جو زیادہ تر اس وقت تک سوتا ہے جب تک کہ NIFTY کوئی حقیقی حرکت نہیں کرتا۔ یہ وہ تجارتیں ہیں جہاں حکمت عملی بنانے والے کے نمبر اپنے پاس رکھتے ہیں، کیونکہ شکلیں اب نام سے واضح نہیں ہوتیں۔ تمام اعداد و شمار 26 جون 2026، اسپاٹ 24,056، لاٹ 65، 28 جولائی 2026 کی میعاد ختم ہونے میں تقریباً 32 دن بعد کیپچر کیے گئے حقیقی NIFTY ڈیٹا کا استعمال کرتے ہیں۔</p>\n<h2 id=\"the-one-line-idea\">ایک لائن کا خیال</h2>\n<p>تینوں ڈھانچے ایک تک پہنچ جاتے ہیں۔ <strong>لامحدود الٹا</strong>لیکن وہ اس کی ادائیگی بالکل مختلف طریقوں سے کرتے ہیں۔ کوئی اپنے نقصان کو مضبوطی سے روکتا ہے اور صرف ایک معمولی رقم کا خطرہ مول لیتا ہے۔ دیگر دو آپشنز میں سے فیوچر پوزیشن کو دوبارہ بناتے ہیں، اس لیے ان کا منفی پہلو کھلا ہے اور ان کا مارجن بھاری ہے۔ یہ باب جو مہارت سکھاتا ہے وہ پڑھ رہا ہے کہ چارٹ کا کون سا رخ لامحدود، یا قریب لا محدود، نقصان کو چھپاتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>لامحدود منافع دیکھنا آسان حصہ ہے۔ ایماندارانہ سوال ہمیشہ وہی ہوتا ہے جو دوسری طرف بیٹھتا ہے۔ کال ریشو بیک اسپریڈ سے 26,930 روپے کا خطرہ ہے۔ مصنوعی مستقبل اور آگے کی حد ہر خطرے کو 15 لاکھ سے زیادہ نقصان پہنچاتی ہے، کیونکہ فروخت ہونے والی ٹانگ منفی پہلو کو کھلا چھوڑ دیتی ہے۔ ایک ہی خواب، تین بہت مختلف قیمتیں۔</p>\n</div></div>\n<h2 id=\"strategy-one-the-call-ratio-back-spread\">حکمت عملی ایک: کال ریشو بیک اسپریڈ</h2>\n<p>بیک اسپریڈ میں ٹانگوں کی غیر مساوی تعداد کا استعمال ہوتا ہے۔ یہاں آپ ایک ایٹ دی منی کال بیچتے ہیں اور دو کالز ایک سٹرائیک زیادہ خریدتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>1 کال فروخت کریں۔</td>\n<td>24,050</td>\n<td>425.8 موصول ہوا۔</td>\n<td>علاوہ 27,677 روپے میں</td>\n</tr>\n<tr>\n<td>2</td>\n<td>2 کالز خریدیں۔</td>\n<td>24,150</td>\n<td>370.1 ہر ایک ادا کیا</td>\n<td>48,107 روپے (2 لاٹ)</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>خالص ڈیبٹ</strong></td>\n<td><strong>20,430 روپے باہر</strong></td>\n</tr>\n</tbody></table>\n<p>سنگل سیلڈ کال فنڈز ان دونوں کا حصہ جو آپ خریدتے ہیں، لیکن جوڑے کی مجموعی قیمت زیادہ ہے، اس لیے آپ ایک ادا کرتے ہیں۔ <strong>20,430 روپے کا خالص ڈیبٹ</strong>. بدلے میں آپ ہڑتال کے اوپر ایک اضافی لمبی کال کے مالک ہیں، اور وہ اضافی کال ہے جو ڈھانچے کو ایک مضبوط ریلی میں اس کا لامحدود الٹ پلٹ دیتی ہے۔</p>\n<p>تینوں نمبر مندرجہ ذیل ہیں۔</p>\n<p><strong>زیادہ سے زیادہ نقصان 26,930 روپے ہے، اور یہ درمیان میں رہتا ہے، دم نہیں.</strong> 24,050 سے نیچے ہر کال کی میعاد بے کار ہو جاتی ہے اور آپ صرف خالص ڈیبٹ کھو دیتے ہیں۔ اصل درد 24,150 سٹرائیک پر بیٹھا ہے، جہاں فروخت شدہ کال 100 پوائنٹس سے پوری طرح رقم میں ہے لیکن دو خریدی گئی کالیں بمشکل بیدار ہوئی ہیں۔ یہ شارٹ پر 100 پوائنٹ کا نقصان ہے، جس کی مالیت 6,500 روپے ہے، اس کے علاوہ 20,430 روپے ڈیبٹ، جو مل کر 26,930 روپے بنتے ہیں۔</p>\n<p><strong>Breakeven 24,564 ہے۔</strong> 24,150 سے اوپر دو لانگ کالز سنگل شارٹ ہارنے سے دوگنا تیزی سے فائدہ اٹھاتی ہیں، فی شیئر خالص ایک پوائنٹ، اس لیے پوزیشن اپنی وادی سے باہر نکل جاتی ہے اور ایک بار جب یہ فائدہ ڈیبٹ فی شیئر کی وصولی کرتا ہے تو صفر کو عبور کرتا ہے۔ <strong>زیادہ سے زیادہ منافع لامحدود ہے۔</strong> وہاں کے اوپر.</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>24,150 پلس نیٹ ڈیبٹ پر مختصر کال کا نقصان</td>\n<td>6,500 روپے جمع 20,430 روپے 26,930 کے برابر ہے۔</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>ایک فالتو لمبی کال مفت چل رہی ہے۔</td>\n<td>لا محدود</td>\n</tr>\n<tr>\n<td>بریک ایون</td>\n<td>اوپری کراسنگ جہاں دو لانگ ڈیبٹ کی وصولی کرتے ہیں۔</td>\n<td>24,564</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-call-ratio-back-spread.png\" alt=\"NIFTY کال ریشو بیک اسپریڈ، ایک 24,050 کال فروخت اور دو 24,150 کالز خریدی۔ اورنج لائن 24,150 سٹرائیک پر 26,930 روپے کے اپنے بدترین نقصان میں ڈوبتی ہے، 24,564 پر بریک ایون کے ذریعے چڑھتی ہے، پھر بغیر کسی حد کے سبز رنگ میں بڑھ جاتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY کال ریشو بیک اسپریڈ، ایک 24,050 کال فروخت اور دو 24,150 کالز خریدی۔ اورنج لائن 24,150 سٹرائیک پر 26,930 روپے کے اپنے بدترین نقصان میں ڈوبتی ہے، 24,564 پر بریک ایون کے ذریعے چڑھتی ہے، پھر بغیر کسی حد کے سبز رنگ میں بڑھ جاتی ہے۔</figcaption></figure>\n<p>اب اسے ختم ہونے پر حل کریں۔ فروخت شدہ کال کی قیمت زیادہ سے زیادہ ہے دو خریدی گئی کالیں ہر ایک کی قیمت زیادہ سے زیادہ ہے (NIFTY مائنس 24,150, 0)۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>24,050 کال فروخت ہوئی۔</th>\n<th>24,150 کالز خریدی گئیں (ہر ایک)</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,900</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مائنس 20,430 روپے (ڈیبٹ)</td>\n</tr>\n<tr>\n<td>24,150</td>\n<td>100 کی مالیت</td>\n<td>مالیت 0</td>\n<td>مائنس 26,930 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>24,564</td>\n<td>مالیت 514</td>\n<td>مالیت 414</td>\n<td>تقریباً 0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>24,800</td>\n<td>مالیت 750</td>\n<td>مالیت 650</td>\n<td>علاوہ 15,320 روپے</td>\n</tr>\n<tr>\n<td>25,050</td>\n<td>مالیت 1,000</td>\n<td>900 کی مالیت</td>\n<td>علاوہ 31,570 روپے (اور بڑھتا ہوا)</td>\n</tr>\n</tbody></table>\n<p>نیچے پڑھیں اور وادی خود کو ظاہر کرتی ہے۔ سب سے برا معاملہ کریش نہیں ہے بلکہ ایک ہلکا بڑھاؤ ہے جو 24,150 پر فروخت ہونے والی ہڑتال کو پن کرتا ہے۔ یہ وہ نایاب ڈھانچہ ہے جہاں لامحدود کا مطلب ہے لامحدود منافع، لامحدود خطرہ نہیں، اور نقصان 26,930 روپے مقرر ہے۔</p>\n<h2 id=\"strategy-two-the-long-synthetic-future\">حکمت عملی دو: طویل مصنوعی مستقبل</h2>\n<p>اگلا ڈھانچہ منحنی خطوط کو مکمل طور پر ترک کر دیتا ہے۔ ایک ہی سٹرائیک پر ایک خریدی ہوئی کال اور ایک بیچی ہوئی کال کو ملا کر، آپ ایک سیدھی ترچھی لکیر بناتے ہیں جو بالکل اسی طرح اٹھتی اور گرتی ہے جیسے ایک NIFTY مستقبل کا مالک ہو۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>نقد بہاؤ فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>کال خریدیں۔</td>\n<td>24,050</td>\n<td>425.8 ادا کیا گیا۔</td>\n<td>27,677 روپے باہر</td>\n</tr>\n<tr>\n<td>2</td>\n<td>ڈال فروخت</td>\n<td>24,050</td>\n<td>295.1 موصول ہوا۔</td>\n<td>علاوہ 19,182 روپے میں</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>خالص ڈیبٹ</strong></td>\n<td><strong>8,496 روپے باہر</strong></td>\n</tr>\n</tbody></table>\n<p>خریدی ہوئی کال آپ کو مستقبل کے تمام پہلوؤں کے حوالے کرتی ہے۔ بیچنے والے نے اس کے تمام منفی پہلوؤں کو آپ کے ہاتھ میں ڈال دیا۔ ایک ساتھ مل کر ان کی قیمت تھوڑی ہے۔ <strong>8,496 روپے کا خالص ڈیبٹ</strong>، اور پوزیشن پھر دونوں سمتوں میں پوائنٹ کے لیے NIFTY پوائنٹ کو ٹریک کرتی ہے۔ کہیں بھی حفاظتی ٹانگ نہیں ہے، لہذا کوئی فلیٹ فرش نہیں ہے. یہ ایک مکمل مستقبل ہے، دو اختیارات سے دوبارہ بنایا گیا ہے۔</p>\n<p><strong>زیادہ سے زیادہ منافع لامحدود ہے۔</strong> بریک ایون کے اوپر۔ <strong>زیادہ سے زیادہ نقصان صفر کی طرف جاتا ہے، تقریباً 1,571,746 روپے</strong>کیونکہ بریک ایون کے نیچے پوزیشن روپے کے بدلے روپے کی گرتی ہے بالکل ایسے ہی جیسے ایک طویل مستقبل۔ <strong>Breakeven 24,181 ہے۔</strong>، اسٹرائیک کے علاوہ 130.7 کا خالص ڈیبٹ فی شیئر، جو کہ وہ موثر قیمت ہے جس پر آپ نے NIFTY خریدا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>مستقبل کی طرح، بریک ایون کے اوپر کوئی چھت نہیں۔</td>\n<td>لا محدود</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>مستقبل کی طرح صفر کی طرف گرنا</td>\n<td>تقریباً 1,571,746 روپے</td>\n</tr>\n<tr>\n<td>بریک ایون</td>\n<td>ہڑتال کے علاوہ فی شیئر خالص ڈیبٹ</td>\n<td>24,050 جمع 130.7 برابر 24,181</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-long-synthetic.png\" alt=\"NIFTY لمبا مصنوعی مستقبل، 24,050 کال خریدنا اور 24,050 کا پوٹ بیچنا۔ اورنج لائن ایک واحد سیدھی ترچھی ہے، جو 24,181 کے بریک ایون کے اوپر بغیر کسی حد کے بڑھ رہی ہے اور اس کے نیچے روپے کے بدلے روپیہ گر رہی ہے، بالکل ایک طویل مستقبل کی طرح۔ نیلی T+0 لائن تقریباً اس کے اوپر واقع ہے، کیونکہ مصنوعی مستقبل تقریباً کوئی وقت کی قدر نہیں رکھتا۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY لمبا مصنوعی مستقبل، 24,050 کال خریدنا اور 24,050 کا پوٹ بیچنا۔ اورنج لائن ایک واحد سیدھی ترچھی ہے، جو 24,181 کے بریک ایون کے اوپر بغیر کسی حد کے بڑھ رہی ہے اور اس کے نیچے روپے کے بدلے روپیہ گر رہی ہے، بالکل ایک طویل مستقبل کی طرح۔ نیلی T+0 لائن تقریباً اس کے اوپر واقع ہے، کیونکہ مصنوعی مستقبل تقریباً کوئی وقت کی قدر نہیں رکھتا۔</figcaption></figure>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>24,050 کال خریدی گئی۔</th>\n<th>24,050 میں فروخت ہوا۔</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,000</td>\n<td>مالیت 0</td>\n<td>مالیت 1,050</td>\n<td>مائنس 76,746 روپے (اور گرتا ہوا)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مائنس 8,496 روپے</td>\n</tr>\n<tr>\n<td>24,181</td>\n<td>مالیت 131</td>\n<td>مالیت 0</td>\n<td>تقریباً 0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>24,500</td>\n<td>مالیت 450</td>\n<td>مالیت 0</td>\n<td>علاوہ 20,755 روپے</td>\n</tr>\n<tr>\n<td>25,000</td>\n<td>950 کی مالیت</td>\n<td>مالیت 0</td>\n<td>علاوہ 53,255 روپے (اور بڑھتا ہوا)</td>\n</tr>\n</tbody></table>\n<p>لائن میں تشریح کرنے کے لئے کچھ نہیں ہے، جو نقطہ ہے. 24,181 سے اوپر آپ بغیر کسی حد کے پوائنٹ کے لیے پوائنٹ حاصل کرتے ہیں۔ اس کے نیچے آپ پوائنٹ کے لیے پوائنٹ کھو دیتے ہیں، صرف NIFTY کے صفر پر گرنے سے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>طویل مصنوعی مستقبل بالکل ایک لمبے NIFTY مستقبل کی طرح برتاؤ کرتا ہے، لہذا اس کا خطرہ دو طرفہ اور بہت بڑا ہے۔ زیادہ سے زیادہ نقصان تقریباً 1,571,746 روپے ہے اگر NIFTY گر جاتا ہے، فروخت شدہ پوٹ ایک ننگی شارٹ ٹانگ ہے، اور ایکسچینج 173,537 روپے کے قریب بھاری مارجن کو روکتا ہے۔ یہاں کوئی طے شدہ منزل نہیں ہے۔ یہ ایک فیوچر-گریڈ پوزیشن ہے جو دو آپشنز کے طور پر ملبوس ہے، اور ایک ابتدائی کو اس کے ساتھ فیوچر-گریڈ کے احترام کے ساتھ برتاؤ کرنا چاہئے، ایسا کبھی نہیں کہ جیسے یہ مستقبل سے زیادہ محفوظ ہو۔</p>\n</div></div>\n<h2 id=\"strategy-three-the-range-forward\">حکمت عملی تین: آگے کی حد</h2>\n<p>تیسرا ڈھانچہ نرم ہے۔ اے <strong>آگے کی حد</strong>، جسے بعض اوقات بلش کالر کہا جاتا ہے، مارکیٹ کے نیچے رکھی ہوئی رقم کو فروخت کرتا ہے تاکہ اس کے اوپر کی رقم سے باہر کی کال کو فنڈ کیا جاسکے۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>ڈال فروخت</td>\n<td>23,950</td>\n<td>256.6 موصول ہوا۔</td>\n<td>علاوہ 16,679 روپے میں</td>\n</tr>\n<tr>\n<td>2</td>\n<td>کال خریدیں۔</td>\n<td>24,150</td>\n<td>370.1 ادا کیا گیا۔</td>\n<td>24,057 روپے باہر</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>خالص ڈیبٹ</strong></td>\n<td><strong>7,378 روپے باہر</strong></td>\n</tr>\n</tbody></table>\n<p>بیچا ہوا پوٹ زیادہ تر خریدی ہوئی کال کے لیے ادائیگی کرتا ہے، جس میں ایک چھوٹا سا رہ جاتا ہے۔ <strong>7,378 روپے کا خالص ڈیبٹ</strong>. دو سٹرائیکس کے درمیان، 23,950 سے 24,150 تک، کسی بھی آپشن کی اندرونی قدر نہیں ہے، لہذا پوزیشن اس چھوٹے ڈیبٹ پر منحصر ہے، ایک فلیٹ ڈیڈ زون جہاں بہت کم ہوتا ہے۔ سٹرائیکس کے باہر اس میں جان پڑتی ہے: 24,150 سے اوپر کی خریدی ہوئی کال لامحدود الٹ دیتی ہے، 23,950 سے نیچے بیچی جانے والی کال آپ کو مستقبل کی طرح منفی پہلو دیتی ہے۔</p>\n<p><strong>زیادہ سے زیادہ منافع لامحدود ہے۔</strong> بریک ایون کے اوپر۔ <strong>زیادہ سے زیادہ نقصان صفر کی طرف جاتا ہے، تقریباً 1,564,128 روپے</strong>, ننگے ڈال پر. <strong>Breakeven 24,264 ہے۔</strong>، 24,150 کی اوپری ہڑتال کے علاوہ 113.5 کا خالص ڈیبٹ فی شیئر۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>اپر ہڑتال کے اوپر مفت چل رہی کال خریدی۔</td>\n<td>لا محدود</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>فروخت صفر کی طرف گر رہی ہے۔</td>\n<td>تقریباً 1,564,128 روپے</td>\n</tr>\n<tr>\n<td>بریک ایون</td>\n<td>اوپری ہڑتال کے علاوہ فی شیئر خالص ڈیبٹ</td>\n<td>24,150 جمع 113.5 برابر 24,264</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-range-forward.png\" alt=\"NIFTY رینج فارورڈ، 23,950 کا پوٹ بیچنا اور 24,150 کال خریدنا۔ اورنج لائن تقریباً ایک لمبا مستقبل ہے جس میں سٹرائیکس کے درمیان ایک چھوٹا سا فلیٹ ڈیڈ زون ہے، جو 24,264 کے بریک ایون سے لامحدود ہے اور 23,950 سے نیچے گہرا مستقبل جیسا نقصان ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY رینج فارورڈ، 23,950 کا پوٹ بیچنا اور 24,150 کال خریدنا۔ اورنج لائن تقریباً ایک لمبا مستقبل ہے جس میں سٹرائیکس کے درمیان ایک چھوٹا سا فلیٹ ڈیڈ زون ہے، جو 24,264 کے بریک ایون سے لامحدود ہے اور 23,950 سے نیچے گہرا مستقبل جیسا نقصان ہے۔</figcaption></figure>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>23,950 پوٹ فروخت ہوا۔</th>\n<th>24,150 کال خریدی گئی۔</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,000</td>\n<td>950 کی مالیت</td>\n<td>مالیت 0</td>\n<td>مائنس 69,128 روپے (اور گرتا ہوا)</td>\n</tr>\n<tr>\n<td>24,000</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مائنس 7,378 روپے (ڈیڈ زون)</td>\n</tr>\n<tr>\n<td>24,264</td>\n<td>مالیت 0</td>\n<td>مالیت 114</td>\n<td>تقریباً 0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>24,600</td>\n<td>مالیت 0</td>\n<td>مالیت 450</td>\n<td>علاوہ 21,873 روپے</td>\n</tr>\n<tr>\n<td>25,100</td>\n<td>مالیت 0</td>\n<td>مالیت 950</td>\n<td>علاوہ 54,373 روپے (اور بڑھتا ہوا)</td>\n</tr>\n</tbody></table>\n<p>ہڑتالوں کے درمیان ڈیڈ زون تجارت کو پرسکون محسوس کرتا ہے، لیکن اس سکون سے 23,950 تک فوری طور پر NIFTY گر جاتا ہے، جہاں فروخت شدہ پوٹ روپے کے بدلے روپیہ کھونا شروع کر دیتا ہے، صرف NIFTY صفر پر گرنے سے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>رینج فارورڈ ایک برہنہ پوٹ بیچ کر اپنی لاگت کو مٹا دیتا ہے، اس لیے منفی پہلو مستقبل جیسا اور بہت بڑا ہے، زیادہ سے زیادہ نقصان 1,564,128 روپے کے قریب، مارجن 166,553 روپے کے قریب۔ اس منفی پہلو کا بالکل اسی طرح علاج کریں جیسا کہ آپ مختصر الفاظ میں کریں گے۔ فلیٹ مڈل اطمینان کو دعوت دیتا ہے، لیکن نچلی ہڑتال کے ذریعے حقیقی زوال ایک مختصر مستقبل کی طرح برتاؤ کرتا ہے، نہ کہ کسی متعین خطرے کے پھیلاؤ کی طرح۔</p>\n</div></div>\n<h2 id=\"your-odds-across-the-three\">تینوں میں آپ کی مشکلات</h2>\n<p>دی <strong>منافع کا امکان</strong> صاف طور پر ان کی درجہ بندی: کے بارے میں <strong>28 فیصد</strong> کال ریشو بیک اسپریڈ کے لیے، <strong>44 فیصد</strong> مصنوعی مستقبل کے لیے، اور <strong>40 فیصد</strong> آگے کی حد کے لیے۔ بیک اسپریڈ سب سے کم بیٹھتا ہے کیونکہ NIFTY کو اپنے چارٹ پر پلس ون سگما بینڈ سے آگے، اوپن اینڈڈ اپسائیڈ کی ادائیگی سے پہلے 24,564 کو صاف کرنا ہوگا۔ مصنوعی اور رینج فارورڈ اس لیے بھی قریب ہے کہ وہ مستقبل کی طرح برتاؤ کرتے ہیں، بریک ایون سے تھوڑی ہی اوپر کی جگہ سے گزرنے والے کسی بھی اقدام پر فائدہ اٹھاتے ہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>کم POP خود بخود خراب تجارت نہیں ہے، اور اعلیٰ خود بخود اچھی نہیں ہے۔ کال ریشو بیک اسپریڈ صرف 28 فیصد وقت جیتتا ہے، پھر بھی اس کے نقصان کی حد 26,930 روپے ہے اور اس کی جیت اوپن اینڈڈ ہو سکتی ہے۔ مصنوعی کا 44 فیصد اس وقت تک بہتر نظر آتا ہے جب تک کہ آپ اسے اس کی 1,571,746 روپے کی دم کے ساتھ لگا دیں۔ ہمیشہ زیادہ سے زیادہ نقصان کے آگے POP پڑھیں، خود کبھی نہیں۔</p>\n</div></div>\n<h2 id=\"margin\">مارجن</h2>\n<p>مارجن ان تینوں کو خطرے کے لحاظ سے کسی بھی دوسرے نمبر سے زیادہ ایمانداری سے ترتیب دیتا ہے۔ دی <strong>کال ریشو بیک اسپریڈ</strong> کے بارے میں تعلقات <strong>52,256 روپے</strong>, معمولی، کیونکہ اس کے نقصان کی وضاحت کی گئی ہے اور لمبی کالیں بڑی حد تک مختصر کا احاطہ کرتی ہیں۔ دی <strong>طویل مصنوعی مستقبل</strong> کے بارے میں بلاکس <strong>173,537 روپے</strong> اور <strong>آگے کی حد</strong> کے بارے میں <strong>166,553 روپے</strong>, دونوں بھاری، کیونکہ ہر ایک ننگی چھوٹی ٹانگ رکھتا ہے جس میں کھلے نیچے کی طرف ایکسچینج کا احاطہ کرنا ضروری ہے۔</p>\n<p>مارجن پر واپسی تب ہی معنی رکھتی ہے جب منافع کی حد ہوتی ہے، اور ان میں سے دو کی کوئی حد نہیں ہے، اس لیے حوالہ دینے کے لیے کوئی مقررہ پیداوار نہیں ہے۔ ٹیک وے خود اس کے برعکس ہے۔</p>\n<h2 id=\"time-decay\">وقت کا زوال</h2>\n<p>تینوں گھڑی کے خلاف الگ الگ بیٹھتے ہیں۔ دی <strong>کال ریشو بیک اسپریڈ</strong> اختیارات کا خالص خریدار ہے، طویل ایک اضافی کال، اس لیے وقت کا زوال اس کے خلاف نرمی سے کام کرتا ہے: اس کی نیلی T+0 لائن اورنج ایکسپائری لائن کے اوپر تیرتی ہے، اور 28 جولائی کے قریب آتے ہی وادی قدرے گہری ہوتی جاتی ہے۔ دی <strong>طویل مصنوعی مستقبل</strong> تقریباً کوئی وقت کی قدر نہیں رکھتا ہے، اس لیے اس کی T+0 لائن ایکسپائری لائن پر بالکل موجود ہے۔ یہ مستقبل کی طرح بنیادی طور پر وقت سے غیر جانبدار ہے۔ دی <strong>آگے کی حد</strong> غیر جانبدار کے قریب بھی بیٹھتا ہے، اس کی لمبی کال پر صرف ایک چھوٹا سا خون بہہ جاتا ہے۔ ان میں سے کوئی بھی تنزل کی تجارت نہیں ہے۔ وہ سمت سے جیتے ہیں یا مرتے ہیں۔</p>\n<h2 id=\"three-shapes-one-bullish-family\">تین شکلیں، ایک تیز خاندان</h2>\n<table>\n<thead>\n<tr>\n<th>حکمت عملی</th>\n<th>زیادہ سے زیادہ نقصان</th>\n<th>زیادہ سے زیادہ منافع</th>\n<th>بریک ایون</th>\n<th>مارجن</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>کال ریشو بیک اسپریڈ</td>\n<td>26,930 روپے</td>\n<td>لا محدود</td>\n<td>24,564</td>\n<td>52,256 روپے</td>\n</tr>\n<tr>\n<td>طویل مصنوعی مستقبل</td>\n<td>تقریباً 1,571,746 روپے</td>\n<td>لا محدود</td>\n<td>24,181</td>\n<td>173,537 روپے</td>\n</tr>\n<tr>\n<td>آگے کی حد</td>\n<td>تقریباً 1,564,128 روپے</td>\n<td>لا محدود</td>\n<td>24,264</td>\n<td>166,553 روپے</td>\n</tr>\n</tbody></table>\n<p>زیادہ سے زیادہ نقصان والے کالم کو غور سے پڑھیں، کیونکہ یہ ان کو خطرے کے مطابق ترتیب دیتا ہے۔ کال ریشو بیک اسپریڈ وہ واحد ہے جس کے لیے ایک ابتدائی کو پہنچنا چاہیے: اس کی سب سے بری صورت 26,930 روپے کی ہے اور یہ معمولی مارجن مانگتا ہے۔ مصنوعی مستقبل اور آگے کی حد ہر ایک ننگی چھوٹی ٹانگ، پندرہ لاکھ سے زیادہ نیچے کی طرف، اور بھاری مارجن لے کر آتی ہے، کیونکہ ہر ایک واقعی ایک مستقبل ہے جو آپشن کاسٹیوم پہنے ہوئے ہے۔</p>\n<h2 id=\"key-takeaways\">اہم نکات</h2>\n<ul>\n<li>تینوں ایک کے ساتھ تیز ہیں۔ <strong>لامحدود الٹا</strong>، لیکن وہ اس میں مکمل طور پر مختلف ہیں کہ انہیں اس تک پہنچنے کا خطرہ ہے۔</li>\n<li>دی <strong>کال ریشو بیک اسپریڈ</strong> 26,930 روپے کا زیادہ سے زیادہ نقصان ہے جو 24,150 سٹرائیک پر درمیان میں بیٹھتا ہے، دم میں نہیں، اور 24,564 کے بریک ایون سے اوپر مفت چلتا ہے۔ یہ یہاں ابتدائی طور پر محفوظ انتخاب ہے۔</li>\n<li>دی <strong>طویل مصنوعی مستقبل</strong> ایک طویل NIFTY مستقبل کے مساوی: بریک ایون 24,181، 1,571,746 روپے کی طرف تقریباً چھ فیگر-گنا-دس کی کمی، بھاری مارجن، اور تقریباً کوئی وقت کی کمی۔</li>\n<li>دی <strong>آگے کی حد</strong> سٹرائیکس کے درمیان ایک فلیٹ ڈیڈ زون کے ساتھ ایک تیزی کا کالر ہے، لیکن فروخت شدہ پوٹ 23,950 سے نیچے 1,564,128 روپے کے قریب مستقبل کی طرح کی کمی چھوڑ دیتا ہے۔</li>\n<li><strong>مارجن سچ کہتا ہے۔</strong>: تقریباً 52,000 روپے متعین شدہ رسک بیک اسپریڈ کے لیے، جبکہ مستقبل کی طرح کے دو ڈھانچے کے لیے تقریباً 1.7 لاکھ روپے۔</li>\n<li>ہمیشہ چیک کریں۔ <strong>چارٹ کا کون سا رخ لامحدود، یا قریب لامحدود، نقصان کو چھپاتا ہے۔</strong> لامحدود منافع کی طرف سے تیار ہونے سے پہلے.</li>\n</ul>\n","toc":[{"level":2,"text":"ایک لائن کا خیال","id":"the-one-line-idea"},{"level":2,"text":"حکمت عملی ایک: کال ریشو بیک اسپریڈ","id":"strategy-one-the-call-ratio-back-spread"},{"level":2,"text":"حکمت عملی دو: طویل مصنوعی مستقبل","id":"strategy-two-the-long-synthetic-future"},{"level":2,"text":"حکمت عملی تین: آگے کی حد","id":"strategy-three-the-range-forward"},{"level":2,"text":"تینوں میں آپ کی مشکلات","id":"your-odds-across-the-three"},{"level":2,"text":"مارجن","id":"margin"},{"level":2,"text":"وقت کا زوال","id":"time-decay"},{"level":2,"text":"تین شکلیں، ایک تیز خاندان","id":"three-shapes-one-bullish-family"},{"level":2,"text":"اہم نکات","id":"key-takeaways"}],"imgCount":3,"hasContent":true},"7":{"html":"<p>اب تک کی ہر تجارت نے NIFTY کو وسیع تر حق کے لیے کہا ہے: براہِ کرم اٹھیں، براہِ کرم کریش نہ ہوں، براہِ کرم تقریباً یہاں رہیں۔ اس باب میں دو ڈھانچے کہیں زیادہ درست چیز کا مطالبہ کرتے ہیں۔ دی <strong>تیز تتلی</strong> اور <strong>تیز کنڈور</strong> چھوٹے، جراحی شرط ہیں جو NIFTY ایک مخصوص لینڈنگ اسپاٹ تک پہنچ جاتے ہیں اور میعاد ختم ہونے پر وہاں بیٹھ جاتے ہیں۔ ان کی قیمت تقریباً کچھ نہیں، بمشکل سو روپے کا خطرہ، اور وہ اس سے کئی گنا زیادہ رقم واپس کر سکتے ہیں۔ کیچ، جو ایمانداری کے ساتھ سامنے بیان کی گئی ہے، وہ یہ ہے کہ وہ دس میں سے صرف ایک بار جیتتے ہیں، کیونکہ انڈیکس کو ایک تنگ ونڈو کے اندر ختم ہونا پڑتا ہے۔ یہ باب 26 جون 2026، اسپاٹ 24,056، لاٹ 65، ایکسپائری 28 جولائی 2026 کو حاصل کیے گئے حقیقی NIFTY ڈیٹا دونوں پر بناتا ہے، اور انہیں بالکل وہی سکھاتا ہے جو وہ ہیں: ایک درست منظر پر سستے ٹکٹ، کمانے کا کبھی بھی مستحکم طریقہ نہیں۔</p>\n<h2 id=\"the-one-line-idea\">ایک لائن کا خیال</h2>\n<p>دونوں ڈھانچے مکمل طور پر کال کے اختیارات سے بنائے گئے ہیں، اور دونوں ہی خریدی اور فروخت کی گئی ہڑتالوں کا ایک سیٹ اسٹیک کرتے ہیں تاکہ ہر طرف آپ کے خطرے میں پنکھوں کی باڑ لگ جائے۔ اے <strong>تیز تتلی</strong> ایک لوئر کال خریدتا ہے، دو درمیانی کالیں فروخت کرتا ہے، اور ایک اونچی کال خریدتا ہے، جس کا باڈی پیسے کے بالکل اوپر ہوتا ہے تاکہ یہ ایک ہی ہدف پر بہترین ادائیگی کرے۔ اے <strong>تیز کنڈور</strong> اس باڈی کو دو الگ الگ فروخت شدہ سٹرائیکس میں پھیلاتا ہے، ایک پوائنٹ کے بجائے چھوٹے لینڈنگ زون کے لیے نچلی چوٹی پر تجارت کرتا ہے۔ دونوں میں، آپ فروخت شدہ کالوں سے جو پریمیم جمع کرتے ہیں وہ آپ کی خریدی ہوئی کالوں کے لیے تقریباً بالکل ٹھیک ادا کرتے ہیں، اس لیے آپ ایک چھوٹے سے خالص ڈیبٹ کے لیے چلتے ہیں، اور وہ چھوٹا سا ڈیبٹ آپ کا سارا خطرہ ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک بلش بٹر فلائی اور ایک بلش کنڈور سستے، متعین خطرے والے شرط ہیں جو NIFTY ایکسپائری کے ذریعے ایک درست ہدف پر چڑھتے ہیں اور وہیں رک جاتے ہیں۔ آپ ایک چھوٹا سا ڈیبٹ ادا کرتے ہیں، وہ ڈیبٹ سب سے زیادہ ہوتا ہے جسے آپ کھو سکتے ہیں، اور دونوں طرف سے تجارت کو ونگز کیپ کرتے ہیں۔ خطرے کا انعام شاندار ہے، لیکن کھڑکی میں اترنے کے امکانات کم ہیں۔ یہ ٹارگٹ لمبے شاٹس ہیں، بنیادی پوزیشنز نہیں۔</p>\n</div></div>\n<h2 id=\"the-bullish-butterfly-rupee-by-rupee\">تیزی کی تتلی، روپیہ بہ روپیہ</h2>\n<p>یہ ہے تتلی حقیقی NIFTY قیمتوں پر، تین ضربیں اور چار ٹانگیں، جسم دو بار 24,150 میں فروخت ہوا اور پنکھ 24,050 اور 24,250 میں خریدے گئے۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>نقد بہاؤ فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>کال خریدیں۔</td>\n<td>24,050</td>\n<td>425.8 ادا کیا گیا۔</td>\n<td>27,677 روپے باہر</td>\n</tr>\n<tr>\n<td>2</td>\n<td>دو کالیں فروخت کریں۔</td>\n<td>24,150</td>\n<td>740.2 موصول ہوئے۔</td>\n<td>علاوہ 48,113 روپے میں</td>\n</tr>\n<tr>\n<td>3</td>\n<td>کال خریدیں۔</td>\n<td>24,250</td>\n<td>316.1 ادا کیا گیا۔</td>\n<td>20,547 روپے باہر</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>خالص ڈیبٹ</strong></td>\n<td><strong>تقریباً 120 روپے</strong></td>\n</tr>\n</tbody></table>\n<p>خریدے گئے دونوں پروں کو ایک ساتھ جوڑیں اور ان کی قیمت 48,224 روپے ہے۔ دو فروخت شدہ باڈی کالز 48,113 روپے واپس لاتی ہیں۔ ان کے درمیان فاصلہ صرف ہے۔ <strong>120 روپے</strong>، اور یہ تجارت کی پوری قیمت ہے۔ چونکہ پنکھ اوپر اور نیچے ڈھانچے کو باکس کرتے ہیں، آپ سے کبھی بھی ایک روپیہ زیادہ نہیں مانگا جا سکتا، اس لیے یہ 120 روپے بھی زیادہ سے زیادہ نقصان ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bullish-butterfly.png\" alt=\"NIFTY تیزی والی تتلی، 24,050 اور 24,250 کالز خریدتی ہے اور دو 24,150 کالز فروخت کرتی ہے۔ اورنج ایٹ ایکسپائری لائن ایک تیز ٹینٹ ہے جس کی قیمت 6,380 روپے 24,150 پر پہنچتی ہے، جس میں بیرونی پنکھوں کے قریب بریک ایون اور فلیٹ فلور کے قریب ہر جگہ صرف 120 روپے کا زیادہ سے زیادہ نقصان ہوتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY تیزی والی تتلی، 24,050 اور 24,250 کالز خرید رہی ہے اور دو 24,150 کالیں بیچ رہی ہے۔ اورنج ایٹ ایکسپائری لائن ایک تیز ٹینٹ ہے جس کی قیمت 6,380 روپے 24,150 پر پہنچتی ہے، جس میں بیرونی پنکھوں کے قریب بریک ایون اور فلیٹ فلور کے قریب ہر جگہ صرف 120 روپے کا زیادہ سے زیادہ نقصان ہوتا ہے۔</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">تین نمبر، اور وہ کہاں سے آتے ہیں۔</h2>\n<p>ہر نمبر براہ راست تجارت سے باہر آتا ہے۔ چوٹی جسم کی ہڑتال پر بیٹھتی ہے، فرش ڈیبٹ ہے، اور بریکونز پنکھوں کو گلے لگاتے ہیں.</p>\n<p><strong>زیادہ سے زیادہ منافع 6,380 روپے ہے۔</strong> اگر NIFTY 24,150 کی باڈی اسٹرائیک پر بالکل ختم ہوجاتا ہے، تو آپ کی خریدی گئی 24,050 کال رقم میں 100 پوائنٹس ہے جبکہ دو فروخت شدہ کالیں اور اوپری ونگ سب بیکار ہیں۔ وہ اندرونی قیمت 100 گنا 65 ہے، جو کہ 6,500 روپے ہے، اور 120 روپے کو گھٹانے کے بعد آپ نے 6,380 روپے اپنے پاس رکھے ہیں۔ یہ خیمے کی واحد تیز نوک ہے۔</p>\n<p><strong>زیادہ سے زیادہ نقصان 120 روپے ہے، خالص ڈیبٹ۔</strong> جہاں کہیں بھی ڈھانچہ پنکھوں کے باہر ختم ہو جاتا ہے، ہر کال یا تو منسوخ ہو جاتی ہے یا بیکار ہوتی ہے، اور آپ جو کچھ ضائع کرتے ہیں وہ وہ چھوٹی رقم ہے جو آپ نے داخل کرنے کے لیے ادا کی تھی۔</p>\n<p><strong>بریکیون تقریباً 24,042 اور 24,254 پر بیٹھتے ہیں، بنیادی طور پر بیرونی پروں پر۔</strong> ڈیبٹ اتنا چھوٹا ہے، دو پوائنٹس ایک شیئر کے نیچے، کہ یہ بمشکل ان پوائنٹس کو شفٹ کرتا ہے جہاں خیمہ صفر کو عبور کرتا ہے، اس لیے وہ سیدھے پروں پر اترتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>ونگ سے باڈی تک کا فرق، بار لاٹ، مائنس ڈیبٹ</td>\n<td>100 پوائنٹس گنا 65، جو کہ 6,500 روپے، مائنس 120 روپے، برابر ہے 6,380 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>خالص ڈیبٹ جو آپ نے ادا کیا ہے۔</td>\n<td>120 روپے</td>\n</tr>\n<tr>\n<td>Breakevens</td>\n<td>بیرونی پنکھ، چھوٹے ڈیبٹ سے بمشکل منتقل ہوئے۔</td>\n<td>تقریباً 24,042 اور 24,254</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-outcomes-at-expiry\">میعاد ختم ہونے پر نتائج پر چلنا</h2>\n<p>تتلی کو پانچ NIFTY سطحوں پر طے کریں اور خیمہ خود کو کھینچ لے۔ ہر کال کی میعاد ختم ہونے پر اس کی داخلی قدر کی قیمت ہوتی ہے، ایک کال اس کے اسٹرائیک سے اوپر ختم ہونے والی ہر چیز کی قیمت ہوتی ہے، اور جسم کی دگنی ٹانگ آپ کو اس سے دوگنا واجب الادا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>24,050 کال (خرید)</th>\n<th>24,150 کالز (بیچ، دو)</th>\n<th>24,250 کال (خرید)</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,900</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مائنس 120 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مائنس 120 روپے (منزل)</td>\n</tr>\n<tr>\n<td>24,150</td>\n<td>100 کی مالیت</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>علاوہ 6,380 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,250</td>\n<td>مالیت 200</td>\n<td>2 گنا 100 واجب الادا</td>\n<td>مالیت 0</td>\n<td>مائنس 120 روپے (واپس منزل پر)</td>\n</tr>\n<tr>\n<td>24,400</td>\n<td>مالیت 350</td>\n<td>2 گنا 250 واجب الادا</td>\n<td>مالیت 150</td>\n<td>مائنس 120 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n</tbody></table>\n<p>اسے صفحہ کے نیچے پڑھیں۔ بہت دائیں بائیں اور دائیں طرف لائن 120 روپے کے نقصان پر فلیٹ ہے، اتنی چھوٹی کہ یہ تقریباً صفر کو چھوتی ہے۔ صرف 24,150 کے ارد گرد یہ ایک لمبی، پتلی چوٹی میں بڑھتا ہے۔ 24,400 پر سب سے اوپر کی قطار پر غور کریں: خریدا ہوا 24,250 ونگ زندہ ہو جاتا ہے اور دونوں فروخت شدہ کالوں کی واجب الادا رقم کو پورا کرتا ہے، یہی وجہ ہے کہ نقصان کبھی بھی 120 روپے سے آگے نہیں بڑھتا چاہے وہ کتنی ہی دور چلا جائے۔</p>\n<h2 id=\"the-bullish-condor-rupee-by-rupee\">تیزی کا کنڈور، روپیہ بہ روپیہ</h2>\n<p>کنڈور بھی یہی خیال لیتا ہے اور چوٹی کو سطح مرتفع میں پھیلا دیتا ہے۔ ایک سٹرائیک کو دو بار بیچنے کے بجائے، آپ دو مختلف درمیانی سٹرائیکس، 24,100 اور 24,200 بیچتے ہیں، اس لیے خیمے کا اوپری حصہ ایک پوائنٹ کے بجائے ایک چھوٹا فلیٹ شیلف بن جاتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>نقد بہاؤ فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>کال خریدیں۔</td>\n<td>24,050</td>\n<td>425.8 ادا کیا گیا۔</td>\n<td>27,677 روپے باہر</td>\n</tr>\n<tr>\n<td>2</td>\n<td>کال فروخت کریں۔</td>\n<td>24,100</td>\n<td>397.6 موصول ہوا۔</td>\n<td>علاوہ 25,844 روپے میں</td>\n</tr>\n<tr>\n<td>3</td>\n<td>کال فروخت کریں۔</td>\n<td>24,200</td>\n<td>342.9 موصول ہوا۔</td>\n<td>علاوہ 22,289 روپے میں</td>\n</tr>\n<tr>\n<td>4</td>\n<td>کال خریدیں۔</td>\n<td>24,250</td>\n<td>316.1 ادا کیا گیا۔</td>\n<td>20,547 روپے باہر</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>خالص ڈیبٹ</strong></td>\n<td><strong>تقریباً 88 روپے</strong></td>\n</tr>\n</tbody></table>\n<p>ایک بار پھر دو فروخت شدہ کالیں تقریباً دو خریدے ہوئے پنکھوں کی ادائیگی کرتی ہیں، جس سے خالص ڈیبٹ صرف <strong>88 روپے</strong>جو کہ پورا زیادہ سے زیادہ نقصان ہے۔ دو فروخت شدہ ہڑتالیں ان کے درمیان ایک فلیٹ منافع کی سطح کے کناروں کو نشان زد کرتی ہیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bullish-condor.png\" alt=\"NIFTY بلش کنڈور، 24,050 اور 24,250 کالز خرید رہا ہے اور 24,100 اور 24,200 کالز فروخت کر رہا ہے۔ اورنج لائن تقریباً 24,100 اور 24,200 کے درمیان 3,162 روپے کے زیادہ سے زیادہ منافع پر ایک فلیٹ ٹاپ ٹینٹ بناتی ہے، جس میں ڈھانچے کے بالکل باہر بریک ایون اور قریب فلیٹ فلور زیادہ سے زیادہ صرف 88 روپے کے نقصان پر ہوتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY بلش کنڈور، 24,050 اور 24,250 کالز خرید رہا ہے اور 24,100 اور 24,200 کالز بیچ رہا ہے۔ اورنج لائن تقریباً 24,100 اور 24,200 کے درمیان 3,162 روپے کے زیادہ سے زیادہ منافع پر ایک فلیٹ ٹاپ ٹینٹ بناتی ہے، جس میں ڈھانچے کے بالکل باہر بریک ایون اور قریب فلیٹ فلور زیادہ سے زیادہ صرف 88 روپے کے نقصان پر ہوتا ہے۔</figcaption></figure>\n<p>اس کے تین نمبر اسی طرح بنائے گئے ہیں۔ دی <strong>زیادہ سے زیادہ منافع 3,162 روپے ہے۔</strong>: سطح مرتفع پر کہیں بھی خریدی گئی 24,050 کال پہلی فروخت ہونے والی اسٹرائیک سے 50 پوائنٹس آگے بیٹھتی ہے، جس کی قیمت 50 گنا 65 ہے، جو کہ 3,250 روپے ہے، اور 88 روپے ڈیبٹ کے بعد آپ 3,162 روپے رکھیں گے۔ دی <strong>زیادہ سے زیادہ نقصان 88 روپے ہے۔</strong>، ڈیبٹ. دی <strong>breakevens تقریباً 24,040 اور 24,254 پر بیٹھتے ہیں۔</strong>، پھر بنیادی طور پر ساخت کے بیرونی کناروں کو۔ اب اسے پانچ سطحوں پر چلائیں۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>24,050 کال (خرید)</th>\n<th>24,100 کال (فروخت)</th>\n<th>24,200 کال (فروخت)</th>\n<th>24,250 کال (خرید)</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,950</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مائنس 88 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>24,100</td>\n<td>مالیت 50</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>علاوہ 3,162 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,150</td>\n<td>100 کی مالیت</td>\n<td>50 واجب الادا</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>علاوہ 3,162 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,200</td>\n<td>150 کی مالیت</td>\n<td>100 واجب الادا ہیں۔</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>علاوہ 3,162 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,350</td>\n<td>300 کی مالیت</td>\n<td>250 واجب الادا ہیں۔</td>\n<td>150 واجب الادا ہیں۔</td>\n<td>100 کی مالیت</td>\n<td>مائنس 88 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n</tbody></table>\n<p>تین درمیانی قطاریں کہانی بیان کرتی ہیں: کہیں بھی 24,100 سے 24,200 تک تجارت وہی 3,162 روپے ادا کرتی ہے جو تتلی کے سنگل اسپائک کے بجائے ایک فلیٹ شیلف ہے۔ آپ نے چوٹی کی اونچائی، تتلی کے 6,380 روپے کے مقابلے میں 3,162 روپے، ایک وسیع جگہ پر اترنے کے لیے تجارت کی۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>ان دونوں کے درمیان واحد حقیقی فرق بلسی کی چوڑائی ہے۔ تتلی سب سے زیادہ ادائیگی کرتی ہے لیکن صرف ایک عین ہڑتال پر، 24,150۔ کنڈور کم ادائیگی کرتا ہے لیکن ہڑتالوں کے ایک چھوٹے بینڈ میں، 24,100 سے 24,200 تک۔ کنڈور کا انتخاب اس وقت کریں جب آپ کے پاس ٹارگٹ زون ہو، تتلی کا انتخاب کریں جب عین لینڈنگ پوائنٹ کے بارے میں آپ کا یقین مضبوط ہو۔</p>\n</div></div>\n<h2 id=\"your-odds\">آپ کی مشکلات</h2>\n<p>یہ وہ جگہ ہے جہاں ایمانداری سب سے زیادہ اہمیت رکھتی ہے۔ دونوں ڈھانچے خطرے کا شاندار انعام دکھاتے ہیں، تتلی 1 سے 53 اور کنڈور 1 سے 36، لیکن <strong>ہر ایک پر منافع کا امکان صرف 10 فیصد ہے۔</strong>. یہ اعداد و شمار آپشن مارکیٹ سے ہی آتا ہے: اتار چڑھاؤ کا استعمال کرتے ہوئے جس کی قیمت 12.7 فیصد ہے، اور 32 دن باقی ہیں، مارکیٹ کا مطلب دس میں سے صرف ایک موقع ہے کہ انڈیکس آپ کی تنگ کھڑکی میں چلا جائے اور وہیں رہے۔ چارٹ کو دیکھیں اور وجہ صاف ہے۔ بیہوش سگما بینڈز اس حد کو ظاہر کرتے ہیں کہ NIFTY ایک ماہ میں سفر کرنے کی توقع ہے، اور منافع بخش زون اس کے اندر ایک پتلی سی سلیور ہے۔ دس میں تقریباً نو بار NIFTY ونڈو کے باہر ختم ہو جاتا ہے اور آپ اپنا چھوٹا ڈیبٹ کھو دیتے ہیں۔ دس میں سے ایک بار یہ زون میں اترتا ہے اور آپ اس کا ایک کثیر جمع کرتے ہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>1 سے 53 تک کے انعام کو کبھی بھی اپنے طور پر خطرے میں نہ پڑھیں۔ اسے ہمیشہ اس کے ساتھ بیٹھے منافع کے 10 فیصد امکان کے ساتھ جوڑیں۔ سب سے زیادہ ممکنہ واحد نتیجہ، اب تک، چھوٹا نقصان ہے۔ یہ تجارت خاص طور پر سستی ہیں کیونکہ وہ شاذ و نادر ہی ادائیگی کرتے ہیں، اور سستی مارکیٹ ہے جو آپ کو مشکلات بتاتی ہے۔</p>\n</div></div>\n<h2 id=\"margin-and-what-you-really-tie-up\">مارجن، اور جو آپ واقعی باندھتے ہیں۔</h2>\n<p>یہ ہے ایماندارانہ شکن جسے چھوٹا سا ڈیبٹ چھپاتا ہے۔ اگرچہ آپ جو نقدی کھو سکتے ہیں وہ صرف 88 سے 120 روپے ہے، لیکن ایکسچینج بلاکس کا مارجن کہیں زیادہ ہے، تقریباً <strong>تتلی کے لیے 63,628 روپے اور کنڈور کے لیے 63,757 روپے</strong>، کیونکہ ہر ڈھانچے میں فروخت شدہ کال ٹانگیں ہوتی ہیں جو نمائش پر مارجنڈ ہوتی ہیں۔ لہذا آپ کا حقیقی خطرہ معمولی ہے، لیکن آپ پھر بھی اس عہدے پر فائز رہنے کے لیے بامعنی سرمایہ باندھتے ہیں۔</p>\n<p>یہ فرق نئی شکل دیتا ہے کہ آپ واپسی کا فیصلہ کیسے کرتے ہیں۔ بٹر فلائی کا بہترین کیس، بلاک شدہ سرمائے کے 63,628 روپے کے مقابلے میں 6,380 روپے، تقریباً کے مارجن پر واپسی ہے۔ <strong>10 فیصد</strong> اگر یہ بالکل ٹھیک اترتا ہے، اور کنڈور کی قیمت 63،757 روپے کے مقابلے میں 3,162 روپے ہے۔ <strong>5 فیصد</strong>. یہ ٹھیک واپسی ہیں، لیکن یاد رکھیں کہ وہ دس میں سے صرف ایک بار آتے ہیں، یہی وجہ ہے کہ یہ اکاؤنٹ کے ایک چھوٹے سے کونے سے تعلق رکھتے ہیں، کبھی بھی چھوٹے یا مکمل سرمایہ کاری والے کے لیے بنیادی ہولڈنگ کے طور پر نہیں۔</p>\n<h2 id=\"time-decay\">وقت کا زوال</h2>\n<p>ٹھوس اورنج ایٹ-ایکسپائری لائن کے خلاف نیلی ڈیشڈ T+0 لائن کو دیکھیں۔ آج نیلی لکیر ایک نرم، گول کوبڑ ہے۔ صرف میعاد ختم ہونے پر ہی اورنج لائن لمبے خیمے میں تیز ہوجاتی ہے۔ یہ فرق وقت کی قدر ہے، اور ان ڈھانچے کے لیے وقت ایک مخصوص طریقے سے خاموش اتحادی ہے۔ اگر NIFTY پہلے سے ہی آپ کے ہدف کے قریب بیٹھا ہوا ہے جیسے جیسے میعاد ختم ہو رہی ہے، فروخت شدہ باڈی کالز ان کے بقیہ وقت کی قیمت کو خون بہا دیتی ہیں اور پوزیشن فرم اپنے عروج کی طرف جاتی ہے۔ اگر NIFTY ہدف کے قریب کہیں بھی نہیں ہے، تو وقت صرف چھوٹے ڈیبٹ کی میعاد ختم ہونے دیتا ہے، جس کی قیمت آپ کو تقریباً کچھ نہیں ہوتی۔ زوال صرف آپ کے لیے کام کرتا ہے جب قیمت بلسی پر پڑی ہو۔</p>\n<h2 id=\"butterfly-or-condor-and-when-to-use-either\">تتلی یا کنڈور، اور کب استعمال کرنا ہے۔</h2>\n<p>یہ وہی ٹول ہیں جو دو مختلف چوڑائیوں پر سیٹ کیے گئے ہیں، لہذا انتخاب اس بات کے بارے میں ہے کہ آپ لینڈنگ اسپاٹ کے بارے میں کتنے یقینی ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>تیز تتلی</th>\n<th>بلش کنڈور</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>خالص ڈیبٹ اور زیادہ سے زیادہ نقصان</td>\n<td>120 روپے</td>\n<td>88 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>6,380 روپے</td>\n<td>3,162 روپے</td>\n</tr>\n<tr>\n<td>رسک پر انعام</td>\n<td>1 سے 53</td>\n<td>1 سے 36</td>\n</tr>\n<tr>\n<td>منافع کا امکان</td>\n<td>تقریبا 10 فیصد</td>\n<td>تقریبا 10 فیصد</td>\n</tr>\n<tr>\n<td>بہترین جب</td>\n<td>آپ کے پاس ایک ہی درست ہدف ہے۔</td>\n<td>آپ کے پاس ایک چھوٹا ہدف زون ہے۔</td>\n</tr>\n</tbody></table>\n<p>یا تو صرف اس صورت میں پہنچیں جب آپ کے پاس واضح ہدف کی قیمت اور ایک واضح ختم ہو جائے، مثال کے طور پر آپ توقع کرتے ہیں کہ NIFTY تقریباً 24,150 تک پیس جائے گا اور مہینے کے آخر تک رک جائے گا۔ جسم کو اس ہدف پر رکھیں، داؤ کو چھوٹا رکھیں کیونکہ مشکلات آپ کے خلاف ہیں، اور نایاب بڑے معاوضے کو پلان کی بجائے بونس کے طور پر سمجھیں۔ اگر آپ کے پاس کوئی قطعی ہدف نہیں ہے تو، پہلے کے ابواب سے طے شدہ خطرے کا پھیلاؤ بہتر اور کہیں زیادہ قابل اعتماد تیزی کا آلہ ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>تنہائی میں خطرہ مول لینے کے لیے 1 سے 53 انعام کے بہکاوے میں نہ آئیں۔ منافع کا امکان صرف 10 فیصد ہے، اس لیے وسیع مارجن سے سب سے زیادہ ممکنہ نتیجہ یہ ہے کہ NIFTY ونڈو سے محروم ہوجاتا ہے اور آپ چھوٹے ڈیبٹ سے محروم ہوجاتے ہیں۔ یہ دائو سستے ہیں کیونکہ وہ شاذ و نادر ہی ادائیگی کرتے ہیں۔ ان کے ساتھ کبھی کبھار، کم داؤ والے پنٹس کے طور پر ایک درست نقطہ نظر پر برتاؤ کریں، پیسہ کمانے کے قابل اعتماد طریقے کے طور پر کبھی نہیں، اور ان کا سائز اس طرح رکھیں کہ چھوٹے نقصانات کا سلسلہ کبھی اہمیت نہ رکھتا ہو۔</p>\n</div></div>\n<h2 id=\"key-takeaways\">اہم نکات</h2>\n<ul>\n<li>ایک تیز تتلی ایک نچلی کال خریدتی ہے، دو باڈی کالز بیچتی ہے، اور ایک اونچی کال خریدتی ہے، یہ سب کچھ ایک چھوٹے کے لیے <strong>تقریباً 120 روپے کا خالص ڈیبٹ</strong>جو کہ پورا زیادہ سے زیادہ نقصان ہے۔</li>\n<li>ایک تیز کنڈور جسم کو دو فروخت شدہ ہڑتالوں میں پھیلاتا ہے a for a <strong>تقریباً 88 روپے کا خالص ڈیبٹ</strong>، ایک چوٹی کو ایک چھوٹی سطح مرتفع میں تبدیل کرنا۔</li>\n<li>زیادہ سے زیادہ منافع جسم پر یا سطح مرتفع کے اس پار اترتا ہے، <strong>تتلی کے لیے 6,380 روپے اور کنڈور کے لیے 3,162 روپے</strong>1 سے 53 اور 1 سے 36 کے خطرے کو شاندار انعام دینا۔</li>\n<li>دی <strong>منافع کا امکان صرف 10 فیصد ہے۔</strong> ہر ایک پر، کیونکہ NIFTY کو ایک تنگ ونڈو کے اندر ختم ہونا چاہیے۔ سستی ان طویل مشکلات کی مارکیٹ کی قیمتوں کا تعین ہے.</li>\n<li>اگرچہ نقدی کا نقصان بہت کم ہے، <strong>مارجن بلاک تقریباً 63,000 روپے ہے۔</strong> فروخت شدہ ٹانگوں کی وجہ سے ہر ایک پر، لہذا یہ دس میں سے ایک ادائیگی کے لئے حقیقی سرمایہ باندھتے ہیں۔</li>\n<li>ان کا استعمال اس وقت کریں جب آپ کے پاس ایک درست ہدف اور ایک واضح میعاد ختم ہو، داؤ کو چھوٹا رکھیں، اور آمدنی کی حکمت عملی کے لیے کبھی بھی سستے طویل شاٹ کی غلطی نہ کریں۔</li>\n</ul>\n","toc":[{"level":2,"text":"ایک لائن کا خیال","id":"the-one-line-idea"},{"level":2,"text":"تیزی کی تتلی، روپیہ بہ روپیہ","id":"the-bullish-butterfly-rupee-by-rupee"},{"level":2,"text":"تین نمبر، اور وہ کہاں سے آتے ہیں۔","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"میعاد ختم ہونے پر نتائج پر چلنا","id":"walking-the-outcomes-at-expiry"},{"level":2,"text":"تیزی کا کنڈور، روپیہ بہ روپیہ","id":"the-bullish-condor-rupee-by-rupee"},{"level":2,"text":"آپ کی مشکلات","id":"your-odds"},{"level":2,"text":"مارجن، اور جو آپ واقعی باندھتے ہیں۔","id":"margin-and-what-you-really-tie-up"},{"level":2,"text":"وقت کا زوال","id":"time-decay"},{"level":2,"text":"تتلی یا کنڈور، اور کب استعمال کرنا ہے۔","id":"butterfly-or-condor-and-when-to-use-either"},{"level":2,"text":"اہم نکات","id":"key-takeaways"}],"imgCount":2,"hasContent":true},"8":{"html":"<p>آپ نے سات ابواب تیزی کے ساتھ گزارے ہیں۔ اب دوربین کا رخ موڑ دیں۔ 24,056 پر NIFTY کی تصویر بنائیں اور تصور کریں کہ آپ کو لگتا ہے کہ یہ تھکا ہوا نظر آرہا ہے، کہ اگلا مہینہ کم ہو جائے گا، شاید 23,500 کی طرف۔ اس نقطہ نظر پر عمل کرنے کے دو خالص واحد ٹانگ طریقے ہیں، اور وہ ایک ہی دانو کے مخالف سمتوں پر بیٹھتے ہیں۔ آپ کر سکتے ہیں۔ <strong>ایک ڈال خریدیں</strong>,NIFTYگرنے پر منافع کے حق کے لیے ایک پریمیم ادا کرنا۔ یا آپ کر سکتے ہیں۔ <strong>ایک کال فروخت کریں</strong>، ایک پریمیم جمع کرنا اور شرط لگانا کہ NIFTY نہیں چڑھتا۔ یہ لانگ کال اور شارٹ پوٹ کے عین مطابق بیئرش آئینے ہیں جو آپ پہلے ملے تھے۔ ایک سب سے صاف، محفوظ ترین مندی کی تجارت ہے جو ایک ابتدائی شخص کر سکتا ہے۔ دوسرا اس پورے کورس میں سب سے خطرناک عہدوں میں سے ہے۔ یہ باب 26 جون 2026 کو حاصل کیے گئے حقیقی NIFTY ڈیٹا کے ساتھ ساتھ، دونوں کو سکھاتا ہے، اور اس بارے میں دو ٹوک ہے کہ کون سا ہے۔</p>\n<h2 id=\"the-one-line-idea\">ایک لائن کا خیال</h2>\n<p>اے <strong>طویل ڈال</strong> ایک مقررہ ہڑتال پر NIFTY کو فروخت کرنے کا حق خریدتا ہے، اس لیے جتنا انڈیکس گرتا ہے یہ زیادہ قیمتی ہوتا ہے۔ آپ ایک پریمیم ادا کرتے ہیں، وہ پریمیم سب سے زیادہ ہے جسے آپ کھو سکتے ہیں، اور آپ کا منافع بڑھتا ہے کیونکہ NIFTY ہڑتال سے نیچے گر جاتا ہے۔ اے <strong>مختصر کال</strong> اس کے برعکس تجارت ہے: آپ کسی اور کو ہڑتال پر NIFTY خریدنے کا حق بیچتے ہیں، آج ہی ایک پریمیم جمع کرتے ہیں، اور جب تک انڈیکس اس ہڑتال کے بعد بڑھنے میں ناکام ہوجاتا ہے اسے برقرار رکھیں۔ پوٹ کے خریدار کو بہت زیادہ پیچھا کرنے کے لئے تھوڑا سا خطرہ ہوتا ہے۔ کال بیچنے والا تھوڑا جمع کرتا ہے جبکہ بہت کچھ بے نقاب کرتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک لمبا پوٹ گرنے سے منافع کے حق کے لیے ایک پریمیم ادا کرتا ہے، جس میں نقصان کو پریمیم پر محدود کیا جاتا ہے۔ اگر مارکیٹ میں اضافہ نہیں ہوتا ہے تو ایک مختصر کال ایک پریمیم اور منافع جمع کرتی ہے، لیکن نقصان کی کوئی حد نہیں ہے۔ ایک وضاحت شدہ خطرہ اور ابتدائی طور پر محفوظ ہے۔ دوسرا ننگا اور خطرناک ہے۔ وہ تجارت کے مخالف فریقوں سے اسی مندی کے نقطہ نظر کا اظہار کرتے ہیں۔</p>\n</div></div>\n<h2 id=\"the-long-put-rupee-by-rupee\">لمبا پوٹ، روپیہ بہ روپیہ</h2>\n<p>آپ 28 جولائی 2026 کو ختم ہونے والی رقم 24,050 پوٹ خریدتے ہیں۔ یہ ایک ٹانگ ہے، لہذا آپ جو پریمیم ادا کرتے ہیں وہ پوری کہانی ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>ڈال خریدیں</td>\n<td>24,050</td>\n<td>295.1 ادا کیا گیا۔</td>\n<td><strong>19,182 روپے باہر</strong></td>\n</tr>\n</tbody></table>\n<p>295.1 ایک شیئر کا پریمیم کام کرتا ہے۔ <strong>19,182 روپے</strong> 65 کی ایک لاٹ کے لیے، اور وہ ڈیبٹ اسی وقت مارکیٹ میں آتا ہے جب آپ خریدتے ہیں۔ کیونکہ آپ سے کبھی بھی ایک روپیہ زیادہ نہیں مانگا جا سکتا ہے، ڈیبٹ بھی زیادہ سے زیادہ نقصان ہے، یہی وجہ ہے کہ طویل عرصے سے طے شدہ خطرے کی تجارت ہوتی ہے۔ ایکسچینج بلاکس کا مارجن صرف خود پریمیم ہے، 19,182 روپے، اور اس سے آگے کچھ نہیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-long-put.png\" alt=\"لانگ پوٹ پے آف: 24,050 سٹرائیک کے اوپر 19,182 روپے کا فلیٹ نقصان، 23,755 پر بریک ایون، اور منافع کی لکیر جو NIFTY گرتے ہی تیزی سے چڑھتی ہے، بیہوش سگما بینڈ کے ساتھ یہ ظاہر ہوتا ہے کہ آپشن مارکیٹ کی قیمتوں میں اضافہ ہو رہا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>لانگ پوٹ پے آف: 24,050 سٹرائیک کے اوپر 19,182 روپے کا فلیٹ نقصان، 23,755 پر بریک ایون، اور منافع کی لکیر جو کہ NIFTY گرتے ہی تیزی سے چڑھتی ہے، بیہوش سگما بینڈ کے ساتھ یہ ظاہر ہوتا ہے کہ آپشن مارکیٹ میں قیمتوں کا تعین ہو رہا ہے۔</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">تین نمبر، اور وہ کہاں سے آتے ہیں۔</h2>\n<p><strong>زیادہ سے زیادہ نقصان 19,182 روپے ہے، جو آپ نے ادا کیا ہے۔</strong> آپ اسے مکمل طور پر صرف اسی صورت میں ضائع کر سکتے ہیں جب NIFTY ایکسپائری پر 24,050 پر یا اس سے اوپر بند ہو جائے، جہاں پوٹ کی میعاد ختم ہو جاتی ہے۔</p>\n<p><strong>زیادہ سے زیادہ منافع 1,544,068 روپے ہے، نظریاتی حد۔</strong> اگر NIFTY صفر تک گر جاتا ہے، تو 24,050 پوٹ کی قیمت 24,050 پوائنٹس ہوگی، یعنی 24,050 گنا 65، جو کہ 1,563,250 روپے ہے، اور پریمیم کو گھٹانے کے بعد آپ 1,544,068 روپے صاف کریں گے۔ NIFTY کبھی بھی صفر تک نہیں پہنچے گا، اس لیے اس نمبر کو \"حقیقی کمی پر بہت بڑا\" کے لیبل کے طور پر پڑھیں، ہدف نہیں۔</p>\n<p><strong>Breakeven 23,755 ہے، اسٹرائیک مائنس پریمیم فی شیئر۔</strong> آپ نے 295 پوائنٹس ایک شیئر کی ادائیگی کی، اس لیے NIFTY کو 24,050 سٹرائیک کے نیچے 295 کو بند کرنا چاہیے، 23,755 پر، اس سے پہلے کہ پوٹ آپ کی جیب میں رقم ڈالنا شروع کرے۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>پریمیم ادا کیا</td>\n<td>19,182 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>اسٹرائیک پوائنٹس بار لاٹ، مائنس پریمیم</td>\n<td>24,050 گنا 65، جو کہ 1,563,250 روپے، مائنس 19,182 روپے، برابر ہے 1,544,068 روپے</td>\n</tr>\n<tr>\n<td>بریک ایون</td>\n<td>ہڑتال مائنس پریمیم فی شیئر</td>\n<td>24,050 مائنس 295 برابر 23,755</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-long-put-to-expiry\">لمبا پیدل چلنا ختم ہو جانا</h2>\n<p>پوٹ کو پانچ اختتامی سطحوں پر طے کریں اور چڑھنے کی ادائیگی ظاہر ہوگی۔ پوٹ 24,050 سے نیچے ختم ہونے والی ہر چیز کی قیمت ہے، اور اگر NIFTY اس سے اوپر ہے تو کچھ بھی نہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>24,050 آپ نے خریدا۔</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>24,200</td>\n<td>مالیت 0</td>\n<td>مائنس 19,182 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>مالیت 0</td>\n<td>مائنس 19,182 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>23,755</td>\n<td>مالیت 295</td>\n<td>تقریباً 0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>23,500</td>\n<td>مالیت 550</td>\n<td>علاوہ 16,568 روپے</td>\n</tr>\n<tr>\n<td>23,000</td>\n<td>مالیت 1,050</td>\n<td>علاوہ 49,068 روپے</td>\n</tr>\n</tbody></table>\n<p>ہڑتال کے اوپر آپ فلیٹ زیادہ سے زیادہ نقصان پر بیٹھتے ہیں، پریمیم اور مزید نہیں۔ 23,755 بریک ایون پر پوٹ بالکل ٹھیک ہو گیا ہے جو آپ نے ادا کیا تھا۔ اس کے نیچے، ہر پوائنٹ NIFTY آپ کے منافع میں 65 روپے کا اضافہ کرتا ہے، اور یہ مشکل NIFTY ڈراپس کو چڑھتا رہتا ہے۔ خطرے کا انعام ایک شاندار 1 سے 80 تک پڑھتا ہے، لیکن یہ ایک بہت بڑے، انتہائی غیر متوقع انعام کے خلاف ایک چھوٹا، مخصوص خطرہ جوڑتا ہے۔ ایماندار نمبر جو آپ کو گراؤنڈ رکھتا ہے۔ <strong>منافع کا امکان، تقریباً 38 فیصد</strong>: زیادہ تر مہینوں NIFTY کافی دور نہیں گرتا، اور پوٹ خاموشی سے سڑ جاتا ہے۔</p>\n<h2 id=\"the-short-call-rupee-by-rupee\">مختصر کال، روپیہ بہ روپیہ</h2>\n<p>اب دوسری طرف۔ زوال سے منافع کے لیے کوئی پوٹ خریدنے کے بجائے، آپ <strong>24,050 کال فروخت کریں۔</strong> اور جب آپ تجارت کھولیں گے تو اس کا پریمیم جمع کریں۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>کال فروخت کریں۔</td>\n<td>24,050</td>\n<td>425.8 موصول ہوا۔</td>\n<td><strong>علاوہ 27,677 روپے میں</strong></td>\n</tr>\n</tbody></table>\n<p>تم اندر لے لو <strong>27,677 روپے</strong> بہت کچھ کے لیے، اور یہ کریڈٹ سب سے زیادہ ہے جو آپ کبھی بنا سکتے ہیں۔ اگر NIFTY 24,050 پر یا اس سے نیچے بند ہوتا ہے تو آپ یہ سب اپنے پاس رکھتے ہیں، جہاں آپ کی فروخت کردہ کال کی میعاد ختم ہوجاتی ہے۔ دی <strong>بریک ایون 24,476 ہے۔</strong>، ہڑتال کے علاوہ 426 پوائنٹس ایک حصہ جو آپ نے جمع کیا ہے، اور <strong>منافع کا امکان آرام دہ 69 فیصد ہے۔</strong>، کیونکہ NIFTY کو صرف اس بریک ایون سے گزرنے سے بچنا ہے۔ وہ اعلی جیت کی شرح لالچ ہے۔ یہ ہے پکڑنے کا کریڈٹ چھپاتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک مختصر کال کا زیادہ سے زیادہ منافع 27,677 روپے اور زیادہ سے زیادہ نقصان جو کہ UNLIMITED ہے۔ آپ نے ایک بے نقاب کال فروخت کی ہے، لہذا ایک تیز ریلی آپ کو بریک ایون کے اوپر روپیہ کے بدلے خرچ کرتی ہے جس کی کوئی حد نہیں ہے۔ ایکسچینج یہ جانتا ہے، یہی وجہ ہے کہ یہ تقریباً 177,541 روپے کے مارجن کو روکتا ہے، جو آپ کے جمع کردہ کریڈٹ سے تقریباً سات گنا زیادہ ہے۔ یہ ایک ننگا شارٹ ہے، اور ایک ہی گیپ اپ ایک صبح میں جیتنے والی بہت سی تجارتوں کو مٹا سکتا ہے۔ ابتدائی طور پر اس کا احترام کرنے کے لیے اسے سمجھنا چاہیے۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-short-call.png\" alt=\"شارٹ کال کی ادائیگی: 24,050 سٹرائیک کے نیچے 27,677 روپے کا فلیٹ منافع، 24,476 پر بریک ایون، اور نقصان کی لکیر جو کہ NIFTY بڑھنے پر بغیر کسی حد کے گرتی ہے، ایک لمبی کال کی بالکل الٹا تصویر۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>شارٹ کال کی ادائیگی: 24,050 سٹرائیک کے نیچے 27,677 روپے کا فلیٹ منافع، 24,476 پر بریک ایون، اور نقصان کی لکیر جو NIFTY بڑھنے کے ساتھ بغیر کسی حد کے گرتی ہے، ایک لمبی کال کی بالکل الٹا تصویر۔</figcaption></figure>\n<h2 id=\"walking-the-short-call-to-expiry\">ایکسپائری کے لیے مختصر کال پر چلنا</h2>\n<p>مختصر کال کو پانچ سطحوں پر طے کریں اور بے پایاں دم کو کھلتا دیکھیں۔ آپ نے جو کال فروخت کی ہے اس کی قیمت 24,050 سے اوپر ختم ہونے والی کوئی بھی ہے، اور وہ قیمت آپ پر واجب الادا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>24,050 کال آپ نے فروخت کی۔</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,800</td>\n<td>مالیت 0</td>\n<td>جمع 27,677 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>مالیت 0</td>\n<td>جمع 27,677 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,476</td>\n<td>426 واجب الادا</td>\n<td>تقریباً 0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>24,700</td>\n<td>650 واجب الادا ہیں۔</td>\n<td>مائنس 14,573 روپے</td>\n</tr>\n<tr>\n<td>25,000</td>\n<td>950 واجب الادا</td>\n<td>مائنس 34,073 روپے</td>\n</tr>\n</tbody></table>\n<p>ہڑتال کے نیچے آپ 27,677 روپے کے اپنے فلیٹ زیادہ سے زیادہ منافع پر بیٹھتے ہیں۔ 24,476 بریک ایون سے گزر کر لائن خسارے میں جاتی ہے، اور وہاں سے یہ ہمیشہ کے لیے گرتی رہتی ہے۔ ٹیبل میں کوئی منزل نہیں ہے کیونکہ حقیقت میں کوئی منزل نہیں ہے: 25,000 پر آپ 34,073 روپے نیچے ہیں، 25,500 سے کہیں زیادہ، اور نقصان ہر پوائنٹ NIFTY چڑھنے کے ساتھ ہی بڑھتا ہے۔ لامحدود کا یہی معنی ہے۔</p>\n<h2 id=\"your-odds-side-by-side\">آپ کی مشکلات، شانہ بہ شانہ</h2>\n<p>دونوں تجارت خریدار بمقابلہ بیچنے والے کے سودے کے مخالف سروں پر بیٹھتے ہیں، اور ان کی مشکلات اسے صاف کہتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>لمبا ڈالنا</th>\n<th>مختصر کال</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>1,544,068 روپے</td>\n<td>27,677 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>19,182 روپے</td>\n<td>لا محدود</td>\n</tr>\n<tr>\n<td>بریک ایون</td>\n<td>23,755</td>\n<td>24,476</td>\n</tr>\n<tr>\n<td>منافع کا امکان</td>\n<td>38 فیصد</td>\n<td>69 فیصد</td>\n</tr>\n<tr>\n<td>رسک پر انعام</td>\n<td>1 سے 80</td>\n<td>NA</td>\n</tr>\n<tr>\n<td>خالص کریڈٹ یا ڈیبٹ</td>\n<td>ڈیبٹ روپے 19,182</td>\n<td>کریڈٹ 27,677 روپے</td>\n</tr>\n<tr>\n<td>مارجن درکار ہے۔</td>\n<td>19,182 روپے</td>\n<td>177,541 روپے</td>\n</tr>\n</tbody></table>\n<p>طویل پوٹ میں منافع کا کم امکان ہوتا ہے لیکن معلوم، معمولی لاگت اور اگر NIFTY واقعتاً گرتا ہے تو بہت زیادہ اضافہ ہوتا ہے۔ شارٹ کال میں منافع کا زیادہ امکان ہوتا ہے لیکن نقصان کے مقابلے میں ایک محدود انعام ہوتا ہے جو بغیر کسی حد کے بھاگ سکتا ہے، جس کے انعقاد کے لیے بڑے مارجن کا مطالبہ کیا جاتا ہے۔ ایک بہت کچھ کرنے کے لیے تھوڑا سا خطرہ مول لیتا ہے۔ دوسرا بہت کچھ بے نقاب کرتے ہوئے تھوڑا سا جمع کرتا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>ہمیشہ زیادہ سے زیادہ نقصان کے آگے نفع کے امکان کو پڑھیں، خود کبھی نہیں۔ شارٹ کال کا 69 فیصد لانگ پوٹ کے 38 فیصد سے بہتر لگتا ہے، پھر بھی یہ لامحدود نقصان اور 177,541 روپے کے مارجن بلاک کے ساتھ بیٹھا ہے، جبکہ پٹ کی سب سے بری صورت ٹکٹ پر چھپی ہوئی 19,182 روپے ہے۔ غیر محدود نقصان کے ساتھ جیت کی اعلی شرح یہ ہے کہ کس طرح نظم و ضبط والے اکاؤنٹس ایک ہی صبح میں ختم ہو جاتے ہیں۔</p>\n</div></div>\n<h2 id=\"margin-and-return\">مارجن اور واپسی</h2>\n<p>دونوں فریق سرمائے پر زیادہ مختلف نظر نہیں آ سکتے تھے۔ لانگ پوٹ صرف اس کا اپنا پریمیم بلاک کرتا ہے، <strong>19,182 روپے</strong>کیونکہ آپ اپنی ادائیگی سے زیادہ نہیں کھو سکتے، اس لیے مارجن زیادہ سے زیادہ نقصان کے بالکل برابر ہے۔ مختصر کال بلاکس <strong>177,541 روپے</strong> SPAN پلس ایکسپوژر کا، کیونکہ ایکسچینج کو اوپن اینڈڈ نقصان کو پورا کرنا چاہیے۔ اس بلاک کے خلاف ماپا گیا، شارٹ کال کا بہترین کیس 27,677 روپے کے مارجن پر واپسی ہے۔ <strong>16 فیصد</strong>، جو پرکشش لگتا ہے جب تک کہ آپ کو یاد نہ ہو کہ مماثلت کا خطرہ لا محدود ہے۔ پوٹ کا تعلق بہت کم ہے، لیکن ایک خریدار کے طور پر آپ کو اقتباس کرنے کے لیے مارجن پر کوئی واپسی نہیں ہے، صرف ایک بڑے ممکنہ انعام کے خلاف پریمیم خطرے میں ہے۔</p>\n<h2 id=\"time-decay\">وقت کا زوال</h2>\n<p>وقت دونوں تجارت کو مخالف سمتوں میں کھینچتا ہے، اور نیلی ڈیشڈ T+0 لائن اسے دکھاتی ہے۔ لمبے لمبے الفاظ میں، نیلی لائن اورنج ایٹ-ایکسپائری لائن کے اوپر بیٹھتی ہے، یعنی پوزیشن آج وقت کی قدر رکھتی ہے جو ختم ہونے کے قریب آتے ہی خون بہہ جاتی ہے۔ ہر پرسکون دن خریدار کو تھوڑا سا خرچ کرتا ہے، اس لیے لمبا پوٹ گھڑی سے لڑتا ہے اور اس کے پریمیم ختم ہونے سے پہلے اسے گرنے کے لیے NIFTY کی ضرورت ہوتی ہے۔ شارٹ کال پر، نیلی لائن منافع کی طرف اورنج لائن کے نیچے بیٹھتی ہے، کیونکہ آپ کی فروخت کردہ وقت کی قیمت ابھی تک آپ کے حق میں ختم نہیں ہوئی ہے۔ ہر پرسکون دن بیچنے والے کو چوٹی کی طرف کھینچتا ہے۔ زوال خریدار کا دشمن اور بیچنے والے کا دوست ہے، یہی وجہ ہے کہ خطرناک تجارت بھی پرکشش ہے۔</p>\n<h2 id=\"which-one-a-beginner-should-reach-for\">جس کے لیے ایک مبتدی کو پہنچنا چاہیے۔</h2>\n<p>اگر آپ کا ایماندارانہ نظریہ ہے کہ NIFTY گرتا ہے، تو اس تک پہنچیں۔ <strong>طویل ڈال</strong>. آپ کا آرڈر دینے سے پہلے ٹکٹ پر آپ کا بدترین کیس پرنٹ ہوتا ہے، 19,182 روپے اور ایک روپیہ زیادہ نہیں، اور مارجن اسی چھوٹے اعداد کے برابر ہے۔ آپ غلط ہو سکتے ہیں، پریمیم کھو سکتے ہیں، اور اپنے اکاؤنٹ کو برقرار رکھتے ہوئے چلے جا سکتے ہیں۔ بالکل اسی قسم کا خطرہ ایک سیکھنے والے کو لینا چاہیے۔</p>\n<p>دی <strong>مختصر کال</strong> ایک پیشہ ور کا آلہ ہے، نہ کہ ابتدائی کا۔ 69 فیصد جیت کی شرح اسے خوش کرتی ہے، لیکن یہ لامحدود نقصان اور بھاری مارجن بلاک کے مقابلے میں ایک چھوٹا، محدود انعام جوڑتا ہے۔ جس طرح سے تجربہ کار تاجر اس پر قابو پاتے ہیں وہ ہے ایک سستی، اعلیٰ کال کو تحفظ کے طور پر خریدنا، جو کہ برہنہ شارٹ کو متعین خطرے والے ریچھ کال اسپریڈ میں بدل دیتا ہے، جو اگلے ہی باب کا موضوع ہے۔ وہ واحد خریدا ہوا بازو \"لامحدود\" کو معلوم تعداد میں بدل دیتا ہے۔ آپ سینڈ باکس ٹریڈنگ میں دونوں تجارتوں کی مشق کر سکتے ہیں ( OpenAlgo میں تجزیہ کرنے والا موڈ)، ہر ایک ٹانگ کو رکھ کر اور اورنج لائن کو جھکاتے ہوئے دیکھ سکتے ہیں جب آپ ماڈل کی گئی قیمت کو جھکاتے ہیں۔</p>\n<h2 id=\"key-takeaways\">اہم نکات</h2>\n<ul>\n<li>ایک طویل پوٹ زوال سے منافع کے حق کے لیے ایک پریمیم ادا کرتا ہے۔ دی <strong>پریمیم، 19,182 روپے، پورا زیادہ سے زیادہ نقصان ہے۔</strong>، اور مارجن اس کے برابر ہے۔</li>\n<li>لانگ پوٹ کا بریک ایون ہے۔ <strong>اسٹرائیک مائنس پریمیم، 23,755</strong>، اور اس کے منافع کا امکان تقریباً 38 فیصد ہے، اس لیے اسے ادائیگی کے لیے حقیقی کمی کی ضرورت ہے۔</li>\n<li>ایک مختصر کال جمع کرتا ہے a <strong>اس کے زیادہ سے زیادہ منافع کے طور پر 27,677 روپے کا کریڈٹ</strong> اور اسے برقرار رکھتا ہے اگر NIFTY سٹرائیک پر یا نیچے رہتا ہے، منافع کے 69 فیصد امکان کے ساتھ۔</li>\n<li>مختصر کال ایک کی جاتی ہے۔ <strong>UNLIMITED نقصان</strong> اور بلاکس کے بارے میں <strong>177,541 روپے</strong> مارجن کا ایک ہی گیپ اپ بہت سی جیتنے والی تجارت کو کالعدم کر سکتا ہے۔</li>\n<li>وقت کا زوال دیرینہ دشمن اور شارٹ کال کا دوست ہے، یہی وجہ ہے کہ خطرناک تجارت بھی موہک ہے۔</li>\n<li>جب آپ ابھی بھی سیکھ رہے ہیں، کال بیچنے کے بجائے پوٹ خریدیں: آپ جیت کی بلند شرح کو ترک کر دیتے ہیں لیکن ایک مقررہ، زندہ رہنے کے قابل بدترین کیس حاصل کرتے ہیں۔</li>\n</ul>\n","toc":[{"level":2,"text":"ایک لائن کا خیال","id":"the-one-line-idea"},{"level":2,"text":"لمبا پوٹ، روپیہ بہ روپیہ","id":"the-long-put-rupee-by-rupee"},{"level":2,"text":"تین نمبر، اور وہ کہاں سے آتے ہیں۔","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"لمبا پیدل چلنا ختم ہو جانا","id":"walking-the-long-put-to-expiry"},{"level":2,"text":"مختصر کال، روپیہ بہ روپیہ","id":"the-short-call-rupee-by-rupee"},{"level":2,"text":"ایکسپائری کے لیے مختصر کال پر چلنا","id":"walking-the-short-call-to-expiry"},{"level":2,"text":"آپ کی مشکلات، شانہ بہ شانہ","id":"your-odds-side-by-side"},{"level":2,"text":"مارجن اور واپسی","id":"margin-and-return"},{"level":2,"text":"وقت کا زوال","id":"time-decay"},{"level":2,"text":"جس کے لیے ایک مبتدی کو پہنچنا چاہیے۔","id":"which-one-a-beginner-should-reach-for"},{"level":2,"text":"اہم نکات","id":"key-takeaways"}],"imgCount":2,"hasContent":true},"9":{"html":"<p>آخری باب نے آپ کو ایک پریشانی میں ڈال دیا۔ مختصر کال ایک پرکشش مندی کی تجارت ہے، منافع کا 69 فیصد موقع اور ایک موٹا کریڈٹ، لیکن اس میں لامحدود نقصان ہوتا ہے اور 177,541 روپے مارجن بلاک کا مطالبہ کرتا ہے۔ آپ گھر پر شرط لگائے بغیر مندی کا شکار ہونا چاہتے تھے۔ دی <strong>ریچھ کال پھیل گئی</strong> جواب ہے. یہ فروخت شدہ کال کو برقرار رکھتا ہے جو آپ کو ادائیگی کرتا ہے جب NIFTY پرسکون رہتا ہے یا گر جاتا ہے، اور اس میں ایک سیکنڈ کا اضافہ ہوتا ہے، تھوڑی اونچی خریدی گئی سستی کال جو کسی معلوم نمبر پر تباہی کو روکتی ہے۔ آپ اپنے نقصان پر سخت حد کے بدلے کریڈٹ کا ایک ٹکڑا واپس دیتے ہیں۔ یہ بیل پوٹ اسپریڈ کا بیئرش کریڈٹ اسپریڈ کزن ہے جس سے آپ پہلے ملے تھے: وہی متعین شدہ رسک، کریڈٹ اکٹھا کرنے کی شکل، بس کالز سے بنائی گئی اور مارکیٹ میں اضافہ نہ ہونے پر منافع کی طرف جھکاؤ۔ ایک مبتدی کے لیے جو بیئرش ویو پر پریمیم اکٹھا کرنا چاہتا ہے، یہ وہ تجارت ہے جو ننگی شارٹ کے ساتھ ہونی چاہیے تھی۔</p>\n<h2 id=\"the-one-line-idea\">ایک لائن کا خیال</h2>\n<p>اے <strong>ریچھ کال پھیل گئی</strong> ایک ہی میعاد ختم ہونے پر کال کے دو اختیارات ہیں۔ آپ <strong>ایک کم ہڑتال کال فروخت</strong> چربی کا پریمیم جمع کرنے کے لیے، وہ ٹانگ جو آپ کو ادائیگی کرتی ہے اگر NIFTY ہڑتال پر یا نیچے رہتا ہے، اور آپ <strong>ایک اعلی ہڑتال کال خریدیں</strong> ایک حقیقی ریلی کے خلاف سستی انشورنس کے طور پر۔ آپ فرق کو خالص کریڈٹ کے طور پر برقرار رکھتے ہیں، اور یہ کریڈٹ سب سے زیادہ ہے جو آپ کر سکتے ہیں۔ چونکہ خریدی گئی کال کیپس آپ کو کس حد تک نقصان پہنچا سکتی ہیں، اس لیے آپ جو زیادہ سے زیادہ کھو سکتے ہیں وہ بٹن پر کلک کرنے سے پہلے ہی طے شدہ اور معلوم ہوتا ہے۔</p>\n<p>آپ اسے استعمال کرتے ہیں جب آپ کا نقطہ نظر ہے <strong>معتدل مندی سے غیر جانبدار</strong>، یعنی آپ کو لگتا ہے کہ NIFTY گرے گا، فلیٹ رہے گا، یا بدترین عروج پر صرف تھوڑا ہی ہوگا۔ آپ کو حادثے کی ضرورت نہیں ہے۔ مشکل سے چڑھنے سے بچنے کے لیے آپ کو صرف NIFTY کی ضرورت ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>بیئر کال اسپریڈ کم کال فروخت کرتا ہے اور خالص کریڈٹ کے لیے زیادہ کال خریدتا ہے۔ آپ کو فائدہ ہوتا ہے اگر NIFTY آپ کی نچلی سٹرائیک پر یا اس سے نیچے رہتا ہے، تو آپ کو نقصان صرف اس صورت میں ہوتا ہے جب یہ آپ کی اونچی سٹرائیک سے آگے بڑھ جائے، اور نفع اور نقصان دونوں کی حد ہوتی ہے۔ یہ شرط ہے کہ بازار میں تیزی نہیں آئے گی، یہ شرط نہیں ہے کہ گر جائے گی۔</p>\n</div></div>\n<h2 id=\"the-real-trade-rupee-by-rupee\">اصل تجارت، روپیہ بہ روپیہ</h2>\n<p>یہ ہے حقیقی NIFTY قیمتوں پر درست تجارت، جو 26 جون 2026 کو 24,056 پر انڈیکس کے ساتھ کیپچر ہوئی اور 28 جولائی 2026 کو ختم ہونے میں تقریباً 32 دن باقی ہیں۔ ہم 24,050 کال پر پیسے بیچتے ہیں اور اوپر 24,150 کال ون سٹرائیک خریدتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>کال فروخت کریں۔</td>\n<td>24,050</td>\n<td>425.8 موصول ہوا۔</td>\n<td>علاوہ 27,677 روپے میں</td>\n</tr>\n<tr>\n<td>2</td>\n<td>کال خریدیں۔</td>\n<td>24,150</td>\n<td>370.1 ادا کیا گیا۔</td>\n<td>24,057 روپے باہر</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>نیٹ کریڈٹ</strong></td>\n<td><strong>علاوہ 3,624 روپے میں</strong></td>\n</tr>\n</tbody></table>\n<p>24,050 کال کے لیے آپ جو پریمیم وصول کرتے ہیں وہ اس پریمیم سے بڑا ہے جو آپ 24,150 کال کے لیے ادا کرتے ہیں، کیونکہ کم ہڑتال کی قیمت زیادہ ہے۔ وہ خلا آپ کا ہے۔ <strong>تقریباً 3,624 روپے کا خالص کریڈٹ</strong>اور جب آپ تجارت کھولتے ہیں تو یہ آپ کے اکاؤنٹ میں آتا ہے۔ یہی وجہ ہے کہ ریچھ کی کال اسپریڈ کو کریڈٹ اسپریڈ کہا جاتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bear-call-spread.png\" alt=\"NIFTY بیئر کال اسپریڈ: 24,050 سے نیچے 3,624 روپے کی فلیٹ منافع کی حد، 24,106 پر ایک بریک ایون، اور 24,150 سے اوپر 2,876 روپے کا محدود نقصان، نیلی ڈیشڈ T+0 لائن نارنجی ایکسپائری لائن کے نیچے بیٹھی ہے کیونکہ فروخت کا وقت ابھی باقی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY بیئر کال اسپریڈ: 24,050 سے نیچے 3,624 روپے کی فلیٹ منافع کی حد، 24,106 پر ایک بریک ایون، اور 24,150 سے اوپر 2,876 روپے کا محدود نقصان، نیلی ڈیشڈ T+0 لائن نارنجی ایکسپائری لائن کے نیچے بیٹھی ہے کیونکہ فروخت کا وقت ابھی باقی ہے۔</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">تین نمبر، اور وہ کہاں سے آتے ہیں۔</h2>\n<p>ہر نمبر براہ راست اوپر کی تجارت سے باہر آتا ہے، یاد رکھنے کی ضرورت نہیں ہے۔</p>\n<p><strong>زیادہ سے زیادہ منافع خالص کریڈٹ ہے، 3,624 روپے۔</strong> اگر NIFTY 24,050 سٹرائیک پر یا اس سے نیچے ختم ہو جاتا ہے، تو دونوں کالیں بیکار ختم ہو جاتی ہیں، جب انڈیکس سٹرائیک سے نیچے ہوتا ہے تو کوئی بھی کال نہیں کرتا، آپ پر کچھ واجب نہیں ہوتا، اور آپ پورا کریڈٹ رکھتے ہیں۔</p>\n<p><strong>زیادہ سے زیادہ نقصان اسپریڈ مائنس کریڈٹ، 2,876 روپے ہے۔</strong> اسپریڈ دو سٹرائیکس کے درمیان فرق ہے، 100 پوائنٹس، مالیت کا 100 گنا 65، جو کہ 6,500 روپے ہے۔ اگر NIFTY 24,150 سے اوپر جاتی ہے، تو دونوں کالز رقم میں ہیں اور آپ کے خلاف 100 پوائنٹ کا پورا فرق بند ہے۔ آپ وہ 6,500 روپے کھو دیتے ہیں، لیکن آپ پہلے ہی 3,624 روپے جیب میں ڈال چکے ہیں، لہذا آپ کا اصل نقصان 6,500 مائنس 3,624 ہے، جو <strong>2,876 روپے</strong>. خریدا ہوا کال وہی ہے جو اس سے پہلے بڑھتے ہوئے نقصان کو روکتا ہے۔</p>\n<p><strong>Breakeven کم سٹرائیک کے علاوہ کریڈٹ فی شیئر، 24,106 ہے۔</strong> آپ نے ایک شیئر میں تقریباً 56 پوائنٹس کریڈٹ جمع کیا۔ NIFTY 24,050 سٹرائیک سے 56 پوائنٹس بڑھ سکتا ہے، <strong>24,106</strong>اس سے پہلے کہ آپ کی مختصر کال پر ہونے والا نقصان پورا کریڈٹ کھا جائے۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>خالص کریڈٹ</td>\n<td>3,624 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>پھیلاؤ مائنس نیٹ کریڈٹ</td>\n<td>6,500 روپے مائنس 3,624 روپے 2,876 روپے کے برابر ہے۔</td>\n</tr>\n<tr>\n<td>بریک ایون</td>\n<td>کم ہڑتال پلس کریڈٹ فی شیئر</td>\n<td>24,050 جمع 56 برابر 24,106</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-outcomes-at-expiry\">میعاد ختم ہونے پر نتائج پر چلنا</h2>\n<p>اسپریڈ کو پانچ اختتامی قیمتوں پر طے کریں اور شکل خود ہی ظاہر ہوتی ہے۔ ہر کال اس کی سٹرائیک سے اوپر ختم ہونے والی ہر کال کی قیمت ہے، اور جو کچھ آپ نے بیچا وہ آپ پر واجب الادا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>24,050 کال آپ نے فروخت کی۔</th>\n<th>24,150 کال آپ نے خریدی۔</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,800</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>علاوہ 3,624 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>علاوہ 3,624 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,106</td>\n<td>56 واجب الادا</td>\n<td>مالیت 0</td>\n<td>تقریباً 0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>24,150</td>\n<td>100 واجب الادا ہیں۔</td>\n<td>مالیت 0</td>\n<td>مائنس 2,876 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>24,400</td>\n<td>350 واجب الادا</td>\n<td>مالیت 250</td>\n<td>مائنس 2,876 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n</tbody></table>\n<p>اسے صفحہ کے نیچے پڑھیں۔ 24,050 نیچے سے کہیں بھی آپ پورے 3,624 روپے اکٹھے کرتے ہیں، اور دیکھیں کہ یہ کام کرتا ہے یہاں تک کہ اگر NIFTY صرف ساکن ہو، نہ صرف یہ کہ گر جائے۔ 24,150 اوپر سے کہیں بھی آپ پورے 2,876 روپے کھو دیتے ہیں۔ دونوں سٹرائیکس کے درمیان نتیجہ ایک شیلف سے دوسرے شیلف پر پھسلتا ہے، صفر کو 24,106 پر عبور کرتا ہے۔ نیچے کی قطار کو دیکھیں: 24,400 پر فروخت شدہ کال 350 کی واجب الادا ہے جبکہ خریدی گئی کال 250 واپس کرتی ہے، خالص 100 پوائنٹس چھوڑ کر، پوری چوڑائی، یہی وجہ ہے کہ نقصان کبھی بھی 2,876 روپے سے آگے نہیں بڑھتا چاہے وہ کتنا ہی اونچا چلا جائے۔</p>\n<h2 id=\"your-odds\">آپ کی مشکلات</h2>\n<p>زیادہ سے زیادہ جاننا کہ آپ جیت سکتے ہیں اور ہار سکتے ہیں صرف آدھی کہانی ہے۔ وہ سوال جو فیصلہ کرتا ہے کہ آیا تجارت ہوشیار ہے کہ ہر نتیجہ کا کتنا امکان ہے۔ اس کے لیے پھیلاؤ <strong>منافع کا امکان تقریباً 53 فیصد ہے۔</strong>، سکوں کے پلٹنے سے بہتر ٹچ۔ یہ نمبر خود آپشن مارکیٹ سے آتا ہے: اتار چڑھاؤ کا استعمال کرتے ہوئے جس کی قیمت 12.7 فیصد ہے، اور 32 دن باقی ہیں، مارکیٹ کا مطلب یہ ہے کہ 53 فیصد موقع NIFTY ختم ہونے تک 24,106 بریک ایون سے نیچے ختم ہوجاتا ہے۔ چارٹ کو دوبارہ دیکھیں۔ بیہوش سگما بینڈ اس حرکت کو ظاہر کرتے ہیں جس کی مارکیٹ کی توقع ہے، اور 24,106 پر بریک ایون جگہ کے بالکل اوپر بیٹھا ہے، آرام سے اندرونی بینڈ کے اندر۔ NIFTY کو گرنے کی ضرورت نہیں ہے۔ اسے صرف ایک حقیقی ریلی سے بچنے کی ضرورت ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>ہمیشہ نفع کے امکان کے آگے زیادہ سے زیادہ نقصان پڑھیں، کبھی تنہا نہ ہوں۔ یہ اسپریڈ 3,624 روپے بنانے کے لیے 2,876 روپے کا خطرہ رکھتا ہے، لہذا یہاں محدود شدہ انعام دراصل محدود خطرے سے تھوڑا بڑا ہے، 1 سے 1.26 کے خطرے کا انعام، اور مشکلات آپ کے راستے پر 53 فیصد تک جھکتی ہیں۔ یہ مجموعہ، ایک سازگار ادائیگی اور آپ کی طرف سے وقت کے ساتھ مشکلات سے بھی بہتر، وہی ہے جو کریڈٹ اسپریڈ کو رکھنے کے قابل بناتا ہے۔</p>\n</div></div>\n<h2 id=\"margin\">مارجن</h2>\n<p>چونکہ آپ خالص فروخت کنندہ ہیں، ایکسچینج مارجن کو سیکورٹی کے طور پر روکتا ہے، یہاں کے بارے میں <strong>34,789 روپے</strong>، SPAN جزو کے علاوہ ایک نمائش بفر سے بنا ہے۔ خریدی گئی 24,150 کال اس نمبر کو چھوٹا رکھتی ہے۔ آخری باب کی ننگی مختصر کال نے 177,541 روپے کا معاہدہ کیا۔ یہ پھیلاؤ، اسی مندی کے موقف کے ساتھ، اس کا تقریباً پانچواں حصہ روکتا ہے، کیونکہ حفاظتی ونگ ایکسچینج کے لیے بدترین صورت حال کی وضاحت کرتا ہے۔ وہ ایک خریدی ہوئی ٹانگ ڈبل ڈیوٹی کرتی ہے: یہ آپ کے نقصان کو 2,876 روپے تک محدود کرتی ہے اور اس سے تجارت کی ضرورت کے سرمائے میں کمی آتی ہے۔</p>\n<p>یہ مارجن آپ کو مارجن پر واپسی کے ذریعے دیانتداری سے تجارت کا فیصلہ کرنے دیتا ہے۔ آپ تقریباً ایک ماہ کے لیے بلاک کیے گئے 34,789 روپے کے مقابلے میں 3,624 روپے کمانے کے لیے کھڑے ہیں، جو کہ تقریباً ہے۔ <strong>خطرے میں دارالحکومت پر 10 فیصد</strong> اگر تجارت کام کرتی ہے۔ یہ پیداوار، خام کریڈٹ نہیں، وہ تعداد ہے جو ایک سنجیدہ تاجر تمام خیالات میں موازنہ کرتا ہے۔</p>\n<h2 id=\"time-decay\">وقت کا زوال</h2>\n<p>ایک بار پھر چارٹ کو دیکھیں، نیلے رنگ کے ڈیشڈ T+0 لائن پر جو منافع کی طرف ٹھوس اورنج ایٹ-ایکسپائری لائن کے نیچے بیٹھی ہے۔ یہ فرق وقت کی قدر ہے، اور خالص بیچنے والے کے لیے یہ ایک تحفہ ہے۔ ہر پرسکون دن آپ کی کال میں تھوڑا سا پریمیم پگھل جاتا ہے، اور نیلی لکیر نارنجی کی طرف آ جاتی ہے۔ آپ نے سامنے کریڈٹ جمع کیا، اور وقت خاموشی سے اسے حقیقی منافع میں بدل دیتا ہے جب تک کہ NIFTY برتاؤ کرتا ہے۔ ایک طویل آپشن خریدار ہر روز اس کشی کا مقابلہ کرتا ہے۔ کریڈٹ اسپریڈ بیچنے والے کے طور پر، آپ کو اس کے ذریعے ادائیگی کی جاتی ہے۔</p>\n<h2 id=\"bear-call-spread-or-long-put\">ریچھ کال پھیلاؤ یا طویل ڈال دیا؟</h2>\n<p>آپ نے لمبے لمبے آخری باب سے ملاقات کی، اور جب NIFTY گرتا ہے تو اس کا فائدہ بھی ہوتا ہے، تو آپ کس کا انتخاب کرتے ہیں؟ ایماندارانہ جواب یہ ہے کہ وہ مختلف خیالات کے مطابق ہیں۔ لانگ پوٹ ایک ڈیبٹ ٹریڈ ہے جو سخت، تیزی سے زوال پر اچھی طرح سے ادائیگی کرتا ہے، کیونکہ اس کا منافع مزید NIFTY کی کمی پر چڑھتا رہتا ہے۔ بیئر کال اسپریڈ آپ کے انعام کو 3,624 روپے کے معمولی کریڈٹ پر محدود کر دیتی ہے اس سے کوئی فرق نہیں پڑتا ہے کہ NIFTY کتنی دور تک گرتا ہے، لیکن یہ آپ کو ادائیگی کرتا ہے یہاں تک کہ اگر انڈیکس محض کہیں بھی نہیں جاتا ہے، اور وقت کی کمی آپ کے حق میں کام کرتی ہے۔</p>\n<p>تک پہنچیں۔ <strong>ریچھ کال پھیل گئی</strong> جب آپ کو لگتا ہے کہ الٹا ختم ہو گیا ہے لیکن آپ کو آتش بازی کی توقع نہیں ہے، اور آپ اپنی طرف وقت چاہتے ہیں۔ تک پہنچیں۔ <strong>طویل ڈال</strong> جب آپ ایک حقیقی، تیز کمی کی توقع کرتے ہیں اور اس کے ساتھ آنے والی کھلی ادائیگی چاہتے ہیں۔ پھیلاؤ کہتا ہے \"ریلی ختم ہو گئی ہے\"؛ پوٹ کہتا ہے \"زوال آ رہا ہے\"۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>متعین خطرہ چھوٹے خطرے کی طرح نہیں ہے۔ 2,876 روپے فی لاٹ اصلی رقم ہے، اور اگر NIFTY 24,150 پر یا اس سے اوپر بند ہوتا ہے تو آپ یہ سب کھو دیتے ہیں، جسے ایک مضبوط اپ دن فراہم کر سکتا ہے۔ ہمیشہ زیادہ سے زیادہ نقصان کے لیے سائز کریں، کبھی کریڈٹ کے لیے نہیں۔ فیصلہ کریں کہ اگر انڈیکس آپ کے خلاف ہوتا ہے تو آپ کتنا کھونے کے متحمل ہو سکتے ہیں، پھر گنیں کہ کتنی لاٹیں اجازت دیتی ہیں۔</p>\n</div></div>\n<h2 id=\"key-takeaways\">اہم نکات</h2>\n<ul>\n<li>ایک بیئر کال اسپریڈ کم کال کو فروخت کرتا ہے اور a کے لیے زیادہ کال خریدتا ہے۔ <strong>خالص کریڈٹ</strong>, منافع بخش اگر NIFTY نچلی سٹرائیک پر یا اس سے نیچے رہتا ہے۔</li>\n<li><strong>زیادہ سے زیادہ منافع خالص کریڈٹ ہے۔</strong> (یہاں 3,624 روپے) <strong>زیادہ سے زیادہ نقصان اسپریڈ مائنس کریڈٹ ہے۔</strong> (2,876 روپے)، اور <strong>breakeven لوئر سٹرائیک پلس کریڈٹ ہے۔</strong> (24,106).</li>\n<li>یہاں محدود انعام محدود خطرے سے تھوڑا بڑا ہے، a <strong>1 سے 1.26 کے خطرے کا انعام</strong>، ایک کے ساتھ <strong>53 فیصد منافع کا امکان</strong> اور آپ کی طرف وقت کی کمی.</li>\n<li>یہ بلاک کرتا ہے۔ <strong>تقریباً 34,789 روپے کا مارجن</strong>, ننگ شارٹ کال کے بلاک کا تقریباً پانچواں حصہ، کیونکہ خریدا ہوا ونگ بدترین صورت کی وضاحت کرتا ہے۔ اس کی طرف سے فیصلہ کریں <strong>مارجن پر واپسی، تقریباً 10 فیصد</strong>.</li>\n<li>یہ بیل پوٹ اسپریڈ کا بیئرش کریڈٹ اسپریڈ کزن ہے: وہی ڈیفائنڈ رسک، کریڈٹ اکٹھا کرنے والی شکل، کالز سے بنائی گئی ہے۔</li>\n<li>جب آپ کو توقع ہے کہ NIFTY کریش کے بجائے رک جائے گا، اور آپ انتظار کرنے کے لیے ادائیگی کرنا چاہتے ہیں۔</li>\n</ul>\n","toc":[{"level":2,"text":"ایک لائن کا خیال","id":"the-one-line-idea"},{"level":2,"text":"اصل تجارت، روپیہ بہ روپیہ","id":"the-real-trade-rupee-by-rupee"},{"level":2,"text":"تین نمبر، اور وہ کہاں سے آتے ہیں۔","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"میعاد ختم ہونے پر نتائج پر چلنا","id":"walking-the-outcomes-at-expiry"},{"level":2,"text":"آپ کی مشکلات","id":"your-odds"},{"level":2,"text":"مارجن","id":"margin"},{"level":2,"text":"وقت کا زوال","id":"time-decay"},{"level":2,"text":"ریچھ کال پھیلاؤ یا طویل ڈال دیا؟","id":"bear-call-spread-or-long-put"},{"level":2,"text":"اہم نکات","id":"key-takeaways"}],"imgCount":1,"hasContent":true},"10":{"html":"<p>زیادہ تر لوگ جو NIFTY پر مندی کا شکار ہو جاتے ہیں وہ براہ راست پوٹ کے لیے پہنچ جاتے ہیں، فیٹ پریمیم ادا کرتے ہیں، اور پھر صرف بریک ایون تک پہنچنے کے لیے حقیقی پلنگ کی ضرورت ہوتی ہے۔ ریچھ پوٹ اسپریڈ اسی جبلت کا نظم و ضبط ورژن ہے۔ آپ اب بھی گرنے سے منافع کے لیے ایک پوٹ خریدتے ہیں، لیکن آپ زیادہ تر لاگت کو واپس کرنے کے لیے ایک سیکنڈ، کم پوٹ بیچتے ہیں، اس لیے آپ کا ٹکٹ سستا ہے اور آپ کا بریک ایون آج کی قیمت کے بہت قریب ہے۔ آپ حادثے پر لامحدود ونڈ فال کا خواب ترک کر دیتے ہیں، اور اس کے بدلے میں آپ کو ایک عام کمی پر ایک متعین، سستی، اور کہیں زیادہ ممکنہ ادائیگی ملتی ہے۔ یہ باب حقیقی NIFTY قیمتوں پر تجارت کی تشکیل کرتا ہے، یہ ظاہر کرتا ہے کہ ہر روپیہ کہاں سے آتا ہے، اور آپ کو تین جہتیں فراہم کرتا ہے جن کو زیادہ تر وضاحت کرنے والے نظر انداز کرتے ہیں: مشکلات، مارجن، اور ڈیبٹ تجارت پر وقت دبانے کا طریقہ۔</p>\n<h2 id=\"the-one-line-idea\">ایک لائن کا خیال</h2>\n<p>اے <strong>ریچھ پھیل گیا</strong> ایک ہی ایکسپائری پر دو پوٹ آپشنز ہیں۔ آپ <strong>ایک اعلی ہڑتال خریدیں</strong> NIFTY گرنے کے ساتھ حاصل کرنے کے لیے، اور آپ <strong>ایک کم ہڑتال ڈال فروخت</strong> زیادہ تر لاگت واپس لینے کے لیے۔ جو آپ بیلنس پر ادا کرتے ہیں وہ ہے a <strong>خالص ڈیبٹ</strong>, اور چونکہ آپ اپنی ادا کردہ رقم سے زیادہ قرضدار نہیں ہو سکتے، اس لیے وہ ڈیبٹ بھی سب سے زیادہ ہے جسے آپ کھو سکتے ہیں۔ اسٹرائیکس مائنس کے درمیان جو آپ نے ادا کیا ہے اس پر انعام بھی محدود ہے۔</p>\n<p>آپ اسے استعمال کرتے ہیں جب آپ کا نقطہ نظر ہے <strong>اعتدال پسند مندی</strong>، یعنی آپ کو NIFTY کے گرنے کی توقع ہے، لیکن پہاڑ سے گرنے کی بجائے ایک سمجھدار سطح پر۔ آپ گرنے کی ادائیگی نہیں کر رہے ہیں۔ آپ کو صرف ایک پیمائش شدہ سلائیڈ کی ضرورت ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>بیئر پوٹ اسپریڈ زیادہ پوٹ خریدتا ہے اور خالص ڈیبٹ کے لیے کم پوٹ فروخت کرتا ہے۔ آپ کو فائدہ ہوتا ہے اگر NIFTY آپ کی اونچی سٹرائیک سے نیچے آجاتا ہے، تو آپ کا فائدہ محدود ہو جاتا ہے جب یہ آپ کی نچلی سٹرائیک سے گزر جاتا ہے، اور آپ کا نقصان آپ کے ادا کردہ ڈیبٹ پر محدود ہو جاتا ہے۔ یہ کریڈٹ اور سیل بیئر کال اسپریڈ کا ڈیبٹ اور خرید کا آئینہ ہے، جو خاموشی سے بڑھنے کے بجائے ایک فعال زوال تک پہنچتا ہے۔</p>\n</div></div>\n<h2 id=\"the-real-trade-rupee-by-rupee\">اصل تجارت، روپیہ بہ روپیہ</h2>\n<p>26 جون 2026 کو انڈیکس کے ساتھ حاصل کی گئی حقیقی NIFTY قیمتوں پر درست تجارت یہ ہے۔ <strong>24,056</strong> اور 28 جولائی 2026 کو ختم ہونے میں تقریباً 32 دن باقی ہیں۔ ہم 24,050 پوٹ پر رقم خریدتے ہیں اور 23,950 پوٹ ون سٹرائیک نیچے فروخت کرتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>ڈال خریدیں</td>\n<td>24,050</td>\n<td>295.1 ادا کیا گیا۔</td>\n<td>19,182 روپے باہر</td>\n</tr>\n<tr>\n<td>2</td>\n<td>ڈال فروخت</td>\n<td>23,950</td>\n<td>256.6 موصول ہوا۔</td>\n<td>علاوہ 16,676 روپے میں</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>خالص ڈیبٹ</strong></td>\n<td><strong>2,506 روپے باہر</strong></td>\n</tr>\n</tbody></table>\n<p>اکیلے 24,050 پوٹ پر پورے 19,182 روپے لاگت آئے گی۔ 23,950 پوٹ ون سٹرائیک لوئر فروخت کرنے سے 16,676 روپے ملتے ہیں، جو اس بل کا زیادہ تر حصہ ادا کرتا ہے اور ایک چھوڑ دیتا ہے۔ <strong>2,506 روپے کا خالص ڈیبٹ</strong>. جب آپ تجارت کھولتے ہیں تو آپ اسے جیب سے ادا کرتے ہیں، اور آپ سے کبھی دوسرا روپیہ نہیں مانگا جا سکتا ہے۔ یہی وجہ ہے کہ ریچھ پوٹ اسپریڈ کو کہا جاتا ہے۔ <strong>ڈیبٹ پھیلاؤ</strong>.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bear-put-spread.png\" alt=\"اصلی NIFTY بیئر پوٹ اسپریڈ: 23,950 سے نیچے 3,994 روپے کا فلیٹ پرافٹ شیلف، 24,050 سے اوپر 2,506 روپے کا فلیٹ نقصان کا شیلف، اور اسپاٹ کے بالکل نیچے 24,011 پر سنگل بریک ایون۔ NIFTY گرنے کے ساتھ ہی اورنج ایٹ-ایکسپائری لائن منافع میں چڑھ جاتی ہے۔ نیلی ڈیشڈ T+0 لائن آج کی قیمت کے قریب اس کے اوپر بیٹھی ہے کیونکہ خریدا ہوا پوٹ اب بھی وقت کی قدر رکھتا ہے جو ابھی تک ختم نہیں ہوا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>اصلی NIFTY بیئر پوٹ اسپریڈ: 23,950 سے نیچے 3,994 روپے کا فلیٹ پرافٹ شیلف، 24,050 سے اوپر 2,506 روپے کا فلیٹ نقصان کا شیلف، اور اسپاٹ کے بالکل نیچے 24,011 پر سنگل بریک ایون۔ NIFTY گرنے کے ساتھ ہی اورنج ایٹ-ایکسپائری لائن منافع میں چڑھ جاتی ہے۔ نیلی ڈیشڈ T+0 لائن آج کی قیمت کے قریب اس کے اوپر بیٹھی ہے کیونکہ خریدا ہوا پوٹ اب بھی وقت کی قدر رکھتا ہے جو ابھی تک ختم نہیں ہوا ہے۔</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">تین نمبر، اور وہ کہاں سے آتے ہیں۔</h2>\n<p>ہر بیئر پوٹ اسپریڈ کو تین نمبروں سے نیچے کیا جاتا ہے، اور ہر ایک سیدھا اوپر کی تجارت سے باہر ہو جاتا ہے۔ منطق کو ایک بار پڑھیں اور آپ کو انہیں کبھی یاد کرنے کی ضرورت نہیں ہے۔</p>\n<p><strong>زیادہ سے زیادہ نقصان خالص ڈیبٹ ہے، 2,506 روپے۔</strong> اگر NIFTY 24,050 اسٹرائیک پر یا اس سے اوپر کہیں بھی ختم ہوجاتا ہے، تو دونوں پوٹس بیکار ختم ہوجاتے ہیں۔ جب انڈیکس اسٹرائیک کے اوپر بیٹھتا ہے تو کوئی بھی پٹ کی مشق نہیں کرتا ہے۔ آپ صرف اس چیز کو کھو دیتے ہیں جو آپ نے ادا کی ہے، اور یہ تجارت سب سے بری چیز ہے۔</p>\n<p><strong>زیادہ سے زیادہ منافع اسپریڈ مائنس ڈیبٹ ہے، 3,994 روپے۔</strong> اسپریڈ دو سٹرائیکس کے درمیان فرق ہے، 100 پوائنٹس، مالیت کا 100 گنا 65، جو کہ 6,500 روپے ہے۔ اگر NIFTY 23,950 سے نیچے آتا ہے، تو دونوں پوٹس پیسے میں گہرے ہیں اور مکمل 100 پوائنٹ کا فرق آپ کے حق میں بند ہے۔ آپ وہ 6,500 روپے جمع کرتے ہیں، لیکن آپ نے داخل ہونے کے لیے پہلے ہی 2,506 روپے ادا کر دیے ہیں، لہذا آپ کا خالص فائدہ 6,500 مائنس 2,506 ہے، جو کہ <strong>3,994 روپے</strong>. فروخت شدہ پوٹ وہ ہے جو یہاں انعام کو محدود کرتا ہے، اور ہمیشہ کی طرح عمودی پھیلاؤ کے ساتھ، زیادہ سے زیادہ نفع اور زیادہ سے زیادہ نقصان پوری اسٹرائیک چوڑائی میں شامل ہوتا ہے۔</p>\n<p><strong>Breakeven زیادہ سٹرائیک مائنس ڈیبٹ فی شیئر، 24,011 ہے۔</strong> آپ نے 38.55 پوائنٹس فی شیئر ادا کیا۔ NIFTY کو 24,050 سٹرائیک سے 38.55 پوائنٹس نیچے گرنا پڑا، <strong>24,011</strong>، اس سے پہلے کہ خریدا ہوا پوٹ واپس حاصل کر لے جو آپ نے پوزیشن کے لئے ادا کیا تھا۔ 24,011 سے نیچے آپ منافع میں ختم کرتے ہیں۔ اس کے اوپر آپ خسارے میں ختم ہوتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>خالص ڈیبٹ</td>\n<td>2,506 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>مائنس خالص ڈیبٹ پھیلائیں۔</td>\n<td>6,500 روپے مائنس 2,506 روپے = 3,994 روپے</td>\n</tr>\n<tr>\n<td>بریک ایون</td>\n<td>زیادہ ہڑتال مائنس ڈیبٹ فی شیئر</td>\n<td>24,050 منفی 38.55 = 24,011</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-outcomes-at-expiry\">میعاد ختم ہونے پر نتائج پر چلنا</h2>\n<p>کسی حکمت عملی پر بھروسہ کرنے کا سب سے یقینی طریقہ یہ ہے کہ اسے مٹھی بھر بند قیمتوں پر طے کیا جائے اور رقم کی منتقلی کو دیکھیں۔ یہ ہے ایکسپائری ڈے پر NIFTY کی پانچ سطحوں پر بیئر پوٹ پھیلا ہوا ہے، فی لاٹ 65۔ ایک پوٹ کی قیمت زیادہ سے زیادہ ہے (اسٹرائیک مائنس NIFTY، 0)۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>24,050 آپ نے خریدا۔</th>\n<th>23,950 میں آپ نے فروخت کیا۔</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,800</td>\n<td>مالیت 250</td>\n<td>150 کی مالیت</td>\n<td>علاوہ 3,994 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>23,950</td>\n<td>100 کی مالیت</td>\n<td>مالیت 0</td>\n<td>علاوہ 3,994 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,011</td>\n<td>مالیت 39</td>\n<td>مالیت 0</td>\n<td>0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مائنس 2,506 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>24,300</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مائنس 2,506 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n</tbody></table>\n<p>ٹیبل کو پڑھیں اور شکل خود کو کھینچتی ہے۔ 23,950 نیچے سے کہیں بھی آپ پورے 3,994 روپے اکٹھے کر لیتے ہیں، کیونکہ ہر ایک اضافی پوائنٹ جو آپ نے بیچا ہے اس کے ذریعے حاصل کیا جاتا ہے۔ 24,050 اوپر سے کہیں بھی آپ پورے 2,506 روپے کھو دیتے ہیں۔ دونوں سٹرائیکس کے درمیان نتیجہ ایک شیلف سے دوسرے شیلف پر آسانی سے پھسلتا ہے، صفر کو 24,011 پر عبور کرتا ہے۔ یہ پوری ادائیگی ہے، اور یہ چارٹ پر موجود اورنج لائن سے بالکل مماثل ہے۔</p>\n<h2 id=\"your-odds\">آپ کی مشکلات</h2>\n<p>زیادہ سے زیادہ جاننا کہ آپ جیت سکتے ہیں اور ہار سکتے ہیں صرف آدھی کہانی ہے۔ سوال جو فیصلہ کرتا ہے کہ آیا تجارت ہوشیار ہے، ہر ایک کے نتائج کا کتنا امکان ہے؟ وہ ہے <strong>منافع کا امکان</strong>، یا POP، اور بلڈر اسے سیدھے پینل پر پرنٹ کرتا ہے۔</p>\n<p>اس کے لیے پھیلاؤ <strong>POP تقریباً 49 فیصد ہے۔</strong>، سکے کے پلٹنے کے قریب۔ یہ اعداد و شمار آپشن مارکیٹ سے ہی آتا ہے۔ NIFTY اختیارات میں قیمت کے اتار چڑھاؤ کا استعمال کرتے ہوئے، تقریباً 12.7 فیصد، اور 32 دن باقی ہیں، مارکیٹ کا مطلب یہ ہے کہ 49 فیصد امکان ہے کہ NIFTY ایکسپائری کے ذریعے 24,011 بریک ایون سے نیچے ختم ہوجائے۔ چارٹ کو دوبارہ دیکھیں۔ بیہوش سایہ دار <strong>سگما بینڈ</strong> مارکیٹ کی توقع کے مطابق حرکت دکھائیں، اور 24,011 پر بریک ایون اندرونی بینڈ کے اندر آرام سے 24,056 کی جگہ سے صرف 45 پوائنٹ نیچے بیٹھا ہے۔ تم کوئی معجزہ نہیں مانگ رہے ہو۔ آپ ایک چھوٹا سا قدم چھوڑنے کے لیے کہہ رہے ہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>ہمیشہ زیادہ سے زیادہ نقصان کے ساتھ POP پڑھیں، کبھی اکیلے نہیں۔ یہ اسپریڈ 3,994 روپے بنانے کے لیے 2,506 روپے کا خطرہ رکھتا ہے، جو کہ رسک سے بڑا انعام ہے، لیکن یہ آدھے وقت سے تھوڑا کم ہی جیتتا ہے کیونکہ اسے درحقیقت گرنے کے لیے NIFTY کی ضرورت ہوتی ہے۔ ڈیبٹ اسپریڈ کریڈٹ اسپریڈ کے برعکس سودا ہوتا ہے: آپ اپنی پیش کردہ رقم سے زیادہ ادائیگی کے بدلے بدتر مشکلات کو قبول کرتے ہیں۔ POP یہ ہے کہ آپ کس طرح تصدیق کرتے ہیں کہ تجارت لینے کے قابل ہے۔</p>\n</div></div>\n<h2 id=\"margin\">مارجن</h2>\n<p>چونکہ ہر ٹانگ کی تعریف کی گئی ہے اور آپ کے نقصان کو ڈیبٹ پر محدود کیا گیا ہے، ایکسچینج صرف تھوڑا سا روکتا ہے۔ <strong>مارجن</strong> کے بارے میں <strong>34,113 روپے</strong> اس پوزیشن کو برقرار رکھنے کے لئے. فروخت شدہ پٹ وہی ہے جو اس تعداد کو چھوٹا رکھتا ہے۔ ایک لون لانگ پوٹ بالکل اپنے پریمیم کو جوڑتا ہے، لیکن اس کو اسپریڈ کے اندر جوڑنا، ایک خریدی اور ایک بیچی ہوئی ٹانگ کے ساتھ ایکسچینج ایک دوسرے کے خلاف جا سکتا ہے، سرمایہ کو صاف رکھتا ہے۔</p>\n<p>یہ مارجن آپ کو تجارت کا ایمانداری سے فیصلہ کرنے دیتا ہے۔ <strong>مارجن پر واپسی</strong>. آپ تقریباً ایک ماہ کے لیے بلاک کیے گئے 34,113 روپے کے مقابلے میں 3,994 روپے کمانے کے لیے کھڑے ہیں، جو کہ تقریباً ہے۔ <strong>خطرے میں دارالحکومت پر 11.7 فیصد</strong> اگر تجارت کام کرتی ہے۔ یہ واپسی، خام روپے کا نہیں، وہ نمبر ہے جو ایک سنجیدہ تاجر ایک ہی سرمائے کے لیے مقابلہ کرنے والے ہر دوسرے آئیڈیا کے خلاف کھڑا ہے۔</p>\n<h2 id=\"time-decay\">وقت کا زوال</h2>\n<p>چارٹ پر ایک بار پھر دیکھیں <strong>نیلی ڈیشڈ T+0 لائن</strong> موجودہ قیمت کے قریب ٹھوس اورنج ایٹ ایکسپائری لائن کے اوپر بیٹھا ہے۔ وہ خلا ہے۔ <strong>وقت کی قدر</strong>اور خالص خریدار کے لیے یہ تحفہ کے بجائے سست روی ہے۔ آج کے 24,056 کے اسپاٹ پر تجارت ختم ہونے پر اپنے زیادہ سے زیادہ نقصان والے شیلف پر بیٹھی ہے، پھر بھی بلیو لائن ابھی ایک چھوٹا نقصان دکھاتی ہے، کیونکہ خریدا گیا 24,050 پوٹ ابھی بھی ٹائم پریمیم رکھتا ہے۔ جیسے جیسے پرسکون دن گزرتے ہیں، وہ پریمیم پگھل جاتا ہے اور نیلی لائن نارنجی فرش کی طرف دھنس جاتی ہے۔</p>\n<p>صاف لفظوں میں، کچھ بھی کرنے سے آپ کی قیمت نہیں لگتی۔ ہر پرسکون دن جو NIFTY گرنے سے انکار کرتا ہے آپ کی ملکیت میں سے تھوڑا سا خون بہہ جاتا ہے، اور وقت کا زوال آہستہ آہستہ پوزیشن کو اپنے زیادہ سے زیادہ نقصان کی طرف کھینچتا ہے۔ کریڈٹ اسپریڈ بیچنے والے کو گھڑی کے حساب سے ادائیگی کی جاتی ہے۔ ڈیبٹ اسپریڈ خریدار کے طور پر، آپ اس کی دوڑ لگا رہے ہیں، اس لیے آپ چاہتے ہیں کہ آپ کا زوال آخری دن پر نہیں بلکہ اچھے وقت پر پہنچے۔</p>\n<h2 id=\"choosing-your-strikes\">اپنی ہڑتالوں کا انتخاب کرنا</h2>\n<p>اوپر 100 نکاتی پھیلاؤ بہت سے لوگوں میں سے ایک انتخاب ہے۔ ہڑتالوں کے درمیان فرق کو وسیع یا تنگ کریں اور آپ پوری تجارت کو نئی شکل دیں۔ یہاں ایک ہی NIFTY اور ایک ہی ایکسپائری پر تین بیئر پوٹ اسپریڈز ہیں، ہر نمبر کو ایک ہی آپشن چین سے شمار کیا گیا ہے، تاکہ آپ ٹریڈ آف کو صاف طور پر دیکھ سکیں۔</p>\n<table>\n<thead>\n<tr>\n<th>پھیلاؤ</th>\n<th>خریدیں / بیچیں۔</th>\n<th>خالص ڈیبٹ</th>\n<th>زیادہ سے زیادہ منافع</th>\n<th>بریک ایون</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>50 پوائنٹس</td>\n<td>24,050 خریدیں / 24,000 بیچیں۔</td>\n<td>1,170 روپے</td>\n<td>2,080 روپے</td>\n<td>24,032</td>\n</tr>\n<tr>\n<td>100 پوائنٹس</td>\n<td>24,050 خریدیں / 23,950 بیچیں۔</td>\n<td>2,506 روپے</td>\n<td>3,994 روپے</td>\n<td>24,011</td>\n</tr>\n<tr>\n<td>200 پوائنٹس</td>\n<td>24,050 خریدیں / 23,850 بیچیں۔</td>\n<td>4,615 روپے</td>\n<td>8,385 روپے</td>\n<td>23,979</td>\n</tr>\n</tbody></table>\n<p>پیٹرن واضح ہے۔ اے <strong>تنگ پھیلاؤ</strong> سستا ہے اور اس کا بریک ایون جگہ کے سب سے قریب بیٹھتا ہے، اس لیے یہ سب سے چھوٹی گرنے پر ادائیگی شروع کر دیتا ہے، لیکن اس کا اجر کم ہے۔ اے <strong>وسیع تر پھیلاؤ</strong> زیادہ لاگت آتی ہے اور اسے بریک ایون تک پہنچنے کے لیے تھوڑا سا آگے سفر کرنے کی ضرورت ہوتی ہے، پھر بھی اس سے کہیں زیادہ ادائیگی ہوتی ہے اگر آپ کی توقع کی کمی واقع ہو جاتی ہے۔ اپنی فروخت کردہ ہڑتال کو اس سطح پر سیٹ کریں جس پر آپ حقیقی طور پر سوچتے ہیں کہ NIFTY تک پہنچ سکتے ہیں، کیونکہ زیادہ سے زیادہ منافع بالکل وہیں پہنچتا ہے۔ دسترخوان پر کوئی مفت لنچ نہیں ہے، صرف ایک ڈائل جو آپ اپنے یقین سے مطابقت رکھتا ہے۔</p>\n<h2 id=\"bear-put-spread-or-bear-call-spread\">ریچھ پھیلاؤ یا ریچھ کال پھیلاؤ؟</h2>\n<p>آپ نے پچھلے باب میں پھیلنے والی ریچھ کی کال سے ملاقات کی، اور یہ اسی بیئرش نقطہ نظر کا اظہار کرتا ہے جس کی تعمیر میں تقریباً ایک جیسی ادائیگی کی شکل پلٹ گئی ہے۔ تو آپ کون سا انتخاب کرتے ہیں؟ ایماندارانہ جواب ہے، یہ اس بات پر منحصر ہے کہ آپ NIFTY کیا کرنا چاہتے ہیں۔</p>\n<ul>\n<li>دی <strong>ریچھ کال پھیل گئی</strong> ایک ہے <strong>کریڈٹ</strong> تجارت آپ کو پہلے سے 3,624 روپے ادا کیے جاتے ہیں اور آپ جیت جاتے ہیں اگر NIFTY صرف بڑھنے میں ناکام رہتے ہیں، آپ کی طرف وقت کی کمی کے ساتھ۔ آپ خاموشی چاہتے ہیں۔</li>\n<li>دی <strong>ریچھ پھیل گیا</strong> ایک ہے <strong>ڈیبٹ</strong> تجارت آپ آگے 2,506 روپے ادا کرتے ہیں اور آپ صرف اس صورت میں جیتتے ہیں جب NIFTY فعال طور پر 24,011 سے نیچے آجائے، وقت آپ کے خلاف نرمی سے گرے گا۔ آپ تحریک چاہتے ہیں۔</li>\n</ul>\n<p>بیئر پوٹ اسپریڈ تک پہنچیں جب آپ کسی حقیقی، کافی فوری کمی کی توقع کرتے ہیں، شاید کسی معروف سپورٹ میں یا کسی کاتالسٹ سے آگے جو آپ کے خیال میں مارکیٹ کو کم کر دیتا ہے۔ اس کا 2,506 روپے کے خطرے کے مقابلے میں 3,994 روپے کا انعام، تقریباً 1 سے 1.59 کا تناسب، بیئر کال اسپریڈ سے زیادہ فراخدلی ہے، اور یہ آپ کو سب سے زیادہ درست طریقے سے ادائیگی کرتا ہے جب NIFTY آپ کی نچلی ہڑتال پر پہنچ جاتا ہے۔ اس کے بجائے ریچھ کی کال پھیلنے تک پہنچیں جب آپ کو یقین ہو کہ الٹا بند ہے، نہ کہ گرنے والا ہے۔ بہت سے تاجر دونوں کو ہاتھ میں رکھتے ہیں اور مارکیٹ کے موڈ کو پرسکون ہونے دیں یا ٹوٹنے سے، فیصلہ کریں کہ کون سا فٹ بیٹھتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>بیئر پوٹ اسپریڈ ڈیفائنڈ رسک ہے، لیکن خطرہ حقیقی ہے اور اس کی پوری ادائیگی کی جاتی ہے۔ اگر NIFTY ایکسپائری پر 24,050 پر یا اس سے اوپر بند ہو جاتا ہے تو پورے 2,506 روپے فی لاٹ ختم ہو جاتے ہیں، جو یہ آج کے 24,056 سے صرف مستحکم ہو کر کر سکتا ہے۔ ڈیبٹ ٹریڈ خاموشی سے اس نقصان کی طرف خون بہاتی ہے جیسے جیسے وقت گزرتا ہے اگر زوال کبھی نہیں آتا ہے۔ ہر پوزیشن کو اس کے زیادہ سے زیادہ نقصان کے حساب سے سائز کریں، کبھی بھی انعام سے نہیں، اور صرف اتنی ہی لاٹیں لگائیں جتنی آپ کا اکاؤنٹ جذب کر سکتا ہے اگر آپ کی بیئرش کال ابتدائی یا سادہ غلط ہے۔</p>\n</div></div>\n<p>آپ اس پھیلی ہوئی ٹانگ کو ٹانگ کے ذریعے جمع کر سکتے ہیں۔ <strong>سینڈ باکس ٹریڈنگ ( OpenAlgo میں تجزیہ کار موڈ)</strong>سستا، قریب سے بریک ایون کو دیکھتے ہی فوری طور پر آپ سیلڈ پوٹ کو لون لانگ پوٹ میں شامل کرتے ہیں۔ سنگل پوٹ کے گہرے منافع کی لکیر دیکھیں 3,994 روپے کی حد تک، اور اسی اقدام میں لاگت 19,182 روپے سے کم ہوکر 2,506 روپے ہوگئی۔ وہ تجارت، محدود انعام کے لیے سستا داخلہ، ہر پھیلاؤ کا دل ہے۔ اس کے بعد ہم شائستہ دو ٹانگوں کے اسپریڈ کو پیچھے چھوڑتے ہیں اور تین بولڈ بیئرش شکلیں دریافت کرتے ہیں: پوٹ ریشو بیک اسپریڈ، مختصر مصنوعی مستقبل، اور رسک ریورسل۔</p>\n<h2 id=\"key-takeaways\">اہم نکات</h2>\n<ul>\n<li>ایک ریچھ پوٹ اسپریڈ ایک اعلی پوٹ خریدتا ہے اور ایک کے لئے کم پوٹ فروخت کرتا ہے۔ <strong>خالص ڈیبٹ</strong>اگر NIFTY اعلی اسٹرائیک سے نیچے آتا ہے تو منافع۔</li>\n<li><strong>زیادہ سے زیادہ نقصان خالص ڈیبٹ ہے۔</strong> (2506 روپے یہاں) <strong>زیادہ سے زیادہ منافع اسپریڈ مائنس ڈیبٹ ہے۔</strong> (3,994 روپے)، اور <strong>breakeven زیادہ سٹرائیک مائنس ڈیبٹ ہے۔</strong> (24,011).</li>\n<li>انعام خطرے سے بڑا ہے، لیکن <strong>POP صرف 49 فیصد ہے۔</strong>کیونکہ تجارت کو درحقیقت گرنے کے لیے NIFTY کی ضرورت ہے، اور <strong>وقت کا زوال آپ کے خلاف نرمی سے کام کرتا ہے۔</strong> ایک خالص خریدار کے طور پر.</li>\n<li>یہ ایک چھوٹا سا بلاک کرتا ہے <strong>مارجن</strong> تقریباً 34,113 روپے کا، اور فروخت ہونے والا پوٹ وہ ہے جو نقصان اور مارجن دونوں کو صاف رکھتا ہے۔ اس کی طرف سے فیصلہ کریں <strong>مارجن پر واپسی</strong>یہاں تقریباً 11.7 فیصد ہے۔</li>\n<li><strong>تنگ پھیلتا ہے۔</strong> قریب بریک ایون اور چھوٹے انعام کے ساتھ سستے ہیں۔ <strong>وسیع پھیلاؤ</strong> زیادہ قیمت اور زیادہ ادائیگی. فروخت ہونے والی ہڑتال کو سیٹ کریں جہاں آپ کو NIFTY کے اترنے کی توقع ہے۔</li>\n<li>جب آپ کو توقع ہو تو اسے بیئر کال اسپریڈ پر منتخب کریں۔ <strong>حقیقی، فوری کمی</strong>، اور جب آپ پیسے کے قریب بریک ایون کے ساتھ سستا ٹکٹ چاہتے ہیں۔</li>\n</ul>\n","toc":[{"level":2,"text":"ایک لائن کا خیال","id":"the-one-line-idea"},{"level":2,"text":"اصل تجارت، روپیہ بہ روپیہ","id":"the-real-trade-rupee-by-rupee"},{"level":2,"text":"تین نمبر، اور وہ کہاں سے آتے ہیں۔","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"میعاد ختم ہونے پر نتائج پر چلنا","id":"walking-the-outcomes-at-expiry"},{"level":2,"text":"آپ کی مشکلات","id":"your-odds"},{"level":2,"text":"مارجن","id":"margin"},{"level":2,"text":"وقت کا زوال","id":"time-decay"},{"level":2,"text":"اپنی ہڑتالوں کا انتخاب کرنا","id":"choosing-your-strikes"},{"level":2,"text":"ریچھ پھیلاؤ یا ریچھ کال پھیلاؤ؟","id":"bear-put-spread-or-bear-call-spread"},{"level":2,"text":"اہم نکات","id":"key-takeaways"}],"imgCount":1,"hasContent":true},"11":{"html":"<p>آپ نے ابھی جو دو بیئر اسپریڈ بنائے ہیں وہ شائستہ، متعین خطرے والے تجارت تھے جن کے دونوں سروں پر انعامات تھے۔ یہ باب تین بولڈ بیئرش شکلوں تک پہنچتا ہے، ہر ایک زوال کے وقت بہت زیادہ بڑے معاوضے کا پیچھا کرتا ہے، اور ان میں سے دو میں نقصان کا دم ہوتا ہے جو کبھی الٹا بند نہیں ہوتا۔ آپ سے ملیں گے۔ <strong>تناسب واپس پھیلائیں</strong>, جس کی قیمت بہت کم ہے اور حقیقی وقفے سے کم پر بہت زیادہ ادائیگی ہوتی ہے۔ دی <strong>مختصر مصنوعی مستقبل</strong>، جہاں ایک کال اور ایک پوٹ بالکل ایسے ہی برتاؤ کرتے ہیں جیسے کہ ایک NIFTY مستقبل فروخت کرنا۔ اور <strong>خطرے کی تبدیلی</strong>، ایک بیئرش کالر جو کریڈٹ کے لیے کھلتا ہے۔ ہر ایک ٹانگوں سے جمع کیا جاتا ہے جو آپ پہلے سے جانتے ہیں، اور ہر ایک مختلف طریقے سے نیچے کی طرف سخت جھکتا ہے۔</p>\n<h2 id=\"the-one-line-idea\">ایک لائن کا خیال</h2>\n<p>تینوں تجارتوں میں مندی کا جھکاؤ ہے، لیکن وہ اس بات پر تیزی سے تقسیم ہو جاتے ہیں جہاں خطرہ رہتا ہے۔ دی <strong>تناسب واپس پھیلائیں</strong> ٹکٹ پر اپنے بدترین کیس کو پرنٹ کرتا ہے اور کریش کی حد کے بغیر ادائیگی کرتا ہے۔ دی <strong>مختصر مصنوعی مستقبل</strong> اور <strong>خطرے کی تبدیلی</strong> دونوں کریڈٹ کے لیے کھلے ہیں اور زیادہ کثرت سے منافع بخش ختم کرتے ہیں، لیکن ہر ایک کال فروخت کرتا ہے جس کے اوپر کچھ نہیں ہوتا ہے، اس لیے ریلی کی قیمت بغیر کسی اختتام کے ہوتی ہے۔ ہر ایک کو پڑھیں کہ اس کا نقصان کہاں ہے اور کہاں نہیں ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>پوٹ ریشو بیک اسپریڈ ایک سستا، متعین خطرے کی شرط ہے جو سخت زوال پر بہت زیادہ ادائیگی کرتی ہے۔ ایک مختصر مصنوعی مستقبل دو اختیارات ہیں جو ایک مختصر NIFTY مستقبل کے برابر ہیں، جس میں غیر محدود الٹا خطرہ ہے۔ رسک ریورسل ایک بیئرش کالر ہے جو کریڈٹ کے لیے کھولا جاتا ہے، جس میں غیر محدود اوپری خطرہ بھی ہوتا ہے۔ پہلا ابتدائی طور پر محفوظ ہے۔ باقی دو لیوریجڈ شارٹس ہیں جو احترام اور بڑے مارجن کا مطالبہ کرتے ہیں۔</p>\n</div></div>\n<h2 id=\"the-put-ratio-back-spread\">ڈال تناسب واپس پھیل گیا</h2>\n<p>ایک ریشو بیک اسپریڈ جان بوجھ کر ایک عام اسپریڈ کے ون فار ون توازن کو توڑ دیتا ہے۔ آپ ایک ایٹ دی منی پوٹ بیچتے ہیں اور دو پوٹ اسٹرائیک لوئر خریدتے ہیں، اس طرح آپ ایک اضافی پوٹ رکھتے ہیں، جس کا مطلب ہے کہ اگر NIFTY مشکل سے گرتا ہے تو آپ کو زبردست فائدہ ہوتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>ایکشن</th>\n<th></th>\n<th>پریمیم فی شیئر</th>\n<th></th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td></td>\n<td>24,050</td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td>2</td>\n<td></td>\n<td>23,950</td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong></strong></td>\n<td><strong></strong></td>\n</tr>\n</tbody></table>\n<p> <strong></strong> <strong></strong> </p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th></th>\n</tr>\n</thead>\n<tbody><tr>\n<td></td>\n<td>اضافی طویل پوٹ بغیر کسی حد کے حاصل کرتا ہے کیونکہ NIFTY صفر کی طرف آتا ہے۔</td>\n<td></td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td></td>\n<td>شارٹ سٹرائیک مائنس وادی کا نقصان ایک جال میں پھیل گیا۔</td>\n<td></td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-put-ratio-back-spread.png\" alt=\"NIFTY پوٹ ریشو بیک اسپریڈ: 23,950 شارٹ سٹرائیک پر 20,670 روپے کی نیچے والی ایک اتلی نقصان والی وادی، 23,632 پر ایک بریک ایون، اور منافع کی لکیر جو اس سے بہت نیچے تیز ہوتی ہے کیونکہ آپ ایک اضافی لمبا پوٹ رکھتے ہیں۔ 24,050 سے اوپر کے تینوں پوٹس بیکار ختم ہوجاتے ہیں اور آپ صرف 14,170 روپے ڈیبٹ سے محروم ہوجاتے ہیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\"></span></figcaption></figure>\n<p>یہاں خطرہ الٹا نہیں، درمیان میں ہے۔ آپ کا سب سے برا معاملہ کسی بڑے اقدام پر نہیں بلکہ ایک چھوٹی پر، بالکل 23,950 شارٹ سٹرائیک پر ہے، جہاں آپ نے جو پوٹ بیچا ہے وہ آپ کے خلاف رقم میں 100 پوائنٹس ہے جبکہ آپ کے خریدے ہوئے دونوں پوٹس ابھی بھی بیکار ہیں۔ یہاں تجارت NIFTY کی پانچ سطحوں پر طے کی گئی ہے، فی لاٹ۔</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th></th>\n<th></th>\n<th></th>\n</tr>\n</thead>\n<tbody><tr>\n<td>24,200</td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td>23,950</td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td>23,632</td>\n<td>مالیت 418</td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td>23,300</td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td>23,000</td>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n</tbody></table>\n<p></p>\n<h2 id=\"the-short-synthetic-future\"></h2>\n<p></p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th></th>\n<th></th>\n<th></th>\n<th></th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td></td>\n<td>24,050</td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td>2</td>\n<td></td>\n<td>24,050</td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong></strong></td>\n<td><strong></strong></td>\n</tr>\n</tbody></table>\n<p> <strong></strong>. وہاں سے یہ سیدھی لکیر ہے۔ ہر پوائنٹ NIFTY گرتا ہے، آپ کو 65 روپے کا فائدہ ہوتا ہے۔ ہر پوائنٹ بڑھتا ہے، آپ کو 65 روپے کا نقصان ہوتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th></th>\n<th></th>\n</tr>\n</thead>\n<tbody><tr>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td>بریک ایون</td>\n<td>ہڑتال کے علاوہ کریڈٹ فی شیئر</td>\n<td>24,050 جمع 130.7 = 24,181</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-short-synthetic.png\" alt=\"NIFTY مختصر مصنوعی مستقبل: 24,181 پر صفر کو عبور کرنے والی واحد سیدھی ترچھی لکیر، ہر پوائنٹ NIFTY گرنے کے لیے 65 روپے کا فائدہ اور اس کے بڑھنے والے ہر پوائنٹ کے لیے 65 روپے کا نقصان، مستقبل کو فروخت کرنے کے مترادف ہے۔ نیلی T+0 لائن تقریباً اورنج ایٹ-ایکسپائری لائن کے اوپر ہوتی ہے کیونکہ مصنوعی مستقبل میں وقت کی کوئی قدر نہیں ہوتی۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY مختصر مصنوعی مستقبل: 24,181 پر صفر کو عبور کرنے والی واحد سیدھی ترچھی لکیر، ہر پوائنٹ کے لیے 65 روپے کا فائدہ NIFTY گرتا ہے اور ہر پوائنٹ کے لیے 65 روپے کا نقصان ہوتا ہے، جو کہ مستقبل کو بیچنے کے مترادف ہے۔ نیلی T+0 لائن تقریباً اورنج ایٹ-ایکسپائری لائن کے اوپر ہوتی ہے کیونکہ مصنوعی مستقبل میں وقت کی کوئی قدر نہیں ہوتی۔</figcaption></figure>\n<p>بریک ایون پر <strong>24,181</strong> مصنوعی مستقبل کی قیمت ہے، جگہ کے بالکل اوپر بیٹھی ہے کیونکہ لے جانے کی قیمت آپشنز میں بیک کی جاتی ہے۔ یہاں چار سطحوں پر سیدھی لکیر آباد ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>24,050 کال آپ نے فروخت کی۔</th>\n<th>24,050 آپ نے خریدا۔</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,550</td>\n<td>مالیت 0</td>\n<td>500 کی مالیت</td>\n<td>علاوہ 40,996 روپے</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>علاوہ 8,496 روپے</td>\n</tr>\n<tr>\n<td>24,181</td>\n<td>مالیت 131</td>\n<td>مالیت 0</td>\n<td>0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>24,550</td>\n<td>500 کی مالیت</td>\n<td>مالیت 0</td>\n<td>مائنس 24,004 روپے</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک مختصر مصنوعی مستقبل میں زیادہ سے زیادہ نقصان ہوتا ہے جو کہ UNLIMITED ہے۔ چونکہ آپ نے ایک کال فروخت کی ہے جس کے اوپر کوئی تحفظ نہیں ہے، اس لیے پوزیشن ہر پوائنٹ NIFTY بڑھنے کے لیے 65 روپے کھو دیتی ہے، جس کی کوئی حد نہیں ہے۔ یہ انڈیکس پر لیوریجڈ شارٹ ہے، یہی وجہ ہے کہ ایکسچینج تقریباً 1.69 لاکھ روپے کے مارجن کو روکتا ہے۔ منافع کا 56 فیصد امکان اس غیر منقطع دم کو نرم نہیں کرتا ہے۔ ایک تیز ریلی آپ کی جمع کردہ کسی بھی چیز سے کہیں زیادہ نقصان پہنچا سکتی ہے۔</p>\n</div></div>\n<p>مصنوعی مستقبل کسی ابتدائی کی پہلی تجارت نہیں ہے۔ اس کی اصل قدر تصوراتی ہے: ایک سٹرائیک پر پوٹ خریدتے وقت کال بیچنا مستقبل کے مختصر ہونے کے برابر ہے، اس بات کا ثبوت کہ کال اور پوٹ ایک ہی آلے کے دو حصے ہیں۔</p>\n<h2 id=\"the-risk-reversal\">خطرہ الٹ جانا</h2>\n<p>آخری شکل مصنوعی کو بیئرش کالر میں نرم کرتی ہے۔ آپ منفی منافع کے لیے پیسے کے نیچے ایک پوٹ خریدتے ہیں اور اس کی ادائیگی کے لیے پیسے کے اوپر ایک کال بیچتے ہیں، درمیان میں ہلکی ڈھلوان چھوڑتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>ڈال خریدیں</td>\n<td>23,950</td>\n<td>256.6 ادا کیا گیا۔</td>\n<td>16,679 روپے باہر</td>\n</tr>\n<tr>\n<td>2</td>\n<td>کال فروخت کریں۔</td>\n<td>24,150</td>\n<td>370.1 موصول ہوا۔</td>\n<td>علاوہ 24,057 روپے میں</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>نیٹ کریڈٹ</strong></td>\n<td><strong>علاوہ 7,378 روپے میں</strong></td>\n</tr>\n</tbody></table>\n<p>آپ جو کال بیچتے ہیں اس سے آپ کی قیمت خریدی گئی قیمت سے زیادہ ہوتی ہے، لہذا <strong>خطرے کی تبدیلی</strong> a کے لیے کھولتا ہے۔ <strong>7,378 روپے کا خالص کریڈٹ</strong>. 23,950 سے نیچے لانگ پوٹ پرافٹ اور فائدہ بڑھتا ہے اور NIFTY گرتا ہے۔ دونوں حملوں کے درمیان آپ صرف کریڈٹ رکھتے ہیں۔ 24,150 سے اوپر فروخت شدہ کال آپ کے خلاف ہو جاتی ہے اور نقصان بغیر کسی حد کے چلتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>NIFTY صفر کی طرف گرنے کے ساتھ ساتھ لانگ پوٹ فائدہ</td>\n<td>1,564,128 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>فروخت کی گئی 24,150 کال کے اوپر کچھ نہیں ہے۔</td>\n<td>لا محدود</td>\n</tr>\n<tr>\n<td>بریک ایون</td>\n<td>کال ہڑتال کے علاوہ کریڈٹ فی شیئر</td>\n<td>24,150 جمع 113.5 = 24,264</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-risk-reversal.png\" alt=\"NIFTY بیئرش رسک ریورسل: 23,950 سے نیچے ایک طویل مدتی منافع کا زون، دونوں سٹرائیکس کے درمیان 7,378 روپے کا تقریباً فلیٹ کریڈٹ، اور فروخت شدہ کال کے ذریعے 24,264 پر بریک ایون کے اوپر لامحدود نقصان۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY بیئرش رسک ریورسل: 23,950 سے نیچے ایک طویل مدتی منافع کا زون، دونوں سٹرائیکس کے درمیان 7,378 روپے کا تقریباً فلیٹ کریڈٹ، اور فروخت شدہ کال کے ذریعے 24,264 پر بریک ایون کے اوپر لامحدود نقصان۔</figcaption></figure>\n<p>یہ ہے کالر NIFTY کی پانچ سطحوں پر، فی لاٹ پر آباد ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>23,950 آپ نے خریدا۔</th>\n<th>24,150 کال آپ نے فروخت کی۔</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,450</td>\n<td>500 کی مالیت</td>\n<td>مالیت 0</td>\n<td>علاوہ 39,878 روپے</td>\n</tr>\n<tr>\n<td>23,950</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>علاوہ 7,378 روپے</td>\n</tr>\n<tr>\n<td>24,150</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>علاوہ 7,378 روپے</td>\n</tr>\n<tr>\n<td>24,264</td>\n<td>مالیت 0</td>\n<td>مالیت 114</td>\n<td>0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>24,550</td>\n<td>مالیت 0</td>\n<td>400 کی مالیت</td>\n<td>مائنس 18,622 روپے</td>\n</tr>\n</tbody></table>\n<p>7,378 روپے کا فلیٹ شیلف 23,950 سے 24,150 تک پورے فرق پر چل رہا ہے۔ وہ وسیع پرسکون بینڈ ہے جہاں سے منافع کا 60 فیصد امکان آتا ہے، لیکن یہ اس کے اوپر دم کو لپیٹنے کے لیے کچھ نہیں کرتا۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>بیئرش رسک ریورسل میں زیادہ سے زیادہ نقصان ہوتا ہے جو کہ UNLIMITED ہے۔ فروخت ہونے والی 24,150 کال کو اس کے اوپر کوئی تحفظ نہیں ہے، لہذا 24,264 کے بریک ایون سے گزرنے والی ریلی آپ کو بغیر کسی حد کے خرچ کرتی ہے، اور ایکسچینج اسے رکھنے کے لیے تقریباً 1.64 لاکھ روپے کا مارجن روکتا ہے۔ منافع کا 60 فیصد امکان نقصان شروع ہونے سے پہلے مکمل طور پر وسیع خلا سے آتا ہے، نہ کہ اس پر کسی حد سے۔ اسے ایک لیوریجڈ بیئرش پوزیشن کے طور پر دیکھیں، کبھی بھی محفوظ آمدنی کی تجارت کے طور پر نہیں۔</p>\n</div></div>\n<h2 id=\"your-odds-across-the-three\">تینوں میں آپ کی مشکلات</h2>\n<p>منافع کے امکانات وہی کہانی بیان کرتے ہیں جو شکلیں کرتی ہیں۔ دی <strong>تناسب واپس پھیلائیں</strong> صرف پرنٹ کرتا ہے <strong>32 فیصد</strong>کیونکہ اسے اپنی وادی کو صاف کرنے اور منافع کی تیز رفتار لائن تک پہنچنے کے لیے حقیقی زوال کی ضرورت ہے۔ دی <strong>مختصر مصنوعی مستقبل</strong> پر بیٹھتا ہے <strong>56 فیصد</strong> اور <strong>خطرے کی تبدیلی</strong> پر <strong>60 فیصد</strong>, دونوں نصف سے اوپر، کیونکہ ہر ایک کریڈٹ کے ساتھ شروع ہوتا ہے اور قیمت کے وسیع پیمانے پر جہاں یہ آسانی سے جیت جاتا ہے۔ لیکن غیر منقطع دم کے ساتھ خریدی جانے والی اعلی مشکلات حفاظت نہیں ہیں: وہ دونوں زیادہ بار جیتتے ہیں اور جس دن وہ ہارتے ہیں اس دن بہت زیادہ خراب ہوتے ہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>نقصان کی حد کے آگے نفع کے امکان کو ہمیشہ پڑھیں۔ خطرے کے الٹ جانے پر منافع کا 60 فیصد موقع اس وقت تک آرام دہ لگتا ہے جب تک کہ آپ محسوس کریں کہ باقی 40 فیصد میں کوئی منزل نہیں ہے۔ پوٹ ریشو بیک اسپریڈ پر 32 فیصد کا موقع اس وقت تک ناقص لگتا ہے جب تک کہ آپ اس کی سب سے خراب صورت ٹکٹ پر پرنٹ شدہ 20,670 روپے کا ہے۔ نقصان کی شکل سرخی کی مشکلات سے زیادہ اہمیت رکھتی ہے۔</p>\n</div></div>\n<h2 id=\"margin-the-cost-of-an-open-tail\">مارجن، کھلی دم کی قیمت</h2>\n<p>تینوں مارجن کو ساتھ ساتھ دیکھیں اور ایکسچینج آپ کو بتاتا ہے، نقد میں، بالکل کون سی تجارت خطرناک ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>حکمت عملی</th>\n<th>نیٹ</th>\n<th>زیادہ سے زیادہ نقصان</th>\n<th>مارجن</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>تناسب کو واپس پھیلائیں۔</td>\n<td>ڈیبٹ روپے 14,170</td>\n<td>20,670 روپے</td>\n<td>46,304 روپے</td>\n</tr>\n<tr>\n<td>مختصر مصنوعی مستقبل</td>\n<td>کریڈٹ روپے 8,496</td>\n<td>لا محدود</td>\n<td>169,046 روپے</td>\n</tr>\n<tr>\n<td>خطرہ الٹ جانا</td>\n<td>کریڈٹ روپے 7,378</td>\n<td>لا محدود</td>\n<td>163,941 روپے</td>\n</tr>\n</tbody></table>\n<p>ڈیفائنڈ رسک پوٹ ریشو بیک اسپریڈ بلاکس 46,304 روپے، اس کے اپنے بدترین نقصان سے دوگنا تھوڑا زیادہ۔ دو غیر متعینہ رسک ہر بلاک پر 1.6 لاکھ روپے سے زیادہ تجارت کرتے ہیں، کیونکہ ایکسچینج ایک دم کے خلاف کولیٹرل رکھتا ہے جس کی کوئی انتہا نہیں ہے۔ جب بھی کوئی ڈھانچہ اس قسم کے سرمائے کو جوڑتا ہے، اسے ایک سگنل کے طور پر لیں تاکہ یہ معلوم کریں کہ لامحدود سائیڈ آپ کے رکھنے سے پہلے کہاں رہتی ہے۔</p>\n<h2 id=\"time-decay\">وقت کا زوال</h2>\n<p>وقت تینوں تجارتوں کے ساتھ مختلف سلوک کرتا ہے۔ دی <strong>تناسب واپس پھیلائیں</strong> نیٹ لانگ ون پوٹ ہے، لہذا گھڑی اس کے خلاف کام کرتی ہے: شارٹ اسٹرائیک کے قریب بیٹھنے سے لانگ پوٹس کو خون بہنے دیتا ہے، اس کا ایک حصہ کیوں خاموشی سے 23,950 کی طرف بڑھنا اس کا بدترین نتیجہ ہے۔ دی <strong>مختصر مصنوعی مستقبل</strong> تقریباً کوئی وقت کی قدر نہیں ہے، اس لیے اس کی نیلی T+0 لائن اور اورنج ایٹ-ایکسپائری لائن تقریباً ایک دوسرے کے اوپر پڑی ہے، جو ایک حقیقی مستقبل سے زیادہ زوال پذیر نہیں ہوتی۔ دی <strong>خطرے کی تبدیلی</strong> زوال سے تھوڑا کماتا ہے جبکہ NIFTY اپنے فلیٹ بینڈ کے اندر رکھتا ہے، کیونکہ فروخت شدہ کال خریدے گئے پوٹ سے زیادہ تیزی سے ضائع ہوتی ہے، لیکن اس چھوٹی سی مدد کو دونوں طرف سے دشاتمک خطرے کی وجہ سے کم کر دیا جاتا ہے۔</p>\n<h2 id=\"how-the-three-compare\">تینوں کا موازنہ کیسے کریں؟</h2>\n<p>پوٹ ریشو بیک اسپریڈ تینوں کا واحد ممبر ہے جس کی وضاحت بدترین صورت ہے، 20,670 روپے 23,950 پر، جو اسے پہلے نمبر پر پہنچنے والا بناتا ہے۔ مختصر مصنوعی مستقبل خالص لیوریجڈ شارٹ ہے، 24,181 سے اوپر لامحدود، اور رسک ریورسل ایک بیئرش لین ہے جس میں وسیع کشن ہے لیکن 24,264 سے اوپر وہی غیر کیپڈ ٹیل ہے۔</p>\n<p>اگر آپ بیئرش ہیں اور اب بھی سیکھ رہے ہیں، تو اس تینوں سے پوٹ ریشو بیک اسپریڈ کو ترجیح دیں، یا آخری باب سے سادہ ریچھ کے اسپریڈ کو بہتر کریں۔ دونوں اپنے بدترین کیس کو ٹکٹ پر رکھتے ہیں جہاں آپ اس کے خلاف سائز کر سکتے ہیں۔ مختصر مصنوعی اور خطرے کے الٹ جانے کو اس وقت تک چھوڑ دیں جب تک کہ آپ ایک غیر کیپڈ شارٹ کو فعال طور پر منظم نہ کر لیں، اور پہلے اوپر کیپ کرنے کی منصوبہ بندی کے بغیر کسی معروف ایونٹ کے ذریعے اسے کبھی نہ روکیں۔</p>\n<p>آپ تینوں کو اندر بنا سکتے ہیں۔ <strong>سینڈ باکس ٹریڈنگ ( OpenAlgo میں تجزیہ کار موڈ)</strong>, ٹانگوں کو رکھ کر اور پوٹ ریشو کو پیچھے پھیلاتے ہوئے اس کے نقصان کی وادی کو تراشتا ہے، مصنوعی بالکل سیدھی لکیر کھینچتا ہے، اور اس کے حملوں کے درمیان رسک ریورسل ڈھلوان۔ دو کریڈٹ ٹریڈز پر ماڈل کی گئی قیمت کو اوپر کی طرف گھسیٹیں اور نقصان کی لکیر کو بغیر ختم ہوتے دیکھیں۔ وہ ایک نظر سارا سبق ہے۔ اس کے بعد ہم بیئرش بٹر فلائی اور کنڈور کے ساتھ ڈیفائنڈ رسک گراؤنڈ پر واپس آتے ہیں، دو سستے، ٹارگٹڈ بیٹس پیسے سے نیچے ایک عین مطابق لینڈنگ پر۔</p>\n<h2 id=\"key-takeaways\">اہم نکات</h2>\n<ul>\n<li>دی <strong>تناسب واپس پھیلائیں</strong> ایک پوٹ بیچتا ہے اور چھوٹے ڈیبٹ کے عوض دو لوئر پوٹس خریدتا ہے۔ اس کا سب سے برا معاملہ 23,950 پر 20,670 روپے کا ہے، اس کا بریک ایون 23,632 ہے، اور یہ منافع کے 32 فیصد امکانات کے ساتھ حقیقی کمی پر بہت زیادہ ادائیگی کرتا ہے۔</li>\n<li>دی <strong>مختصر مصنوعی مستقبل</strong> 24,050 کال فروخت کرتا ہے اور 24,050 کا پوٹ خریدتا ہے، جو ایک مختصر مستقبل کے برابر ہے: ایک سیدھی لکیر، بریک ایون 24,181، UNLIMITED اس کے اوپر کا نقصان۔</li>\n<li>دی <strong>خطرے کی تبدیلی</strong> 23,950 پوٹ خریدتا ہے اور کریڈٹ کے لیے 24,150 کال فروخت کرتا ہے، سٹرائیکس کے درمیان 7,378 روپے کے فلیٹ شیلف کے ساتھ ایک بیئرش کالر اور 24,264 سے زائد UNLIMITED نقصان۔</li>\n<li>دو کریڈٹ ٹریڈز زیادہ مشکلات، 56 اور 60 فیصد دکھاتے ہیں، لیکن یہ مشکلات ایک دم کے اوپر بیٹھی ہیں بغیر فرش کے، اور ایکسچینج ہر ایک کے مقابلے میں 1.6 لاکھ روپے سے زیادہ کا مارجن روکتا ہے۔</li>\n<li>ایک ابتدائی کے لیے، ڈیفائنڈ رسک پوٹ ریشو بیک اسپریڈ تینوں میں سے صرف ایک ہے جو پہلے تک پہنچ سکتا ہے، اور صرف اس کے بدترین کیس کے ساتھ پوزیشن میں ہے۔</li>\n</ul>\n","toc":[{"level":2,"text":"ایک لائن کا خیال","id":"the-one-line-idea"},{"level":2,"text":"ڈال تناسب واپس پھیل گیا","id":"the-put-ratio-back-spread"},{"level":2,"text":"","id":"the-short-synthetic-future"},{"level":2,"text":"خطرہ الٹ جانا","id":"the-risk-reversal"},{"level":2,"text":"تینوں میں آپ کی مشکلات","id":"your-odds-across-the-three"},{"level":2,"text":"مارجن، کھلی دم کی قیمت","id":"margin-the-cost-of-an-open-tail"},{"level":2,"text":"وقت کا زوال","id":"time-decay"},{"level":2,"text":"تینوں کا موازنہ کیسے کریں؟","id":"how-the-three-compare"},{"level":2,"text":"اہم نکات","id":"key-takeaways"}],"imgCount":3,"hasContent":true},"12":{"html":"<p>اب تک کی ہر بیئرش ٹریڈ نے گراوٹ کا صلہ دیا ہے، اور جتنی بڑی زوال اتنا ہی بہتر ہے۔ یہ باب مخالف جبلت کا درس دیتا ہے۔ کیا ہوگا اگر آپ صرف یہ نہیں سوچتے کہ NIFTY گر جائے گا، بلکہ یہ سوچتے ہیں کہ یہ کسی خاص جگہ پر گر جائے گا اور رک جائے گا، تھوڑا نیچے ایک تنگ بینڈ میں بس جائے گا جہاں یہ اب بیٹھا ہے؟ جب آپ کا نظریہ بالکل درست ہے، تو آپ ایک ایسا ڈھانچہ خرید سکتے ہیں جس کی قیمت تقریباً کچھ بھی نہیں ہے اور اگر انڈیکس بالکل اسی جگہ پر اترتا ہے جہاں آپ نے اندازہ لگایا تھا۔ یہ ہیں <strong>بیئرش تتلی</strong> اور <strong>بیئرش کنڈور</strong>, مکمل طور پر پوٹس سے بنایا گیا ہے، صرف پیسے کے نیچے بیٹھا ہے۔ وہ سستے ہیں، وہ خطرے سے دوچار ہیں، اور وہ ایک چھوٹے سے اخراجات کے مقابلے میں شاندار انعام پیش کرتے ہیں۔ ایماندار کیچ، جسے یہ باب نہیں چھپائے گا، یہ ہے کہ جیتنے کے امکانات کم ہیں، کیونکہ قیمت میں سوئی ڈالنی پڑتی ہے۔</p>\n<h2 id=\"the-one-line-idea\">ایک لائن کا خیال</h2>\n<p>ایک بیئرش بٹر فلائی اور بیئرش کنڈور دونوں ہیں۔ <strong>رینج کی شرط موجودہ جگہ کے نیچے رکھی گئی ہے۔</strong>. آپ چار پوٹ ٹانگوں کو جمع کرتے ہیں تاکہ ڈھانچہ ایک تنگ زون سے باہر تقریباً کچھ بھی نہیں ہوتا اور اگر NIFTY اس میں نیچے چلا جاتا ہے تو اس کی قیمت بہت زیادہ ہے۔ آپ داخل ہونے کے لیے ایک چھوٹا سا خالص ڈیبٹ ادا کرتے ہیں، اور یہ ڈیبٹ سب سے زیادہ ہے جسے آپ کھو سکتے ہیں۔ انعام، چند سو کے مقابلے میں کئی ہزار روپے، شاندار لگتا ہے، اور اسے جمع کرنے کا امکان وہ حصہ ہے جسے آپ کو ایمانداری سے رکھنا چاہیے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک بیئرش بٹر فلائی اور کنڈور سستے، متعین خطرے والے شرط ہیں جو کہ NIFTY ایک مخصوص سطح تک نیچے آ جائیں گے اور وہیں رک جائیں گے۔ آپ جو چھوٹا ڈیبٹ ادا کرتے ہیں وہ آپ کا زیادہ سے زیادہ نقصان ہے، ادائیگی ڈیبٹ سے کئی گنا زیادہ ہے، اور منافع کا امکان صرف دس میں سے ایک ہے۔ وہ لینڈنگ اسپاٹ پر عین مطابق، کم مشکلات والے ٹکٹ ہوتے ہیں، بڑے اقدام پر شرط نہیں لگاتے۔</p>\n</div></div>\n<h2 id=\"the-bearish-butterfly\">بیئرش تتلی</h2>\n<p>تتلی کی تین ٹانگیں اور چار ٹانگیں ہوتی ہیں۔ آپ اوپر سے ایک پوٹ خریدتے ہیں، بیچ میں دو بیچتے ہیں، اور نیچے سے ایک خریدتے ہیں، تو دونوں نے باڈی پر بیچے گئے دو پٹس میں پروں کی باڑ خریدی۔ اسپاٹ کے نیچے رکھا گیا، اگر NIFTY درمیانی سٹرائیک کی طرف بڑھتا ہے تو پورا ڈھانچہ چوٹی پر آجاتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>ڈال خریدیں</td>\n<td>24,050</td>\n<td>295.1 ادا کیا گیا۔</td>\n<td>19,182 روپے باہر</td>\n</tr>\n<tr>\n<td>2</td>\n<td>سیل ڈال (x2)</td>\n<td>23,950</td>\n<td>256.6 ہر ایک موصول ہوا۔</td>\n<td>علاوہ 33,358 روپے میں</td>\n</tr>\n<tr>\n<td>3</td>\n<td>ڈال خریدیں</td>\n<td>23,850</td>\n<td>224.1 ادا کیا گیا۔</td>\n<td>14,567 روپے باہر</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>خالص ڈیبٹ</strong></td>\n<td><strong>تقریباً 393 روپے</strong></td>\n</tr>\n</tbody></table>\n<p>باڈی پر فروخت ہونے والے دو پوٹس زیادہ تر پریمیم لاتے ہیں، اور دو خریدے ہوئے پروں کی قیمت تھوڑی زیادہ ہے، جس سے ایک چھوٹا سا رہ جاتا ہے۔ <strong>تقریباً 393 روپے کا خالص ڈیبٹ</strong> پوری جگہ کے لئے. وہ ڈیبٹ آپ کا زیادہ سے زیادہ نقصان ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>خالص ڈیبٹ، پنکھوں سے باہر کھو گیا۔</td>\n<td>393 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>ونگ کی چوڑائی 6,500 روپے مائنس ڈیبٹ، باڈی اسٹرائیک پر</td>\n<td>6,500 روپے مائنس 393 روپے = 6,107 روپے</td>\n</tr>\n<tr>\n<td>Breakevens</td>\n<td>ہر ونگ کے اندر چند پوائنٹس</td>\n<td>23,856 اور 24,047</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bearish-butterfly.png\" alt=\"NIFTY بیئرش بٹر فلائی ان پوٹس: 23,950 باڈی پر 6,107 روپے کی چوٹی پر تیز منافع کا ٹینٹ، 23,856 اور 24,047 پر بریک ایونز، اور پنکھوں کے باہر ہر جگہ 393 روپے کا چھوٹا نقصان۔ 24,056 پر گلابی اسپاٹ لائن ٹینٹ کے بالکل دائیں طرف بیٹھتی ہے، اس لیے NIFTY کو ادائیگی کے لیے بینڈ میں نیچے آنا پڑتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY بیئرش بٹر فلائی ان پوٹس: 23,950 باڈی پر 6,107 روپے کی چوٹی پر تیز منافع کا ٹینٹ، 23,856 اور 24,047 پر بریک وینز، اور پنکھوں کے باہر ہر جگہ 393 روپے کا چھوٹا نقصان۔ 24,056 پر گلابی اسپاٹ لائن ٹینٹ کے بالکل دائیں طرف بیٹھتی ہے، لہذا NIFTY کو ادائیگی کے لیے بینڈ میں نیچے آنا پڑتا ہے۔</figcaption></figure>\n<p>تجارت کو پانچ اختتامی سطحوں پر چلائیں اور خیمہ خود کو کھینچ لے گا۔ ایک پوٹ میعاد ختم ہونے پر زیادہ سے زیادہ (اسٹرائیک مائنس NIFTY، 0) کے قابل ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>24,050 PE خریدا گیا۔</th>\n<th>23,950 PE فروخت (ہر ایک)</th>\n<th>23,850 PE خریدا گیا۔</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,800</td>\n<td>مالیت 250</td>\n<td>150 کی مالیت</td>\n<td>مالیت 50</td>\n<td>مائنس 393 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>23,856</td>\n<td>مالیت 194</td>\n<td>مالیت 94</td>\n<td>مالیت 0</td>\n<td>0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>23,950</td>\n<td>100 کی مالیت</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>جمع 6,107 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,000</td>\n<td>مالیت 50</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>علاوہ 2,857 روپے</td>\n</tr>\n<tr>\n<td>24,100</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مائنس 393 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n</tbody></table>\n<p>23,850 سے نیچے اور 24,050 سے اوپر کی چار ٹانگیں منسوخ ہو جاتی ہیں اور آپ 393 روپے کے چھوٹے نقصان پر بیٹھ جاتے ہیں۔ کے breakevens کے درمیان <strong>23,856 اور 24,047</strong> ڈھانچہ صفر سے اوپر نکلتا ہے، اپنی پوری 6,107 روپے کی چوٹی پر صرف اسی صورت میں چڑھتا ہے جب NIFTY 23,950 باڈی کو بالکل ٹھیک کرتا ہے۔ کسی بھی طرح سے پچاس پوائنٹس بھی پھسل جائیں اور انعام تیزی سے سکڑ جاتا ہے۔ وہ نفاست تتلی کی فطرت ہے: ایک نقطہ سب سے زیادہ قیمت ادا کرتا ہے۔</p>\n<h2 id=\"the-bearish-condor\">بیئرش کنڈور</h2>\n<p>کونڈور ایک تتلی ہے جس کی چوٹی سطح مرتفع میں پھیلی ہوئی ہے۔ ایک باڈی اسٹرائیک پر دو پوٹس بیچنے کے بجائے، آپ انہیں دو ملحقہ اسٹرائیکس پر بیچتے ہیں، جو زیادہ سے زیادہ منافع کو ایک پوائنٹ کی بجائے چھوٹی رینج میں پھیلاتا ہے۔ یہ اس بارے میں قدرے زیادہ معاف کرنے والا ہے کہ NIFTY کم چوٹی کی قیمت پر کہاں اترتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>ڈال خریدیں</td>\n<td>24,050</td>\n<td>295.1 ادا کیا گیا۔</td>\n<td>19,182 روپے باہر</td>\n</tr>\n<tr>\n<td>2</td>\n<td>ڈال فروخت</td>\n<td>24,000</td>\n<td>277.1 موصول ہوا۔</td>\n<td>علاوہ 18,012 روپے میں</td>\n</tr>\n<tr>\n<td>3</td>\n<td>ڈال فروخت</td>\n<td>23,900</td>\n<td>241.6 موصول ہوا۔</td>\n<td>علاوہ 15,704 روپے میں</td>\n</tr>\n<tr>\n<td>4</td>\n<td>ڈال خریدیں</td>\n<td>23,850</td>\n<td>224.1 ادا کیا گیا۔</td>\n<td>14,567 روپے باہر</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>خالص ڈیبٹ</strong></td>\n<td><strong>تقریباً 36 روپے</strong></td>\n</tr>\n</tbody></table>\n<p>دو فروخت شدہ اندرونی پوٹس دوبارہ زیادہ تر پریمیم لاتے ہیں، ایک چھوڑ کر <strong>تقریباً 36 روپے کا خالص ڈیبٹ</strong> لاٹ کے لیے، اس پورے کورس میں سب سے سستا داخلہ۔ یہ 36 روپے سب سے زیادہ نقصان ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>خالص ڈیبٹ، پنکھوں سے باہر کھو گیا۔</td>\n<td>36 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>50 پوائنٹ کا اوپری اسپریڈ (3,250 روپے) مائنس ڈیبٹ، پورے سطح مرتفع پر</td>\n<td>3,250 روپے مائنس 36 روپے = 3,214 روپے</td>\n</tr>\n<tr>\n<td>Breakevens</td>\n<td>ہر بیرونی بازو کے اندر ایک بال</td>\n<td>تقریباً 23,851 اور 24,049</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bearish-condor.png\" alt=\"NIFTY بیئرش کنڈور ان پوٹس: 23,900 اور 24,000 اندرونی سٹرائیکس کے درمیان 3,214 روپے کا فلیٹ منافع پلیٹیو، بیرونی پروں کے بالکل اندر ٹوٹ پھوٹ، اور ان کے باہر ہر جگہ تقریباً صفر روپے کا نقصان۔ تتلی کا خیمہ ٹیبل ٹاپ بن گیا ہے، نچلا لیکن چوڑا۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY بیئرش کنڈور ان پوٹس: 23,900 اور 24,000 اندرونی سٹرائیکس کے درمیان 3,214 روپے کا فلیٹ منافع پلیٹیو، بیرونی پروں کے بالکل اندر ٹوٹ پھوٹ، اور ان کے باہر ہر جگہ تقریباً صفر روپے کا نقصان۔ تتلی کا خیمہ ٹیبل ٹاپ بن گیا ہے، نچلا لیکن چوڑا۔</figcaption></figure>\n<p>یہ ہے کونڈور NIFTY کی پانچ سطحوں پر، فی لاٹ پر آباد ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>24,050 PE خریدا گیا۔</th>\n<th>24,000 PE فروخت ہوا۔</th>\n<th>23,900 PE فروخت ہوا۔</th>\n<th>23,850 PE خریدا گیا۔</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>24,100</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مائنس 36 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>24,000</td>\n<td>مالیت 50</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>علاوہ 3,214 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>23,900</td>\n<td>150 کی مالیت</td>\n<td>100 کی مالیت</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>علاوہ 3,214 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>23,851</td>\n<td>مالیت 199</td>\n<td>مالیت 149</td>\n<td>مالیت 49</td>\n<td>مالیت 0</td>\n<td>0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>23,800</td>\n<td>مالیت 250</td>\n<td>مالیت 200</td>\n<td>100 کی مالیت</td>\n<td>مالیت 50</td>\n<td>مائنس 36 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n</tbody></table>\n<p>اورنج لائن دو اندرونی سٹرائیکس کے درمیان سطح مرتفع پر فلیٹ چلتی ہے، 23,900 سے 24,000 تک ایک ہی 3,214 روپے ادا کرتی ہے، پھر پنکھوں کے باہر 36 روپے کے نقصان پر گر جاتی ہے۔ تتلی کے مقابلے میں، خیمہ ٹیبل ٹاپ بن گیا ہے: 6,107 روپے کی بجائے 3,214 روپے کی نچلی حد، لیکن اس نے ایک پوائنٹ کی بجائے وسیع لینڈنگ زون میں کمایا۔</p>\n<h2 id=\"your-odds-told-honestly\">آپ کی مشکلات، ایمانداری سے بتایا</h2>\n<p>ایک چھوٹی سی لاگت کے خلاف شاندار انعام دونوں ڈھانچے کو تقریباً بہت اچھے لگتے ہیں۔ کیچ جیومیٹری ہے۔ جیتنے کے لیے، NIFTY کو صرف چند سو پوائنٹس چوڑے بینڈ کے اندر ختم کرنا ہوگا، اور زیادہ سے زیادہ جیتنے کے لیے اسے اس سے بھی زیادہ تنگ سلائس میں ختم کرنا ہوگا۔ میعاد ختم ہونے میں تقریباً 32 دن کے ساتھ اور چارٹ پر موجود سگما بینڈز یہ بتاتے ہیں کہ NIFTY کتنی دور تک گھوم سکتا ہے، اس کے پیسے کے نیچے کی صحیح جیب میں بسنے کا امکان بہت کم ہے۔ یہ وہی ہے جو <strong>تتلی پر 9 فیصد اور کنڈور پر 10 فیصد امکان</strong> پیمائش کر رہے ہیں.</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>خطرے کے انعام کو دیکھیں۔ تتلی 1 سے 16 تک پڑھتی ہے اور کنڈور 1 سے 90 تک حیران کن ہے، کیونکہ 36 روپے کا ڈیبٹ 3,214 روپے کے مقابلے میں اتنا چھوٹا ہے۔ یہ کورس میں بہترین تجارت کی طرح نظر آتے ہیں۔ وہ نمبر جو آپ کو ایماندار رکھتا ہے منافع کا امکان ہے، صرف 9 سے 10 فیصد۔ دس میں سے ایک بار جیتنے والا 1 سے 90 تک کی ادائیگی لاٹری ٹکٹ ہے، کنارے نہیں۔</p>\n</div></div>\n<p>کم مشکلات تجارت میں کوئی خامی نہیں ہیں۔ وہ بھاری ادائیگی کی قیمت ہیں۔ مارکیٹ ممکنہ واقعات پر 1 سے 90 مشکلات پیش نہیں کرتی ہے۔ لہذا سستی ایک خصوصیت ہے اور ایک ہی وقت میں ایک جال ہے، اور اگلا حصہ وہ ہے جہاں وہ جال کاٹتا ہے۔</p>\n<h2 id=\"margin-and-what-you-actually-risk\">مارجن اور آپ کو اصل میں کیا خطرہ ہے۔</h2>\n<p>دونوں ڈھانچے a دکھاتے ہیں۔ <strong>تقریباً 63,000 روپے کا مارجن</strong>تتلی کے لیے تقریباً 63,606 روپے اور کنڈور کے لیے 63,256 روپے۔ یہ اعداد و شمار چار الگ الگ ٹانگوں کی عکاسی کرتا ہے جو ایکسچینج کو ٹریک کرنا چاہئے، آپ کی حقیقی نمائش کی نہیں۔ خطرے میں آپ کی اصل نقدی صرف ایک چھوٹا سا خالص ڈیبٹ ہے، 393 روپے یا 36 روپے، کیونکہ خریدا ہوا پنکھ ہر نتیجہ کو محدود کرتا ہے۔ ریٹرن آن مارجن لینس جو سادہ اسپریڈز کے لیے موزوں ہے وہ یہاں فٹ نہیں بیٹھتا، کیونکہ مارجن بک کیپنگ وجوہات کی بناء پر بڑا ہوتا ہے جبکہ حقیقی خطرہ ایک گول غلطی ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک بار جب آپ کا سائز بڑھ جاتا ہے تو قریب صفر کی لاگت صفر کے قریب خطرہ نہیں ہے۔ بیئرش کنڈور کے دس لاٹ کا خطرہ 360 روپے اور بٹر فلائی کے دس لاٹ کا خطرہ 3,930 روپے ہے، اور آپ اس پوری رقم کو دس میں سے تقریباً نو یا دس گنا کھو دیں گے، کیونکہ منافع کا امکان صرف 10 فیصد ہے۔ چند سو روپے والے ٹکٹ کو مفت پیسے کے طور پر سمجھنے اور بہت سی لاٹیں لگانے کا لالچ بالکل اسی طرح ہے کہ کم مشکلات والی شرط حقیقی نقصان میں بدل جاتی ہے۔ ان کا سائز چھوٹے، جان بوجھ کر لگائی جانے والی شرطوں کی طرح لگائیں، نہ کہ سستی لاٹری سٹرپس کے طور پر لوڈ کرنے کے لیے۔</p>\n</div></div>\n<h2 id=\"time-decay-and-why-to-place-these-late\">وقت کی خرابی اور ان کو دیر سے کیوں رکھنا ہے۔</h2>\n<p>یہ خالص ڈیبٹ ڈھانچے ہیں، لیکن وقت کے ساتھ ان کا تعلق غیر معمولی ہے۔ ایک تتلی یا کنڈور صرف اس وقت اپنے پورے خیمے تک پہنچتا ہے جب ہر آپشن خالص اندرونی قدر پر پہنچ جاتا ہے۔ ابھی نیلی T+0 لائن اورنج ایٹ-ایکسپائری لائن سے کہیں زیادہ چاپلوسی ہے، کیونکہ فروخت شدہ باڈی پوٹس میں ابھی بھی ٹائم پریمیم ہوتا ہے جو ابھی ختم نہیں ہوا ہے۔ ڈھانچہ اپنی شکل حاصل کرتا ہے جیسے جیسے گھڑی چلتی ہے، لیکن صرف اس صورت میں جب ایسا ہوتا ہے جب NIFTY جیب میں بیٹھا ہو۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>ان کو ایکسپائری کے قریب رکھیں، اس سے دور نہیں۔ ایک تتلی یا کنڈور ہفتے کے اوائل میں پن کی ہوئی تنگ بینڈ سے باہر گھومنے کے لیے NIFTY کو بہت زیادہ وقت دیتی ہے، اور خیمہ بمشکل ہی بنتا ہے۔ وہی ڈھانچہ جو آخری ہفتے میں رکھا گیا تھا، جب سگما بینڈز سکڑ گئے ہوں اور آپ کو اس بات پر مضبوطی سے پڑھا جائے کہ انڈیکس کہاں پر جمے گا، اس کے پاس جیب میں اترنے اور اپنی پوری چوٹی ادا کرنے کا کہیں بہتر موقع ہے۔</p>\n</div></div>\n<h2 id=\"butterfly-or-condor\">تتلی یا کنڈور</h2>\n<p>صاف آنکھوں کے ساتھ استعمال کیا جاتا ہے، دونوں کا ایک حقیقی کردار ہے۔ وہ صحیح ٹول ہیں جب آپ ایک مخصوص، وقتی نظریہ رکھتے ہیں کہ NIFTY کسی خاص سطح پر نیچے آجائے گا اور وہاں رک جائے گا، شاید کسی معروف سپورٹ میں یا کسی ایسے ایونٹ سے پہلے جس کی آپ انڈیکس کو پن کرنے کی توقع رکھتے ہیں۔ آپ اس قطعی نتیجہ پر متعین خطرے والے ٹکٹ کے لیے چند سو روپے ادا کر رہے ہیں، اور اگر آپ صحیح ہیں تو ادائیگی لاگت کو کم کر دیتی ہے۔</p>\n<ul>\n<li>کا انتخاب کریں۔ <strong>تتلی</strong> جب لینڈنگ اسپاٹ کے بارے میں آپ کا نظریہ تیز ہو اور آپ 23,950 باڈی کو بالکل ٹھیک کرنے کے لیے سب سے زیادہ ادائیگی چاہتے ہیں۔ یہ اپنے عروج پر 6,107 روپے ادا کرتا ہے۔</li>\n<li>کا انتخاب کریں۔ <strong>کنڈور</strong> جب آپ تھوڑا اور کمرہ چاہتے ہیں تو 23,900 سے 24,000 تک ادائیگی کرنے والے پلیٹاو کے بدلے میں 3,214 روپے کی نچلی حد کو قبول کریں۔</li>\n</ul>\n<p>دونوں ٹکٹوں پر آپ کا بدترین کیس پرنٹ کرتے ہیں، 393 روپے یا 36 روپے، جو بالکل وہی ڈسپلن ہے جو یہ کورس دباتا رہتا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>ان تجارتوں پر تخمینہ شدہ پریمیم چاروں ٹانگوں میں ٹرن اوور کا اعداد و شمار ہے اور بڑا لگتا ہے، لیکن یہ آپ کا خطرہ نہیں ہے۔ آپ کا خطرہ چھوٹا خالص ڈیبٹ ہے، 393 روپے یا 36 روپے، کیونکہ خریدے گئے پنکھ ہر نتیجہ کو محدود کرتے ہیں۔ مجموعی پریمیم کو اس رقم کے طور پر نہ پڑھیں جو آپ کھو سکتے ہیں۔ خالص ڈیبٹ پڑھیں، جسے بلڈر زیادہ سے زیادہ نقصان کے طور پر رپورٹ کرتا ہے۔</p>\n</div></div>\n<p>آپ دونوں میں تعمیر کر سکتے ہیں۔ <strong>سینڈ باکس ٹریڈنگ (Analyzer mode in OpenAlgo)</strong>, ایک وقت میں ایک ٹانگیں جوڑنا اور تتلی کے تیز خیمے کو کونڈور کے ٹیبل ٹاپ میں نرم ہوتے دیکھنا جب آپ جسم کو دو ضربوں میں تقسیم کرتے ہیں۔ ماڈل شدہ قیمت کو پورے چارٹ میں سلائیڈ کریں اور دیکھیں کہ یہ منافع کے بینڈ میں کتنی کم ہی آتی ہے، اور یہ چند مواقع پر کتنی بھرپور ادائیگی کرتا ہے۔ یہ احساس، سستا اور شاندار لیکن شاذ و نادر ہی صحیح ہے، بالکل دشاتمک تتلی اور کنڈور کا ایماندار سبق ہے۔ اس باب کے ساتھ بیئرش فیملی مکمل ہو گئی ہے، اور اس کے بعد ہم ان تجارتوں کی طرف رجوع کرتے ہیں جو سمت کی بالکل بھی پرواہ نہیں کرتے ہیں، اس کے بجائے یہ شرط لگاتے ہیں کہ NIFTY کس حد تک آگے بڑھتا ہے۔</p>\n<h2 id=\"key-takeaways\">اہم نکات</h2>\n<ul>\n<li>ایک بیئرش تتلی اوپر سے ایک پوٹ خریدتی ہے، جسم پر دو بیچتی ہے، اور نیچے والی جگہ خریدتی ہے۔ چھوٹا <strong>393 روپے ڈیبٹ زیادہ سے زیادہ نقصان ہے۔</strong>, the <strong>زیادہ سے زیادہ منافع 6,107 روپے ہے۔</strong> 23,950 باڈی پر، اور بریک وینز 23،856 اور 24،047 ہیں۔</li>\n<li>ایک بیئرش کنڈور جسم کو دو فروخت شدہ سٹرائیکس میں تقسیم کرتا ہے، ایک فلیٹ دیتا ہے۔ <strong>3,214 روپے مرتفع</strong> ایک کے لیے 23,900 اور 24,000 کے درمیان <strong>زیادہ سے زیادہ نقصان صرف 36 روپے</strong>.</li>\n<li>دونوں خطرے کا شاندار انعام دکھاتے ہیں، 1 سے 16 اور 1 سے 90، لیکن <strong>منافع کا امکان صرف 9 سے 10 فیصد ہے۔</strong>کیونکہ NIFTY کو ایک تنگ جیب میں اترنا چاہیے۔</li>\n<li>63,000 روپے کا بڑا مارجن بک کیپنگ کے چار پیروں کی عکاسی کرتا ہے، حقیقی نمائش نہیں۔ آپ کا حقیقی خطرہ چھوٹا خالص ڈیبٹ ہے، اور خریدے گئے پنکھ ہر نتیجہ کو محدود کرتے ہیں۔</li>\n<li>وقت ختم ہونے کے قریب خیمہ بناتا ہے، اس لیے یہ بہترین کام کرتے ہیں۔ <strong>سائیکل میں دیر سے رکھا</strong>، جب متوقع حد سکڑ جائے اور لینڈنگ اسپاٹ پر آپ کا پڑھنا مضبوط ہو۔</li>\n<li>ان کے ساتھ عین مطابق لینڈنگ پر چھوٹے، جان بوجھ کر، کم مشکلات والے شرطوں کے طور پر سلوک کریں، اتنی سستی رقم کبھی نہیں کہ بہت ساری لاٹوں میں اسٹیک کریں۔</li>\n</ul>\n","toc":[{"level":2,"text":"ایک لائن کا خیال","id":"the-one-line-idea"},{"level":2,"text":"بیئرش تتلی","id":"the-bearish-butterfly"},{"level":2,"text":"بیئرش کنڈور","id":"the-bearish-condor"},{"level":2,"text":"آپ کی مشکلات، ایمانداری سے بتایا","id":"your-odds-told-honestly"},{"level":2,"text":"مارجن اور آپ کو اصل میں کیا خطرہ ہے۔","id":"margin-and-what-you-actually-risk"},{"level":2,"text":"وقت کی خرابی اور ان کو دیر سے کیوں رکھنا ہے۔","id":"time-decay-and-why-to-place-these-late"},{"level":2,"text":"تتلی یا کنڈور","id":"butterfly-or-condor"},{"level":2,"text":"اہم نکات","id":"key-takeaways"}],"imgCount":2,"hasContent":true},"13":{"html":"<p>اب تک کی ہر حکمت عملی کو ایک سمت کی ضرورت ہے۔ آپ تیزی سے جھک گئے یا آپ نے مندی کا جھکاؤ لیا، اور آپ نے مماثل ڈھانچہ کا انتخاب کیا۔ اب پہلی تجارت سے ملیں جو اس بات کی پرواہ نہیں کرتے ہیں کہ NIFTY کس راستے پر جاتا ہے، صرف کتنی دور۔ 24,056 پر بیٹھے ہوئے انڈیکس کی تصویر بنائیں جس میں کیلنڈر پر ایک بڑا واقعہ، کوئی پالیسی فیصلہ یا نتیجہ جو سب جانتے ہیں کہ اترے گا لیکن کوئی پہلے سے کال نہیں کر سکتا۔ آپ کو یقین ہے کہ NIFTY سخت حرکت کرنے والا ہے۔ آپ صرف یہ نہیں جانتے کہ اوپر یا نیچے۔ دی <strong>لمبی پٹی</strong> اور <strong>طویل گلا گھونٹنا</strong> بالکل اسی لمحے کے لیے بنائے گئے ہیں۔ آپ کال اور پوٹ دونوں خریدتے ہیں، لہذا ایک بڑا اقدام کسی بھی طرح سے ادائیگی کرتا ہے، اور آپ کا واحد حقیقی دشمن ایک بازار ہے جو کہیں نہیں جاتا ہے۔</p>\n<h2 id=\"the-one-line-idea\">ایک لائن کا خیال</h2>\n<p>اے <strong>لمبی پٹی</strong> ایک ہی سٹرائیک اور ایکسپائری پر ایٹ دی منی کال اور ایٹ دی منی کو ایک ساتھ خریدتا ہے۔ اے <strong>طویل گلا گھونٹنا</strong> سستی آؤٹ آف دی منی سٹرائیکس، مارکیٹ کے نیچے ایک پوٹ اور اس کے اوپر کال کے ساتھ بھی یہی کام کرتا ہے۔ کسی بھی طرح سے آپ دونوں اطراف کے مالک ہیں، لہذا ایک ٹانگ کو فائدہ ہوتا ہے اگر NIFTY چڑھ جائے اور دوسری اگر گر جائے۔ آپ ادا کرتے ہیں a <strong>خالص ڈیبٹ</strong> تجارت کو شروع کرنے کے لیے، اور وہ ڈیبٹ، ایک ساتھ دو اختیارات کا پریمیم، آپ کا سارا خطرہ ہے۔</p>\n<p>آپ ان کو استعمال کرتے ہیں جب آپ کا نقطہ نظر کے بارے میں ہے <strong>اتار چڑھاؤ، سمت نہیں۔</strong>. آپ کو جلد ہی ایک تیز اقدام کی توقع ہے اور آپ چاہتے ہیں کہ جس طرح بھی یہ ٹوٹے ادائیگی کی جائے۔ جس چیز سے آپ کو پرہیز کرنا چاہیے وہ ایک پرسکون، بہتی ہوئی مارکیٹ ہے، کیونکہ یہی وہ نتیجہ ہے جو خاموشی سے آپ کو آپ کے زیادہ سے زیادہ نقصان سے دوچار کرتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک لمبا straddle یا گلا گھونٹنا کسی بھی سمت میں ایک بڑی حرکت سے فائدہ اٹھانے کے لئے ایک کال اور ایک جمع خریدتا ہے۔ آپ جو پریمیم ادا کرتے ہیں وہ پورا رسک ہے، منافع ایک حقیقی اقدام پر کھلا ختم ہوتا ہے، اور ایک پرسکون مارکیٹ ہی لاٹ کھونے کا واحد راستہ ہے۔ یہ حرکت پر شرط ہے، نہ کہ مارکیٹ کس راستے پر جاتی ہے۔</p>\n</div></div>\n<h2 id=\"the-straddle-rupee-by-rupee\">سٹرڈل، روپیہ بہ روپیہ</h2>\n<p>26 جون 2026 کو انڈیکس کے ساتھ حاصل کی گئی حقیقی NIFTY کی قیمتوں کا یہ ہے <strong>24,056</strong> اور 28 جولائی 2026 کی میعاد تقریباً 32 دن ختم ہو رہی ہے۔ آپ ایٹ دی منی 24,050 کال خریدتے ہیں اور 24,050 پوٹ پر۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>کال خریدیں۔</td>\n<td>24,050</td>\n<td>425.8 ادا کیا گیا۔</td>\n<td>27,677 روپے باہر</td>\n</tr>\n<tr>\n<td>2</td>\n<td>ڈال خریدیں</td>\n<td>24,050</td>\n<td>295.1 ادا کیا گیا۔</td>\n<td>19,182 روپے باہر</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>خالص ڈیبٹ</strong></td>\n<td><strong>46,858 روپے باہر</strong></td>\n</tr>\n</tbody></table>\n<p>دونوں ٹانگیں پیسے پر دائیں بیٹھتی ہیں، جہاں وقت کی قیمت سب سے زیادہ ہوتی ہے، اس لیے بل بہت زیادہ ہے۔ آپ دونوں اختیارات میں تقریباً 720.9 پوائنٹس ایک شیئر ادا کرتے ہیں، جو کہ ہے۔ <strong>46,858 روپے</strong> 65 کی ایک لاٹ کے لیے۔ کیونکہ آپ نے پہلے ہی اس کی ادائیگی کر دی ہے اور اس سے زیادہ ایک روپیہ کبھی نہیں مانگا جا سکتا ہے، یہ سب سے زیادہ ہے جو آپ کھو سکتے ہیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-long-straddle.png\" alt=\"NIFTY پر لمبا سٹرڈل: 24,050 اسٹرائیک پر ایک تیز V جہاں مکمل 46,858 روپے ضائع ہو جاتے ہیں، 23,329 اور 24,771 پر بریک ایونز، اور منافع کی لکیریں جو بغیر کسی حد کے بڑھ جاتی ہیں کیونکہ انڈیکس دونوں سمتوں میں بہت دور جاتا ہے۔ نیلی ڈیشڈ T+0 لائن مرکز کے قریب نارنجی V کے اوپر تیرتی ہے، جس وقت کی قیمت آپ لڑ رہے ہیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY پر لمبا سٹرڈل: 24,050 اسٹرائیک پر ایک تیز V جہاں مکمل 46,858 روپے ضائع ہو جاتے ہیں، 23,329 اور 24,771 پر بریک ایونز، اور منافع کی لکیریں جو بغیر کسی حد کے بڑھ جاتی ہیں کیونکہ انڈیکس دونوں سمتوں میں بہت دور جاتا ہے۔ نیلی ڈیشڈ T+0 لائن مرکز کے قریب نارنجی V کے اوپر تیرتی ہے، جس وقت کی قیمت آپ لڑ رہے ہیں۔</figcaption></figure>\n<h2 id=\"the-three-numbers-of-the-straddle\">سٹرڈل کے تین نمبر</h2>\n<p>ہر نمبر اوپر کی تجارت سے سیدھا آتا ہے۔ کل پریمیم فی حصص، 425.8 جمع 295.1، 720.9 ہے، اور وہ واحد اعداد و شمار سب کچھ چلاتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>خالص ڈیبٹ ادا کیا گیا۔</td>\n<td>46,858 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>ایک حقیقی اقدام پر کھلا ختم ہوا۔</td>\n<td>لا محدود</td>\n</tr>\n<tr>\n<td>Breakevens</td>\n<td>اسٹرائیک مائنس، پھر پلس، کل پریمیم فی شیئر</td>\n<td>24,050 مائنس 720.9 برابر 23,329; 24,050 جمع 720.9 برابر 24,771</td>\n</tr>\n</tbody></table>\n<p><strong>زیادہ سے زیادہ نقصان ڈیبٹ ہے، 46,858 روپے۔</strong> آپ اسے صرف ایک عین نقطہ پر برداشت کرتے ہیں، 24,050 پر ایک قریبی حق، جہاں دونوں اختیارات ایک ساتھ بیکار ختم ہوجاتے ہیں۔ <strong>زیادہ سے زیادہ منافع لامحدود ہے۔</strong> اوپری بریک ایون کے اوپر کال بغیر کسی حد کے چلتی ہے، اور گرنے پر پوٹ صفر کی طرف بڑھتا ہے، یہ ایک بہت بڑی لیکن محدود رقم ہے، جسے بلڈر ایمانداری سے لامحدود کا لیبل لگاتا ہے۔ <strong>بریک ایونز 23,329 اور 24,771 ہیں۔</strong>، وہ دو نشانات جہاں ایک اقدام نے آخر کار آپ کے خرچ کردہ پریمیم کے 720.9 پوائنٹس کو واپس کر دیا ہے۔</p>\n<h2 id=\"walking-the-straddle-outcomes-at-expiry\">سٹرڈل پر چلنے کے نتائج ختم ہونے پر</h2>\n<p>تجارت کو پانچ اختتامی قیمتوں پر طے کریں اور V خود ہی ظاہر ہوتا ہے۔ ایک کال ایکسپائری پر زیادہ سے زیادہ( NIFTY مائنس 24,050, 0) کی قیمت ہے، ایک پوٹ زیادہ سے زیادہ (24,050 مائنس NIFTY, 0) کی مالیت ہے، اور نیٹ وہ ہے جو دو بار 65، مائنس 46,858 روپے جو آپ نے ادا کیے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>24,050 کال آپ نے خریدی۔</th>\n<th>24,050 آپ نے خریدا۔</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,000</td>\n<td>مالیت 0</td>\n<td>مالیت 1,050</td>\n<td>علاوہ 21,392 روپے</td>\n</tr>\n<tr>\n<td>23,329</td>\n<td>مالیت 0</td>\n<td>مالیت 721</td>\n<td>0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مائنس 46,858 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>24,771</td>\n<td>مالیت 721</td>\n<td>مالیت 0</td>\n<td>0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>25,300</td>\n<td>مالیت 1,250</td>\n<td>مالیت 0</td>\n<td>علاوہ 34,392 روپے</td>\n</tr>\n</tbody></table>\n<p>کالم کو پڑھیں اور سبق بالکل واضح ہے۔ اترنے کے لیے واحد بدترین جگہ ڈیڈ سینٹر ہے، جو ہڑتال آپ نے خریدی تھی، جہاں آپ سب کچھ کھو دیتے ہیں۔ کسی بھی سمت میں باہر کی طرف چلیں اور ایک ٹانگ زندہ آجاتی ہے، نقصان سکڑ جاتا ہے، آپ بریک ایون پر صفر کو عبور کرتے ہیں، اور اس سے آگے منافع بغیر کسی حد کے چڑھ جاتا ہے۔ آپ وادی کے بالکل نیچے داخل ہوئے ہیں اور آپ کو باہر چڑھنے کے لیے NIFTY کی ضرورت ہے۔</p>\n<h2 id=\"the-strangle-rupee-by-rupee\">گلا گھونٹنا، روپیہ بہ روپیہ</h2>\n<p>اسٹیڈل کام کرتا ہے لیکن یہ مہنگا ہے، کیونکہ دونوں ٹانگیں وہاں بیٹھتی ہیں جہاں وقت کی قیمت سب سے زیادہ ہوتی ہے۔ دی <strong>طویل گلا گھونٹنا</strong> اس کی بجائے پیسے سے باہر کے اختیارات خرید کر کم پیسوں میں ایک ہی شکل رکھتا ہے۔ آپ مارکیٹ کے نیچے 23,950 پوٹ دو سٹرائیکس خریدتے ہیں اور 24,150 اس کے اوپر دو سٹرائیکس کال کرتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>ڈال خریدیں</td>\n<td>23,950</td>\n<td>256.6 ادا کیا گیا۔</td>\n<td>16,679 روپے باہر</td>\n</tr>\n<tr>\n<td>2</td>\n<td>کال خریدیں۔</td>\n<td>24,150</td>\n<td>370.1 ادا کیا گیا۔</td>\n<td>24,057 روپے باہر</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>خالص ڈیبٹ</strong></td>\n<td><strong>40,729 روپے باہر</strong></td>\n</tr>\n</tbody></table>\n<p>کیونکہ دونوں ٹانگیں پیسے سے باہر ہیں، ہر ایک کی قیمت کم ہے، اور <strong>خالص ڈیبٹ 40,729 روپے تک گرتا ہے۔</strong>سٹریڈل سے تقریباً 6,000 روپے سستا ہے۔ کیچ یہ ہے کہ سستا داخلہ بدتر بریک ایون خریدتا ہے، بہتر نہیں، کیونکہ اب درمیان میں ایک ڈیڈ بینڈ ہے جہاں کوئی ٹانگ ادا نہیں کرتی ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-long-strangle.png\" alt=\"NIFTY پر لمبا گلا گھونٹنا: ایک چپٹی نیچے والی بالٹی 23,950 اور 24,150 کے درمیان کہیں بھی پورے 40,729 روپے کھو دیتی ہے، 23,323 اور 24,777 پر بریک ایونز، اور لامحدود منافع ایک بار جب انڈیکس اس سے کہیں آگے بڑھ جاتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY پر لمبا گلا گھونٹنا: ایک فلیٹ نیچے والی بالٹی 23,950 اور 24,150 کے درمیان کہیں بھی پورے 40,729 روپے کھو دیتی ہے، 23,323 اور 24,777 پر بریک ایونز، اور لامحدود منافع ایک بار جب انڈیکس اس سے کہیں آگے بڑھ جاتا ہے۔</figcaption></figure>\n<h2 id=\"the-three-numbers-of-the-strangle\">گلا گھونٹنے کے تین نمبر</h2>\n<p>کل پریمیم فی حصص، 256.6 جمع 370.1، 626.7 ہے، اور یہ آپ کی خریدی گئی دو سٹرائیکس کے وقفے کو سیٹ کرتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>خالص ڈیبٹ ادا کیا گیا۔</td>\n<td>40,729 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>ایک حقیقی اقدام پر کھلا ختم ہوا۔</td>\n<td>لا محدود</td>\n</tr>\n<tr>\n<td>Breakevens</td>\n<td>لوئر سٹرائیک مائنس، اپر سٹرائیک پلس، کل پریمیم فی شیئر</td>\n<td>23,950 مائنس 626.7 برابر 23,323; 24,150 جمع 626.7 برابر 24,777</td>\n</tr>\n</tbody></table>\n<p>گلا گھونٹنا بیچ میں کچھ نہیں دیتا۔ 23,950 اور 24,150 کے درمیان کہیں بھی دونوں آپشن ختم ہونے پر بے کار ہو جاتے ہیں، اس لیے اس پورے مرکزی بینڈ میں آپ پورے 40,729 روپے سے محروم ہو جاتے ہیں۔ اس کی ٹوٹ پھوٹ، <strong>23,323 اور 24,777</strong>، straddle کے مقابلے میں تھوڑا چوڑا بیٹھو. آپ نے داخل ہونے کے لیے کم ادائیگی کی، اور بدلے میں NIFTY کو آپ کو ادائیگی کرنے سے پہلے ایک ٹچ مزید منتقل کرنا ہوگا۔</p>\n<h2 id=\"walking-the-strangle-outcomes-at-expiry\">ختم ہونے پر گلا گھونٹنا نتائج</h2>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>23,950 آپ نے خریدا۔</th>\n<th>24,150 کال آپ نے خریدی۔</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,000</td>\n<td>950 کی مالیت</td>\n<td>مالیت 0</td>\n<td>علاوہ 21,021 روپے</td>\n</tr>\n<tr>\n<td>23,323</td>\n<td>مالیت 627</td>\n<td>مالیت 0</td>\n<td>0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مائنس 40,729 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>24,777</td>\n<td>مالیت 0</td>\n<td>مالیت 627</td>\n<td>0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>25,300</td>\n<td>مالیت 0</td>\n<td>مالیت 1,150</td>\n<td>علاوہ 34,021 روپے</td>\n</tr>\n</tbody></table>\n<p>سٹرڈل کی تیز V ایک چپٹی نیچے والی بالٹی بن گئی ہے۔ ایک گرت کے بجائے، سٹرائیکس کے درمیان پورے وقفے پر نقصان 40,729 روپے پر فلیٹ ہے، پھر لائن صرف پنکھوں سے باہر ہوتی ہے۔ ایک جیسی شکل، رکھنا سستا، لیکن آپ کو ادائیگی کرنے سے پہلے سفر کرنے کے لیے ایک وسیع فاصلہ۔</p>\n<h2 id=\"your-odds\">آپ کی مشکلات</h2>\n<p>زیادہ سے زیادہ جاننا کہ آپ جیت سکتے ہیں اور ہار سکتے ہیں صرف آدھی کہانی ہے۔ سوال جو فیصلہ کرتا ہے کہ آیا تجارت ہوشیار ہے کہ منافع کا کتنا امکان ہے، اور وہ ہے۔ <strong>منافع کا امکان</strong>، دائیں پینل پر دکھایا گیا ہے۔ کے لیے <strong>straddle یہ 42 فیصد ہے۔</strong>، کے لئے <strong>41 فیصد گلا گھونٹنا</strong>. دونوں آدھے سے نیچے بیٹھتے ہیں، اور وجہ دیانت دار ہے: NIFTY کو 720 پوائنٹس سے زیادہ کا سفر کرنا پڑتا ہے تاکہ اسٹریڈل کو واپس کرنے کے لیے اور 626 سے زیادہ پوائنٹس کا گلا واپس کرنے کے لیے، تقریباً ایک مہینے میں انڈیکس کا تقریباً تین فیصد، جو کہ پوچھنے کے لیے ایک حقیقی فاصلہ ہے۔</p>\n<p>بیہوش کو دیکھو <strong>سگما بینڈ</strong> ہر چارٹ پر، آپشن مارکیٹ کی منتقلی اصل میں قیمتوں کا تعین کرتی ہے۔ بریکونز اندرونی بینڈ کے کنارے کے قریب بیٹھتے ہیں، اس کے اندر نہیں۔ یہ وہ مارکیٹ ہے جو آپ کو بتا رہی ہے کہ یہ ایک بڑے اقدام پر تقریباً برابر رقم کی شرطیں ہیں، مزید نہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>ہمیشہ لاگت کے ساتھ منافع کے امکان کو پڑھیں، کبھی اکیلے نہ ہوں۔ منافع کے 42 فیصد امکانات کے ساتھ 46,858 روپے کا خطرہ صرف اس وقت خریدنے کے قابل ہے جب آپ حقیقی طور پر اس سے بڑے اقدام کی توقع کرتے ہیں جس کی مارکیٹ نے پہلے ہی ان چربی پریمیم میں قیمت رکھی ہے۔ بہترین اندراج اس وقت ہوتا ہے جب مضمر اتار چڑھاؤ کم ہو اور آپ اس کے بڑھنے کی توقع کرتے ہیں، اس کے بعد نہیں کہ کسی معروف واقعہ کے پہلے ہی اختیارات میں اضافہ ہو جائے۔ اس اقدام کو خریدیں اس سے پہلے کہ ہجوم اس کی قیمت لگائے، اس کے بعد نہیں۔</p>\n</div></div>\n<h2 id=\"margin\">مارجن</h2>\n<p>کیونکہ آپ ایک خالص خریدار ہیں، ایکسچینج بلاکس <strong>ڈیبٹ کے برابر مارجن</strong>کے بارے میں <strong>سٹرڈل کے لیے 46,858 روپے</strong> اور <strong>گلا گھونٹنے کے لیے 40,729 روپے</strong>اور ایک روپیہ زیادہ نہیں۔ کوئی SPAN جرمانہ نہیں ہے اور نہ ہی کوئی ایکسپوزر بفر ہے، کیونکہ آپ نے پہلے ہی سب سے زیادہ حوالے کر دیے ہیں جو آپ کھو سکتے ہیں۔ یہ طویل اختیارات ہونے کا خاموش تحفہ ہے: آپ کے آرڈر دینے سے پہلے ہی آپ کا بدترین کیس ٹکٹ پر پرنٹ ہوجاتا ہے، اور مارجن اس کے برابر ہوجاتا ہے۔</p>\n<p>یہاں کوٹ کرنے کے لیے مارجن پر کوئی مقررہ واپسی نہیں ہے، کیونکہ منافع محدود ہونے کے بجائے کھلا ہوا ہے۔ ان تجارتوں کو اس اقدام کے مقابلے میں ان کی لاگت سے اندازہ لگائیں جس کی آپ توقع کرتے ہیں: آپ ایک بڑے جھولے پر ایک طے شدہ خطرے والے ٹکٹ کے لیے 46,858 روپے یا 40,729 روپے ادا کر رہے ہیں، اور ادائیگی مزید NIFTY کے وقفے سے گزرنے کے بعد بڑھتی ہے۔</p>\n<h2 id=\"time-decay-is-the-enemy\">وقت کا زوال دشمن ہے۔</h2>\n<p>کو دوبارہ دیکھیں <strong>نیلی ڈیشڈ T+0 لائن</strong> ہر چارٹ کے مرکز کے قریب اورنج at-expiry V کے اوپر تیرتا ہے۔ وہ خلا ہے۔ <strong>وقت کی قدر</strong>اور خریدار کے لیے یہ روزانہ ٹیکس ہے۔ آپ کے پاس ایک ہی وقت میں دو اختیارات ہیں، اس لیے دونوں ٹانگوں سے کشی آپ کے خلاف چلتی ہے۔ ہر پرسکون دن نیلی لائن نارنجی کی طرف جھکتی ہے، اور پوزیشن پیسے کھو دیتی ہے یہاں تک کہ جب NIFTY بمشکل حرکت کرتا ہے۔ ایک خالص بیچنے والے کو اسی خرابی سے ادائیگی کی جاتی ہے۔ ایک سٹریڈل یا گلا گھونٹنے والا خریدار ہر ایک سیشن سے لڑتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک لمبا سٹریڈل یا گلا گھونٹنے سے ہر پرسکون دن وقت کی قیمت نکلتی ہے، اور اس سے ایک ہی وقت میں دو ٹانگوں سے خون نکلتا ہے۔ 46,858 روپے یا 40,729 روپے جو آپ نے ادا کیے ہیں وہ نہ صرف خطرے میں ہے اگر NIFTY ساکن رہے بلکہ اگر یہ آہستہ آہستہ بڑھے، کیونکہ یہ اقدام کشی کو پیچھے چھوڑنے کے لیے بڑا اور معقول حد تک تیز ہونا چاہیے۔ ان کو کبھی بھی رکھنے اور بھول جانے کے عہدوں کے طور پر نہ سمجھیں۔ وہ شرط لگاتے ہیں کہ جلد ہی کچھ ہونے والا ہے، اور ایک پُرسکون پندرھواڑہ ختم ہونے سے پہلے ہی حقیقی نقصان پہنچانے کے لیے کافی ہے۔</p>\n</div></div>\n<h2 id=\"straddle-or-strangle\">گلا گھونٹنا یا گلا گھونٹنا؟</h2>\n<p>دونوں کو ساتھ ساتھ رکھیں اور انتخاب فاصلے کے خلاف لاگت کے بارے میں ایک سادہ سودا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>لمبا سٹرڈل</th>\n<th>لمبا گلا گھونٹنا</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>لا محدود</td>\n<td>لا محدود</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>46,858 روپے</td>\n<td>40,729 روپے</td>\n</tr>\n<tr>\n<td>Breakevens</td>\n<td>23,329 اور 24,771</td>\n<td>23,323 اور 24,777</td>\n</tr>\n<tr>\n<td>منافع کا امکان</td>\n<td>42 فیصد</td>\n<td>41 فیصد</td>\n</tr>\n<tr>\n<td>خالص ڈیبٹ</td>\n<td>46,858 روپے</td>\n<td>40,729 روپے</td>\n</tr>\n<tr>\n<td>مارجن درکار ہے۔</td>\n<td>46,858 روپے</td>\n<td>40,729 روپے</td>\n</tr>\n</tbody></table>\n<p>اسٹریڈل کی قیمت زیادہ ہے لیکن کچھ پوائنٹس جلد کام کرنا شروع کر دیتا ہے، کیونکہ اس کی ٹانگیں پہلے ہی پیسے پر ہیں۔ گلا گھونٹنے کی قیمت تقریباً 6,000 روپے کم ہے لیکن اس کی ادائیگی سے پہلے قدرے بڑے اقدام کا مطالبہ کرتا ہے۔ جب آپ سخت ترین ممکنہ بریک ایونز چاہتے ہیں اور پرتشدد، فوری اقدام کی توقع کرتے ہیں تو اسٹریڈل کا انتخاب کریں۔ جب آپ کم خطرہ مول لینا چاہتے ہیں اور بڑے جھولے کا انتظار کرنے میں خوش ہوں تو گلا کا انتخاب کریں۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>آپ دونوں میں تعمیر کر سکتے ہیں۔ <strong>سینڈ باکس ٹریڈنگ ( OpenAlgo میں تجزیہ کار موڈ)</strong>، ایک وقت میں کال اور پوٹ ایک ٹانگ کو شامل کرتے ہوئے اور لمبی آپشن کی سنگل لائن کو سٹریڈل کے V میں فولڈ ہوتے دیکھنا، پھر گلا گھونٹنے والی بالٹی میں پھیل جاتے ہیں جب آپ سٹرائیکس کو الگ کرتے ہیں۔ ماڈل کی قیمت کو پورے چارٹ میں سلائیڈ کریں اور محسوس کریں کہ ایک پرسکون دن آپ کی کتنی کم ہی مدد کرتا ہے اور ایک حقیقی اقدام کتنی بھرپور ادائیگی کرتا ہے۔ وہ جبلت، کہ آپ حرکت خرید رہے ہیں اور گھڑی سے لڑ رہے ہیں، ہر طویل اتار چڑھاؤ کی تجارت کا دل ہے۔</p>\n</div></div>\n<h2 id=\"key-takeaways\">اہم نکات</h2>\n<ul>\n<li>ایک لمبا اسٹراڈل ایٹ دی منی کال خریدتا ہے اور ڈالتا ہے، ایک لمبا گلا سستا پیسہ باہر کی ہڑتالوں کو خریدتا ہے، اور دونوں میں ایک بڑی حرکت سے منافع ہوتا ہے۔ <strong>یا تو سمت</strong>.</li>\n<li>دی <strong>خالص ڈیبٹ سارا خطرہ ہے۔</strong>, 46,858 روپے اسٹریڈل کے لیے اور 40,729 روپے گلا گھونٹنے کے لیے، اور مارجن صرف اس کے برابر ہے کیونکہ تجارت کی وضاحت شدہ خطرہ ہے۔</li>\n<li><strong>منافع لامحدود ہے۔</strong> ایک حقیقی اقدام پر، لیکن بریک ایونز جگہ سے بہت دور بیٹھتے ہیں، اسٹریڈل کے لیے 23,329 اور 24,771 اور گلا گھونٹنے کے لیے 23,323 اور 24,777 پر۔</li>\n<li>دی <strong>منافع کا امکان نصف سے کم ہے۔</strong>, 42 اور 41 فیصد، کیونکہ مارکیٹ نے پہلے ہی ان پریمیم میں ایک مناسب سائز کی قیمت مقرر کر دی ہے۔</li>\n<li><strong>وقت کا زوال دشمن ہے۔</strong>: آپ کے پاس دو اختیارات طویل ہیں، قیمت دو گنا تیزی سے بہہ رہی ہے، اور ایک پرسکون بازار وہ نتیجہ ہے جو آپ کو سب کچھ کھو دیتا ہے۔</li>\n<li>سٹریڈل سخت بریک وینس کے لیے زیادہ قیمت ادا کرتا ہے۔ گلا گھونٹنے کی قیمت کم ہے لیکن ایک بڑے اقدام کی ضرورت ہے۔ اگلے باب میں آپ دونوں کا دوسرا رخ لیں گے، پریمیم بیچنا اور مخالف خطرے کو وراثت میں لینا۔</li>\n</ul>\n","toc":[{"level":2,"text":"ایک لائن کا خیال","id":"the-one-line-idea"},{"level":2,"text":"سٹرڈل، روپیہ بہ روپیہ","id":"the-straddle-rupee-by-rupee"},{"level":2,"text":"سٹرڈل کے تین نمبر","id":"the-three-numbers-of-the-straddle"},{"level":2,"text":"سٹرڈل پر چلنے کے نتائج ختم ہونے پر","id":"walking-the-straddle-outcomes-at-expiry"},{"level":2,"text":"گلا گھونٹنا، روپیہ بہ روپیہ","id":"the-strangle-rupee-by-rupee"},{"level":2,"text":"گلا گھونٹنے کے تین نمبر","id":"the-three-numbers-of-the-strangle"},{"level":2,"text":"ختم ہونے پر گلا گھونٹنا نتائج","id":"walking-the-strangle-outcomes-at-expiry"},{"level":2,"text":"آپ کی مشکلات","id":"your-odds"},{"level":2,"text":"مارجن","id":"margin"},{"level":2,"text":"وقت کا زوال دشمن ہے۔","id":"time-decay-is-the-enemy"},{"level":2,"text":"گلا گھونٹنا یا گلا گھونٹنا؟","id":"straddle-or-strangle"},{"level":2,"text":"اہم نکات","id":"key-takeaways"}],"imgCount":2,"hasContent":true},"14":{"html":"<p>آخری باب میں آپ خریدار تھے، ایک بھرپور پریمیم ادا کر رہے تھے اور بڑے اقدام کی دعا کر رہے تھے۔ اب اسی تجارت کے دوسری طرف کھڑے ہوں۔ کسی کو سٹریڈل خریدار کو ان کی کال اور ان کا پوٹ بیچنا ہے، اس فیٹ پریمیم میں لینا ہے، اور اس کے برعکس شرط لگانا ہے، کہ NIFTY کہیں نہیں جاتا ہے۔ اس باب میں وہ بیچنے والے آپ ہیں۔ دی <strong>مختصر straddle</strong> اور <strong>مختصر گلا گھونٹنا</strong> پرسکون مارکیٹ کی آمدنی کی تجارت ہیں۔ آپ سامنے پریمیم جمع کرتے ہیں، اور ہر پرسکون دن پوزیشن کو منافع کی طرف کھینچتا ہے۔ شکل موہک ہے اور جیت کی شرح زیادہ ہے۔ خطرہ یہ ہے کہ آپ کو خریدار کے لامحدود انعام کو آپ کے اپنے لامحدود نقصان کے طور پر وراثت میں ملا ہے، اور یہ کہ ایک حقیقت آپ کے یہاں ہر کام کو کنٹرول کرتی ہے۔</p>\n<h2 id=\"the-one-line-idea\">ایک لائن کا خیال</h2>\n<p>اے <strong>مختصر straddle</strong> ایٹ دی منی کال اور ایٹ دی منی کو ایک ساتھ فروخت کرتا ہے۔ اے <strong>مختصر گلا گھونٹنا</strong> سستی فروخت کرتا ہے۔ کسی بھی طرح سے آپ کو ایک میں لے <strong>خالص کریڈٹ</strong> سامنے، اور آپ اسے اس وقت تک رکھتے ہیں جب تک کہ NIFTY ایک بینڈ کے اندر رہتا ہے۔ آپ اس اقدام کو فروخت کر رہے ہیں جس کی قیمت ایک سٹرڈل خریدار ادا کر رہا ہے، شرط لگاتے ہوئے کہ مارکیٹ آپشن پریمیم سے زیادہ پرسکون ہو گی۔</p>\n<p>کریڈٹ آپ کا زیادہ سے زیادہ منافع ہے۔ کیچ، اور یہ ایک سنگین ہے، کہ دونوں ٹانگیں ننگی ہیں۔ ایک مختصر کال کی اس کے اوپر کوئی حد نہیں ہوتی ہے، اور ایک مختصر پوٹ صفر کی طرف بہت نیچے چلا جاتا ہے، اس لیے نقصان اوپر کھلا ہوا اور بہت بڑا ہے اگرچہ نیچے بندھا ہوا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک چھوٹا سا سٹریڈل یا گلا گھونٹنا ایک پرسکون بازار سے پریمیم جمع کرنے کے لیے کال اور ایک ساتھ مل کر فروخت کرتا ہے۔ کریڈٹ آپ سب سے زیادہ بنا سکتے ہیں، وقت کی کمی آپ کے لیے کام کرتی ہے، اور آپ زیادہ تر مہینے جیت جاتے ہیں۔ لیکن بیچی ہوئی دونوں ٹانگیں ننگی ہیں، نقصان کی اوپر کوئی حد نہیں ہے اور وہ نیچے ایک بہت بڑی لیکن جکڑے ہوئے اعداد و شمار تک چلا جاتا ہے، اور ایکسچینج اس کھلی دم کی وجہ سے خاص طور پر ایک بڑے مارجن کو روکتا ہے۔</p>\n</div></div>\n<h2 id=\"the-short-straddle-rupee-by-rupee\">مختصر سٹرڈل، روپیہ بہ روپیہ</h2>\n<p>یہ ہے حقیقی NIFTY قیمتوں پر مختصر اسٹریڈل، 26 جون 2026 کو انڈیکس کے ساتھ پکڑا گیا <strong>24,056</strong> اور 28 جولائی 2026 کی میعاد تقریباً 32 دن ختم ہو رہی ہے۔ آپ ایٹ دی منی 24,050 کال اور ایٹ دی منی 24,050 پوٹ بیچتے ہیں، دونوں پریمیم ایک ساتھ جمع کرتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>کال فروخت کریں۔</td>\n<td>24,050</td>\n<td>425.8 موصول ہوا۔</td>\n<td>27,677 روپے میں</td>\n</tr>\n<tr>\n<td>2</td>\n<td>ڈال فروخت</td>\n<td>24,050</td>\n<td>295.1 موصول ہوا۔</td>\n<td>19,182 روپے میں</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>نیٹ کریڈٹ</strong></td>\n<td><strong>46,858 روپے میں</strong></td>\n</tr>\n</tbody></table>\n<p>آپ دونوں اختیارات میں تقریباً 720.9 پوائنٹس کا حصہ لیتے ہیں، <strong>46,858 روپے</strong> 65 کی ایک لاٹ کے لیے، اور جب آپ تجارت کھولتے ہیں تو یہ آپ کے اکاؤنٹ میں آتا ہے۔ وہ کریڈٹ آپ کا ہے۔ <strong>زیادہ سے زیادہ منافع</strong>مکمل طور پر صرف اسی صورت میں رکھا جائے گا جب NIFTY بالکل 24,050 پر ختم ہو جائے، جہاں آپ کے بیچے گئے دونوں آپشنز کی میعاد ختم ہو جاتی ہے اور آپ پر کچھ واجب نہیں ہوتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-short-straddle.png\" alt=\"NIFTY پر مختصر اسٹریڈل: ایک الٹا V 24,050 پر مکمل 46,858 روپے کے کریڈٹ پر چوٹی، 23,329 اور 24,771 پر بریک ایونز، اور نقصان کی لکیریں جو دونوں طرف بغیر کسی حد کے گرتی ہیں کیونکہ انڈیکس اسٹرائیک سے ہٹ جاتا ہے۔ نیلی ڈیشڈ T+0 لائن نارنجی چوٹی کے نیچے بیٹھی ہے، وقت کی قدر ابھی بھی آپ کے حق میں زوال پذیر ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY پر مختصر اسٹریڈل: ایک الٹا V 24,050 پر مکمل 46,858 روپے کے کریڈٹ پر چوٹی، 23,329 اور 24,771 پر بریک ایونز، اور نقصان کی لکیریں جو دونوں طرف بغیر کسی حد کے گرتی ہیں کیونکہ انڈیکس اسٹرائیک سے ہٹ جاتا ہے۔ نیلی ڈیشڈ T+0 لائن نارنجی چوٹی کے نیچے بیٹھی ہے، وقت کی قدر ابھی بھی آپ کے حق میں زوال پذیر ہے۔</figcaption></figure>\n<h2 id=\"the-three-numbers-of-the-short-straddle\">مختصر اسٹریڈل کے تین نمبر</h2>\n<p>کل پریمیم فی حصص، 425.8 جمع 295.1، 720.9 ہے، وہی اعداد و شمار جس نے لمبے لمبے راستے کو آگے بڑھایا، کیونکہ آپ نے صرف دوسری طرف لے لیا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>خالص کریڈٹ جمع کیا گیا۔</td>\n<td>46,858 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>ایک بڑے اقدام پر کھلا ختم ہوا۔</td>\n<td>لا محدود</td>\n</tr>\n<tr>\n<td>Breakevens</td>\n<td>اسٹرائیک مائنس، پھر پلس، کل پریمیم فی شیئر</td>\n<td>24,050 مائنس 720.9 برابر 23,329; 24,050 جمع 720.9 برابر 24,771</td>\n</tr>\n</tbody></table>\n<p>NIFTY بریک ایونز کے درمیان 1,442-پوائنٹ بینڈ کے اندر کہیں بھی گھوم سکتا ہے اور آپ پھر بھی سیاہ رنگ میں ختم ہوجاتے ہیں۔ 24,771 سے آگے برہنہ کال آپ کو بغیر کسی حد کے روپے کے بدلے روپیہ خرچ کرتی ہے، اور 23,329 سے نیچے ننگی پوٹ پوری طرح سے NIFTY خریدتے رہنے کی ذمہ داری کی طرح برتاؤ کرتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک مختصر اسٹریڈل کا زیادہ سے زیادہ منافع 46,858 روپے ہے اور نقصان جو دونوں طرف کھلا ہوا ہے۔ آپ نے ایک برہنہ کال فروخت کی ہے، لہذا ایک مضبوط ریلی آپ کو بغیر کسی حد کے 24,771 سے اوپر خرچ کرتی ہے، اور ایک برہنہ پوٹ، لہذا حادثے کی قیمت آپ کو 23,329 سے نیچے اس منزل کی طرف لے جاتی ہے جہاں انڈیکس صفر تک پہنچ جاتا ہے۔ الٹا نقصان واقعی لامحدود ہے۔ منفی پہلو صرف اس منزل سے جڑا ہوا ہے، جس کا مطلب اب بھی ایک انڈیکس پر اتنا بڑا ہے کہ یہ کسی بھی عملی مقصد کے لیے تباہ کن ہے۔ یہ ایک ہی اسٹرائیک پر ڈھیر دو ننگی چھوٹی ٹانگیں ہیں، اور ایک ہی وقفہ، اوپر یا نیچے، ایک صبح میں کئی مہینوں کے خاموش کریڈٹ کو مٹا سکتا ہے۔</p>\n</div></div>\n<h2 id=\"walking-the-short-straddle-outcomes-at-expiry\">ایکسپائری پر شارٹ سٹریڈل کے نتائج پر چلنا</h2>\n<p>پانچ اختتامی قیمتوں پر تجارت طے کریں۔ ایک کال کی میعاد ختم ہونے پر زیادہ سے زیادہ مالیت (NIFTY مائنس 24,050, 0) ہے، ایک پوٹ کی قیمت زیادہ سے زیادہ (24,050 مائنس NIFTY, 0) ہے، اور آپ کا نیٹ 46,858 روپے کا کریڈٹ ہے ان دونوں اقدار کو مائنس 65 گنا۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>24,050 کال آپ نے فروخت کی۔</th>\n<th>24,050 میں آپ نے فروخت کیا۔</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,000</td>\n<td>مالیت 0</td>\n<td>مالیت 1,050</td>\n<td>مائنس 21,392 روپے</td>\n</tr>\n<tr>\n<td>23,329</td>\n<td>مالیت 0</td>\n<td>مالیت 721</td>\n<td>0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>جمع 46,858 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,771</td>\n<td>مالیت 721</td>\n<td>مالیت 0</td>\n<td>0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>25,300</td>\n<td>مالیت 1,250</td>\n<td>مالیت 0</td>\n<td>مائنس 21,392 روپے</td>\n</tr>\n</tbody></table>\n<p>اترنے کے لیے واحد بہترین جگہ ڈیڈ سینٹر ہے، جس ہڑتال پر آپ نے فروخت کیا، جہاں آپ پورا کریڈٹ رکھتے ہیں۔ باہر کی طرف چلتے ہیں اور منافع سکڑ جاتا ہے، بریک ایون پر صفر کو عبور کرتا ہے، اور پھر نقصان ختم ہو جاتا ہے، جس کے اوپر کوئی چھت نہیں ہوتی اور صرف زیرو پر منزل ہوتی ہے۔ نوٹ کریں کہ ٹیبل صرف 25,300 تک پہنچتا ہے، جہاں نقصان پہلے ہی 21,392 روپے ہے اور اب بھی بڑھ رہا ہے۔ کوئی آخری قطار نہیں ہے، کیونکہ اوپر کی طرف کوئی زیادہ سے زیادہ نہیں ہے۔</p>\n<h2 id=\"the-short-strangle-rupee-by-rupee\">مختصر گلا گھونٹنا، روپیہ بہ روپیہ</h2>\n<p>مختصر اسٹریڈل سب سے زیادہ ادائیگی کرتا ہے، لیکن اس کے بریک وینس غیر آرام دہ طور پر جگہ کے قریب بیٹھتے ہیں۔ دی <strong>مختصر گلا گھونٹنا</strong> اس کی بجائے پیسے سے باہر کے اختیارات بیچ کر غلطی کے لیے وسیع مارجن خریدتا ہے۔ آپ 23,950 پوٹ اور 24,150 کال بیچتے ہیں، دونوں ٹانگوں کے زندہ ہونے سے پہلے ہر طرف ایک کشن چھوڑ دیتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>ڈال فروخت</td>\n<td>23,950</td>\n<td>256.6 موصول ہوا۔</td>\n<td>16,679 روپے میں</td>\n</tr>\n<tr>\n<td>2</td>\n<td>کال فروخت کریں۔</td>\n<td>24,150</td>\n<td>370.1 موصول ہوا۔</td>\n<td>24,057 روپے میں</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>نیٹ کریڈٹ</strong></td>\n<td><strong>40,729 روپے میں</strong></td>\n</tr>\n</tbody></table>\n<p>کیونکہ دونوں ٹانگیں پیسے سے باہر ہیں، ہر ایک کو کم ملتا ہے، لہذا <strong>خالص کریڈٹ 40,729 روپے تک گرتا ہے۔</strong>، straddle سے تقریباً 6,000 روپے کم۔ بدلے میں آپ کو ایک چوٹی کے بجائے درمیان میں ایک فلیٹ منافع کی سطح مرتفع ملتی ہے، اور اس سے پہلے کہ دونوں طرف سے آپ کو تکلیف پہنچے ایک وسیع تر محفوظ زون۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-short-strangle.png\" alt=\"NIFTY پر مختصر گلا گھونٹنا: 23,950 اور 24,150 کے درمیان کہیں بھی 40,729 روپے کا فلیٹ منافع، 23,323 اور 24,777 پر بریک وینس، اور ایک بار جب انڈیکس دونوں بازو سے بہت آگے بڑھ جاتا ہے تو لامحدود نقصان۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY پر مختصر گلا گھونٹنا: 23,950 اور 24,150 کے درمیان کہیں بھی 40,729 روپے کا فلیٹ منافع، 23,323 اور 24,777 پر بریک ایون، اور ایک بار جب انڈیکس دونوں بازو سے بہت آگے بڑھ جاتا ہے تو لامحدود نقصان۔</figcaption></figure>\n<h2 id=\"the-three-numbers-of-the-short-strangle\">مختصر گلا گھونٹنے کے تین نمبر</h2>\n<p>کل پریمیم فی حصص، 256.6 جمع 370.1، 626.7 ہے، اور یہ آپ کی فروخت کردہ دو سٹرائیکس کو ختم کرتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>خالص کریڈٹ جمع کیا گیا۔</td>\n<td>40,729 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>پنکھوں سے باہر لامحدود</td>\n<td>لا محدود</td>\n</tr>\n<tr>\n<td>Breakevens</td>\n<td>لوئر سٹرائیک مائنس، اپر سٹرائیک پلس، کل پریمیم فی شیئر</td>\n<td>23,950 مائنس 626.7 برابر 23,323; 24,150 جمع 626.7 برابر 24,777</td>\n</tr>\n</tbody></table>\n<p>23,950 اور 24,150 کے درمیان آپ پورا کریڈٹ اپنے پاس رکھتے ہیں، کیونکہ دونوں آپشنز اس بینڈ میں بیکار ختم ہو جاتے ہیں۔ بریک وینز، <strong>23,323 اور 24,777</strong>، straddle کے مقابلے میں چوڑا بیٹھیں، یہی وجہ ہے کہ یہ ورژن زیادہ محفوظ محسوس ہوتا ہے۔ یہ نہیں ہے. وسیع خطہ صرف خطرے میں تاخیر کرتا ہے، یہ اس پر قابو نہیں رکھتا۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک مختصر گلا کا زیادہ سے زیادہ منافع 40,729 روپے ہے اور زیادہ سے زیادہ نقصان جو اب بھی کھلا ہے۔ وسیع بریک وینس اسے زیادہ محفوظ محسوس کرتے ہیں اور منافع کا زیادہ امکان اسے مزید خوش کرتا ہے، لیکن فروخت ہونے والی دونوں ٹانگیں ننگی ہیں۔ 24,777 سے اوپر شارٹ کال بغیر کسی چھت کے بہہ رہی ہے، اور 23,323 سے نیچے شارٹ پٹ صفر پر فرش کی طرف چلتی ہے۔ تجارت پر جیت کی زیادہ شرح جو بغیر پابند کے ہار سکتی ہے حفاظت نہیں ہے، یہ ایک سست فیوز ہے۔</p>\n</div></div>\n<h2 id=\"walking-the-short-strangle-outcomes-at-expiry\">ایکسپائری پر مختصر گلا گھونٹنے کے نتائج</h2>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>23,950 میں آپ نے فروخت کیا۔</th>\n<th>24,150 کال آپ نے فروخت کی۔</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,000</td>\n<td>950 کی مالیت</td>\n<td>مالیت 0</td>\n<td>مائنس 21,021 روپے</td>\n</tr>\n<tr>\n<td>23,323</td>\n<td>مالیت 627</td>\n<td>مالیت 0</td>\n<td>0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>جمع 40,729 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,777</td>\n<td>مالیت 0</td>\n<td>مالیت 627</td>\n<td>0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>25,300</td>\n<td>مالیت 0</td>\n<td>مالیت 1,150</td>\n<td>مائنس 34,021 روپے</td>\n</tr>\n</tbody></table>\n<p>اسٹریڈل کا الٹا V ایک ٹیبل ٹاپ میں چپٹا ہو گیا ہے۔ مرکزی بینڈ میں کہیں بھی مکمل کریڈٹ آپ کا ہے، پھر لائن پنکھوں کے باہر نیچے مڑ جاتی ہے اور دونوں طرف سے گر جاتی ہے، جس کے اوپر کوئی چھت نہیں ہوتی ہے اور صرف زیرو پر فرش ہوتی ہے۔ سطح مرتفع سکون ہے، گرتی ہوئی دم خطرہ ہے، اور دم کبھی نہیں رکتی۔</p>\n<h2 id=\"your-odds\">آپ کی مشکلات</h2>\n<p>دی <strong>اسٹریڈل کے لیے منافع کا امکان 58 فیصد اور گلا گھونٹنے کے لیے 59 فیصد ہے۔</strong>, دونوں آرام سے نصف سے اوپر، کیونکہ زیادہ تر مہینوں NIFTY کسی بھی طرح سے 720 پوائنٹس کا سفر نہیں کرتا ہے۔ جیت کی یہ بلند شرح پریمیم بیچنے کا پورا لالچ ہے، اور یہ بالکل وہی ہے جو ان تجارتوں کو بے خبروں کے لیے خطرناک بناتا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>58 یا 59 فیصد جیتنے کی شرح کا مطلب ہے کہ آپ بار بار کریڈٹ جمع کریں گے، پرسکون اعتماد پیدا کریں گے، اور نایاب نقصان جو آخر کار پہنچتا ہے اس سے پہلے کے ہر فائدہ سے کئی گنا بڑا ہو سکتا ہے۔ اس چاپلوسی کے امکان کے آگے لامحدود زیادہ سے زیادہ نقصان کو ہمیشہ پڑھیں، کبھی تنہا نہیں۔ مارکیٹ سے منسلک مشکلات بھی ایک ہی ہولڈ کو ختم کرنے کا فرض کرتی ہیں، لیکن زیادہ تر بیچنے والے کبھی بھی اتنا انتظار نہیں کرتے: کریڈٹ کا ایک بڑا حصہ ختم ہونے کے بعد وہ تجارت کو ختم کر دیتے ہیں، یا اس لمحے سے باہر نکل جاتے ہیں جبNIFTY′ کا خطرہ ہوتا ہے، لامحدود کو خطرے میں ڈالنے کے بجائے چھوٹے نقصان کو قبول کرتے ہیں۔ باہر نکلنے کا منصوبہ اس کورس میں کسی بھی متعین خطرے کی تجارت سے زیادہ اہمیت رکھتا ہے۔</p>\n</div></div>\n<h2 id=\"margin\">مارجن</h2>\n<p>یہ وہ جگہ ہے جہاں ننگے بیچنے کی ایماندارانہ قیمت ظاہر ہوتی ہے۔ تبادلے کے بارے میں بلاکس <strong>شارٹ اسٹریڈل کے لیے 162,339 روپے اور شارٹ اسٹریگل کے لیے 162,195 روپے</strong>, ایک بھاری SPAN جزو کے علاوہ ایک نمائش بفر سے بنا، خاص طور پر اس لیے کہ نقصان کھلا ہوا ہے۔ آپ چند دسیوں ہزار روپے پریمیم جمع کرنے کے لیے ڈیڑھ لاکھ سے زیادہ سرمایہ لگا رہے ہیں۔</p>\n<p>یہ آپ کو اس کے ذریعہ تجارت کا فیصلہ کرنے دیتا ہے۔ <strong>مارجن پر واپسی</strong>. سٹریڈل 162,339 روپے کے مقابلے میں 46,858 روپے اکٹھا کرتا ہے، تقریباً <strong>29 فیصد</strong> اگر یہ کام کرتا ہے. گلا گھونٹنے سے تقریباً 162,195 روپے کے مقابلے میں 40,729 روپے جمع ہوتے ہیں۔ <strong>25 فیصد</strong>. وہ امیر نظر آتے ہیں، لیکن شخصیت ایک ایسی پوزیشن کو خوش کرتی ہے جس کا منفی پہلو لامحدود ہے۔ ایک برا مہینہ آپ پر 29 فیصد خرچ نہیں کرتا، اس کی لاگت پورے مارجن کا ایک سے زیادہ ہو سکتی ہے۔</p>\n<h2 id=\"time-decay-is-your-ally\">وقت کا زوال آپ کا اتحادی ہے۔</h2>\n<p>کو دوبارہ دیکھیں <strong>نیلی ڈیشڈ T+0 لائن</strong> ہر چارٹ کے مرکز کے قریب اورنج ایٹ-ایکسپائری چوٹی کے نیچے بیٹھنا۔ یہ فرق وقت کی قیمت ہے جو ابھی پگھلنا باقی ہے، اور بطور فروخت کنندہ آپ کو اس سے ادائیگی کی جاتی ہے۔ ہر پرسکون دن نیلی لائن نارنجی کی طرف بڑھ جاتی ہے جیسا کہ آپ نے اپنے حق میں جمع کیا ہوا بوسیدہ ہو جاتا ہے۔ وقت کا زوال، آخری باب میں خریدار کا دشمن، اب آپ کا اتحادی ہے۔ پوری تجارت ایک دانو ہے جو آپ کو تکلیف پہنچانے والے کسی بھی اقدام سے زیادہ تیزی سے زوال پذیر ہوتی ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>اگر آپ کبھی بھی اس طرح سے پریمیم بیچتے ہیں، تو نقصان کو پورا کرنے کے منصوبے کے بغیر کبھی بھی ننگے شارٹ اسٹریڈل یا گلا نہ پکڑیں۔ پیشہ ورانہ حل یہ ہے کہ ایک سستی، مزید رقم سے باہر کی کال خریدیں اور انشورنس کے طور پر لگائیں، جو لامحدود دم کو معلوم نمبروں میں بدل دیتا ہے اور تجارت کو لوہے کی مکھی یا آئرن کنڈور میں بدل دیتا ہے۔ وہ اس عین خیال کے متعین خطرے والے ورژن ہیں، اور یہ وہیں ہیں جہاں اگلا باب جاتا ہے۔ ایک مبتدی کو مختصر straddle اور گلا گھونٹنا سیکھنا چاہیے بنیادی طور پر ان کا احترام کرنے کے لیے، نہ کہ انھیں برہنہ کرنے کے لیے۔</p>\n</div></div>\n<h2 id=\"the-two-trades-side-by-side\">دونوں ساتھ ساتھ تجارت کرتے ہیں۔</h2>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>مختصر اسٹریڈل</th>\n<th>مختصر گلا گھونٹنا</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>46,858 روپے</td>\n<td>40,729 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>لا محدود</td>\n<td>لا محدود</td>\n</tr>\n<tr>\n<td>Breakevens</td>\n<td>23,329 اور 24,771</td>\n<td>23,323 اور 24,777</td>\n</tr>\n<tr>\n<td>منافع کا امکان</td>\n<td>58 فیصد</td>\n<td>59 فیصد</td>\n</tr>\n<tr>\n<td>نیٹ کریڈٹ</td>\n<td>46,858 روپے</td>\n<td>40,729 روپے</td>\n</tr>\n<tr>\n<td>مارجن درکار ہے۔</td>\n<td>162,339 روپے</td>\n<td>162,195 روپے</td>\n</tr>\n</tbody></table>\n<p>کالم پڑھیں اور سودا واضح ہے۔ اسٹریڈل ایک سخت محفوظ زون کے ساتھ بڑا کریڈٹ اکٹھا کرتا ہے، گلا گھونٹنے والا کم جمع کرتا ہے جس میں غلط ہونے کی زیادہ گنجائش ہوتی ہے، اور دونوں زیادہ تر وقت جیت جاتے ہیں۔ وہ ایک ایسی خصوصیت بھی شیئر کرتے ہیں جو ایک ابتدائی وقفہ کرے: نقصان کی کوئی حد نہیں ہے اور مارجن بڑا ہے۔ آپ اپنے آپ کو ایک دم سے بے نقاب کرتے ہوئے چند ہزار روپے جمع کرتے ہیں جو آپ نے پہلے سے کہیں زیادہ لے سکتے ہیں۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>آپ دونوں میں مشق کر سکتے ہیں۔ <strong>سینڈ باکس ٹریڈنگ ( OpenAlgo میں تجزیہ کار موڈ)</strong>، کال اور پوٹ کو بیچنا اور اسٹراڈل کے الٹے V کو گلا گھونٹنے کے ٹیبل ٹاپ میں پھیلتے دیکھنا جیسے ہی آپ سٹرائیکس کو الگ کرتے ہیں۔ ماڈل کی گئی قیمت کو بریک ایون کی طرف سلائیڈ کریں اور گرتی ہوئی دم کو چلتے ہوئے دیکھیں، اوپر کی طرف بالکل بھی چھت نہیں ہے اور نیچے کی طرف صرف صفر سے جکڑا ہوا ہے۔ دونوں حصوں کو ایک ساتھ محسوس کریں: آپ کے حق میں کشی کی روزانہ کی خاموشی، اور دونوں طرف کھلی چٹان کہ ایک پرتشدد سیشن آپ کو بھیج سکتا ہے۔ وہ تناؤ، ایک غیر منقطع دم کے خلاف مستحکم آمدنی، وہی ہے جس کے ساتھ ہر پریمیم بیچنے والا رہتا ہے۔</p>\n</div></div>\n<h2 id=\"key-takeaways\">اہم نکات</h2>\n<ul>\n<li>ایک شارٹ اسٹریڈل ایٹ دی منی کال اور پوٹ کو فروخت کرتا ہے، ایک چھوٹا سا سٹریگل سستی قیمت سے باہر کی سٹرائیکس فروخت کرتا ہے، اور دونوں ایک جمع کرتے ہیں۔ <strong>خالص کریڈٹ</strong> یہ زیادہ سے زیادہ منافع ہے.</li>\n<li>straddle اندر لیتا ہے <strong>46,858 روپے</strong> 23,329 اور 24,771 پر breakevens کے ساتھ؛ گلا اندر لے جاتا ہے <strong>40,729 روپے</strong> 23,323 سے 24,777 کے وسیع تر محفوظ زون کے ساتھ۔</li>\n<li>دی <strong>زیادہ سے زیادہ نقصان دونوں طرف کھلا ہوا ہے۔</strong> ہر ایک تجارت کا، واقعی لامحدود ہے اور بہت بڑا اگرچہ نیچے کی طرف جکڑا ہوا ہے، کیونکہ ہر فروخت شدہ ٹانگ ننگی ہے، اور یہی حقیقت ہے جو ہر چیز پر حکومت کرتی ہے۔</li>\n<li>دی <strong>منافع کا امکان زیادہ ہے</strong>58 اور 59 فیصد، جو لالچ ہے؛ ایک ہی نایاب نقصان چھوٹی جیت کے طویل دور کو بونا کر سکتا ہے۔</li>\n<li><strong>مارجن بڑا ہے۔</strong>ہر ایک کے لیے تقریباً 1.62 لاکھ روپے، اور وقت کی کمی آپ کے حق میں کام کرتی ہے، لیکن مارجن پر امیر نظر آنے والی واپسی کھلی دم والی پوزیشن کو خوش کرتی ہے۔</li>\n<li>ایک ابتدائی شخص کو ان کا احترام کرنا سیکھنا چاہیے، پھر دم کو باڑ لگانا چاہیے۔ اگلا باب اس صحیح آمدنی کی شکل کو متعین خطرے والے آئرن کنڈور میں بدل دیتا ہے۔</li>\n</ul>\n","toc":[{"level":2,"text":"ایک لائن کا خیال","id":"the-one-line-idea"},{"level":2,"text":"مختصر سٹرڈل، روپیہ بہ روپیہ","id":"the-short-straddle-rupee-by-rupee"},{"level":2,"text":"مختصر اسٹریڈل کے تین نمبر","id":"the-three-numbers-of-the-short-straddle"},{"level":2,"text":"ایکسپائری پر شارٹ سٹریڈل کے نتائج پر چلنا","id":"walking-the-short-straddle-outcomes-at-expiry"},{"level":2,"text":"مختصر گلا گھونٹنا، روپیہ بہ روپیہ","id":"the-short-strangle-rupee-by-rupee"},{"level":2,"text":"مختصر گلا گھونٹنے کے تین نمبر","id":"the-three-numbers-of-the-short-strangle"},{"level":2,"text":"ایکسپائری پر مختصر گلا گھونٹنے کے نتائج","id":"walking-the-short-strangle-outcomes-at-expiry"},{"level":2,"text":"آپ کی مشکلات","id":"your-odds"},{"level":2,"text":"مارجن","id":"margin"},{"level":2,"text":"وقت کا زوال آپ کا اتحادی ہے۔","id":"time-decay-is-your-ally"},{"level":2,"text":"دونوں ساتھ ساتھ تجارت کرتے ہیں۔","id":"the-two-trades-side-by-side"},{"level":2,"text":"اہم نکات","id":"key-takeaways"}],"imgCount":2,"hasContent":true},"15":{"html":"<p>آخری باب کے مختصر گلا میں ایک خوبصورت آمدنی کی شکل اور ایک مہلک خامی تھی، دم جو ہمیشہ کے لیے گر گئی۔ واضح سوال یہ ہے کہ کیا آپ نقصان کے نیچے سخت منزل ڈالتے ہوئے مستحکم پریمیم رکھ سکتے ہیں۔ آپ کر سکتے ہیں، اور جو ڈھانچہ یہ کرتا ہے وہ ہے۔ <strong>لوہے کا کنڈور</strong>آپشنز کی دنیا میں سب سے زیادہ مقبول ڈیفائنڈ رسک انکم ٹریڈ۔ بیچا ہوا گلا گھونٹ لیں اور ایک سستا خریدیں، مزید پیسے سے باہر کال کریں اور انشورنس کے طور پر ڈالیں۔ وہ دو خریدے گئے پنکھ لامحدود دموں کو معلوم تعداد میں بدل دیتے ہیں، جس سے چار ٹانگوں کا ڈھانچہ نکل جاتا ہے جو ایک حد کے اندر منافع بخش ہوتا ہے اور ایک مقررہ، معمولی رقم سے زیادہ کبھی نہیں کھو سکتا۔ NIFTY، ملک میں سب سے گہری انڈیکس آپشن مارکیٹ، اس کا قدرتی گھر ہے۔</p>\n<h2 id=\"the-one-line-idea\">ایک لائن کا خیال</h2>\n<p>آئرن کنڈور دو عمودی اسپریڈز ہیں جن میں ایک ختم ہونے کا اشتراک ہوتا ہے، a <strong>بیل ڈال پھیل گیا</strong> منفی پہلو پر اور ایک <strong>ریچھ کال پھیل گئی</strong> الٹا، موجودہ قیمت کے ارد گرد رکھا. دو اندرونی سٹرائیکس کو پریمیم جمع کرنے کے لیے فروخت کیا جاتا ہے، اور دو بیرونی پنکھوں کو ہر دم کو کیپ کرنے کے لیے خریدا جاتا ہے۔ پوری چیز کا معلوم زیادہ سے زیادہ منافع اور معلوم زیادہ سے زیادہ نقصان ہے، جس کے دونوں طرف کوئی کھلی چٹان نہیں ہے۔</p>\n<p>ایک موڑ ہے جو آپ کو سمجھنا چاہیے، اور یہ اس باب کے دل میں بیٹھا ہے۔ OpenAlgo بلڈر ایک ہی چار سٹرائیکس کے دو چہرے پیش کرتا ہے، a <strong>لمبا آئرن کنڈور</strong> اور a <strong>مختصر آئرن کنڈور</strong>، اور کون سا آپ کو فٹ بیٹھتا ہے اس کا انحصار بٹن پر موجود الفاظ پر نہیں بلکہ آپ کی مطلوبہ مشکلات پر ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>آئرن کنڈور ایک بیل پوٹ اسپریڈ پلس ایک بیئر کال اسپریڈ ہے جس میں ایک میعاد ختم ہوتی ہے۔ اندرونی فروخت شدہ ہڑتالیں پریمیم جمع کرتی ہیں، بیرونی خریدے ہوئے پنکھوں کی دونوں دموں کو ٹوپی۔ یہ مختصر گلا گھونٹنے کا متعین شدہ رسک ورژن ہے، ایک ہی حد تک محدود آمدنی کی شکل، لیکن کھلی دم کی بجائے ایک معروف، چھوٹے زیادہ سے زیادہ نقصان کے ساتھ۔</p>\n</div></div>\n<h2 id=\"the-long-iron-condor-rupee-by-rupee\">لمبا لوہے کا کنڈور، روپیہ بہ روپیہ</h2>\n<p>یہ وہ ورژن ہے جسے بلڈر کال کرتا ہے۔ <strong>لمبا آئرن کنڈور</strong>، حقیقی NIFTY قیمتوں پر 26 جون 2026 کو انڈیکس کے ساتھ <strong>24,056</strong> اور 28 جولائی 2026 کی میعاد تقریباً 32 دن ختم ہو رہی ہے۔ یہ پیسے کے ساتھ مضبوط بنایا گیا ہے، اندرونی ضربیں جگہ سے صرف دو قدم کے فاصلے پر اور پنکھ ان سے سو پوائنٹس کے فاصلے پر ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>ڈال خریدیں</td>\n<td>23,850</td>\n<td>224.1 ادا کیا گیا۔</td>\n<td>14,567 روپے باہر</td>\n</tr>\n<tr>\n<td>2</td>\n<td>ڈال فروخت</td>\n<td>23,950</td>\n<td>256.6 موصول ہوا۔</td>\n<td>16,679 روپے میں</td>\n</tr>\n<tr>\n<td>3</td>\n<td>کال فروخت کریں۔</td>\n<td>24,150</td>\n<td>370.1 موصول ہوا۔</td>\n<td>24,057 روپے میں</td>\n</tr>\n<tr>\n<td>4</td>\n<td>کال خریدیں۔</td>\n<td>24,250</td>\n<td>316.1 ادا کیا گیا۔</td>\n<td>20,547 روپے باہر</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>نیٹ کریڈٹ</strong></td>\n<td><strong>5,616 روپے میں</strong></td>\n</tr>\n</tbody></table>\n<p>دو اندرونی فروخت شدہ اختیارات، 23,950 پوٹ اور 24,150 کال، ایک ہی ٹانگیں ہیں جیسے ایک مختصر گلا گھونٹنا اور زیادہ تر پریمیم لاتے ہیں۔ دو بیرونی خریدے گئے آپشنز، 23,850 پوٹ اور 24,250 کال، کی قیمت تھوڑی ہے اور انشورنس کے طور پر کام کرتے ہیں، ہر دم کو ایک سو پوائنٹس کیپ کرتے ہوئے۔ جال ہے a <strong>5,616 روپے کا کریڈٹ</strong> جو آپ کے اکاؤنٹ میں آتا ہے جب آپ تجارت کھولتے ہیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-long-iron-condor.png\" alt=\"NIFTY پر لانگ آئرن کنڈور: 23,950 اور 24,150 شارٹ سٹرائیکس کے درمیان 5,616 روپے کا فلیٹ منافع، 23,864 اور 24,236 پر بریک ایون، اور ایک بار جب انڈیکس دونوں طرف سے گزر جاتا ہے تو صرف 884 روپے کا محدود نقصان۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY پر لانگ آئرن کنڈور: 23,950 اور 24,150 شارٹ سٹرائیکس کے درمیان 5,616 روپے کا فلیٹ منافع کا پلیٹیو، 23,864 اور 24,236 پر بریک وینس، اور ایک بار جب انڈیکس کسی بھی طرف سے گزر جاتا ہے تو صرف 884 روپے کا محدود نقصان۔</figcaption></figure>\n<h2 id=\"the-three-numbers-of-the-long-iron-condor\">لوہے کے لمبے کنڈور کے تین نمبر</h2>\n<p>فی حصص کریڈٹ 5,616 روپے ہے جس کو 65 سے تقسیم کیا گیا ہے، تقریباً 86.4 پوائنٹس، اور یہ واحد اعداد دو اندرونی شارٹ سٹرائیکس کے بریک وینس کو سیٹ کرتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>خالص کریڈٹ جمع کیا گیا۔</td>\n<td>5,616 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>ونگ کی چوڑائی مائنس کریڈٹ</td>\n<td>6,500 روپے مائنس 5,616 روپے 884 روپے کے برابر ہے۔</td>\n</tr>\n<tr>\n<td>Breakevens</td>\n<td>اندرونی مختصر ہڑتال مائنس، پھر پلس، کریڈٹ فی شیئر</td>\n<td>23,950 مائنس 86.4 برابر 23,864; 24,150 جمع 86.4 برابر 24,236</td>\n</tr>\n</tbody></table>\n<p><strong>زیادہ سے زیادہ منافع کریڈٹ ہے، 5,616 روپے</strong>، اگر 23,950 اور 24,150 کی اندرونی سٹرائیکس کے درمیان NIFTY ختم ہو جائے تو اسے مکمل رکھا جائے۔ <strong>زیادہ سے زیادہ نقصان 884 روپے کا ہے۔</strong> ہر ونگ ایک سو پوائنٹس چوڑا ہے، جس کی قیمت 6500 روپے کے لاٹ پر ہے، اور آپ نے پہلے ہی اس میں سے 5,616 روپے اکٹھے کر لیے ہیں، اس لیے آپ سب سے زیادہ کھو سکتے ہیں وہ فرق ہے۔ سب سے برا معاملہ لامحدود، ننگے گلا گھونٹنے پر، معلوم 884 روپے تک چلا گیا ہے۔</p>\n<h2 id=\"walking-the-long-iron-condor-outcomes-at-expiry\">لمبے لوہے کے کنڈور پر چلنے کے نتائج ختم ہونے پر</h2>\n<p>تجارت کو پانچ اختتامی قیمتوں پر طے کریں، ہر ٹانگ کو ختم ہونے پر اس کی اندرونی قیمت کے طور پر لے کر۔ لمبی ٹانگیں آپ کی مدد کرتی ہیں، چھوٹی ٹانگیں آپ کو خرچ کرتی ہیں، اور نیٹ ہے 5,616 روپے کا کریڈٹ پلس لمبی ویلیوز مائنس شارٹ ویلیوز، گنا 65۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>23,850 پوٹ (لمبا)</th>\n<th>23,950 پوٹ (مختصر)</th>\n<th>24,150 کال (مختصر)</th>\n<th>24,250 کال (لمبی)</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,700</td>\n<td>150 کی مالیت</td>\n<td>مالیت 250</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مائنس 884 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>23,864</td>\n<td>مالیت 0</td>\n<td>مالیت 86</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>جمع 5,616 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,236</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مالیت 86</td>\n<td>مالیت 0</td>\n<td>0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>24,400</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مالیت 250</td>\n<td>150 کی مالیت</td>\n<td>مائنس 884 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n</tbody></table>\n<p>قطاروں میں پڑھیں اور شکل ایک فلیٹ ٹاپ ٹیبل ہے۔ اندرونی حملوں کے درمیان آپ پورا کریڈٹ رکھتے ہیں۔ ایک بازو سے آگے بڑھیں اور نقصان کی حد 884 روپے ہے، کیونکہ خریدی گئی ٹانگ اس سے آگے کے پوائنٹ کے لیے فروخت شدہ ٹانگ پوائنٹ سے ملتی ہے۔ 24,056 پر گلابی اسپاٹ لائن سطح مرتفع کے اندر بیٹھی ہے، لہذا آج آپ منافع بخش زون میں ہیں۔</p>\n<h2 id=\"the-honest-catch-a-narrow-band-and-low-odds\">دیانتدار کیچ: ایک تنگ بینڈ اور کم مشکلات</h2>\n<p>لیکن دیکھیں کہ منافع کا بینڈ کتنا تنگ ہے۔ بریک ایونز اسپاٹ کے ہر طرف صرف 190 پوائنٹس پر ہیں، اور چارٹ شو NIFTY پر سگما بینڈز ایکسپائری تک اس سے تین یا چار گنا آسانی سے سفر کر سکتے ہیں۔ یہی وجہ ہے کہ <strong>منافع کا امکان صرف 17 فیصد ہے۔</strong>. ڈھانچہ اپنے خطرے کے خلاف خوبصورتی سے ادائیگی کرتا ہے۔ <strong>تقریباً 1 سے 6.4 کے خطرے کا انعام</strong>کیونکہ اندرونی حملے پیسے کو گلے لگاتے ہیں اور ایک بھرپور کریڈٹ جمع کرتے ہیں۔ اس امیر کریڈٹ کی قیمت ایک تنگ، کم مشکلات والے منافع کا زون ہے، اس لیے آپ کے 884 روپے کے چھوٹے نقصان اور کبھی کبھار پورے 5,616 روپے کے ساتھ جانے کا امکان ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>1 سے 6.4 کے خطرے کا انعام اس وقت تک شاندار لگتا ہے جب تک کہ آپ اس کے ساتھ منافع کے 17 فیصد امکان کو نہیں پڑھتے۔ مارکیٹ کسی ممکنہ واقعہ پر چھ سے ایک کی ادائیگی نہیں کرتی ہے۔ بڑے کریڈٹ اور چھوٹے خطرے کی ادائیگی ایک تنگ بینڈ کے ساتھ کی جاتی ہے جس سے NIFTY عام طور پر بچ جاتا ہے۔</p>\n</div></div>\n<h2 id=\"the-short-iron-condor-the-high-probability-inverse\">مختصر لوہے کا کنڈور، زیادہ امکان الٹا</h2>\n<p>بلڈر عین آئینہ بھی پیش کرتا ہے، جسے وہ کہتے ہیں۔ <strong>مختصر آئرن کنڈور</strong>. آپ چاروں ٹانگوں کا دوسرا رخ لیں، اندرونی سٹرائیکس خریدیں اور بیرونی پنکھوں کو بیچیں، اور کریڈٹ جمع کرنے کے بجائے ڈیبٹ ادا کریں۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>ڈال فروخت</td>\n<td>23,850</td>\n<td>224.1 موصول ہوا۔</td>\n<td>14,567 روپے میں</td>\n</tr>\n<tr>\n<td>2</td>\n<td>ڈال خریدیں</td>\n<td>23,950</td>\n<td>256.6 ادا کیا گیا۔</td>\n<td>16,679 روپے باہر</td>\n</tr>\n<tr>\n<td>3</td>\n<td>کال خریدیں۔</td>\n<td>24,150</td>\n<td>370.1 ادا کیا گیا۔</td>\n<td>24,057 روپے باہر</td>\n</tr>\n<tr>\n<td>4</td>\n<td>کال فروخت کریں۔</td>\n<td>24,250</td>\n<td>316.1 موصول ہوا۔</td>\n<td>20,547 روپے میں</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>خالص ڈیبٹ</strong></td>\n<td><strong>5,616 روپے باہر</strong></td>\n</tr>\n</tbody></table>\n<p>کیونکہ یہ الٹا ہے، ہر نمبر پلٹ جاتا ہے۔ اب آپ داخل ہونے کے لیے 5,616 روپے ادا کرتے ہیں، اور جب بھی NIFTY ڈیڈ سینٹر سے دور ہوتا ہے تو منافع ہوتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>بازو کی چوڑائی مائنس ڈیبٹ</td>\n<td>6,500 روپے مائنس 5,616 روپے 884 روپے کے برابر ہے۔</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>ڈیبٹ ادا کیا</td>\n<td>5,616 روپے</td>\n</tr>\n<tr>\n<td>Breakevens</td>\n<td>طویل ورژن کے طور پر ایک ہی</td>\n<td>23,864 اور 24,236</td>\n</tr>\n</tbody></table>\n<p>دی <strong>زیادہ سے زیادہ منافع 884 روپے ہے۔</strong>، جب بھی NIFTY بریک ایونز کے باہر ختم ہوتا ہے، تنگ مرکزی بینڈ کے اندر پن کے علاوہ کہیں بھی کمایا جاتا ہے۔ دی <strong>زیادہ سے زیادہ نقصان 5,616 روپے ہے۔</strong>، صرف اس صورت میں نقصان اٹھانا پڑا جب NIFTY اندرونی حملوں کے درمیان طے پا جائے۔ سرخی ہے <strong>83 فیصد منافع کا امکان</strong>کیونکہ NIFTY تقریباً ہمیشہ ہی 32 دنوں کے دوران ڈیڈ سینٹر سے دور ہو جاتا ہے، اور اس طرح کا کوئی بھی ڈرفٹ اس ورژن کو اس کی چھوٹی جیت کے حوالے کرتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-short-iron-condor.png\" alt=\"NIFTY پر شارٹ آئرن کنڈور: الٹی شکل، 23,864 سے 24,236 بینڈ کے باہر کہیں بھی 884 روپے کا چھوٹا منافع، لیکن 5,616 روپے کا نقصان اگر انڈیکس ایکسپائری پر سینٹرل زون کو پن کرتا ہے، منافع کے 83 فیصد امکان کے ساتھ۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY پر شارٹ آئرن کنڈور: الٹی شکل، 23,864 سے 24,236 بینڈ کے باہر کہیں بھی 884 روپے کا چھوٹا منافع، لیکن 5,616 روپے کا نقصان اگر انڈیکس ایکسپائری پر سینٹرل زون کو پن کرتا ہے، منافع کے 83 فیصد امکان کے ساتھ۔</figcaption></figure>\n<h2 id=\"walking-the-short-iron-condor-outcomes-at-expiry\">میعاد ختم ہونے پر مختصر لوہے کے کنڈور کے نتائج پر چلنا</h2>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>23,850 پوٹ (مختصر)</th>\n<th>23,950 پوٹ (لمبا)</th>\n<th>24,150 کال (لمبی)</th>\n<th>24,250 کال (مختصر)</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,700</td>\n<td>150 کی مالیت</td>\n<td>مالیت 250</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>جمع 884 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>23,864</td>\n<td>مالیت 0</td>\n<td>مالیت 86</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مائنس 5,616 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>24,236</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مالیت 86</td>\n<td>مالیت 0</td>\n<td>0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>24,400</td>\n<td>مالیت 0</td>\n<td>مالیت 0</td>\n<td>مالیت 250</td>\n<td>150 کی مالیت</td>\n<td>جمع 884 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n</tbody></table>\n<p>تو آپ کے پاس ایک ڈھانچہ اور دو چہرے ہیں۔ کوئی بڑا کریڈٹ اکٹھا کرتا ہے اور شاذ و نادر ہی رکھتا ہے۔ دوسرا ڈیبٹ ادا کرتا ہے، زیادہ تر وقت تھوڑا سا جیتتا ہے، اور نایاب موقع پر بہت کچھ کھو دیتا ہے NIFTY مرکز کو پن کرتا ہے، بالکل جہاں لمبا آئرن کنڈور سب سے زیادہ خوش ہوتا ہے۔</p>\n<h2 id=\"your-odds-and-choosing-strikes-to-match-them\">آپ کی مشکلات، اور ان سے ملنے کے لیے سٹرائیکس کا انتخاب کرنا</h2>\n<p>یہ جوڑی مشکلات کو ایمانداری سے پڑھنے کے بارے میں کورس کا سب سے واضح سبق ہے۔ ایک تاجر پیچھا کر رہا ہے۔ <strong>آمدنی</strong> اکثر صحیح ہونا چاہتا ہے، لہذا <strong>اعلی امکان کی طرف</strong>، 83 فیصد شارٹ آئرن کونڈور، مطالعہ کرنے والا ہے۔ ایک تاجر کا پیچھا <strong>ایک خاموش میعاد ختم ہونے پر بڑی ادائیگی</strong> 17 فیصد لانگ آئرن کونڈور چاہتا ہے، جو چھ سے ایک ادا کرتا ہے جب NIFTY رینج کو پن کرتا ہے۔</p>\n<p>لیکن ایک گہرا نکتہ ہے۔ یہ سخت ہڑتالیں واحد کنڈور نہیں ہیں جو آپ بنا سکتے ہیں۔ اے <strong>کلاسک انکم آئرن کنڈور پیسے سے مزید ہڑتالیں فروخت کرتا ہے۔</strong>شارٹ پٹ اور شارٹ کال کو جگہ سے دور دھکیلنا۔ اس سے منافع کا دائرہ وسیع ہو جاتا ہے، منافع کا امکان بڑھ جاتا ہے اور کریڈٹ سکڑ جاتا ہے۔ آپ بہتر مشکلات اور پرسکون رات کے لیے ایک چھوٹے انعام کی تجارت کرتے ہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>سٹرائیکس کو ایک ڈائل کے طور پر سمجھیں جو آپ اپنے مطلوبہ منافع کے امکان سے ملنے کے لیے سیٹ کرتے ہیں۔ بڑے کریڈٹ اور کم مشکلات کے لیے پیسے کے قریب اندرونی سٹرائیکس بیچیں، جیسے یہاں سخت لانگ آئرن کنڈور۔ انہیں ایک وسیع بینڈ، زیادہ منافع کے امکان اور چھوٹے کریڈٹ کے لیے مزید فروخت کریں۔ ہر بار زیادہ سے زیادہ نقصان کے ساتھ منافع کے امکان کو پڑھیں، اور ایسی سٹرائیکس چنیں جو آپ کو وہ مشکلات فراہم کرتی ہیں جن کے ساتھ آپ رہ سکتے ہیں۔</p>\n</div></div>\n<h2 id=\"margin\">مارجن</h2>\n<p>یا تو چہرے کے بلاکس اس ننگے گلا سے کہیں کم ہیں جس سے اسے بنایا گیا ہے، کیونکہ خریدے ہوئے پروں سے نقصان ہوتا ہے۔ دی <strong>لانگ آئرن کنڈور کو تقریباً 64,319 روپے کی ضرورت ہے۔</strong>, the <strong>شارٹ آئرن کنڈور تقریباً 68,864 روپے</strong>، چار ٹانگوں کی عکاسی کرتے ہوئے ایکسچینج کو ٹریک کرنا چاہئے۔ خطرے میں آپ کی حقیقی نقدی، اگرچہ، صرف متعین زیادہ سے زیادہ نقصان ہے، طویل ورژن پر 884 روپے یا مختصر ورژن پر 5,616 روپے۔</p>\n<p>پر <strong>مارجن پر واپسی</strong>لمبا آئرن کنڈور 64,319 روپے کے مقابلے میں 5,616 روپے کی پیشکش کرتا ہے، تقریباً <strong>9 فیصد</strong> اگر یہ جیت جاتا ہے، لیکن یہ صرف 17 فیصد وقت جیتتا ہے۔ شارٹ آئرن کنڈور 68,864 روپے کے مقابلے میں صرف 884 روپے کی پیشکش کرتا ہے۔ <strong>1.3 فیصد</strong> جب یہ جیتتا ہے، لیکن یہ 83 فیصد وقت جیتتا ہے۔ کسی بھی اعداد و شمار کا مطلب اس کے ساتھ اس کے امکان کے بغیر بہت زیادہ ہے۔</p>\n<h2 id=\"time-decay\">وقت کا زوال</h2>\n<p>دونوں چہرے گھڑی کے مخالف سمتوں پر بیٹھے ہیں۔ دی <strong>لانگ آئرن کونڈور ایک خالص کریڈٹ ہے۔</strong>، لہذا آپ بینڈ کے اندر پریمیم کے خالص فروخت کنندہ ہیں، اور <strong>وقت کا زوال آپ کے لیے کام کرتا ہے۔</strong>: ہر پرسکون دن نیلی T+0 لائن نارنجی سطح مرتفع کی طرف اٹھتی ہے جیسا کہ آپ کے جمع کردہ پریمیم پگھل جاتا ہے۔ دی <strong>شارٹ آئرن کونڈور ایک خالص ڈیبٹ ہے۔</strong>تو آپ خالص خریدار ہیں، اور <strong>وقت کا زوال آپ کے خلاف کام کرتا ہے۔</strong>: گھڑی کے پوزیشن کو خراب کرنے سے پہلے بینڈ سے باہر نکلنے کے لیے آپ کو NIFTY کی ضرورت ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>کسی بلڈر پر لانگ اور شارٹ کے الفاظ پر بھروسہ نہ کریں، اور یہ نہ سمجھیں کہ کریڈٹ کا مطلب اچھی تجارت ہے یا ڈیبٹ کو برا۔ یہاں لانگ آئرن کونڈور کریڈٹ ورژن ہے اور شارٹ آئرن کونڈور ڈیبٹ ورژن ہے، جو زیادہ تر لوگوں کی وجدان کے خلاف چلتا ہے۔ کسی بھی ڈھانچے کا فیصلہ کرنے کا واحد ایماندار طریقہ یہ ہے کہ اس کے نو نمبروں کو پڑھا جائے، اور کیا کریڈٹ یا ڈیبٹ آپ کی توقع کے مطابق نتائج کے مطابق ہے۔ لیبل آپ کو گمراہ کر سکتا ہے۔ نمبر نہیں ہو سکتے۔</p>\n</div></div>\n<h2 id=\"the-two-faces-side-by-side\">دونوں آمنے سامنے</h2>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>لمبا آئرن کنڈور</th>\n<th>مختصر آئرن کنڈور</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>5,616 روپے</td>\n<td>884 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>884 روپے</td>\n<td>5,616 روپے</td>\n</tr>\n<tr>\n<td>Breakevens</td>\n<td>23,864 اور 24,236</td>\n<td>23,864 اور 24,236</td>\n</tr>\n<tr>\n<td>منافع کا امکان</td>\n<td>17 فیصد</td>\n<td>83 فیصد</td>\n</tr>\n<tr>\n<td>خالص کریڈٹ یا ڈیبٹ</td>\n<td>کریڈٹ 5,616 روپے</td>\n<td>ڈیبٹ روپے 5,616</td>\n</tr>\n<tr>\n<td>مارجن درکار ہے۔</td>\n<td>64,319 روپے</td>\n<td>68,864 روپے</td>\n</tr>\n</tbody></table>\n<p>کسی بھی طرح سے پوزیشن خطرے کی وضاحت کی گئی ہے، ٹکٹ پر چھپی ہوئی بدترین صورت، ایک طرف 884 روپے یا دوسری طرف 5,616 روپے۔ یہ تنہا لوہے کے کنڈور کو اس ننگے گلا سے کہیں زیادہ محفوظ بناتا ہے جس سے اسے بنایا گیا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>دونوں چہروں کو اندر بنائیں <strong>سینڈ باکس ٹریڈنگ ( OpenAlgo میں تجزیہ کار موڈ)</strong>, چار ٹانگوں کو جوڑ کر اور سطح مرتفع کی شکل کو دیکھتے ہوئے، پھر ہر ٹانگ کو پلٹتے ہوئے ادائیگی کو الٹا دیکھتے ہیں۔ شارٹ سٹرائیکس کو باہر کی طرف گھسیٹیں اور بینڈ کو چوڑا ہوتے دیکھیں اور منافع میں اضافے کا امکان دیکھیں۔</p>\n</div></div>\n<h2 id=\"key-takeaways\">اہم نکات</h2>\n<ul>\n<li>ایک لوہے کا کنڈور ہے a <strong>بیل پوٹ اسپریڈ پلس بیئر کال اسپریڈ</strong> ایک میعاد ختم ہونے پر؛ اندرونی فروخت ہونے والی ہڑتالیں پریمیم جمع کرتی ہیں اور بیرونی پنکھ دونوں دموں کو ایک مقررہ زیادہ سے زیادہ نقصان میں ڈھانپ دیتے ہیں۔</li>\n<li>بلڈر کا <strong>لانگ آئرن کونڈور کریڈٹ ورژن ہے۔</strong>: یہ 5,616 روپے میں لیتا ہے، صرف 884 روپے کا خطرہ ہے، لیکن اس کا سخت بینڈ صرف منافع کا امکان دیتا ہے <strong>17 فیصد</strong>.</li>\n<li>دی <strong>شارٹ آئرن کونڈور ڈیبٹ ورژن ہے۔</strong>: یہ 5,616 روپے ادا کرتا ہے، صرف 884 روپے کماتا ہے، لیکن جیتتا ہے۔ <strong>83 فیصد</strong> اس وقت کی وجہ سے NIFTY عام طور پر مرکز سے ہٹ جاتا ہے۔</li>\n<li>زیادہ سے زیادہ نقصان ہے <strong>ونگ کی چوڑائی مائنس کریڈٹ</strong> طویل ورژن پر (6,500 روپے مائنس 5,616 روپے 884 روپے کے برابر) اور صرف <strong>ڈیبٹ</strong> مختصر ورژن پر، دونوں کے لیے 23,864 اور 24,236 پر breakevens کے ساتھ۔</li>\n<li>ہڑتالیں a <strong>مشکلات کے لیے ڈائل کریں۔</strong>: ایک کلاسک انکم کنڈور ایک وسیع بینڈ، زیادہ مشکلات اور چھوٹے کریڈٹ کے لیے پیسے میں سے مزید فروخت کرتا ہے۔ دونوں چہرے معمولی مارجن کے ساتھ خطرے سے دوچار ہیں، اور وقت کی کمی کریڈٹ ورژن میں مدد کرتی ہے جب کہ یہ ڈیبٹ والے کو نقصان پہنچاتا ہے۔ ہر ایک کو اس کے نو نمبروں سے پرکھیں، اس کے لیبل سے کبھی نہیں۔</li>\n</ul>\n","toc":[{"level":2,"text":"ایک لائن کا خیال","id":"the-one-line-idea"},{"level":2,"text":"لمبا لوہے کا کنڈور، روپیہ بہ روپیہ","id":"the-long-iron-condor-rupee-by-rupee"},{"level":2,"text":"لوہے کے لمبے کنڈور کے تین نمبر","id":"the-three-numbers-of-the-long-iron-condor"},{"level":2,"text":"لمبے لوہے کے کنڈور پر چلنے کے نتائج ختم ہونے پر","id":"walking-the-long-iron-condor-outcomes-at-expiry"},{"level":2,"text":"دیانتدار کیچ: ایک تنگ بینڈ اور کم مشکلات","id":"the-honest-catch-a-narrow-band-and-low-odds"},{"level":2,"text":"مختصر لوہے کا کنڈور، زیادہ امکان الٹا","id":"the-short-iron-condor-the-high-probability-inverse"},{"level":2,"text":"میعاد ختم ہونے پر مختصر لوہے کے کنڈور کے نتائج پر چلنا","id":"walking-the-short-iron-condor-outcomes-at-expiry"},{"level":2,"text":"آپ کی مشکلات، اور ان سے ملنے کے لیے سٹرائیکس کا انتخاب کرنا","id":"your-odds-and-choosing-strikes-to-match-them"},{"level":2,"text":"مارجن","id":"margin"},{"level":2,"text":"وقت کا زوال","id":"time-decay"},{"level":2,"text":"دونوں آمنے سامنے","id":"the-two-faces-side-by-side"},{"level":2,"text":"اہم نکات","id":"key-takeaways"}],"imgCount":2,"hasContent":true},"16":{"html":"<p>لوہے کے کنڈور نے آپ کو ایک وسیع کمرے کے اندرNIFTYکو رکھنے کے لیے ادائیگی کی۔ یہ باب اس کمرے کو سکڑتا ہے جب تک کہ یہ واحد دروازہ نہ ہو۔ اگر آپ کا نظریہ یہ ہے کہ انڈیکس تقریباً اسی جگہ پر ٹھیک ہو جائے گا جہاں یہ آج بیٹھا ہے، 24,050 کے قریب، آپ ایک ایسا ڈھانچہ بنا سکتے ہیں جو اس ایک سٹرائیک پر تیزی سے چوٹی پر جائے اور دونوں طرف سے ڈھلوان ہو جائے۔ یہ ہیں <strong>لوہے کی مکھی</strong> اور <strong>تتلی</strong>، پن-دی-سٹرائیک تجارت۔ یہ پوری طرح سے طے شدہ خطرے کے ہیں، چند سو روپے کی لاگت آتی ہے یا ایک بھرپور کریڈٹ جمع کرتے ہیں، اور اگر NIFTY کیل پر اترتا ہے تو ان کی قیمت کئی گنا ادا کرتے ہیں۔ ایماندارانہ کیچ یہ ہے کہ ایک اسٹرائیک کو پن کرنا ایک کم مشکلات والا واقعہ ہے، جو یہاں ایک ہی چوٹی کے تین راستے دکھائے گئے ہیں۔</p>\n<h2 id=\"the-one-line-idea\">ایک لائن کا خیال</h2>\n<p>اے <strong>پن-دی-ہڑتال</strong> تجارت اپنی چربی کے پریمیم کی کٹائی کے لیے پیسے پر اختیارات بیچتی ہے، پھر ہر طرف سستا پنکھ خریدتی ہے تاکہ نقصان پر باڑ لگ جائے۔ نتیجہ ایک خیمہ ہے: مرکزی ہڑتال پر منافع کی ایک اونچی چوٹی جو کسی بھی طرح سے بڑھنے کے بعد تیزی سے گر جاتی ہے۔ آپ ایک ہی خیمہ کو تین طریقوں سے بناتے ہیں، ایک آئرن فلائی، کال بٹر فلائی، یا پوٹ بٹر فلائی، اور تینوں ایک ہی بات کہتے ہیں، کہ NIFTY جہاں ہے اس کے بہت قریب ختم ہو جائے گا۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک پن-دی-ہڑتال کی تجارت لوہے کا کنڈور ہے جس میں کوئی سطح مرتفع نہیں ہے۔ یہ ایک ہی مرکزی ہڑتال پر پہنچتا ہے، اپنی زیادہ تر قیمت پیسے کے اختیارات سے اکٹھا کرتا ہے، اور خریدے گئے پنکھوں کے ساتھ ایک چھوٹی سی معلوم رقم پر نقصان کو پورا کرتا ہے۔ یہ سب سے زیادہ ادائیگی صرف اسی صورت میں کرتا ہے جب NIFTY ختم ہونے پر باڈی اسٹرائیک پر تقریباً بالکل ٹھیک ہو جائے۔</p>\n</div></div>\n<h2 id=\"the-real-trade-rupee-by-rupee\">اصل تجارت، روپیہ بہ روپیہ</h2>\n<p>یہاں ہے <strong>لمبی لوہے کی مکھی</strong> حقیقی NIFTY قیمتوں پر، 26 جون 2026 کو انڈیکس کے ساتھ <strong>24,056</strong> اور 28 جولائی 2026 کو ختم ہونے میں تقریباً 32 دن باقی ہیں۔ آپ ایٹ دی منی 24,050 پوٹ اور 24,050 کال کو ایک ساتھ بیچتے ہیں، ایک مختصر اسٹریڈل، پھر 23,950 پوٹ اور 24,150 کال کو ہر طرف ایک سو پوائنٹس کے طور پر خریدیں۔ OpenAlgo بلڈر اس کریڈٹ ورژن کو کہتے ہیں۔ <strong>لوہے کی لمبی مکھی</strong>.</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>ڈال خریدیں</td>\n<td>23,950</td>\n<td>256.6 ادا کیا گیا۔</td>\n<td>16,679 روپے باہر</td>\n</tr>\n<tr>\n<td>2</td>\n<td>ڈال فروخت</td>\n<td>24,050</td>\n<td>295.1 موصول ہوا۔</td>\n<td>علاوہ 19,182 روپے میں</td>\n</tr>\n<tr>\n<td>3</td>\n<td>کال فروخت کریں۔</td>\n<td>24,050</td>\n<td>425.8 موصول ہوا۔</td>\n<td>علاوہ 27,677 روپے میں</td>\n</tr>\n<tr>\n<td>4</td>\n<td>کال خریدیں۔</td>\n<td>24,150</td>\n<td>370.1 ادا کیا گیا۔</td>\n<td>24,057 روپے باہر</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>نیٹ کریڈٹ</strong></td>\n<td><strong>علاوہ 6,130 روپے میں</strong></td>\n</tr>\n</tbody></table>\n<p>پیسے پر فروخت ہونے والے دو اختیارات شیر ​​کا حصہ لاتے ہیں، جبکہ دو خریدے گئے پروں کی قیمت تھوڑی کم ہے۔ خلا آپ کا ہے۔ <strong>6,130 روپے کا خالص کریڈٹ</strong>، جو آپ کے اکاؤنٹ میں اس وقت آتا ہے جب آپ تجارت کھولتے ہیں، اور یہ اس پوزیشن میں سب سے زیادہ ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-long-iron-fly.png\" alt=\"NIFTY پر لمبی لوہے کی پرواز: 24,050 باڈی اسٹرائیک پر 6,130 روپے کی تیز منافع کی چوٹی، 23,956 اور 24,148 پر تنگ بریک وینس، اور ایک بار جب انڈیکس دونوں بازو سے گزر جاتا ہے تو صرف 370 روپے کا نقصان۔ 24,056 پر گلابی سپاٹ لائن تقریبا چوٹی پر بیٹھتی ہے، جو اپیل اور ٹریپ دونوں ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY پر لمبی لوہے کی پرواز: 24,050 باڈی اسٹرائیک پر 6,130 روپے کی تیز منافع کی چوٹی، 23,956 اور 24,148 پر تنگ بریک وینس، اور ایک بار جب انڈیکس دونوں بازو سے گزر جاتا ہے تو صرف 370 روپے کا محدود نقصان۔ 24,056 پر گلابی سپاٹ لائن تقریبا چوٹی پر بیٹھتی ہے، جو اپیل اور ٹریپ دونوں ہے۔</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">تین نمبر، اور وہ کہاں سے آتے ہیں۔</h2>\n<p><strong>زیادہ سے زیادہ منافع خالص کریڈٹ ہے، 6,130 روپے۔</strong> اگر NIFTY بالکل 24,050 پر ختم ہو جاتا ہے، تو چاروں آپشنز بیکار ختم ہو جاتے ہیں، پنکھوں کی کبھی ضرورت نہیں تھی، اور آپ پورا کریڈٹ اپنے پاس رکھیں گے۔</p>\n<p><strong>زیادہ سے زیادہ نقصان ونگ کی چوڑائی مائنس کریڈٹ، 370 روپے ہے۔</strong> ہر بازو جسم سے ایک سو پوائنٹس پر بیٹھتا ہے، جس کی قیمت 6500 روپے ہے۔ ماضی میں یا تو ونگ جس نے آپ کے خلاف پورے 6,500 روپے میں تالے پھیلائے، لیکن آپ نے پہلے ہی 6,130 روپے کا بینک کیا، لہذا اصل نقصان 6,500 مائنس 6,130 ہے، جو کہ <strong>370 روپے</strong>.</p>\n<p><strong>Breakevens 23,956 اور 24,148 پر ہر ونگ کے بالکل اندر بیٹھتے ہیں۔</strong> آپ نے فی حصص تقریباً 94 پوائنٹس کا کریڈٹ اکٹھا کیا، اس لیے NIFTY باڈی سے 94 پوائنٹس نیچے گر سکتا ہے یا اس سے پہلے کہ ٹیسٹ شدہ سائیڈ کا نقصان کریڈٹ کھاتا ہے اس کے اوپر 98 پوائنٹس بڑھ سکتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>خالص کریڈٹ</td>\n<td>6,130 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>ونگ چوڑائی مائنس خالص کریڈٹ</td>\n<td>6,500 روپے مائنس 6,130 روپے = 370 روپے</td>\n</tr>\n<tr>\n<td>Breakevens</td>\n<td>باڈی اسٹرائیک، کم یا زیادہ کریڈٹ فی شیئر</td>\n<td>24,050 منفی 94 = 23,956; 24,050 جمع 98 = 24,148</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-outcomes-at-expiry\">میعاد ختم ہونے پر نتائج پر چلنا</h2>\n<p>تجارت کو پانچ اختتامی قیمتوں پر طے کریں اور خیمہ خود ہی ظاہر ہوتا ہے۔ ایکسپائری پر ایک پوٹ کی قیمت زیادہ سے زیادہ ہے (اسٹرائیک مائنس NIFTY، 0) اور کال کی قیمت زیادہ سے زیادہ ہے (NIFTY مائنس اسٹرائیک، 0) فی شیئر، نیٹ فی لاٹ 65 کے ساتھ۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>لمبا 23,950 PE</th>\n<th>مختصر 24,050 PE</th>\n<th>مختصر 24,050 CE</th>\n<th>لمبا 24,150 CE</th>\n<th>نیٹ پی اینڈ ایل فی لاٹ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,850</td>\n<td>100</td>\n<td>200</td>\n<td>0</td>\n<td>0</td>\n<td>مائنس 370 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>23,956</td>\n<td>0</td>\n<td>94</td>\n<td>0</td>\n<td>0</td>\n<td>تقریباً 0 روپے (کم بریک ایون)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>0</td>\n<td>0</td>\n<td>0</td>\n<td>0</td>\n<td>علاوہ 6,130 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,150</td>\n<td>0</td>\n<td>0</td>\n<td>100</td>\n<td>0</td>\n<td>مائنس 370 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n<tr>\n<td>24,250</td>\n<td>0</td>\n<td>0</td>\n<td>200</td>\n<td>100</td>\n<td>مائنس 370 روپے (زیادہ سے زیادہ نقصان)</td>\n</tr>\n</tbody></table>\n<p>تصویر سخت ہے۔ پورے 6,130 روپے صرف ایک قیمت، 24,050 پر جمع ہوتے ہیں۔ دونوں طرف ایک سرگوشی اور کریڈٹ تیزی سے سکڑتا ہے، جب تک NIFTY ایک بازو کو چھوتا ہے، 24,148 پر کال سائیڈ بریک ایون کے ساتھ 370 روپے کے نقصان کے شیلف تک پہنچ جاتا ہے۔ یہ اورنج لائن سے بالکل میل کھاتا ہے۔</p>\n<h2 id=\"your-odds\">آپ کی مشکلات</h2>\n<p>وہ نمبر جو فیصلہ کرتا ہے کہ آیا تجارت سمارٹ ہے، اس سنگل چوٹی کا کتنا امکان ہے؟ وہ ہے <strong>منافع کا امکان</strong>، اور لوہے کی لمبی مکھی کے لئے یہ صرف ہے۔ <strong>9 فیصد</strong>. NIFTY کی قیمت میں اتار چڑھاؤ کا استعمال کرتے ہوئے، تقریباً 12.7 فیصد، اور 32 دن باقی ہیں، مارکیٹ کا مطلب صرف 9 فیصد امکان ہے کہ انڈیکس 23,956 سے 24,148 بینڈ کے اندر ختم ہوجائے۔ چارٹ پر، منافع کا زون اندرونی سگما بینڈ سے بھی زیادہ سخت ہے۔ آپ NIFTY کو پرسکون رہنے کے لیے نہیں کہہ رہے ہیں، آپ اسے منجمد کرنے کے لیے کہہ رہے ہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>ہمیشہ انعام کے آگے نفع کا امکان اور زیادہ سے زیادہ نقصان کو ایک ساتھ پڑھیں۔ لانگ آئرن فلائی 6,130 روپے کمانے کے لیے صرف 370 روپے کا خطرہ مول لیتی ہے، تقریباً 1 سے 16.5 کے خطرے کا ایک شاندار انعام، لیکن یہ صرف 9 فیصد وقت میں پوری ادائیگی کرتی ہے۔ ایک چمکدار ادائیگی کا ایک سے زیادہ مطلب بہت کم ہے اگر آپ اسے تقریبا کبھی جمع نہیں کرتے ہیں۔</p>\n</div></div>\n<h2 id=\"margin-and-return-on-margin\">مارجن اور مارجن پر واپسی</h2>\n<p>چونکہ تجارت مکمل طور پر باڑ لگا ہوا ہے، ایکسچینج ایک معمولی رکاوٹ کو روکتا ہے۔ <strong>تقریباً 63,940 روپے کا مارجن</strong>,لاکھوں سے بہت نیچے ایک ننگا پیٹھ مانگے گا۔ خریدے گئے پنکھوں سے تجارت کی ضرورت کے سرمائے کو کم کر دیا جاتا ہے۔ پر <strong>مارجن پر واپسی</strong>63,940 روپے بلاک شدہ کے مقابلے میں 6,130 روپے تقریباً ہیں۔ <strong>9.6 فیصد</strong> اگر پن اترتا ہے، لیکن وزن کہ 9 فیصد مشکلات سے پہلے۔</p>\n<h2 id=\"time-decay\">وقت کا زوال</h2>\n<p>دی <strong>نیلی ڈیشڈ T+0 لائن</strong> جسم میں اورنج ایٹ-ایکسپائری چوٹی کے نیچے اچھی طرح بیٹھتا ہے۔ یہ فرق وقت کی قدر ہے، اور لوہے کی لمبی مکھی کے لیے یہ ایک دوست ہے، لیکن صرف اس صورت میں جب NIFTY 24,050 پر کھڑی ہو۔ جیسے جیسے ایکسپائری قریب آتی ہے اور انڈیکس ساکن ہوتا ہے، آپ کے لیے جو بھرپور آپشن ہوتے ہیں وہ پگھل جاتے ہیں اور نیلی لکیر نارنجی رنگ کی تیز چوٹی کی طرف بڑھ جاتی ہے۔ اگر NIFTY ایک بازو پر گھوم گیا ہے، تو وقت آپ کو اس کی بجائے 370 روپے کے شیلف تک لے جائے گا۔ زوال خاموشی کا بدلہ دیتا ہے، اور بہاؤ کو سزا دیتا ہے۔</p>\n<h2 id=\"the-short-iron-fly-the-high-probability-inverse\">مختصر لوہے کی مکھی: زیادہ امکان الٹا</h2>\n<p>بلڈر آئینہ پیش کرتا ہے، <strong>شارٹ آئرن فلائی</strong>. آپ چاروں ٹانگوں کی دوسری طرف لے جاتے ہیں، ایک ادائیگی کرتے ہیں۔ <strong>6,130 روپے کا خالص ڈیبٹ</strong> اسے جمع کرنے کے بجائے.</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>ڈال فروخت</td>\n<td>23,950</td>\n<td>256.6 موصول ہوا۔</td>\n<td>علاوہ 16,679 روپے میں</td>\n</tr>\n<tr>\n<td>2</td>\n<td>ڈال خریدیں</td>\n<td>24,050</td>\n<td>295.1 ادا کیا گیا۔</td>\n<td>19,182 روپے باہر</td>\n</tr>\n<tr>\n<td>3</td>\n<td>کال خریدیں۔</td>\n<td>24,050</td>\n<td>425.8 ادا کیا گیا۔</td>\n<td>27,677 روپے باہر</td>\n</tr>\n<tr>\n<td>4</td>\n<td>کال فروخت کریں۔</td>\n<td>24,150</td>\n<td>370.1 موصول ہوا۔</td>\n<td>علاوہ 24,057 روپے میں</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>خالص ڈیبٹ</strong></td>\n<td><strong>6,130 روپے باہر</strong></td>\n</tr>\n</tbody></table>\n<p>ہر نمبر پلٹ جاتا ہے۔ دی <strong>زیادہ سے زیادہ منافع 370 روپے ہے۔</strong>, تقریباً کہیں بھی NIFTY کی چالیں جیت گئیں۔ دی <strong>زیادہ سے زیادہ نقصان 6,130 روپے ہے۔</strong>صرف اس صورت میں نقصان اٹھانا پڑا جب انڈیکس 24,050 پر جم جائے۔ دی <strong>منافع کا امکان 91 فیصد تک بڑھ گیا۔</strong>بریک ایونز 23,956 اور 24,148 پر برقرار ہیں، اور مارجن تقریباً 69,490 روپے ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-short-iron-fly.png\" alt=\"NIFTY پر شارٹ آئرن فلائی: لمبی فلائی کا الٹا، 24,050 پر پن کے علاوہ تقریباً کہیں بھی 370 روپے کا چھوٹا منافع، لیکن 6,130 روپے کا نقصان اگر انڈیکس سٹرائیک پر سیٹل ہو جائے، منافع کے 91 فیصد امکان کے ساتھ۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY پر شارٹ آئرن فلائی: لمبی فلائی کا الٹا، 24,050 پر پن کے علاوہ تقریباً کہیں بھی 370 روپے کا چھوٹا منافع، لیکن 6,130 روپے کا نقصان اگر انڈیکس ہڑتال پر سیٹل ہو جائے، منافع کے 91 فیصد امکان کے ساتھ۔</figcaption></figure>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>مختصر آئرن فلائی پر منافع کا 91 فیصد امکان دلکش ہے، لیکن یہ 6,130 روپے کے نقصان کے مقابلے میں صرف 370 روپے جیتتا ہے۔ ایک خراب پن سولہ جیت کو ختم کر دیتا ہے۔ اور لیبلز سے گمراہ نہ ہوں: لانگ آئرن فلائی کریڈٹ ورژن ہے، شارٹ آئرن فلائی ڈیبٹ ورژن ہے، جو وجدان کے خلاف چلتا ہے۔ ہر ایک کو اس کے نو نمبروں سے پرکھیں، اس کے نام سے کبھی نہیں۔</p>\n</div></div>\n<h2 id=\"the-call-butterfly-the-same-peak-from-one-option-type\">کال بٹر فلائی: ایک آپشن کی قسم سے ایک ہی چوٹی</h2>\n<p>آپ ایک ہی آپشن کی قسم کا استعمال کرتے ہوئے بغیر کسی سٹرڈل کو بیچے ایک جیسا خیمہ بنا سکتے ہیں۔ اے <strong>تتلی کو کال کریں</strong> درمیان میں چوٹی کرنے کے لیے تین سٹرائیکس اور چار کال لیگز کا استعمال کرتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>کال خریدیں۔</td>\n<td>23,950</td>\n<td>486.9 ادا کیا گیا۔</td>\n<td>31,649 روپے باہر</td>\n</tr>\n<tr>\n<td>2</td>\n<td>سیل کال (x2)</td>\n<td>24,050</td>\n<td>425.8 موصول ہوا۔</td>\n<td>علاوہ 55,354 روپے میں</td>\n</tr>\n<tr>\n<td>3</td>\n<td>کال خریدیں۔</td>\n<td>24,150</td>\n<td>370.1 ادا کیا گیا۔</td>\n<td>24,053 روپے باہر</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>خالص ڈیبٹ</strong></td>\n<td><strong>باہر 348 روپے</strong></td>\n</tr>\n</tbody></table>\n<p>آپ نیچے ایک کال خریدتے ہیں، باڈی پر دو بیچتے ہیں، اور اوپر ایک خریدتے ہیں۔ دو فروخت شدہ کالیں زیادہ تر پریمیم لاتی ہیں، جس سے ایک چھوٹا سا رہ جاتا ہے۔ <strong>348 روپے کا خالص ڈیبٹ</strong>، آپ کا <strong>زیادہ سے زیادہ نقصان</strong>، اگر NIFTY پنکھوں سے باہر ختم ہوجاتا ہے تو اس کا سامنا کرنا پڑتا ہے۔ دی <strong>زیادہ سے زیادہ منافع 6,152 روپے ہے۔</strong>، صرف اس صورت میں پہنچا جب NIFTY 24,050 کو پن کرتا ہے، جہاں دو بیکار فروخت شدہ کالوں کے مقابلے میں نچلا ونگ اپنے پورے سو پوائنٹس کے قابل ہے۔ دی <strong>breakevens ہیں 23,954 اور 24,148</strong>، دوبارہ منافع کا امکان <strong>9 فیصد</strong>، اور تقریباً 64,000 روپے کے مارجن پر شاندار 1 سے 17.7 تک کا خطرہ مول لینے کا انعام۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-call-butterfly.png\" alt=\"NIFTY پر کال بٹر فلائی: اکیلے کالوں سے بنایا گیا، 24,050 باڈی پر 6,152 روپے پر تیز منافع کا خیمہ، 23,954 اور 24,148 پر بریک ایون، اور پنکھوں کے باہر 348 روپے کا چھوٹا نقصان۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY پر کال بٹر فلائی: اکیلے کالوں سے بنایا گیا، 24,050 باڈی پر 6,152 روپے پر تیز منافع کا ٹینٹ، 23,954 اور 24,148 پر بریک ایون، اور پنکھوں کے باہر 348 روپے کا چھوٹا نقصان۔</figcaption></figure>\n<p>اس چارٹ کو لوہے کی لمبی مکھی کے پاس رکھیں اور وہ تقریباً ایک جیسی تصویر ہیں: 24,050 پر ایک تیز چوٹی، وہی بریک ایونز اور 9 فیصد مشکلات، جو کہ مختلف کیش فلو کے لیے مختلف ٹانگوں سے بنی ہیں۔</p>\n<h2 id=\"the-put-butterfly-two-routes-one-shape\">پوٹ بٹر فلائی: دو راستے، ایک شکل</h2>\n<p>دی <strong>تیتلی رکھو</strong> صرف پوٹس کا استعمال کرتے ہوئے ایک جیسی چوٹی تک پہنچتا ہے، کال ورژن کا آئینہ۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>ڈال خریدیں</td>\n<td>24,150</td>\n<td>339.2 ادا کیا گیا۔</td>\n<td>22,045 روپے باہر</td>\n</tr>\n<tr>\n<td>2</td>\n<td>سیل ڈال (x2)</td>\n<td>24,050</td>\n<td>295.1 موصول ہوا۔</td>\n<td>علاوہ 38,363 روپے میں</td>\n</tr>\n<tr>\n<td>3</td>\n<td>ڈال خریدیں</td>\n<td>23,950</td>\n<td>256.6 ادا کیا گیا۔</td>\n<td>16,679 روپے باہر</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>خالص ڈیبٹ</strong></td>\n<td><strong>باہر 361 روپے</strong></td>\n</tr>\n</tbody></table>\n<p>اس کی قیمت a <strong>361 روپے کا خالص ڈیبٹ</strong>اس کا <strong>زیادہ سے زیادہ نقصان</strong>, اور ادا کرتا ہے a <strong>زیادہ سے زیادہ منافع 6,139 روپے</strong> اگر NIFTY 24,050 پن کرتا ہے۔ بریک ایونز 23,955 اور 24,148 ہیں، دوبارہ منافع کا امکان 9 فیصد، اور مارجن تقریباً 63,877 روپے ہے۔ کال بٹر فلائی اور پوٹ بٹر فلائی کو ساتھ ساتھ رکھیں اور آپ ان کی ادائیگیوں کو الگ نہیں بتا سکتے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-put-butterfly.png\" alt=\"The put Butterfly on NIFTY: اکیلے پوٹس سے بنایا گیا، 24,050 پر 6,139 روپے کی ایک ہی چوٹی، 23,955 اور 24,148 پر بریک ایونز، اور پنکھوں کے باہر تقریباً 361 روپے کا نقصان، کالز اور پوٹس ایک شکل کے دو راستے ہیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>The put Butterfly on NIFTY: اکیلے پوٹس سے بنایا گیا، 24,050 پر 6,139 روپے کی ایک ہی چوٹی، 23,955 اور 24,148 پر بریک ایونز، اور پنکھوں کے باہر تقریباً 361 روپے کا نقصان، کالز اور پوٹس ایک شکل کے دو راستے ہیں۔</figcaption></figure>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>کال بٹر فلائی کی قیمت 348 روپے اور پوٹ بٹر فلائی کی قیمت 361 روپے ہے، چند روپے کے علاوہ، اور دونوں ایک ہی انعام اور اسی 9 فیصد مشکلات کے لیے ایک ہی سٹرائیک پن کرتے ہیں۔ گہرا سبق: ادائیگی کی شکل ایک اختیار کی قسم سے منسلک نہیں ہے۔ کالز اور پوٹس دو زبانیں ہیں جو ایک ہی تصویر کو بیان کرتی ہیں، اور ایک ہنر مند تاجر اپنی مطلوبہ شکل تک پہنچنے کے لیے جو بھی ٹانگیں سستی یا زیادہ مائع ہوتی ہیں اسے چنتا ہے۔</p>\n</div></div>\n<h2 id=\"choosing-among-the-pin-the-strike-family\">پن-دی-سٹرائیک فیملی میں سے انتخاب کرنا</h2>\n<p>اب آپ کے پاس دانو لگانے کے چار طریقے ہیں جہاں NIFTY سیٹ ہوتا ہے۔ انتخاب نقد بہاؤ اور مشکلات پر آتا ہے، خیمے کی شکل پر نہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>ساخت</th>\n<th>سے بنایا گیا ہے۔</th>\n<th>لاگت یا کریڈٹ</th>\n<th>زیادہ سے زیادہ منافع</th>\n<th>زیادہ سے زیادہ نقصان</th>\n<th>POP</th>\n<th>مارجن</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>لوہے کی لمبی مکھی</td>\n<td>مختصر اسٹریڈل کے علاوہ دو پنکھ</td>\n<td>کریڈٹ 6,130 روپے</td>\n<td>6,130 روپے</td>\n<td>370 روپے</td>\n<td>9%</td>\n<td>63,940 روپے</td>\n</tr>\n<tr>\n<td>تتلی کو بلاؤ</td>\n<td>چار کالز</td>\n<td>ڈیبٹ 348 روپے</td>\n<td>6,152 روپے</td>\n<td>348 روپے</td>\n<td>9%</td>\n<td>64,000 روپے</td>\n</tr>\n<tr>\n<td>تتلی ڈالو</td>\n<td>چار پوٹس</td>\n<td>ڈیبٹ 361 روپے</td>\n<td>6,139 روپے</td>\n<td>361 روپے</td>\n<td>9%</td>\n<td>63,877 روپے</td>\n</tr>\n<tr>\n<td>مختصر لوہے کی مکھی</td>\n<td>الٹا، چار ٹانگیں</td>\n<td>ڈیبٹ 6,130 روپے</td>\n<td>370 روپے</td>\n<td>6,130 روپے</td>\n<td>91%</td>\n<td>69,490 روپے</td>\n</tr>\n</tbody></table>\n<p>تین پن-دی-سٹرائیک شرطیں 6,100 روپے کے قریب چوٹی، ایک چھوٹا سا نقصان، اور 9 فیصد مشکلات کا اشتراک کرتی ہیں۔ ایک آپشن کی قسم میں ایک چھوٹا سا معروف ڈیبٹ ادا کرنے کے لیے ایک تتلی کا انتخاب کریں، یا سامنے کا پریمیم جمع کرنے کے لیے کریڈٹ آئرن فلائی کا انتخاب کریں۔ شارٹ آئرن فلائی کو صرف صاف آنکھوں کے ساتھ استعمال کریں، کیونکہ نایاب پن پر بڑے نقصان کے ساتھ چھوٹی جیت کا زیادہ امکان سخت انتظام کا مطالبہ کرتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>پن-دی-سٹرائیک ٹریڈز کو ختم ہونے کے قریب رکھیں، ہفتے کے اوائل میں نہیں، اس لیے NIFTY کے پاس جسم سے بھٹکنے کے لیے کم گنجائش ہے۔ اور کبھی بھی شاندار انعام کے متعدد کو مشکلات کے ساتھ الجھائیں: 9 فیصد پر، لمبی مکھی اور تتلیاں سستی، ٹارگٹڈ، کم امکان والی شرطیں ہیں، آمدنی کی مشینیں نہیں۔ بلڈر کی رپورٹ کے مطابق زیادہ سے زیادہ نقصان کو پڑھیں، چار ٹانگوں کا بڑا مجموعی کاروبار کبھی نہیں۔</p>\n</div></div>\n<h2 id=\"key-takeaways\">اہم نکات</h2>\n<ul>\n<li>پن-دی-سٹرائیک ٹریڈ ایک نقطہ پر گرا ہوا آئرن کنڈور ہے: یہ صرف اس صورت میں سب سے زیادہ ادائیگی کرتا ہے جب NIFTY باڈی اسٹرائیک پر تقریباً مکمل ہو جائے، یہاں 24,050۔</li>\n<li>دی <strong>لمبی لوہے کی مکھی</strong> اکٹھا کرتا ہے <strong>6,130 روپے کا خالص کریڈٹ</strong> (اس کا زیادہ سے زیادہ منافع)، صرف خطرات <strong>370 روپے</strong> (ونگ کی چوڑائی مائنس کریڈٹ)، اور 23,956 اور 24,148 پر بھی ٹوٹ جاتی ہے۔</li>\n<li>دی <strong>تتلی کو کال کریں</strong> اور <strong>تیتلی رکھو</strong> 348 روپے یا 361 روپے کے چھوٹے ڈیبٹ کے لیے ایک آپشن کی قسم سے ایک ہی چوٹی تک پہنچیں، یہ ثابت کرنا کہ کالز اور پوٹس ایک شکل کے دو راستے ہیں۔</li>\n<li>تینوں پن-دی-سٹرائیک دائو کا اشتراک a <strong>9 فیصد منافع کا امکان</strong>: خطرے کا ایک شاندار انعام جو شاذ و نادر ہی اکٹھا کیا جاتا ہے، اس لیے ان کا سائز سستے طویل شاٹس کے طور پر کریں۔</li>\n<li>دی <strong>مختصر لوہے کی مکھی</strong> الٹا ہے، نایاب پن پر 6,130 روپے کے نقصان کے مقابلے میں 370 روپے کی چھوٹی جیت کا 91 فیصد امکان۔ تمام چاروں کو 64,000 روپے کے قریب معمولی مارجن پر خطرے سے دوچار کیا گیا ہے۔ ان کو اندر بنائیں <strong>سینڈ باکس ٹریڈنگ (Analyzer mode in OpenAlgo)</strong> یہ دیکھنے کے لیے کہ چوٹی کتنی تیزی سے گرتی ہے۔</li>\n</ul>\n","toc":[{"level":2,"text":"ایک لائن کا خیال","id":"the-one-line-idea"},{"level":2,"text":"اصل تجارت، روپیہ بہ روپیہ","id":"the-real-trade-rupee-by-rupee"},{"level":2,"text":"تین نمبر، اور وہ کہاں سے آتے ہیں۔","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"میعاد ختم ہونے پر نتائج پر چلنا","id":"walking-the-outcomes-at-expiry"},{"level":2,"text":"آپ کی مشکلات","id":"your-odds"},{"level":2,"text":"مارجن اور مارجن پر واپسی","id":"margin-and-return-on-margin"},{"level":2,"text":"وقت کا زوال","id":"time-decay"},{"level":2,"text":"مختصر لوہے کی مکھی: زیادہ امکان الٹا","id":"the-short-iron-fly-the-high-probability-inverse"},{"level":2,"text":"کال بٹر فلائی: ایک آپشن کی قسم سے ایک ہی چوٹی","id":"the-call-butterfly-the-same-peak-from-one-option-type"},{"level":2,"text":"پوٹ بٹر فلائی: دو راستے، ایک شکل","id":"the-put-butterfly-two-routes-one-shape"},{"level":2,"text":"پن-دی-سٹرائیک فیملی میں سے انتخاب کرنا","id":"choosing-among-the-pin-the-strike-family"},{"level":2,"text":"اہم نکات","id":"key-takeaways"}],"imgCount":4,"hasContent":true},"17":{"html":"<p>پچھلے ابواب سے پھیلنے والے تناسب نے ان کی فروخت سے زیادہ اختیارات خریدے، لہذا انہوں نے ڈیبٹ کے لیے کھولا، ایک متعین نقصان رکھا، اور صرف ایک بڑے، تیز اقدام پر ادائیگی کی۔ یہ باب اس تناسب کو اپنے سر پر بدل دیتا ہے۔ اب آپ خریدنے سے زیادہ بیچتے ہیں۔ آپ پہلے سے موٹا کریڈٹ جمع کرتے ہیں، آپ کو سب سے زیادہ فائدہ ہوتا ہے اگر NIFTY آپ کی فروخت کردہ ہڑتال کی طرف آہستہ سے بڑھتا ہے، اور آپ کے پاس ایک ننگا آپشن ہوتا ہے جو اگر انڈیکس بہت زیادہ غلط راستے پر چلا جاتا ہے تو بھاگ سکتا ہے۔ یہ ہیں <strong>کال تناسب پھیلاؤ</strong> اور <strong>تناسب پھیلاؤ ڈالو</strong>. وہ ہوشیار نظر آتے ہیں، وہ اکثر جیت جاتے ہیں، لیکن غیر منقولہ پہلو حقیقی ہے، لہذا آنکھیں کھول کر دونوں چارٹ پڑھیں۔</p>\n<h2 id=\"the-one-line-idea\">ایک لائن کا خیال</h2>\n<p>اے <strong>تناسب پھیلاؤ</strong> پیسے پر ایک آپشن خریدتا ہے اور ایک ہی قسم کے دو کو تھوڑا آگے بیچتا ہے۔ چونکہ آپ نے اپنی خریدی سے زیادہ فروخت کی ہے، اس لیے پوزیشن فروخت کی گئی ہڑتال سے بالکل کم ہے، جو بالکل وہی جگہ ہے جہاں خطرہ رہتا ہے۔ یہ ایک کریڈٹ ٹریڈ ہے جو چاہتا ہے کہ آپ کی فروخت کردہ ہڑتال کی طرف بڑھے اور وہیں رک جائے، اس ہڑتال پر اپنی چوٹی کا حق ادا کرتے ہوئے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>تناسب کا پھیلاؤ دو اختیارات فروخت کرتا ہے اور ایک خریدتا ہے، کریڈٹ کے لیے کھولتا ہے۔ یہ ایک وسیع علاقے میں منافع بخش ہے، بالکل فروخت کی گئی ہڑتال پر پہنچتا ہے، اور پھر اس سے آگے ایک ہی برہنہ آپشن کو بے نقاب کرتا ہے۔ جو کریڈٹ آپ اکٹھا کرتے ہیں وہ اس غیر منقطع دم کو لے جانے کا انعام ہے۔</p>\n</div></div>\n<h2 id=\"the-real-trade-rupee-by-rupee\">اصل تجارت، روپیہ بہ روپیہ</h2>\n<p>یہاں ہے <strong>کال تناسب پھیلاؤ</strong> حقیقی NIFTY قیمتوں پر، 26 جون 2026 کو انڈیکس کے ساتھ <strong>24,056</strong> اور 28 جولائی 2026 کو ختم ہونے میں تقریباً 32 دن باقی ہیں۔ آپ ایک اٹ دی منی 24,050 کال خریدتے ہیں اور دو 24,150 کالز ایک سٹرائیک زیادہ فروخت کرتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>کال خریدیں۔</td>\n<td>24,050</td>\n<td>425.8 ادا کیا گیا۔</td>\n<td>27,677 روپے باہر</td>\n</tr>\n<tr>\n<td>2</td>\n<td>سیل کال (x2)</td>\n<td>24,150</td>\n<td>370.1 موصول ہوا۔</td>\n<td>علاوہ 48,107 روپے میں</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>نیٹ کریڈٹ</strong></td>\n<td><strong>علاوہ 20,430 روپے میں</strong></td>\n</tr>\n</tbody></table>\n<p>آپ ایک خریدی ہوئی کال کے لیے 27,677 روپے ادا کرتے ہیں اور فروخت ہونے والی دو کالوں کے لیے 48,107 روپے لیتے ہیں، لہذا پوزیشن ایک صحت مند کے لیے کھل جاتی ہے۔ <strong>20,430 روپے کا خالص کریڈٹ</strong>. اگر NIFTY صرف 24,050 پر یا اس سے نیچے رہتا ہے تو یہ کریڈٹ آپ کو ہے، جہاں ہر کال کی میعاد ختم ہوجاتی ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-call-ratio-spread.png\" alt=\"NIFTY کال ریشو اسپریڈ: ایک منافع جو 24,150 اسٹرائیک پر 20,430 روپے کے کریڈٹ فلور سے 26,930 روپے کی تیز چوٹی تک پہنچ جاتا ہے، 24,564 پر ایک بریک ایون، اور ایک ایٹ-ایکسپائری لائن جو اس کے اوپر بغیر کسی حد کے گرتی ہے کیونکہ آپ کو ایک اضافی کال مختصر ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY کال ریشو اسپریڈ: ایک منافع جو 24,150 سٹرائیک پر 20,430 روپے کے کریڈٹ فلور سے 26,930 روپے کی تیز چوٹی تک پہنچ جاتا ہے، 24,564 پر ایک بریک ایون، اور ایک ایٹ ایکسپائری لائن جو اس کے اوپر بغیر کسی حد کے گرتی ہے کیونکہ آپ کو ایک اضافی کال مختصر ہے۔</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">تین نمبر، اور وہ کہاں سے آتے ہیں۔</h2>\n<p><strong>زیادہ سے زیادہ منافع 26,930 روپے ہے، فروخت کی گئی ہڑتال پر پہنچ گیا۔</strong> جیسا کہ NIFTY 24,050 سے بڑھ کر 24,150 کی طرف جاتا ہے، آپ کی خریدی ہوئی کال کی قدر بڑھ جاتی ہے جب کہ فروخت کی گئی دو کالیں اب بھی بیکار ہیں، اس لیے منافع میں اضافہ ہوتا ہے۔ بالکل 24,150 پر خریدی گئی کال کی قیمت پورے سو پوائنٹس یعنی 6,500 روپے ہے، جو کریڈٹ آپ کے پاس پہلے سے ہے۔ تو چوٹی 20,430 جمع 6,500 ہے، جو ہے۔ <strong>26,930 روپے</strong>.</p>\n<p><strong>زیادہ سے زیادہ نقصان لامحدود ہے۔</strong> 24,150 کو آگے بڑھائیں اور دو فروخت شدہ کالیں آپ کے خلاف اٹھیں۔ اب آپ ایک نیٹ کال مختصر کر رہے ہیں، بغیر کسی حد کے 65 روپے فی پوائنٹ کھو رہے ہیں۔ یہ ننگی دم ہے، اور یہ کبھی نہیں رکتی۔</p>\n<p><strong>Breakeven 24,564 ہے۔</strong> 24,150 سے اوپر آپ کی سنگل نیٹ شارٹ کال 26,930 روپے کی چوٹی سے 65 روپے ایک پوائنٹ واپس دیتی ہے۔ چوٹی کی مالیت تقریباً 414 پوائنٹس آف کشن فی شیئر ہے، اس لیے ایکسپائری لائن صفر 414 پوائنٹس کو 24,150 سے اوپر کراس کرتی ہے۔ <strong>24,564</strong>.</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>کریڈٹ کے علاوہ فروخت کی گئی ہڑتال پر خریدی گئی کال</td>\n<td>20,430 روپے جمع 6,500 روپے = 26,930 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>چوٹی کے اوپر ننگی اضافی مختصر کال</td>\n<td>لامحدود</td>\n</tr>\n<tr>\n<td>بریک ایون</td>\n<td>فروخت کی ہڑتال کے علاوہ فی حصص چوٹی کشن</td>\n<td>24,150 جمع 414 = 24,564</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-outcomes-at-expiry\">میعاد ختم ہونے پر نتائج پر چلنا</h2>\n<p>تجارت کو پانچ اختتامی قیمتوں پر طے کریں اور ریمپ، چوٹی اور چٹان دیکھیں۔ ایک کال کی قیمت زیادہ سے زیادہ ہے</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>لمبا 24,050 CE (آپ کے مالک ہیں)</th>\n<th>دو مختصر 24,150 CE (آپ پر واجب ہے)</th>\n<th>نیٹ پی اینڈ ایل فی لاٹ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,950</td>\n<td>0</td>\n<td>0</td>\n<td>علاوہ 20,430 روپے (کریڈٹ فلور)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>0</td>\n<td>0</td>\n<td>علاوہ 20,430 روپے</td>\n</tr>\n<tr>\n<td>24,150</td>\n<td>100</td>\n<td>0</td>\n<td>علاوہ 26,930 روپے (چوٹی)</td>\n</tr>\n<tr>\n<td>24,564</td>\n<td>514</td>\n<td>828</td>\n<td>تقریباً 0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>24,700</td>\n<td>650</td>\n<td>1,100</td>\n<td>مائنس 8,820 روپے (نقصان بڑھتا ہے)</td>\n</tr>\n</tbody></table>\n<p>24,050 سے نیچے لائن 20,430 روپے کے کریڈٹ فلور پر فلیٹ ہے۔ وہاں سے یہ 24,150 پر 26,930 روپے کی چوٹی تک ریمپ کرتا ہے، پھر دوسری شارٹ کال بائٹس کے طور پر نیچے مڑ جاتا ہے، 24,564 پر صفر کو عبور کرتا ہے اور بغیر کسی منزل کے گرتا ہے۔ 24,700 پر آپ پہلے ہی 8,820 روپے نیچے ہیں، اور ہر اگلے پوائنٹ کی قیمت مزید 65 روپے ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>کال ریشو اسپریڈ میں زیادہ سے زیادہ نقصان ہوتا ہے جو لامحدود ہوتا ہے۔ اضافی فروخت ہونے والی 24,150 کال ننگی ہے، اس لیے ایک بار جب NIFTY 24,564 کے بریک ایون کو عبور کر لیتا ہے تو آپ کو ہر ایک پوائنٹ کے لیے 65 روپے کا نقصان ہوتا ہے، جس کی کوئی حد نہیں ہوتی۔ ایکسچینج تقریباً 1.76 لاکھ روپے کے مارجن کو روکتا ہے کیونکہ اس غیر کیپ شدہ دم کی وجہ سے۔ منافع کا آرام دہ امکان نقصان شروع ہونے سے پہلے وسیع کشن سے آتا ہے، لیکن چوٹی سے گزرنے والی مضبوط ریلی جیت کے سلسلے کو ایک بڑے نقصان میں بدل سکتی ہے۔</p>\n</div></div>\n<h2 id=\"your-odds\">آپ کی مشکلات</h2>\n<p>دی <strong>منافع کا امکان 72 فیصد ہے۔</strong>. وہ زیادہ تعداد وسیع کشن سے آتی ہے: NIFTY 24,564 بریک ایون کے نیچے کہیں بھی بیٹھ سکتا ہے اور آپ سبز رنگ میں ختم کرتے ہیں، اور زیادہ تر وقت 32 دنوں میں ایسا ہوتا ہے۔ چارٹ کو دیکھیں اور بریک ایون اوپری سگما بینڈ کے باہر اچھی طرح بیٹھا ہے، جس حرکت کی مارکیٹ کو توقع ہے۔ تجارت اکثر جیت جاتی ہے کیونکہ خطرہ صرف ایک بڑی ریلی کے بعد شروع ہوتا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>لفظ لامحدود، کبھی اکیلے نہیں کے آگے منافع کا 72 فیصد امکان پڑھیں۔ بغیر کیپڈ پونچھ کے ساتھ منسلک ایک اعلی جیت کی شرح کلاسک ٹریپ ہے: یہ آپ کو مہینوں تک مستقل طور پر ادائیگی کرتا ہے، پھر ایک تیز ریلی آپ کے جمع کردہ سے کہیں زیادہ پیچھے ہٹ جاتی ہے۔ اگر آپ ابھی بھی سیکھ رہے ہیں تو، متعین خطرے والے رشتہ داروں کو ترجیح دیں، یا تجارت کرنے سے پہلے کسی دور کی خریدی ہوئی کال کے ساتھ ننگے پہلو کو کیپ کریں۔</p>\n</div></div>\n<h2 id=\"margin-and-return-on-margin\">مارجن اور مارجن پر واپسی</h2>\n<p>ننگی دم کی وجہ سے ایکسچینج ایک بھاری کو روکتا ہے۔ <strong>تقریباً 1,76,491 روپے کا مارجن</strong>، کئی بار اسی طرح کے سائز کے وضاحتی پھیلاؤ کی ضرورت ہوگی۔ وہ بڑی تعداد ایکسچینج ہے جو آپ کو نقد رقم میں بتاتی ہے کہ یہ ڈھانچہ خطرناک ہے، حالانکہ یہ ایک ایسے کریڈٹ کے لیے کھولا گیا ہے جو مفت پیسے کی طرح محسوس ہوتا ہے۔</p>\n<p>پر <strong>مارجن پر واپسی</strong>1,76,491 روپے کے مقابلے میں 26,930 روپے کی چوٹی بلاک ہوئی ہے <strong>15 فیصد</strong>، لیکن یہ عین فروخت شدہ ہڑتال پر بہترین معاملہ ہے، نہ کہ ایسی تعداد جس پر آپ اعتماد کر سکتے ہیں، اور یہ لامحدود منفی پہلو کو نظر انداز کرتا ہے۔ پیداوار کے طور پر حوالہ دینے سے پہلے ہمیشہ مشکلات اور دم سے چوٹی کا وزن کریں۔</p>\n<h2 id=\"time-decay\">وقت کا زوال</h2>\n<p>یہ خالص شارٹ پوزیشن ہے، آپ نے دو آپشن بیچے اور ایک خریدا، اس لیے بیلنس ٹائم ڈے آپ کے لیے کام کرتا ہے۔ چارٹ کو دیکھیں: <strong>نیلی ڈیشڈ T+0 لائن</strong> اورنج ایٹ-ایکسپائری چوٹی کے نیچے بیٹھتا ہے، اور ہر پرسکون دن اس چوٹی کی طرف پوزیشن کو اوپر لے جاتا ہے کیونکہ فروخت شدہ وقت کی قیمت پگھل جاتی ہے۔ کیچ یہ ہے کہ زوال صرف اس وقت مدد کرتا ہے جب NIFTY برتاؤ کرتا ہے۔ ایک بار جب انڈیکس چوٹی سے گزر جاتا ہے، وقت کی اہمیت رک جاتی ہے اور برہنہ کال نقصان کو آگے بڑھاتی ہے۔</p>\n<h2 id=\"the-put-ratio-spread\">ڈال تناسب پھیل گیا</h2>\n<p>دی <strong>تناسب پھیلاؤ ڈالو</strong> ایک ہی خیال نیچے کی طرف اشارہ کرتا ہے۔ آپ ایک ایٹ-دی-منی پوٹ خریدتے ہیں اور دو پوٹ کو تھوڑا سا نیچے بیچتے ہیں، جس سے آپ کا خالص شارٹ ایک پوٹ لوئر اسٹرائیک سے نیچے رہ جاتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>ڈال خریدیں</td>\n<td>24,050</td>\n<td>295.1 ادا کیا گیا۔</td>\n<td>19,182 روپے باہر</td>\n</tr>\n<tr>\n<td>2</td>\n<td>سیل ڈال (x2)</td>\n<td>23,950</td>\n<td>256.6 موصول ہوا۔</td>\n<td>علاوہ 33,352 روپے میں</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>نیٹ کریڈٹ</strong></td>\n<td><strong>علاوہ 14,170 روپے میں</strong></td>\n</tr>\n</tbody></table>\n<p>آپ خریدے گئے پوٹ کے لیے 19,182 روپے ادا کرتے ہیں اور فروخت کیے گئے دو پوٹ کے لیے 33,352 روپے جمع کرتے ہیں۔ <strong>14,170 روپے کا خالص کریڈٹ</strong>اگر NIFTY 24,050 پر یا اس سے اوپر رہتا ہے تو مکمل رکھا جائے گا۔ چوٹی نچلی سٹرائیک پر بیٹھتی ہے: جیسا کہ NIFTY 23,950 کی طرف آتا ہے، خریدا ہوا منافع حاصل ہوتا ہے جب کہ بیچا ہوا پوٹ بیکار رہتا ہے، اس کے منافع کو بڑھاتا ہے۔ <strong>زیادہ سے زیادہ 20,670 روپے</strong> جب NIFTY 23,950 پن کرتا ہے۔ اس کے نیچے دو بیچے گئے پوٹس آپ کے خلاف ہوتے ہیں، آپ خالص شارٹ ایک پوٹ ہیں، اور <strong>بریک ایون 23,632 ہے۔</strong>.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-put-ratio-spread.png\" alt=\"NIFTY پوٹ ریشو اسپریڈ: ایک منافع جو 23,950 سٹرائیک پر 14,170 کریڈٹ فلور سے بڑھ کر 20,670 روپے کی چوٹی تک پہنچ جاتا ہے، 23,632 پر بریک ایون، اور ایک نقصان جو اس سے نیچے ایک بہت بڑی شخصیت کی طرف بڑھتا ہے کیونکہ آپ ایک اضافی پوٹ مختصر ہیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY پوٹ ریشو اسپریڈ: ایک منافع جو 23,950 سٹرائیک پر 14,170 کریڈٹ فلور سے بڑھ کر 20,670 روپے کی چوٹی تک پہنچ جاتا ہے، 23,632 پر بریک ایون، اور ایک نقصان جو اس سے نیچے ایک بہت بڑی شخصیت کی طرف بڑھتا ہے کیونکہ آپ ایک اضافی پوٹ مختصر ہیں۔</figcaption></figure>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>لمبا 24,050 PE (آپ کے مالک ہیں)</th>\n<th>دو مختصر 23,950 PE (آپ پر واجب ہے)</th>\n<th>نیٹ پی اینڈ ایل فی لاٹ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>24,100</td>\n<td>0</td>\n<td>0</td>\n<td>علاوہ 14,170 روپے (کریڈٹ فلور)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>0</td>\n<td>0</td>\n<td>علاوہ 14,170 روپے</td>\n</tr>\n<tr>\n<td>23,950</td>\n<td>100</td>\n<td>0</td>\n<td>علاوہ 20,670 روپے (چوٹی)</td>\n</tr>\n<tr>\n<td>23,632</td>\n<td>418</td>\n<td>636</td>\n<td>تقریباً 0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>23,500</td>\n<td>550</td>\n<td>900</td>\n<td>مائنس 8,580 روپے (نقصان بڑھتا ہے)</td>\n</tr>\n</tbody></table>\n<p>شکل کال ورژن کی آئینہ دار ہے۔ لائن 24,050 کے اوپر 14,170 روپے کی منزل پر فلیٹ ہے، 23,950 پر 20,670 روپے کی چوٹی تک ریمپ، 23,632 پر صفر کو عبور کرتی ہے، اور نیچے گہری ہوتی ہے۔ دی <strong>منافع کا امکان 68 فیصد ہے۔</strong>، اور مارجن تقریباً 1,70,795 روپے ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>پوٹ ریشو اسپریڈ میں بہت بڑا منفی نقصان ہوتا ہے، اگر NIFTY صفر کی طرف گرتا ہے تو تقریباً 15.4 لاکھ روپے درج ہوتا ہے۔ اضافی فروخت ہونے والا 23,950 پوٹ منفی پہلو سے خالی ہے، لہذا ایک بار جب NIFTY 23,632 سے نیچے آجاتا ہے تو آپ کو 65 روپے ایک پوائنٹ کا نقصان ہوتا ہے اور صرف صفر کی منزل اسے روکتی ہے۔ اس لیے ایکسچینج تقریباً 1.71 لاکھ روپے کے مارجن کو روکتا ہے۔ منافع کا 68 فیصد امکان اوپر والے چوڑے کشن کی عکاسی کرتا ہے، دم کی گہرائی کی نہیں۔ ایک تیز زوال بالکل وہی ہے جو اس تجارت کو سب سے زیادہ نقصان پہنچاتا ہے۔</p>\n</div></div>\n<h2 id=\"how-a-ratio-spread-differs-from-a-back-spread\">تناسب کا پھیلاؤ بیک اسپریڈ سے کیسے مختلف ہے۔</h2>\n<p>ان کریڈٹ ریشو اسپریڈز کو پہلے کے ڈیبٹ ریشو بیک اسپریڈز کے ساتھ الجھانا آسان ہے۔ وہ مخالف کے قریب ہیں، اور فرق یہ ہے کہ آپ کا وزن کس طرف ہے۔</p>\n<ul>\n<li>اے <strong>واپس پھیلاؤ</strong> دو خریدتا ہے اور ایک بیچتا ہے، تو یہ خالص طویل ہے۔ یہ ایک چھوٹا سا ڈیبٹ ادا کرتا ہے، ایک متعین نقصان کو برقرار رکھتا ہے، اور ادائیگی کے لیے ایک بڑے، تیز اقدام کی ضرورت ہے۔</li>\n<li>اے <strong>تناسب پھیلاؤ</strong> دو بیچتا ہے اور ایک خریدتا ہے، تو یہ خالص مختصر ہے۔ یہ کریڈٹ اکٹھا کرتا ہے، اگر NIFTY فروخت شدہ ہڑتال کو پن کرتا ہے، اور اس سے آگے ایک ننگی دم کو ظاہر کرتا ہے۔</li>\n</ul>\n<p>بیک اسپریڈ تشدد چاہتا ہے اور بھاری ادائیگی کے لیے کم جیت کی شرح کو قبول کرتا ہے۔ تناسب کا پھیلاؤ فروخت شدہ ہڑتال کی طرف ہلکا، مستحکم بڑھنا چاہتا ہے اور اعلی جیت کی شرح کے لئے ایک ننگی دم کو قبول کرتا ہے۔ ایک جیسی ٹانگیں، مخالف تناسب، مخالف کردار۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>مارجن کا موازنہ کریں۔ دونوں ریشو اسپریڈ بلاک کو 1.7 لاکھ روپے سے زیادہ کا ہے، جب کہ پچھلے بابوں سے بیک اسپریڈ صرف تقریباً 46,000 روپے سے 52,000 روپے تک بلاک ہیں۔ ایکسچینج آپ کو نقد میں بتا رہا ہے کہ تناسب کے پھیلاؤ کی ننگی دم زیادہ خطرناک ڈھانچہ ہے، حالانکہ یہ ایک کریڈٹ کے لئے کھلتا ہے جو آسان رقم کی طرح محسوس ہوتا ہے۔</p>\n</div></div>\n<h2 id=\"key-takeaways\">اہم نکات</h2>\n<ul>\n<li>ریشو اسپریڈ ایک آپشن خریدتا ہے اور ایک ہی قسم میں سے دو کو بیچتا ہے، کریڈٹ کے لیے کھولتا ہے اور فروخت ہونے والی ہڑتال پر بالکل ٹھیک پہنچ جاتا ہے۔</li>\n<li>دی <strong>کال تناسب پھیلاؤ</strong> جمع کرتا ہے <strong>20,430 روپے</strong>، پر چوٹیوں <strong>26,930 روپے</strong> 24,150 پر، 24,564 پر بھی ٹوٹ جاتا ہے، اور پھر ایک لے جاتا ہے۔ <strong>لامحدود</strong> ننگی اضافی کال سے اوپر کا نقصان۔</li>\n<li>دی <strong>تناسب پھیلاؤ ڈالو</strong> جمع کرتا ہے <strong>14,170 روپے</strong>، پر چوٹیوں <strong>20,670 روپے</strong> 23,950 پر، 23,632 پر بھی ٹوٹ جاتا ہے، اور ننگے اضافی پوٹ سے نیچے ایک بہت بڑا منفی نقصان اٹھاتا ہے۔</li>\n<li>دونوں ایک پہنتے ہیں۔ <strong>منافع کا زیادہ امکان</strong>، 72 اور 68 فیصد، کیونکہ خطرہ صرف ایک بڑی حرکت کے بعد شروع ہوتا ہے، لیکن جیت کی شرح ایک غیر منقطع دم کے ساتھ بیٹھتی ہے، لہذا کریڈٹ کے حساب سے کبھی بھی سائز نہ کریں۔</li>\n<li>بھاری <strong>مارجن</strong> 1.7 لاکھ روپے کے قریب ننگی ٹانگ کی قیمت کا تبادلہ ہے۔ تناسب کا پھیلاؤ بیک اسپریڈ کے برعکس ہے: خالص مختصر، کریڈٹ، اور مضبوط اقدام پر خطرناک۔</li>\n<li>دونوں میں تعمیر کریں۔ <strong>سینڈ باکس ٹریڈنگ ( OpenAlgo میں تجزیہ کار موڈ)</strong>، پھر ماڈل شدہ قیمت کو بریک ایون سے باہر گھسیٹیں اور ایکسپائری لائن کو بغیر فرش کے گرتے دیکھیں۔ وہ نظارہ ننگی دم کا پورا سبق ہے۔</li>\n</ul>\n","toc":[{"level":2,"text":"ایک لائن کا خیال","id":"the-one-line-idea"},{"level":2,"text":"اصل تجارت، روپیہ بہ روپیہ","id":"the-real-trade-rupee-by-rupee"},{"level":2,"text":"تین نمبر، اور وہ کہاں سے آتے ہیں۔","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"میعاد ختم ہونے پر نتائج پر چلنا","id":"walking-the-outcomes-at-expiry"},{"level":2,"text":"آپ کی مشکلات","id":"your-odds"},{"level":2,"text":"مارجن اور مارجن پر واپسی","id":"margin-and-return-on-margin"},{"level":2,"text":"وقت کا زوال","id":"time-decay"},{"level":2,"text":"ڈال تناسب پھیل گیا","id":"the-put-ratio-spread"},{"level":2,"text":"تناسب کا پھیلاؤ بیک اسپریڈ سے کیسے مختلف ہے۔","id":"how-a-ratio-spread-differs-from-a-back-spread"},{"level":2,"text":"اہم نکات","id":"key-takeaways"}],"imgCount":2,"hasContent":true},"18":{"html":"<p>جس تناسب سے آپ ابھی ملے ہیں اس نے ایک فراخدلی کریڈٹ اکٹھا کیا لیکن ایک دم کو ننگا اور بے نقاب چھوڑ دیا۔ کیا ہوگا اگر آپ اس کا تقریباً سارا کریڈٹ اپنے پاس رکھ سکتے ہیں اور پھر بھی ایک دم کو مکمل طور پر مٹا سکتے ہیں، تاکہ پوری سمت آپ کو تکلیف نہ دے؟ اس کے پیچھے یہی چال ہے۔ <strong>جیڈ چھپکلی</strong> اور اس کا آئینہ، <strong>ریورس جیڈ چھپکلی</strong>. ہر ایک فروخت شدہ اختیارات کے جوڑے میں ایک سستا خریدا ہوا ونگ شامل کرتا ہے، اس طرح ترتیب دیا گیا ہے کہ آپ جو کریڈٹ جمع کرتے ہیں وہ صرف اس پھیلاؤ سے زیادہ ہے جو کھو سکتا ہے۔ جب کریڈٹ اس پھیلاؤ سے بڑا ہوتا ہے، تو چارٹ کا ایک پورا حصہ کبھی بھی صفر سے نیچے نہیں جا سکتا۔ یہ اس کورس کے سب سے خوبصورت خیالات میں سے ایک ہے، اور ایک بار جب آپ اسے دیکھ لیں گے تو آپ اسے کبھی نہیں دیکھ پائیں گے۔</p>\n<h2 id=\"the-one-line-idea\">ایک لائن کا خیال</h2>\n<p>اے <strong>جیڈ چھپکلی</strong> آمدنی کے لیے ایک پوٹ فروخت کرتا ہے، زیادہ آمدنی کے لیے کال فروخت کرتا ہے، اور الٹا باڑ لگانے کے لیے ایک اور کال خریدتا ہے۔ جمع کیا گیا کریڈٹ جان بوجھ کر اس کال اسپریڈ کی چوڑائی سے بڑا ہے، اس لیے اس سے کوئی فرق نہیں پڑتا ہے کہ کتنا ہی اونچا NIFTY چڑھ جائے، بند کال کا نقصان پہلے سے بنک کی گئی رقم سے کم ہے۔ الٹا کھو نہیں سکتا۔ خطرہ صرف ایک طرف رہتا ہے، جس طرف آپ کو حقیقت میں نظر آتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>جیڈ چھپکلی کا دستخط اس کے محفوظ پھیلاؤ کی چوڑائی سے بڑا کریڈٹ ہوتا ہے۔ جب یہ برقرار رہتا ہے، تو وہ پوری طرف نہیں ہار سکتا: خریدا ہوا بازو نقصان کو پورا کرتا ہے، اور جو کریڈٹ آپ نے بینک کیا ہے وہ کیپ سے بڑا ہے۔ آپ کو صرف ایک ہی سمت پر خطرہ لاحق ہے، دونوں پر نہیں۔</p>\n</div></div>\n<h2 id=\"the-real-trade-rupee-by-rupee\">اصل تجارت، روپیہ بہ روپیہ</h2>\n<p>یہاں ہے <strong>جیڈ چھپکلی</strong> حقیقی NIFTY قیمتوں پر، 26 جون 2026 کو انڈیکس کے ساتھ <strong>24,056</strong> اور 28 جولائی 2026 کو ختم ہونے میں تقریباً 32 دن باقی ہیں۔ آپ پیسے کے نیچے 23,950 کو فروخت کرتے ہیں، اس کے اوپر 24,150 کال فروخت کرتے ہیں، اور 24,250 کال کو ونگ کے طور پر خریدتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>ڈال فروخت</td>\n<td>23,950</td>\n<td>256.6 موصول ہوا۔</td>\n<td>علاوہ 16,679 روپے میں</td>\n</tr>\n<tr>\n<td>2</td>\n<td>کال فروخت کریں۔</td>\n<td>24,150</td>\n<td>370.1 موصول ہوا۔</td>\n<td>علاوہ 24,057 روپے میں</td>\n</tr>\n<tr>\n<td>3</td>\n<td>کال خریدیں۔</td>\n<td>24,250</td>\n<td>316.1 ادا کیا گیا۔</td>\n<td>20,557 روپے باہر</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>نیٹ کریڈٹ</strong></td>\n<td><strong>علاوہ 20,179 روپے میں</strong></td>\n</tr>\n</tbody></table>\n<p>فروخت ہونے والے دونوں آپشنز ان کے درمیان 40,736 روپے لاتے ہیں، اور خریدی گئی 24,250 کال کی قیمت 20,557 روپے ہے، <strong>20,179 روپے کا خالص کریڈٹ</strong>. وہ کریڈٹ بھی آپ کا ہے۔ <strong>زیادہ سے زیادہ منافع</strong>23,950 سے 24,150 تک فروخت ہونے والی ہڑتالوں کے درمیان جب بھی NIFTY ختم ہوتا ہے، مکمل طور پر رکھا جاتا ہے، جہاں تینوں اختیارات کی میعاد ختم ہوجاتی ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-jade-lizard.png\" alt=\"NIFTY جیڈ چھپکلی: درمیان میں 20,179 روپے کا فلیٹ زیادہ سے زیادہ منافع، ایک دائیں طرف جو منافع میں رہتا ہے اس سے کوئی فرق نہیں پڑتا ہے کہ کتنا ہی اونچا NIFTY چڑھتا ہے کیونکہ کریڈٹ کال اسپریڈ کو کور کرتا ہے، اور 23,640 پر سنگل ڈاون سائڈ بریک ایون جہاں ننگے شارٹ پٹ کاٹنا شروع ہوتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY جیڈ چھپکلی: درمیان میں 20,179 روپے کا فلیٹ زیادہ سے زیادہ منافع، ایک دائیں طرف جو منافع میں رہتا ہے اس سے کوئی فرق نہیں پڑتا ہے کہ کتنا ہی اونچا NIFTY چڑھتا ہے کیونکہ کریڈٹ کال اسپریڈ کو کور کرتا ہے، اور 23,640 پر سنگل ڈاون سائڈ بریک ایون جہاں ننگے شارٹ پٹ کاٹنا شروع ہوتا ہے۔</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">تین نمبر، اور وہ کہاں سے آتے ہیں۔</h2>\n<p><strong>زیادہ سے زیادہ منافع خالص کریڈٹ ہے، 20,179 روپے۔</strong> کہیں بھی 23,950 سے 24,150 تک تینوں آپشنز بے کار ہو جاتے ہیں اور آپ پورا کریڈٹ اپنے پاس رکھتے ہیں۔</p>\n<p><strong>کوئی الٹا خطرہ بالکل نہیں ہے۔</strong> ٹانگیں 2 اور 3 ایک ریچھ کی کال بناتی ہیں جو صرف ایک سو پوائنٹس چوڑائی میں 24,150 سے 24,250 تک پھیلی ہوئی ہیں، جس کا سب سے زیادہ نقصان سو گنا 65 ہے، جو کہ 6500 روپے ہے۔ لیکن آپ نے 20,179 روپے اکٹھے کیے جو کہ 6,500 روپے سے کہیں زیادہ ہے۔ تو یہاں تک کہ اگر NIFTY راکٹ دور ہوتا ہے، کال پھیل جاتی ہے جب کہ آپ کا کریڈٹ اس سے زیادہ احاطہ کرتا ہے، اور آپ پھر بھی تقریباً 20,179 مائنس 6,500 کے ساتھ چلے جاتے ہیں، جو کہ 13,679 روپے ہے۔ چارٹ کا پورا دائیں جانب سبز رہتا ہے۔</p>\n<p><strong>زیادہ سے زیادہ نقصان صرف منفی پہلو پر ہوتا ہے، اور بریک ایون 23,640 ہے۔</strong> فروخت ہونے والا 23,950 پوٹ ننگا ہے۔ کریڈٹ کی قیمت تقریباً 310 پوائنٹس فی شیئر ہے، اس لیے NIFTY پوٹ اسٹرائیک سے 310 پوائنٹس نیچے گر سکتا ہے۔ <strong>23,640</strong>اس سے پہلے کہ نقصان پورا کریڈٹ کھا لے۔ اس کے نیچے نقصان ایک بہت بڑے اعداد و شمار کی طرف بڑھتا ہے، اگر انڈیکس صفر کی طرف گرتا ہے تو تقریباً 15.4 لاکھ روپے درج ہوتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>خالص کریڈٹ</td>\n<td>20,179 روپے</td>\n</tr>\n<tr>\n<td>الٹا</td>\n<td>کریڈٹ مائنس کال اسپریڈ چوڑائی</td>\n<td>20,179 روپے مائنس 6,500 روپے = منافع، کوئی خطرہ نہیں۔</td>\n</tr>\n<tr>\n<td>بریک ایون</td>\n<td>سٹرائیک مائنس کریڈٹ فی شیئر ڈالیں۔</td>\n<td>23,950 منفی 310 = 23,640</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-outcomes-at-expiry\">میعاد ختم ہونے پر نتائج پر چلنا</h2>\n<p>پانچ اختتامی قیمتوں پر تجارت طے کریں۔ ایک پوٹ کی قیمت زیادہ سے زیادہ ہے (اسٹرائیک مائنس NIFTY، 0) اور کال کی قیمت زیادہ سے زیادہ ہے (NIFTY مائنس اسٹرائیک، 0) فی شیئر، نیٹ فی لاٹ 65 کے ساتھ۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>مختصر 23,950 PE (آپ پر واجب ہے)</th>\n<th>مختصر 24,150 CE (آپ پر واجب ہے)</th>\n<th>لمبا 24,250 CE (آپ کے مالک ہیں)</th>\n<th>نیٹ پی اینڈ ایل فی لاٹ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,400</td>\n<td>550</td>\n<td>0</td>\n<td>0</td>\n<td>مائنس 15,571 روپے (منفی نقصان)</td>\n</tr>\n<tr>\n<td>23,640</td>\n<td>310</td>\n<td>0</td>\n<td>0</td>\n<td>تقریباً 0 روپے (ڈاؤن سائیڈ بریک ایون)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>0</td>\n<td>0</td>\n<td>0</td>\n<td>علاوہ 20,179 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,150</td>\n<td>0</td>\n<td>0</td>\n<td>0</td>\n<td>علاوہ 20,179 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,450</td>\n<td>0</td>\n<td>300</td>\n<td>200</td>\n<td>پلس 13,679 روپے (الٹا کیپڈ، پھر بھی منافع)</td>\n</tr>\n</tbody></table>\n<p>نیچے پڑھیں اور جادو نیچے کی قطار میں ہے۔ یہاں تک کہ NIFTY اوپر فروخت ہونے والی ہڑتال سے 300 پوائنٹس کے اوپر، آپ پھر بھی 13,679 روپے کا بینک کرتے ہیں، کیونکہ خریدی گئی 24,250 کال کال پھیل جاتی ہے اور کریڈٹ اس کا احاطہ کرتا ہے۔ کھونے کا واحد طریقہ 23,640 سے نیچے گرنا ہے، جہاں ننگے ڈالتے ہیں۔ ایک دم کو آسانی سے مٹا دیا گیا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک جیڈ چھپکلی اب بھی ننگے شارٹ پٹ کو اٹھائے رکھتی ہے، اس لیے اس کا نقصان بہت بڑا ہے، اگر NIFTY صفر کی طرف گر گیا تو تقریباً 15.4 لاکھ روپے درج ہے۔ کوئی الٹا خطرہ نہیں ہے، لیکن بائیں دم اصلی ہے۔ ایک بار جب NIFTY 23,640 کے بریک ایون سے نیچے آجاتا ہے تو آپ کو اس کے گرنے والے ہر پوائنٹ کے لیے 65 روپے کا نقصان ہوتا ہے، یہی وجہ ہے کہ ایکسچینج تقریباً 1.71 لاکھ روپے کے مارجن کو روکتا ہے۔ جیڈ چھپکلی کو غیرجانبدار کریڈٹ ٹریڈ کے لیے تیزی کے طور پر سمجھو جس کا دفاع کرنے کے لیے سنگین منفی پہلو ہے، نہ کہ مفت لنچ۔</p>\n</div></div>\n<h2 id=\"your-odds\">آپ کی مشکلات</h2>\n<p>دی <strong>منافع کا امکان 68 فیصد ہے۔</strong>. NIFTY 23,640 بریک ایون کے اوپر کہیں بھی بیٹھ سکتا ہے اور آپ سبز رنگ میں ختم کرتے ہیں، جو کہ ایک چوڑا کشن ہے، اور پورا الٹا منافع ہوتا ہے چاہے یہ کتنی ہی دور چلے۔ چارٹ نچلے سگما بینڈ کے نیچے بیٹھے ہوئے بریک ایون کو دکھاتا ہے، لہذا صرف وہی نتیجہ جو ہارتا ہے وہ نیچے کی طرف حقیقی وقفہ ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>بہت بڑے نقصان کے الفاظ کے آگے نفع کا 68 فیصد امکان پڑھیں۔ جیڈ چھپکلی زیادہ تر وقت جیتتی ہے اور الٹا پریشانی کو مکمل طور پر دور کر دیتی ہے، لیکن زندہ بچ جانے والا منفی پہلو ننگا ہوتا ہے۔ ایک سازگار جیت کی شرح صرف نصف تجارت ہے۔ جیڈ چھپکلی صرف اس وقت رکھیں جب آپ کے پاس شارٹ پٹ کا دفاع کرنے یا بند کرنے کا منصوبہ ہو اگر NIFTY ٹوٹنا شروع ہو جائے، اور اسے اس طرح سائز دیں کہ اس طرف ایک خراب خلا اکاؤنٹ کو تباہ نہ کر سکے۔</p>\n</div></div>\n<h2 id=\"margin-and-return-on-margin\">مارجن اور مارجن پر واپسی</h2>\n<p>چونکہ شارٹ پٹ ننگا ہے، ایکسچینج ایک بھاری کو روکتا ہے۔ <strong>تقریباً 1,70,750 روپے کا مارجن</strong>. خریدی گئی کال الٹا خطرے کو سکڑ کر کچھ بھی نہیں کرتی ہے لیکن پوٹ کے لیے کچھ نہیں کرتی، اس لیے مارجن بڑا رہتا ہے، اس ایک کھلی دم کو لے جانے کی نقد قیمت۔</p>\n<p>پر <strong>مارجن پر واپسی</strong>20,179 روپے کا کریڈٹ 1,70,750 روپے بلاک ہو گیا ہے۔ <strong>12 فیصد</strong> مہینے کے دوران اگر NIFTY بریک ایون سے اوپر رکھتا ہے۔ یہ ایک حقیقی پیداوار ہے، لیکن یہ ایک غیر متعینہ منفی پہلو پر سوار ہے، لہذا اس کا فیصلہ خطرے سے کریں، سرخی سے نہیں۔</p>\n<h2 id=\"time-decay\">وقت کا زوال</h2>\n<p>جیڈ چھپکلی ایک خالص فروخت کنندہ ہے، جو 20,179 روپے پریمیم اکٹھا کرتا ہے، اس لیے وقت کی کمی آپ کے لیے کام کرتی ہے۔ دی <strong>نیلی ڈیشڈ T+0 لائن</strong> بیچ میں اورنج ایٹ-ایکسپائری پرافٹ شیلف کے نیچے بیٹھتا ہے، اور ہر پرسکون دن پوزیشن کو اوپر لے جاتا ہے کیونکہ فروخت ہونے والے اختیارات پگھل جاتے ہیں۔ وقت آپ کے ساتھ ہے جب تک کہ NIFTY 23,640 سے اوپر ہے۔ اس کے نیچے، کشی مدد کرنا بند کر دیتی ہے اور برہنہ پوٹ اپنے اوپر لے جاتا ہے۔</p>\n<h2 id=\"the-reverse-jade-lizard\">ریورس جیڈ چھپکلی</h2>\n<p>دی <strong>ریورس جیڈ چھپکلی</strong> اس کی بجائے منفی پہلو کو مٹانے کے لیے ڈھانچے کو پلٹتا ہے۔ آپ پیسے کے اوپر ایک کال بیچتے ہیں، اس کے نیچے ایک پوٹ بیچتے ہیں، اور منفی پہلو کو باڑ کرنے کے لیے مزید پوٹ خریدتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>کال فروخت کریں۔</td>\n<td>24,150</td>\n<td>370.1 موصول ہوا۔</td>\n<td>علاوہ 24,057 روپے میں</td>\n</tr>\n<tr>\n<td>2</td>\n<td>ڈال فروخت</td>\n<td>23,950</td>\n<td>256.6 موصول ہوا۔</td>\n<td>علاوہ 16,679 روپے میں</td>\n</tr>\n<tr>\n<td>3</td>\n<td>ڈال خریدیں</td>\n<td>23,850</td>\n<td>224.1 ادا کیا گیا۔</td>\n<td>14,570 روپے باہر</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>نیٹ کریڈٹ</strong></td>\n<td><strong>علاوہ 26,166 روپے میں</strong></td>\n</tr>\n</tbody></table>\n<p>فروخت ہونے والے دو اختیارات 40,736 روپے میں لاتے ہیں، خریدے گئے 23,850 پوٹ کی قیمت 14,570 روپے ہے، اور پوزیشن ایک کے لئے کھلتی ہے۔ <strong>26,166 روپے کا خالص کریڈٹ</strong>، زیادہ سے زیادہ منافع بھی، جو 23,950 اور 24,150 کے درمیان رکھا گیا ہے۔ اس بار ٹانگیں 2 اور 3 ایک بیل پوٹ کی شکل میں 23,950 سے 23,850 تک ایک سو پوائنٹس تک پھیلی ہوئی ہیں، جس کا سب سے زیادہ نقصان 6,500 روپے ہے۔ آپ کا 26,166 روپے کا کریڈٹ بونا ہو جاتا ہے، اس لیے کریش ہونے سے تھوڑا سا نقصان ہو جاتا ہے جو کریڈٹ آسانی سے پورا کر لیتا ہے، جس سے آپ کو تقریباً 19,666 روپے رہ جاتے ہیں۔ یہی وجہ ہے کہ ریورس جیڈ چھپکلی ہے۔ <strong>کوئی منفی خطرہ نہیں</strong>. ننگی طرف اب الٹا ہے، فروخت 24,150 کال، ایک سنگل کے ساتھ <strong>24,553 پر بریک ایون</strong>.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-reverse-jade-lizard.png\" alt=\"NIFTY ریورس جیڈ چھپکلی: درمیان میں 26,166 روپے کا فلیٹ زیادہ سے زیادہ منافع، ایک بائیں جانب جو منافع میں رہتا ہے اس سے کوئی فرق نہیں پڑتا ہے کہ NIFTY کتنی ہی دور گرے کیونکہ کریڈٹ پوٹ اسپریڈ کو کور کرتا ہے، اور 24,553 پر سنگل اپ سائڈ بریک ایون جہاں ننگی شارٹ کال بغیر کسی حد کے چلتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY ریورس جیڈ چھپکلی: درمیان میں 26,166 روپے کا فلیٹ زیادہ سے زیادہ منافع، ایک بائیں جانب جو منافع میں رہتا ہے اس سے کوئی فرق نہیں پڑتا ہے کہ NIFTY کتنا ہی گر جائے کیونکہ کریڈٹ پوٹ اسپریڈ کو کور کرتا ہے، اور 24,553 پر سنگل اپ سائڈ بریک ایون جہاں ننگی شارٹ کال بغیر کسی حد کے چلتی ہے۔</figcaption></figure>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>مختصر 24,150 CE (آپ پر واجب ہے)</th>\n<th>مختصر 23,950 PE (آپ پر واجب ہے)</th>\n<th>لمبا 23,850 PE (آپ کے مالک ہیں)</th>\n<th>نیٹ پی اینڈ ایل فی لاٹ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,600</td>\n<td>0</td>\n<td>350</td>\n<td>250</td>\n<td>پلس 19,666 روپے (کمی ہوئی، پھر بھی منافع)</td>\n</tr>\n<tr>\n<td>23,950</td>\n<td>0</td>\n<td>0</td>\n<td>0</td>\n<td>جمع 26,166 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,150</td>\n<td>0</td>\n<td>0</td>\n<td>0</td>\n<td>جمع 26,166 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,553</td>\n<td>403</td>\n<td>0</td>\n<td>0</td>\n<td>تقریباً 0 روپے (الٹا بریک ایون)</td>\n</tr>\n<tr>\n<td>24,750</td>\n<td>600</td>\n<td>0</td>\n<td>0</td>\n<td>مائنس 12,834 روپے (نقصان حد کے بغیر بڑھتا ہے)</td>\n</tr>\n</tbody></table>\n<p>سب سے اوپر کی قطار جیڈ چھپکلی کے جادو کو ریورس میں آئینہ دار کرتی ہے: یہاں تک کہ 133X0 کم فروخت ہونے والی اسٹرائیک سے 350 پوائنٹس کے نیچے، آپ اب بھی 19,666 روپے بنک کرتے ہیں، کیونکہ خریدی گئی 23,850 پوٹ کیپس دی پوٹ اسپریڈ۔ دی <strong>منافع کا امکان 72 فیصد ہے۔</strong>، اور مارجن تقریباً 1,76,758 روپے ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک ریورس جیڈ چھپکلی کا زیادہ سے زیادہ نقصان ہوتا ہے جو لامحدود ہوتا ہے۔ فروخت ہونے والی 24,150 کال کو اس کے اوپر کوئی تحفظ حاصل نہیں ہے، اس لیے ایک بار جب NIFTY 24,553 کے بریک ایون سے گزر جاتا ہے تو آپ کو بغیر کسی حد کے 65 روپے ایک پوائنٹ کا نقصان ہوتا ہے، یہی وجہ ہے کہ ایکسچینج تقریباً 1.77 لاکھ روپے کے مارجن کو روکتا ہے۔ منفی پہلو مکمل طور پر احاطہ کرتا ہے، لیکن یہاں پر مندی سے لے کر غیر جانبدار جھکاؤ ریلی میں ایک حقیقی غیر کیپڈ دم کے ساتھ آتا ہے۔ مختصر کال کرنے سے پہلے اس کا دفاع کرنے کا منصوبہ بنائیں۔</p>\n</div></div>\n<h2 id=\"why-the-credit-erases-a-tail\">کریڈٹ ایک دم کو کیوں مٹاتا ہے۔</h2>\n<p>دونوں ڈھانچے ریاضی کے ایک ٹکڑے پر قائم ہیں جو صاف طور پر کہنے کے قابل ہیں۔ محفوظ سائیڈ پر آپ ایک اسپریڈ کو ایک سو پوائنٹس چوڑا رکھتے ہیں، اور سب سے زیادہ ایک سو پوائنٹ اسپریڈ 6,500 روپے کھو سکتے ہیں۔ اگر آپ نے جو کریڈٹ اکٹھا کیا ہے وہ 6,500 روپے سے زیادہ ہے، تو اس طرف بھی بدترین صورت آپ کو منافع میں چھوڑ دیتی ہے۔ کریڈٹ پورے پھیلاؤ کے نقصان کو جذب کر لیتا ہے اور پھر بھی رقم باقی ہے۔</p>\n<p>یہی سارا راز ہے۔ آپ مہنگا دور تحفظ نہیں خرید رہے ہیں۔ آپ ایک رچ بیچنے والے آپشن سے پریمیم کا استعمال دوسری طرف چھوٹے اسپریڈ کی ادائیگی سے زیادہ کرنے کے لیے کر رہے ہیں، صرف ایک سمت میں خطرے کے ساتھ ادائیگی چھوڑ کر۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>جیڈ چھپکلی غیر جانبدار سے تیز ہوتی ہے: یہ تب پیسہ کماتی ہے جب NIFTY دائیں جانب بلٹ پروف اور دفاع کے لیے صرف گرنے کے ساتھ، اوپر کو پکڑے یا اوپر چلی جاتی ہے۔ ریورس جیڈ چھپکلی بیئرش سے نیوٹرل ہوتی ہے: جب NIFTY کو نرم کرتا ہے یا اسے تھامتا ہے، بائیں جانب بلٹ پروف اور دفاع کے لیے صرف ایک ریلی کے ساتھ فائدہ ہوتا ہے۔ اس کا انتخاب کریں جس کی ننگی دم آپ کے حقیقی نقطہ نظر سے دور ہو، لہذا آپ جس طرف سے ڈرتے ہیں وہ پہلو ہے جو آپ کو نقصان نہیں پہنچا سکتا۔</p>\n</div></div>\n<h2 id=\"key-takeaways\">اہم نکات</h2>\n<ul>\n<li>ایک جیڈ چھپکلی ایک پوٹ اور ایک کال بیچتی ہے اور ایک اور کال خریدتی ہے، کال پھیلنے کی چوڑائی سے بڑا کریڈٹ اکٹھا کرتی ہے، اس لیے <strong>الٹا کھو نہیں سکتا</strong>.</li>\n<li>یہ جمع کرتا ہے۔ <strong>20,179 روپے</strong> (اس کا زیادہ سے زیادہ منافع)، مکمل کریڈٹ 23,950 اور 24,150 کے درمیان رکھتا ہے، اور صرف نیچے کے منفی پہلو کو خطرہ لاحق ہے۔ <strong>23,640 بریک ایون</strong>، جہاں ننگے شارٹ پوٹ کاٹتے ہیں۔</li>\n<li>الٹی جیڈ چھپکلی اسے پلٹتی ہے: a <strong>26,166 روپے</strong> کریڈٹ منفی پہلو کو مکمل طور پر مٹا دیتا ہے، ایک چھوڑ کر <strong>لامحدود</strong> کے اوپر الٹا دم <strong>24,553 بریک ایون</strong>.</li>\n<li>دونوں میں 68 اور 72 فیصد منافع کا زیادہ امکان ہوتا ہے، کیونکہ ایک پوری دم ہٹا دی جاتی ہے، لیکن بچ جانے والی دم ننگی ہے اور اس کے بارے میں مطالبہ کرتی ہے۔ <strong>مارجن کے 1.7 لاکھ روپے</strong>.</li>\n<li>اس ڈھانچے کا انتخاب کریں جس کی ننگی دم آپ کے نقطہ نظر سے دور ہو: جیڈ چھپکلی جب آپ ہلکے سے تیزی سے جھکتے ہیں، جب آپ ہلکے سے بیئرش کی طرف جھکتے ہیں تو الٹ۔</li>\n<li>دونوں کو اندر بنائیں <strong>سینڈ باکس ٹریڈنگ ( OpenAlgo میں تجزیہ کار موڈ)</strong>قیمت کو محفوظ سائیڈ کی طرف گھسیٹیں اور دیکھیں کہ لائن وہاں کبھی سرخ نہیں ہوتی ہے، پھر اسے ننگی طرف کی طرف گھسیٹ کر دیکھیں کہ نقصان کہاں سے شروع ہوتا ہے۔</li>\n</ul>\n","toc":[{"level":2,"text":"ایک لائن کا خیال","id":"the-one-line-idea"},{"level":2,"text":"اصل تجارت، روپیہ بہ روپیہ","id":"the-real-trade-rupee-by-rupee"},{"level":2,"text":"تین نمبر، اور وہ کہاں سے آتے ہیں۔","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"میعاد ختم ہونے پر نتائج پر چلنا","id":"walking-the-outcomes-at-expiry"},{"level":2,"text":"آپ کی مشکلات","id":"your-odds"},{"level":2,"text":"مارجن اور مارجن پر واپسی","id":"margin-and-return-on-margin"},{"level":2,"text":"وقت کا زوال","id":"time-decay"},{"level":2,"text":"ریورس جیڈ چھپکلی","id":"the-reverse-jade-lizard"},{"level":2,"text":"کریڈٹ ایک دم کو کیوں مٹاتا ہے۔","id":"why-the-credit-erases-a-tail"},{"level":2,"text":"اہم نکات","id":"key-takeaways"}],"imgCount":2,"hasContent":true},"19":{"html":"<p>ہر ڈھانچہ نے اب تک ایک ہی شکل، ایک خیمہ، ایک شیلف، یا ایک وادی کھینچی ہے۔ یہ باب ان میں سے دو کو ایک ہی چارٹ پر رکھتا ہے۔ ایک ادائیگی لینے والی تصویر جس کو آپ پہلے سے جانتے ہیں، اس کی کاپی کرتے ہوئے، اور کاپی کو قیمت کے محور کے ساتھ اس وقت تک سلائیڈ کرتے ہیں جب تک کہ خاکہ ایک کے بجائے دو الگ الگ ہمپس نہ بڑھ جائے۔ اس کے پیچھے بھی یہی راز ہے۔ <strong>بیٹ مین</strong>, the <strong>ڈبل مکھی</strong>، اور <strong>ڈبل کنڈور</strong>. ہر ایک دو رینج ڈھانچے کو ساتھ ساتھ رکھتا ہے اور شرط لگاتا ہے کہ NIFTY کسی ایک پوائنٹ کی بجائے دو زونوں میں سے کسی ایک کے اندر آباد ہو۔ وہ اسکرین پر خوفناک نظر آتے ہیں، پھر بھی ہر ایک صرف دو مانوس ٹکڑے ہیں جو ایک خاکہ بانٹ رہے ہیں۔</p>\n<h2 id=\"the-one-line-idea\">ایک لائن کا خیال</h2>\n<p>تینوں ایک ہی سوال کا جواب دیتے ہیں: اگر آپ ایک ہی پن کے بجائے جڑواں چوٹی یا وسیع تر منافع کا علاقہ چاہتے ہیں تو کیا ہوگا؟ اے <strong>بیٹ مین</strong> پیسے کے نیچے ایک پوٹ ریشو ونگ کو اس کے اوپر کال ریشو ونگ پر لگاتا ہے، ان کے درمیان پرسکون ڈپ کے ساتھ دو اونچی چوٹیوں کو بڑھاتا ہے۔ اے <strong>ڈبل مکھی</strong> دو تتلیوں کو ساتھ ساتھ رکھتا ہے، اور a <strong>ڈبل کنڈور</strong> دو کنڈورس ساتھ ساتھ رکھتا ہے، ہر ایک جڑواں منافع والے زون دیتا ہے جس کے درمیان میں نقصان کی وادی ہوتی ہے۔ بیٹ مین آپ کو خالص کریڈٹ دیتا ہے لیکن ہر سرے پر ایک ننگی دم چھپاتا ہے۔ ڈبل فلائی اور ڈبل کنڈور مکمل طور پر خطرے سے دوچار ہیں، آپ کے داخل ہونے سے پہلے ٹکٹ پر بدترین کیس پرنٹ کیا جاتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>بیٹ مین، ڈبل فلائی، اور ڈبل کنڈور ہر ایک جگہ پر دو رینج ڈھانچے ساتھ ساتھ رکھتے ہیں، اس لیے ادائیگی ایک کے بجائے دو منافع کے زون میں بڑھ جاتی ہے۔ بیٹ مین ایک وسیع، زیادہ امکان والا کریڈٹ ٹریڈ ہے جس کے دونوں سروں پر ننگی دم ہوتی ہے۔ ڈبل فلائی اور ڈبل کنڈور سستے، متعین خطرے والے شرط ہیں جو NIFTY کسی بھی طرح سے ایک اعتدال پسند اقدام کرتے ہیں اور دو زونوں میں سے ایک کے اندر اترتے ہیں۔</p>\n</div></div>\n<h2 id=\"the-batman-leg-by-leg\">بیٹ مین، ٹانگ بہ ٹانگ</h2>\n<p>بیٹ مین اپنا نام اس کی خاکہ سے لیتا ہے، پیسے کے دونوں طرف دو چوٹیاں اٹھتی ہیں جیسے کاؤل کے کان، ان کے درمیان ڈبکی ہوتی ہے۔ آپ اسے 28 جولائی 2026 کی میعاد ختم ہونے پر دو تناسب والے پنکھوں سے بناتے ہیں، پیسے کے نیچے ایک پوٹ ونگ اور اس کے اوپر کال ونگ۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>قسم</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>1 خریدیں۔</td>\n<td>23,550</td>\n<td>ڈالو</td>\n</tr>\n<tr>\n<td>2</td>\n<td>2 فروخت کریں۔</td>\n<td>23,300</td>\n<td>ڈالو</td>\n</tr>\n<tr>\n<td>3</td>\n<td>1 خریدیں۔</td>\n<td>24,550</td>\n<td>کال کریں۔</td>\n</tr>\n<tr>\n<td>4</td>\n<td>2 فروخت کریں۔</td>\n<td>24,800</td>\n<td>کال کریں۔</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td><strong>نیٹ کریڈٹ</strong></td>\n<td><strong>تقریباً 5,941 روپے</strong></td>\n</tr>\n</tbody></table>\n<p>فروخت ہونے والے دو جوڑے دونوں خریدی ہوئی ٹانگوں کی قیمت سے زیادہ پریمیم لاتے ہیں، لہذا بیٹ مین تقریباً 5,941 روپے کے خالص کریڈٹ کے لیے کھلتا ہے۔ ڈیپ ونگ اسٹرائیکس 23,300 اور 24,800 اسنیپ شاٹ کے مرکزی سٹرائیکس سے آگے بیٹھتے ہیں، اس لیے ہم ہر ڈیپ پریمیم کے بجائے ڈھانچے اور اس کے خالص کریڈٹ کا حوالہ دیتے ہیں۔ ہر بازو ایک تناسب فرنٹ اسپریڈ ہے، لمبا ایک آپشن اور مختصر دو آگے، اور ہر ایک اپنی چوٹی بناتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-batman.png\" alt=\"NIFTY بیٹ مین: پیسے کے دونوں طرف 22,191 روپے تک پہنچنے والے جڑواں منافع کی چوٹی، جگہ کے ارد گرد 5,941 روپے کا کریڈٹ رکھنے والا ایک پرسکون ڈِپ، اور 22,959 اور 25,141 پر بریک ایونز جس سے آگے ننگے تناسب کی دمیں بغیر کسی بڑی منزل کے نیچے بھاگتی ہیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY بیٹ مین: پیسے کے دونوں طرف 22,191 روپے تک پہنچنے والے جڑواں منافع کی چوٹییں، جگہ کے ارد گرد 5,941 روپے کا کریڈٹ رکھنے والا ایک پرسکون ڈپ، اور 22,959 اور 25,141 پر بریک ایون جس سے آگے ننگے تناسب کی دمیں بغیر کسی بڑی منزل کے نیچے بھاگتی ہیں۔</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">تین نمبر، اور وہ کہاں سے آتے ہیں۔</h2>\n<p>بیٹ مین کے ہیڈ لائن نمبر سبھی سیدھے اس کے دو پروں سے گر جاتے ہیں، یاد رکھنے کی ضرورت نہیں ہے۔</p>\n<p><strong>زیادہ سے زیادہ منافع یا تو مختصر ہڑتال پر پہنچتا ہے، 22,191 روپے۔</strong> کال سائیڈ لے لو۔ اگر NIFTY 24,800 پر ختم ہو جاتی ہے، تو آپ کی لمبی 24,550 کال 250 پوائنٹس کی ہوتی ہے جب کہ مختصر 24,800 دونوں کالیں بے کار ہیں۔ ان 250 پوائنٹس کی قیمت 250 گنا 65 ہے، جو کہ 16,250 روپے ہے، اور آپ اب بھی 5,941 روپے کا کریڈٹ رکھتے ہیں۔ اس لیے چوٹی 16,250 جمع 5,941 ہے، جو 22,191 روپے کے برابر ہے۔ پوٹ ونگ بالکل اسی 22,191 روپے میں 23,300 پر پہنچ گیا۔</p>\n<p><strong>بریک وینز ننگی دم سے آتے ہیں۔</strong> 24,800 سے اوپر آپ ایک کال کے لیے مختصر ہیں، لہذا 22,191 روپے کی چوٹی ہر پوائنٹ زیادہ کے لیے 65 روپے پر پگھل جاتی ہے۔ 22,191 کو 65 سے تقسیم کرنے سے تقریباً 341 پوائنٹس ملتے ہیں، لہذا اوپری بریک ایون 24،800 جمع 341 ہے، جو کہ 25،141 ہے۔ نچلا بریک ایون اس کا آئینہ دار ہے، 23,300 مائنس 341، جو 22,959 ہے۔ ماضی میں سے کسی بھی نقطہ پر نقصان چلتا رہتا ہے، جس کے اوپر کوئی چھت نہیں اور نیچے ایک بہت بڑی منزل۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>کریڈٹ پلس 250 پوائنٹ ونگ کیپچر</td>\n<td>5,941 روپے جمع 16,250 روپے 22,191 روپے کے برابر</td>\n</tr>\n<tr>\n<td>اپر بریک ایون</td>\n<td>مختصر کال ہڑتال کے علاوہ پوائنٹس کی چوٹی</td>\n<td>24,800 جمع 341 برابر 25,141</td>\n</tr>\n<tr>\n<td>لوئر بریک ایون</td>\n<td>پوائنٹس میں شارٹ پٹ اسٹرائیک مائنس چوٹی</td>\n<td>23,300 مائنس 341 برابر 22,959</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>ننگی دم، کوئی چھت نہیں۔</td>\n<td>لا محدود</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-outcomes-at-expiry\">میعاد ختم ہونے پر نتائج پر چلنا</h2>\n<p>بیٹ مین کو بند ہونے والی قیمتوں کے پھیلاؤ پر طے کریں اور جڑواں چوٹی والی شکل خود ہی ظاہر ہوتی ہے۔ ہر قطار فی لاٹ 65 ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>پنکھ کیا کرتے ہیں۔</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>22,800</td>\n<td>دم چلائیں</td>\n<td>مائنس 10,309 روپے، اور گر رہا ہے۔</td>\n</tr>\n<tr>\n<td>22,959</td>\n<td>کم بریک ایون</td>\n<td>تقریباً 0 روپے</td>\n</tr>\n<tr>\n<td>23,300</td>\n<td>ونگ چوٹی رکھو</td>\n<td>جمع 22,191 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,056</td>\n<td>خاموش وسط</td>\n<td>علاوہ 5,941 روپے (کریڈٹ)</td>\n</tr>\n<tr>\n<td>24,800</td>\n<td>کال ونگ چوٹی</td>\n<td>جمع 22,191 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>25,141</td>\n<td>اوپری بریک ایون</td>\n<td>تقریباً 0 روپے</td>\n</tr>\n<tr>\n<td>25,400</td>\n<td>کال ٹیل چل رہی ہے۔</td>\n<td>مائنس 16,809 روپے، اور بڑھتی ہوئی</td>\n</tr>\n</tbody></table>\n<p>اسے درمیان سے پڑھیں۔ جگہ کے آس پاس پوزیشن صرف اپنا 5,941 روپے کا کریڈٹ رکھتی ہے، دونوں کانوں کے درمیان ڈپ۔ یا تو مختصر ہڑتال کی طرف بڑھیں اور ایک بازو ادائیگی کو اس کے 22,191 روپے کی چوٹی پر لے جائے گا۔ ایک بریک ایون سے آگے بڑھیں اور ننگی دم پر قبضہ ہو گیا، نقصان 25,141 سے اوپر اور 22,959 سے نیچے کی ایک بہت بڑی تعداد کی طرف بڑھ رہا ہے۔</p>\n<h2 id=\"your-odds\">آپ کی مشکلات</h2>\n<p>بیٹ مین کا <strong>منافع کا امکان تقریباً 78 فیصد ہے۔</strong>کورس کے اس حصے میں سب سے زیادہ کریڈٹ ٹریڈ مشکلات۔ یہ نمبر براہ راست بریک وینز کے درمیان چوڑائی سے آتا ہے۔ NIFTY کی تقریباً 12.7 فیصد مضمر اتار چڑھاؤ اور باقی 32 دن کا استعمال کرتے ہوئے، مارکیٹ انڈیکس پر 22,959 اور 25,141 کے درمیان ختم ہونے کا تقریباً 78 فیصد امکان رکھتا ہے، اور وہ پورا بینڈ منافع ہے۔ چارٹ پر دھندلے سگما بینڈ بریک وینز کے اندر اچھی طرح بیٹھتے ہیں، یہی وجہ ہے کہ مشکلات اتنی زیادہ ہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اس کے ساتھ زیادہ سے زیادہ نقصان کو پڑھے بغیر 78 فیصد کو کبھی نہ پڑھیں۔ بیٹ مین پانچ میں سے تقریباً چار بار جیتتا ہے، لیکن ایک ہارنے والا وقت الٹا کھلا ہوا ہوتا ہے، جہاں برہنہ کالوں کی کوئی چھت نہیں ہوتی، اور نیچے کی طرف بہت بڑی ہوتی ہے، جہاں برہنہ پوٹس صفر پر فرش کی طرف بھاگتے ہیں۔ نقصان سے منسلک منافع کا ایک اعلی امکان جو اختیارات میں سب سے زیادہ موہک اور خطرناک شکل ہے۔ اس کا سائز اس اقدام سے بنائیں جس سے تکلیف پہنچے، نہ کہ اس کی ادائیگی کتنی بار ہوتی ہے۔</p>\n</div></div>\n<h2 id=\"margin-the-heaviest-in-the-course\">مارجن، کورس میں سب سے بھاری</h2>\n<p>کیونکہ بیٹ مین دو ننگے چھوٹے جوڑے رکھتا ہے، اس لیے تبادلہ روکتا ہے۔ <strong>مارجن کے 209,721 روپے</strong>, اس کورس میں کہیں بھی سب سے بڑی مانگ ہے، جس میں کوئی حفاظتی دور کا بازو نہیں ہے جس طرح اس کو ایک متعین پھیلاؤ کی طرح سکڑنا ہے۔ اس مارجن کے مقابلے میں ماپنے پر، 5,941 روپے کا پرسکون درمیانی کریڈٹ 3 فیصد سے کم کی پیداوار ہے، اور یہاں تک کہ ایک مختصر ہڑتال پر ایک بہترین پن، 22,191 روپے کی چوٹی، صرف 11 فیصد ہے۔ برہنہ اختیارات کے ساتھ خریدا گیا وسیع وِن زون کبھی بھی سستا نہیں ہوتا۔</p>\n<h2 id=\"time-decay\">وقت کا زوال</h2>\n<p>بیٹ مین ایک خالص کریڈٹ ٹریڈ ہے، لہذا پرسکون دن آپ کے راستے پر جھک جاتے ہیں۔ جوں جوں معیاد ختم ہونے کے قریب ہوتے ہیں اضافی اختیارات آپ کے لمبے ہونے کے مقابلے میں تیزی سے کم ہوتے جاتے ہیں، اگر NIFTY ایک مختصر ہڑتال کی طرف بڑھتا ہے تو ادائیگی کو چوٹی کی طرف جھکاؤ دیتے ہیں۔ نیلے رنگ کی T+0 لائن چارٹ کے وسط میں اورنج ایٹ-ایکسپائری لائن کے نیچے بیٹھتی ہے، اس پوزیشن کا دستخط جو وقت آہستہ آہستہ انعام دیتا ہے، جب تک قیمت پنکھوں کے اندر رہتی ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک بیٹ مین کو مؤثر طریقے سے لامحدود زیادہ سے زیادہ نقصان ہوتا ہے۔ یہ اوپر برہنہ ہے، اضافی فروخت کی گئی 24,800 کالوں کے ذریعے، اور نیچے برہنہ ہے، اضافی فروخت کی گئی 23,300 پوٹس کے ذریعے۔ 25,141 کے اوپری بریک ایون سے گزرتے ہوئے نقصان کسی ریلی میں بغیر کسی حد کے چڑھ جاتا ہے، اس لیے الٹا واقعی لامحدود ہے۔ 22,959 کے نچلے بریک ایون سے گزر کر یہ گرنے پر ایک بہت بڑی شخصیت کی طرف گہرا ہوتا ہے، صرف انڈیکس کے صفر تک پہنچنے سے۔ منافع کا 78 فیصد امکان وسیع پرسکون بینڈ کو بیان کرتا ہے، نہ کہ کسی بھی دم کے سائز کو۔ یہ ایک پیشہ ور کی حد کی تجارت ہے، نہ کہ کسی ابتدائی کا پہلا کریڈٹ، اور اسے کبھی بھی کسی تقریب میں برہنہ نہیں ہونا چاہیے۔</p>\n</div></div>\n<h2 id=\"the-double-fly\">ڈبل فلائی</h2>\n<p>ڈبل فلائی مکمل طور پر متعین خطرے کے لیے بیٹ مین کی ننگی دموں کا کاروبار کرتی ہے۔ یہ دو تتلیوں کو ساتھ ساتھ سیٹ کرتا ہے، ایک 23,650 کے قریب پیسے کے نیچے اور ایک اس کے اوپر 24,450 کے قریب، لہذا موجودہ قیمت پر ایک خیمے کے بجائے آپ کو دو خیمے ملیں گے جس کے درمیان ایک وادی ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>جزو</th>\n<th>منافع کا علاقہ</th>\n<th>قریب چوٹی</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>نچلی تتلی</td>\n<td>23,495 سے 23,805</td>\n<td>23,650</td>\n</tr>\n<tr>\n<td>اوپری تتلی</td>\n<td>24,295 سے 24,605 ​​تک</td>\n<td>24,450</td>\n</tr>\n</tbody></table>\n<p>چار <strong>breakevens، 23,495, 23,805, 24,295 اور 24,605</strong>دو خیموں کے کناروں کو نشان زد کریں۔ آپ کو نچلے خیمے کے اندر اور اوپر کے خیمے کے اندر فائدہ ہوتا ہے۔ آپ اپنا سب سے زیادہ نقصان یا تو مرکزی وادی میں جگہ کے آس پاس یا دونوں خیموں کے باہر لے جاتے ہیں، جہاں ہر لمبا بازو پہلے ہی نقصان کو پورا کر چکا ہے۔ دی <strong>زیادہ سے زیادہ منافع 10,072 روپے ہے۔</strong> ایک چوٹی پر، اور کیونکہ ہر ٹانگ متوازن ہے اور دور کے پروں کو خریدا جاتا ہے۔ <strong>زیادہ سے زیادہ نقصان صرف 2,928 روپے ہے۔</strong>, داخل کرنے کے لیے آپ جو چھوٹا خالص ڈیبٹ ادا کرتے ہیں اور اس تجارت میں آپ کو سب سے زیادہ لاگت آ سکتی ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>میٹرک</th>\n<th>قدر</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>10,072 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>2,928 روپے</td>\n</tr>\n<tr>\n<td>Breakevens</td>\n<td>23,495 / 23,805 / 24,295 / 24,605</td>\n</tr>\n<tr>\n<td>منافع کا امکان</td>\n<td>تقریبا 24 فیصد</td>\n</tr>\n<tr>\n<td>انعام کا خطرہ</td>\n<td>1 : 3.4</td>\n</tr>\n<tr>\n<td>خطرے میں خالص قیمت</td>\n<td>تقریباً 2,928 روپے</td>\n</tr>\n<tr>\n<td>مارجن درکار ہے۔</td>\n<td>130,313 روپے</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-double-fly.png\" alt=\"NIFTY ڈبل فلائی: دو منافع والے خیمے، ایک چوٹی 23,650 کے قریب اور ایک 24,450 کے قریب، جگہ کے آس پاس نقصان کی وادی سے الگ، 23,495، 23,805، 24,295 اور 24,605 ​​پر چار بریک ایونز کے ساتھ اور صرف 298 روپے کا نقصان۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY ڈبل فلائی: دو منافع خیمے، ایک چوٹی 23,650 کے قریب اور ایک 24,450 کے قریب، جگہ کے ارد گرد نقصان کی وادی سے الگ، 23,495، 23,805، 24,295 اور 24,605 ​​پر چار بریک ایونز کے ساتھ اور صرف 298 روپے کا نقصان۔</figcaption></figure>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>ایک ڈبل فلائی اس وقت منافع بخش ہوتی ہے جب NIFTY کسی بھی طرح سے ایک اعتدال پسند حرکت کرتا ہے اور دو خیموں میں سے کسی ایک کے اندر اترتا ہے، اور اگر قیمت مرکزی وادی میں بیٹھی رہتی ہے یا بیرونی پروں سے بہت آگے چلتی ہے تو اسے نقصان ہوتا ہے۔ یہ 10,072 روپے کے انعام کے مقابلے میں 2,928 روپے کے متعین نقصان کو جوڑتا ہے، ایک صاف 1 سے 3.4 ادائیگی، لیکن منافع کا 24 فیصد امکان کیچ کے بارے میں ایماندار ہے: NIFTY کو جیتنے کے لیے کافی تنگ زون میں اترنا ہوگا۔</p>\n</div></div>\n<h2 id=\"the-double-condor\">ڈبل کنڈور</h2>\n<p>ڈبل کنڈور فلیٹ ٹاپس والی ڈبل فلائی ہے۔ یہ دو کنڈورس ساتھ ساتھ رکھتا ہے، ایک پیسے کے بالکل نیچے اور دوسرا اوپر، لہذا ہر منافع کا زون تیز چوٹی کے بجائے ایک چھوٹا سطح مرتفع ہے۔ اس وسیع میٹھی جگہ کے لیے تجارت ایک چھوٹا انعام ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>جزو</th>\n<th>منافع کا علاقہ</th>\n<th>مرکز کے قریب</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>لوئر کنڈور</td>\n<td>23,807 سے 23,991 تک</td>\n<td>23,899</td>\n</tr>\n<tr>\n<td>اپر کنڈور</td>\n<td>24,107 سے 24,291 تک</td>\n<td>24,199</td>\n</tr>\n</tbody></table>\n<p>چار <strong>breakevens، 23,807, 23,991, 24,107 اور 24,291</strong>، ڈبل مکھی کے مقابلے میں پیسے کے قریب بیٹھو، لہذا یہ ڈھانچہ ایک چھوٹی حرکت چاہتا ہے۔ آپ کو نچلی میز پر 23,807 سے 23,991 تک اور اوپری میز پر 24,107 سے 24,291 تک منافع ہوتا ہے، اور آپ تنگ وسطی وادی میں 24,050 کے آس پاس یا بیرونی کناروں سے آگے ہار جاتے ہیں۔ دی <strong>زیادہ سے زیادہ منافع 2,675 روپے ہے۔</strong> اور <strong>زیادہ سے زیادہ نقصان صرف 575 روپے ہے۔</strong>, تینوں میں سے سب سے سستا برا کیس اور اس چھوٹے ڈیبٹ کے برابر جو آپ ادا کرتے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>میٹرک</th>\n<th>قدر</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>2,675 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>575 روپے</td>\n</tr>\n<tr>\n<td>Breakevens</td>\n<td>23,807 / 23,991 / 24,107 / 24,291</td>\n</tr>\n<tr>\n<td>منافع کا امکان</td>\n<td>تقریبا 16 فیصد</td>\n</tr>\n<tr>\n<td>انعام کا خطرہ</td>\n<td>1 : 4.6</td>\n</tr>\n<tr>\n<td>خالص ڈیبٹ</td>\n<td>575 روپے</td>\n</tr>\n<tr>\n<td>مارجن درکار ہے۔</td>\n<td>127,183 روپے</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-double-condor.png\" alt=\"NIFTY ڈبل کنڈور: دو فلیٹ ٹاپ پرافٹ ٹیبلز، ایک 23,900 کے قریب اور ایک 24,200 کے قریب، اسپاٹ کے آس پاس نقصان کی وادی سے الگ، چار بریک ایونز کے ساتھ اور صرف 575 روپے کا ایک چھوٹا بیان کردہ بدترین نقصان۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY ڈبل کنڈور: دو فلیٹ ٹاپڈ پرافٹ ٹیبل، ایک 23,900 کے قریب اور ایک 24,200 کے قریب، جگہ کے ارد گرد نقصان کی وادی سے الگ، چار بریک ایونز کے ساتھ اور صرف 575 روپے کا ایک چھوٹا بیان کردہ بدترین نقصان۔</figcaption></figure>\n<h2 id=\"how-the-three-compare\">تینوں کا موازنہ کیسے کریں؟</h2>\n<table>\n<thead>\n<tr>\n<th>حکمت عملی</th>\n<th>زیادہ سے زیادہ منافع</th>\n<th>زیادہ سے زیادہ نقصان</th>\n<th>منافع کا امکان</th>\n<th>خطرہ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>بیٹ مین</td>\n<td>22,191 روپے</td>\n<td>لا محدود</td>\n<td>78 فیصد</td>\n<td>دونوں طرف ننگے</td>\n</tr>\n<tr>\n<td>ڈبل فلائی</td>\n<td>10,072 روپے</td>\n<td>2,928 روپے</td>\n<td>24 فیصد</td>\n<td>تعریف</td>\n</tr>\n<tr>\n<td>ڈبل کنڈور</td>\n<td>2,675 روپے</td>\n<td>575 روپے</td>\n<td>16 فیصد</td>\n<td>تعریف</td>\n</tr>\n</tbody></table>\n<p>تینوں دو کیمپوں میں بٹ گئے۔ دی <strong>بیٹ مین</strong> ایک اعلی امکانی کریڈٹ ٹریڈ ہے جو ایک بہت بڑی رینج میں جیتتا ہے لیکن دونوں طرف ننگی دم چھپاتا ہے اور کورس میں سب سے زیادہ مارجن۔ دی <strong>ڈبل مکھی</strong> اور <strong>ڈبل کنڈور</strong> کسی بھی طرح سے اعتدال پسند اقدام پر پوری طرح سے طے شدہ خطرے کی شرطیں ہیں، صرف 2,928 روپے اور 575 روپے کے بدترین کیسز کے ساتھ، لیکن کم مشکلات، کیونکہ قیمت ادا کرنے کے لیے کافی سخت زون میں ہونا ضروری ہے۔ نوٹ کریں کہ انعام اور مشکلات کا کاروبار کیسے ہوتا ہے: بیٹ مین اپنی 78 فیصد جیت کی شرح کو ننگی دم بیچ کر خریدتا ہے، جب کہ ڈبل کنڈور کی 1 سے 4.6 تک کی ادائیگی صرف 16 فیصد مشکلات پر آتی ہے۔ کوئی مفت دوپہر کا کھانا نہیں ہے، صرف ننگا خطرہ یا چھوٹا، کم امکان انعام ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>ایک ابتدائی کے لیے، ڈبل فلائی اور ڈبل کنڈور اس خاندان کے محفوظ افراد ہیں۔ ان کی سب سے بری صورت ٹکٹ پر چھپی ہوئی ہے، چند ہزار روپے یا اس سے کم، اور وہ آپ کو سکھاتے ہیں کہ اسٹیک شدہ ڈھانچے آپ کو بھاگے ہوئے نقصان کا سامنا کیے بغیر کیسے برتاؤ کرتے ہیں۔ بیٹ مین کو اس وقت تک چھوڑ دیں جب تک کہ آپ ایک ہی وقت میں دونوں طرف سے ننگے اختیارات کا دفاع کرنے میں مکمل طور پر آرام سے نہ ہوں، اور کبھی بھی اس کی جڑواں دموں کو بغیر کسی ہچکچاہٹ کے دوران نہ لے جائیں۔</p>\n</div></div>\n<p>آپ تینوں کو سینڈ باکس ٹریڈنگ میں بنا سکتے ہیں ( OpenAlgo میں تجزیہ کرنے والا موڈ) اور ماڈل کی گئی قیمت کو ایک خیمے میں اور باہر گھسیٹ کر وادی میں لے جا سکتے ہیں تاکہ یہ محسوس کیا جا سکے کہ ہر ڈھانچہ کہاں جیتتا اور ہارتا ہے، اور بیٹ مین پر، ننگی دم کو سنبھالتے ہوئے دیکھنے کے لیے ایک بازو سے گزر کر۔ اس کے بعد ہم ان ایکسپائری ڈے ڈھانچے سے تجارت کی طرف بڑھتے ہیں جو خود وقت کے ساتھ کام کرتے ہیں، کیلنڈر اور ڈائیگنل اسپریڈز۔</p>\n<h2 id=\"key-takeaways\">اہم نکات</h2>\n<ul>\n<li>بیٹ مین، ڈبل فلائی، اور ڈبل کنڈور ہر جگہ <strong>دو رینج ڈھانچے ساتھ ساتھ</strong>, ایک کے بجائے دو منافع والے زون بڑھ رہے ہیں۔</li>\n<li>دی <strong>بیٹ مین</strong> 5,941 روپے کے کریڈٹ کے لیے کھلتا ہے، شارٹ سٹرائیک پر 22,191 روپے تک پہنچ جاتا ہے، اور ایک وسیع بینڈ میں جیت جاتا ہے۔ <strong>78 فیصد مشکلات</strong>، لیکن اس کا نقصان ہے <strong>لامحدود</strong> دونوں طرف ننگی دموں کے ذریعے۔</li>\n<li>اس کی ٹوٹ پھوٹ، <strong>22,959 اور 25,141</strong>شارٹ سٹرائیکس سے سیدھے پوائنٹس میں چوٹی پلس یا مائنس کریں، اور ان سے گزر کر نقصان دور ہو جاتا ہے۔</li>\n<li>دی <strong>ڈبل مکھی</strong> خطرے کی وضاحت کی گئی ہے: زیادہ سے زیادہ منافع 10,072 روپے، زیادہ سے زیادہ نقصان صرف 2,928 روپے، چار بریک ایونز، 24 فیصد مشکلات پر 1 سے 3.4 ادائیگی۔</li>\n<li>دی <strong>ڈبل کنڈور</strong> سب سے سستا اور فلیٹ ہے: زیادہ سے زیادہ منافع 2,675 روپے، زیادہ سے زیادہ نقصان صرف 575 روپے، وسیع ترین جڑواں میزیں لیکن سب سے کم مشکلات 16 فیصد۔</li>\n<li>beginners کے ساتھ رہنا چاہئے <strong>متعین خطرے کی جوڑی</strong> اور بیٹ مین کو ایک پیشہ ور کے آلے کے طور پر پیش کریں، جس کا سائز ہمیشہ اس اقدام سے ہوتا ہے جس سے تکلیف پہنچے، کبھی بھی جمع کردہ کریڈٹ سے نہیں۔</li>\n</ul>\n","toc":[{"level":2,"text":"ایک لائن کا خیال","id":"the-one-line-idea"},{"level":2,"text":"بیٹ مین، ٹانگ بہ ٹانگ","id":"the-batman-leg-by-leg"},{"level":2,"text":"تین نمبر، اور وہ کہاں سے آتے ہیں۔","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"میعاد ختم ہونے پر نتائج پر چلنا","id":"walking-the-outcomes-at-expiry"},{"level":2,"text":"آپ کی مشکلات","id":"your-odds"},{"level":2,"text":"مارجن، کورس میں سب سے بھاری","id":"margin-the-heaviest-in-the-course"},{"level":2,"text":"وقت کا زوال","id":"time-decay"},{"level":2,"text":"ڈبل فلائی","id":"the-double-fly"},{"level":2,"text":"ڈبل کنڈور","id":"the-double-condor"},{"level":2,"text":"تینوں کا موازنہ کیسے کریں؟","id":"how-the-three-compare"},{"level":2,"text":"اہم نکات","id":"key-takeaways"}],"imgCount":3,"hasContent":true},"20":{"html":"<p>آپ نے اب تک جو بھی حکمت عملی حاصل کی ہے وہ سمت یا حرکت کے سائز پر شرط لگاتی ہے۔ کیلنڈر مختلف ہیں۔ وہ وقت پر ہی شرط لگاتے ہیں۔ اے <strong>کیلنڈر پھیلاؤ</strong> قریب کی میعاد ختم ہونے پر ایک آپشن فروخت کرتا ہے اور بعد میں ایکسپائری میں اسی قسم کا آپشن خریدتا ہے، ایک سادہ سی حقیقت سے اپنا پیسہ کماتا ہے: قریب کا آپشن دور کے مہینے سے زیادہ تیزی سے اپنی ٹائم ویلیو کھو دیتا ہے۔ اگر NIFTY اسٹرائیک کے قریب خاموشی سے بیٹھتا ہے جبکہ اگلی ٹانگ پگھل جاتی ہے، تو پچھلی ٹانگ آپ کے پاس اب بھی اپنی زیادہ تر قیمت رکھتی ہے، اور دونوں کے درمیان فرق آپ کا منافع ہے۔ یہ باب 26 جون 2026 کو کیپچر کیے گئے حقیقی NIFTY آپشن ڈیٹا، اسپاٹ 24,056، لاٹ 65، 28 جولائی 2026 کو ختم ہونے کے قریب اور 25 اگست 2026 کو ختم ہونے والے وقت کے ٹریڈز کو تیار کرتا ہے۔</p>\n<h2 id=\"the-one-line-idea-sell-the-near-own-the-far\">ون لائن آئیڈیا: قریب کو بیچیں، دور کی ملکیت کریں۔</h2>\n<p>وقت کی قدر کسی اختیار سے یکساں طور پر نہیں نکلتی ہے۔ جب میعاد ختم ہونے کا وقت بہت دور ہوتا ہے تو یہ آہستہ آہستہ نکلتا ہے، پھر جیسے جیسے آخری دن قریب آتے ہیں تیزی سے۔ 28 جولائی کا آپشن اور 25 اگست کا آپشن دونوں آج وقت کی قدر رکھتے ہیں، لیکن اگلے مہینے میں جولائی والا اپنا تقریباً تمام حصہ کھو دیتا ہے جب کہ ایک اگست، جس میں ابھی ایک تازہ مہینہ باقی ہے، بمشکل نوٹس لے رہا ہے۔ ایک کیلنڈر اس فرق کو حاصل کرتا ہے۔ آپ <strong>قریب مہینے کی ٹانگ فروخت کریں۔</strong> اور <strong>دور مہینے کی ٹانگ خریدیں</strong> اسی ہڑتال پر، اور چونکہ پچھلے مہینے کے آپشن پر ہمیشہ زیادہ لاگت آتی ہے، اس لیے آپ تھوڑی سی ادائیگی کرتے ہیں۔ <strong>خالص ڈیبٹ</strong> تجارت پر ڈالنے کے لئے.</p>\n<p>اب دیکھیں چارٹ کیا کھینچتا ہے۔ اورنج \"ایٹ ایکسپائری\" لائن پر پلاٹ کی گئی ہے۔ <strong>ختم ہونے کے قریب</strong>جس لمحے آپ کی فروخت شدہ جولائی ٹانگ مر جائے گی۔ اگر NIFTY 28 جولائی کو ہڑتال کے قریب بیٹھتا ہے، تو اگلی ٹانگ بے کار ہو جاتی ہے اور آپ اس کا پریمیم برقرار رکھتے ہیں، جب کہ پچھلی ٹانگ کے پاس آپ کی زندگی کا ایک پورا مہینہ ہے اور اس لیے وقت کی قدر کا ایک صحت مند حصہ ہے۔ مردہ اگلی ٹانگ اور زندہ پچھلی ٹانگ کے درمیان پھیلاؤ کی قیمت آپ کے ادا کردہ ڈیبٹ سے زیادہ ہے، اور یہ اضافی آپ کا فائدہ ہے۔ اسے ہر بند قیمت پر پلاٹ کریں اور آپ کو ایک ملے گا۔ <strong>خیمہ</strong>, دونوں طرف سے نیچے ڈھلوان ہڑتال پر ایک چوٹی.</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک کیلنڈر پھیلاؤ طویل وقت ہے. آپ اپنے بیچے گئے قریب کے مہینے کے آپشن کی تیزی سے زوال جمع کرتے ہیں اور آپ کے پاس موجود دور کے مہینے کے آپشن کے سست ہونے کی ادائیگی کرتے ہیں۔ یہ سب سے زیادہ پیسہ کماتا ہے جب NIFTY قریب ختم ہونے پر سٹرائیک ختم ہو جاتا ہے، جہاں اگلی ٹانگ بیکار مر جاتی ہے اور پچھلی ٹانگ زیادہ سے زیادہ وقت کی قدر رکھتی ہے۔ کسی بھی راستے سے بہت دور چلے جاتے ہیں اور دونوں ٹانگیں ایک ساتھ اپنی وقت کی قدر کھو دیتی ہیں، خیمہ گر جاتا ہے، اور آپ اپنے ادا کردہ ڈیبٹ کے قریب سے محروم ہوجاتے ہیں۔</p>\n</div></div>\n<h2 id=\"the-call-calendar-rupee-by-rupee\">کال کیلنڈر، روپیہ بہ روپیہ</h2>\n<p>سادہ ترین ورژن پیسے کی ہڑتال پر دو کالوں کا استعمال کرتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ختم</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>1 فروخت کریں۔</td>\n<td>28 جولائی 2026</td>\n<td>24,050 کال کریں۔</td>\n<td>425.8 موصول ہوا۔</td>\n<td>علاوہ 27,677 روپے میں</td>\n</tr>\n<tr>\n<td>2</td>\n<td>1 خریدیں۔</td>\n<td>25 اگست 2026</td>\n<td>24,050 کال کریں۔</td>\n<td>627.8 ادا کیا گیا۔</td>\n<td>40,807 روپے باہر</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>خالص ڈیبٹ</strong></td>\n<td><strong>13,130 روپے باہر</strong></td>\n</tr>\n</tbody></table>\n<p>دور کی کال کی قیمت قریب کی کال سے 202 پوائنٹس فی شیئر زیادہ ہے، اس لیے آپ ایک ادائیگی کرتے ہیں۔ <strong>13,130 روپے کا خالص ڈیبٹ</strong>جو کہ 202 گنا 65 اور آپ کا زیادہ سے زیادہ حصہ ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-call-calendar.png\" alt=\"NIFTY کال کیلنڈر، 28 جولائی 24,050 کال کی فروخت اور 25 اگست 24,050 کال خرید رہا ہے۔ اورنج ایٹ-ایکسپائری لائن 24,050 سٹرائیک کے قریب ایک خیمہ بناتی ہے، جہاں 14,480 روپے کا زیادہ سے زیادہ منافع بیٹھتا ہے، جو 23,495 اور 24,634 پر نیچے کی طرف جھک جاتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY کال کیلنڈر، 28 جولائی 24,050 کال کی فروخت اور 25 اگست 24,050 کال خرید رہا ہے۔ اورنج ایٹ-ایکسپائری لائن 24,050 سٹرائیک کے قریب ایک خیمہ بناتی ہے، جہاں 14,480 روپے کا زیادہ سے زیادہ منافع بیٹھتا ہے، جو 23,495 اور 24,634 پر نیچے کی طرف جھک جاتا ہے۔</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">تین نمبر، اور وہ کہاں سے آتے ہیں۔</h2>\n<p><strong>ہڑتال پر زیادہ سے زیادہ منافع 14,480 روپے ہے۔</strong> جب NIFTY 28 جولائی کو 24,050 پر ختم ہو جاتا ہے، تو آپ کی فروخت کردہ جولائی کال کی میعاد بے کار ہو جاتی ہے جب کہ آپ کی اگست کی کال ابھی بھی پورے مہینے کی وقت کی قدر رکھتی ہے۔ آپ نے جو ڈیبٹ ادا کیا اس پر اس زندہ پچھلی ٹانگ کا سرپلس سب سے زیادہ ہے، 14,480 روپے۔</p>\n<p><strong>زیادہ سے زیادہ نقصان 13,090 روپے ہے، ہڑتال سے بہت دور۔</strong> NIFTY کو کسی بھی سمت میں ایک لمبا راستہ دھکیلتا ہے اور دونوں کالیں تقریباً اپنی تمام وقتی قدر کھو دیتی ہیں، اس لیے دو ایک ہی سٹرائیک کالوں کے درمیان پھیلاؤ صفر کی طرف گر جاتا ہے اور آپ پورے ڈیبٹ کے قریب سے محروم ہوجاتے ہیں۔ یہ پورے 13,130 روپے کے بجائے صرف 13,090 روپے ہے کیونکہ پچھلے مہینے کی کال قریب قریب ختم ہونے پر کبھی بھی صفر کی قدر تک نہیں پہنچتی ہے۔</p>\n<p><strong>Breakevens 23,495 اور 24,634 ہیں۔</strong>, وہ دو قیمتیں جہاں خیمہ صفر کو عبور کرتا ہے، اس بینڈ کو بناتا ہے جس کے اندر کیلنڈر پیسہ کماتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>پچھلے مہینے کے وقت کی قدر باقی ہے، ڈیبٹ کو کم کر کے</td>\n<td>14,480 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>ڈیبٹ، پچھلے مہینے کی قدر سے کم</td>\n<td>13,090 روپے</td>\n</tr>\n<tr>\n<td>Breakevens</td>\n<td>جہاں خیمہ صفر کو عبور کرتا ہے، ہڑتال کے ارد گرد</td>\n<td>23,495 / 24,634</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-outcomes-at-the-near-expiry\">قریب کی میعاد ختم ہونے پر نتائج پر چلنا</h2>\n<p>کال کیلنڈر کو 28 جولائی کو پانچ اختتامی قیمتوں پر طے کریں، فی لاٹ 65۔ فروخت ہونے والی جولائی کی کال عین اندرونی قیمت پر طے ہوتی ہے، لیکن اگست کی کال آپ کے پاس اب بھی زندگی کا ایک مہینہ ہے، لہذا اس کی قیمت یہاں ہے۔ <strong>ماڈلنگ اور تخمینی</strong>.</p>\n<table>\n<thead>\n<tr>\n<th>28 جولائی کوNIFTY</th>\n<th>24,050 کال آپ نے فروخت کی۔</th>\n<th>24,050 کال آپ کے پاس اب بھی ہے (تقریبا)</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>23,200</td>\n<td>بیکار ختم</td>\n<td>پتلی، تھوڑا وقت کی قدر باقی ہے۔</td>\n<td>تقریباً مائنس 13,090 روپے (زیادہ سے زیادہ نقصان کے قریب)</td>\n</tr>\n<tr>\n<td>23,495</td>\n<td>بیکار ختم</td>\n<td>معمولی قدر رکھتا ہے۔</td>\n<td>تقریباً 0 روپے (کم بریک ایون)</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>بیکار ختم</td>\n<td>ابھی بھی امیر، زندگی کا ایک مہینہ باقی ہے۔</td>\n<td>جمع 14,480 روپے (زیادہ سے زیادہ منافع)</td>\n</tr>\n<tr>\n<td>24,634</td>\n<td>آپ کے خلاف 584 کی قیمت</td>\n<td>گہرا، لیکن پھیلاؤ پتلا ہے۔</td>\n<td>تقریباً 0 روپے (اوپر بریک ایون)</td>\n</tr>\n<tr>\n<td>25,100</td>\n<td>آپ کے خلاف 1,050 کی قیمت</td>\n<td>گہری، تھوڑی اضافی وقت کی قیمت</td>\n<td>تقریباً مائنس 13,090 روپے (زیادہ سے زیادہ نقصان کے قریب)</td>\n</tr>\n</tbody></table>\n<p>ٹیبل میں خیمہ پڑھیں۔ ہڑتال کے عین موقع پر آپ پورے 14,480 روپے اکٹھے کرتے ہیں، جہاں مردہ اگلی ٹانگ اور زندہ پچھلی ٹانگ سب سے زیادہ دور ہوتی ہے۔ کسی بھی سمت سے ہٹ جائیں اور بریک ایونز پر فائدہ سکڑ کر صفر ہو جاتا ہے، پھر 13,090 روپے کے زیادہ سے زیادہ نقصان کی طرف گرتا رہتا ہے کیونکہ دونوں کالیں ایک ساتھ اپنی ٹائم ویلیو کھو دیتی ہیں۔ یہ منظر نامہ جدول قریب قریب ایکسپائری پر بنایا گیا ہے، جس لمحے کیلنڈر کے ارد گرد ڈیزائن کیا گیا ہے۔</p>\n<h2 id=\"your-odds-margin-and-return\">آپ کی مشکلات، مارجن، اور واپسی۔</h2>\n<p>کال کیلنڈر کا <strong>منافع کا امکان تقریباً 47 فیصد ہے۔</strong>. NIFTY کی تقریباً 12.7 فیصد مضمر اتار چڑھاؤ اور 32 دن کی میعاد ختم ہونے کے قریب کا استعمال کرتے ہوئے، مارکیٹ انڈیکس کو 28 جولائی تک 23,495 سے 24,634 بینڈ کے اندر مکمل ہونے کا ایک چھوٹا سا موقع فراہم کرتی ہے۔</p>\n<p>چونکہ آپ دور مہینے کی ٹانگ کے مالک ہیں، اس لیے ایک کیلنڈر خطرے سے دوچار ہے اور اس کا مارجن معمولی ہے، تقریباً <strong>58,373 روپے</strong>,لاکھوں سے بہت نیچے ایک ننگا شارٹ مانگے گا۔ اس مارجن کے مقابلے میں ماپا گیا، 14,480 روپے کی چوٹی تقریباً 25 فیصد کی واپسی ہے اگر اسٹرائیک کو پن کیا جاتا ہے، ایک ماہ کی صحت مند پیداوار، حالانکہ اس بہترین کیس کو 24,050 پر ختم ہونے کے لیے NIFTY کی ضرورت ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>ایک کیلنڈر ساکن کھڑے ہو کر جیتتا ہے، لہذا اس کا اندازہ اس بات سے لگائیں کہ اس کا منافع بینڈ کتنا وسیع ہے اس کے مقابلے میں NIFTY ایک مہینے میں کس حد تک گھومنے کا رجحان رکھتا ہے۔ 23,495 سے 24,634 کے بینڈ میں 47 فیصد موقع آپ کو بتاتا ہے کہ یہ تجارت حقیقی طور پر پرسکون مہینہ چاہتی ہے۔ اگر آپ حرکت کی توقع کرتے ہیں تو کیلنڈر غلط ٹول ہے چاہے خیمہ کتنا ہی دلکش کیوں نہ ہو۔</p>\n</div></div>\n<h2 id=\"time-decay-is-the-whole-point\">وقت کی زوال پوری بات ہے۔</h2>\n<p>اس کورس میں ہر دوسری ڈیبٹ تجارت کے لیے، وقت کا زوال دشمن ہے۔ کیلنڈر پلٹ جاتا ہے۔ آپ کے پاس تیزی سے زوال پذیر ہونے والے قریب کے مہینے کے آپشن کو مختصر ہے اور سست گرنے والا دور مہینہ طویل ہے، اس لیے ہر پرسکون دن آپ کی بیچی ہوئی اگلی ٹانگ آپ کی اپنی پچھلی ٹانگ سے زیادہ تیزی سے قیمت کھو دیتی ہے، اور یہ فرق آپ کے حق میں بڑھ جاتا ہے۔ نیلی T+0 لائن سٹرائیک کے قریب نارنجی ٹینٹ کے نیچے بیٹھتی ہے، اور جیسے جیسے میعاد ختم ہوتی ہے پوزیشن اس نارنجی چوٹی کی طرف بڑھ جاتی ہے۔ کیلنڈر یہاں ایک ایسا ڈھانچہ ہے جو وقت گزرنے کے ساتھ ادا کیا جاتا ہے۔</p>\n<h2 id=\"the-put-calendar\">پوٹ کیلنڈر</h2>\n<p>ایک ہی سٹرائیک پر پوٹس کے لیے دونوں کالز کو تبدیل کریں اور آپ کو پوٹ کیلنڈر مل جائے گا۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ختم</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>1 فروخت کریں۔</td>\n<td>28 جولائی 2026</td>\n<td>24,050 ڈال دیا</td>\n<td>295.1 موصول ہوا۔</td>\n</tr>\n<tr>\n<td>2</td>\n<td>1 خریدیں۔</td>\n<td>25 اگست 2026</td>\n<td>24,050 ڈال دیا</td>\n<td>384.6 ادا کیا گیا۔</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>خالص ڈیبٹ</strong></td>\n<td><strong>5,818 روپے باہر</strong></td>\n</tr>\n</tbody></table>\n<table>\n<thead>\n<tr>\n<th>میٹرک</th>\n<th>قدر</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>11,236 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>5,817 روپے</td>\n</tr>\n<tr>\n<td>Breakevens</td>\n<td>23,570 / 24,548</td>\n</tr>\n<tr>\n<td>منافع کا امکان</td>\n<td>تقریبا 42 فیصد</td>\n</tr>\n<tr>\n<td>انعام کا خطرہ</td>\n<td>1 : 1.93</td>\n</tr>\n<tr>\n<td>خالص ڈیبٹ</td>\n<td>5,818 روپے</td>\n</tr>\n<tr>\n<td>مارجن درکار ہے۔</td>\n<td>48,986 روپے</td>\n</tr>\n<tr>\n<td>اب کل P&amp;L</td>\n<td>تقریباً 0 روپے</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-put-calendar.png\" alt=\"NIFTY پوٹ کیلنڈر، 28 جولائی 24,050 کا پوٹ بیچ رہا ہے اور 25 اگست 24,050 کا پوٹ خرید رہا ہے۔ ایک ہی خیمے کی شکل ہڑتال کے قریب پہنچتی ہے، لیکن اس کی قیمت صرف 5,818 روپے ہے اور یہ 1 سے 1.93 کے خطرے سے زیادہ مضبوط انعام ظاہر کرتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY پوٹ کیلنڈر، 28 جولائی 24,050 کا پوٹ بیچ رہا ہے اور 25 اگست 24,050 کا پوٹ خرید رہا ہے۔ ایک ہی خیمے کی شکل ہڑتال کے قریب پہنچتی ہے، لیکن اس کی قیمت صرف 5,818 روپے ہے اور یہ 1 سے 1.93 کے خطرے سے زیادہ مضبوط انعام ظاہر کرتا ہے۔</figcaption></figure>\n<p>شکل ایک ہی خیمہ ہے، لیکن تعداد مہربان ہیں۔ اس سنیپ شاٹ پر پوٹ کیلنڈر کی قیمت صرف 5,818 روپے ہے، جو کال ورژن سے بہت کم ہے، پھر بھی اس کا زیادہ سے زیادہ منافع 11,236 روپے تقریباً اتنا ہی بڑا ہے۔ اس لیے اس کا <strong>انعام کا خطرہ 1 سے 1.93 تک ہے۔</strong>, تین میں سے بہترین: آپ کو گیارہ سے زیادہ بنانے کے لیے چھ ہزار سے کم خطرہ ہے۔ 23,570 اور 24,548، بریک ایونز، ہڑتال کے گرد خیمہ بناتے ہیں، اور 5,817 روپے کا زیادہ سے زیادہ نقصان بنیادی طور پر وہ ڈیبٹ ہے جو آپ نے ادا کیا ہے۔</p>\n<h2 id=\"the-diagonal-calendar\">اخترن کیلنڈر</h2>\n<p>اے <strong>اخترن کیلنڈر</strong> وقت کے عنصر کو برقرار رکھتا ہے لیکن دوسرا موڑ جوڑتا ہے: دونوں ٹانگیں مختلف حملوں کے ساتھ ساتھ مختلف ختم ہونے پر بیٹھتی ہیں۔ آپ اب بھی قریب کا مہینہ بیچتے ہیں اور دور کا مہینہ خریدتے ہیں، لیکن اسٹرائیک گیپ خیمے کو جھکاتا اور چوڑا کرتا ہے، جس سے اسے ہموار چوٹی کی بجائے سمتی جھکاؤ ملتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ختم</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>1 فروخت کریں۔</td>\n<td>28 جولائی 2026</td>\n<td>24,050 کال کریں۔</td>\n<td>425.8 موصول ہوا۔</td>\n</tr>\n<tr>\n<td>2</td>\n<td>1 خریدیں۔</td>\n<td>25 اگست 2026</td>\n<td>24,150 کال</td>\n<td>561.1 ادا کیا گیا۔</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>خالص ڈیبٹ</strong></td>\n<td><strong>تقریباً 8,791 روپے</strong></td>\n</tr>\n</tbody></table>\n<table>\n<thead>\n<tr>\n<th>میٹرک</th>\n<th>قدر</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>14,881 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>15,161 روپے</td>\n</tr>\n<tr>\n<td>Breakevens</td>\n<td>23,382 / 24,593</td>\n</tr>\n<tr>\n<td>منافع کا امکان</td>\n<td>تقریبا 50 فیصد</td>\n</tr>\n<tr>\n<td>انعام کا خطرہ</td>\n<td>1 : 0.98</td>\n</tr>\n<tr>\n<td>خالص ڈیبٹ</td>\n<td>تقریباً 8,791 روپے</td>\n</tr>\n<tr>\n<td>مارجن درکار ہے۔</td>\n<td>55,782 روپے</td>\n</tr>\n<tr>\n<td>اب کل P&amp;L</td>\n<td>تقریباً 0 روپے</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-diagonal-calendar.png\" alt=\"NIFTY اخترن کیلنڈر، قریب کے مہینے کی 24,050 کال کی فروخت اور دور مہینے کی 24,150 کال کو خریدنا۔ خیمہ چوڑا ہے اور ایک طرف جھکا ہوا ہے، 23,382 اور 24,593 پر بریک ایونز کے ساتھ اور زیادہ سے زیادہ منافع 14,881 روپے ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY اخترن کیلنڈر، قریب کے مہینے کی 24,050 کال کی فروخت اور دور مہینے کی 24,150 کال کی خریداری۔ خیمہ چوڑا ہے اور ایک طرف جھکا ہوا ہے، 23,382 اور 24,593 پر بریک ایونز کے ساتھ اور زیادہ سے زیادہ منافع 14,881 روپے ہے۔</figcaption></figure>\n<p>چونکہ دور کی کال ایک سٹرائیک زیادہ ہے، ڈیبٹ ایک سادہ کال کیلنڈر سے چھوٹا ہے، تقریباً 8,791 روپے، اور ادائیگی اب متوازن نہیں ہے۔ اس کے بریک ایونز، 23,382 اور 24,593، ایک دوسرے سے زیادہ چوڑے بیٹھتے ہیں، اس لیے یہ پیسہ کمانے سے پہلے ایک بڑے اقدام کو برداشت کرتا ہے، یہی وجہ ہے کہ اس کے منافع کا امکان، تقریباً 50 فیصد، تینوں میں سب سے زیادہ ہے۔ اس وسیع خیمے کی قیمت زیادہ سے زیادہ 15,161 روپے کا نقصان ہے، جو ڈیبٹ سے ایک ٹچ زیادہ ہے، کیونکہ اسٹرائیک گیپ کا مطلب ہے کہ تیز اقدام کی قیمت آپ کی ادائیگی سے کچھ زیادہ ہو سکتی ہے۔ 14,881 روپے کا زیادہ سے زیادہ منافع تب بھی آتا ہے جب NIFTY قریب ختم ہونے پر پچھلے مہینے کی ہڑتال کی طرف بڑھ جاتا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>اخترن کیلنڈر کا زیادہ لچکدار کزن ہے۔ یہ منتخب کر کے کہ دونوں سٹرائیکس کتنے فاصلے پر بیٹھتے ہیں، آپ فیصلہ کرتے ہیں کہ خیمہ کتنا چوڑا ہے اور یہ کس طرف جھکتا ہے، تاکہ آپ ہلکے دشاتمک نظارے کے ساتھ ساتھ وقت پر ایک منظر کا اظہار کر سکیں۔ یہ اب بھی متعین خطرہ ہے، لیکن اسٹرائیک گیپ سادہ کیلنڈرز کے برعکس، سادہ ڈیبٹ سے اس کے بدترین کیس کو تھوڑا بڑا بنا دیتا ہے۔</p>\n</div></div>\n<h2 id=\"choosing-and-managing-a-calendar\">کیلنڈر کا انتخاب اور انتظام کرنا</h2>\n<p>تینوں کو ساتھ ساتھ رکھیں اور تجارت کے معاملات واضح ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>حکمت عملی</th>\n<th>ڈیبٹ</th>\n<th>زیادہ سے زیادہ منافع</th>\n<th>زیادہ سے زیادہ نقصان</th>\n<th>رسک پر انعام</th>\n<th>POP</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>کیلنڈر کو کال کریں۔</td>\n<td>13,130 روپے</td>\n<td>14,480 روپے</td>\n<td>13,090 روپے</td>\n<td>1 : 1.11</td>\n<td>47 فیصد</td>\n</tr>\n<tr>\n<td>کیلنڈر لگائیں۔</td>\n<td>5,818 روپے</td>\n<td>11,236 روپے</td>\n<td>5,817 روپے</td>\n<td>1 : 1.93</td>\n<td>42 فیصد</td>\n</tr>\n<tr>\n<td>ترچھی کیلنڈر</td>\n<td>8,791 روپے</td>\n<td>14,881 روپے</td>\n<td>15,161 روپے</td>\n<td>1 : 0.98</td>\n<td>50 فیصد</td>\n</tr>\n</tbody></table>\n<p>تینوں ایک ہی چیز چاہتے ہیں، ایک پُرسکون NIFTY جو ہڑتال کے قریب رہتا ہے جب کہ قریب مہینے کی ٹانگ ختم ہوجاتی ہے۔ وہ ایک ایسی مارکیٹ کے مطابق ہیں جس کی آپ توقع کرتے ہیں کہ چند ہفتوں کے لیے ایک طرف بہہ جائیں گے، نہ کہ آپ جس مارکیٹ کے ٹوٹنے کی توقع کرتے ہیں۔ کیونکہ آپ جو سب سے زیادہ کھو سکتے ہیں وہ تقریباً ڈیبٹ ہے، یہ وقت بیچنے کا ایک طے شدہ رسک طریقہ ہے، جس میں تقریباً 49,000 روپے سے 58,000 روپے کا مارجن ہے بجائے اس کے کہ ایک ننگے شارٹ کا مطالبہ کیا جائے گا۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>ایک مختصر اسٹریڈل یا گلا گھونٹنے کے برعکس، کیلنڈر کی کوئی لامحدود دم نہیں ہوتی۔ آپ پچھلے مہینے کی ٹانگ کے مالک ہیں، اور یہ لمبا آپشن آپ کے نقصان کو تقریباً آپ کے ادا کردہ ڈیبٹ پر رکھتا ہے۔ یہ کیلنڈرز کو ان چند طریقوں میں سے ایک بناتا ہے جن سے ایک ابتدائی شخص کھلے خطرے کے بغیر وقت کی کمی کو فروخت کر سکتا ہے۔ اس حفاظت کی قیمت یہ ہے کہ آپ کو پچھلے مہینے کے آپشن کے لیے بھی ادائیگی کرنی ہوگی، اس لیے کیلنڈر ڈیبٹ ٹریڈ ہے، کریڈٹ نہیں۔</p>\n</div></div>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک کیلنڈر کی وضاحت خطرے سے ہوتی ہے، لیکن اس میں ایک پوشیدہ حساسیت ہوتی ہے جس کا ایک ابتدائی کو احترام کرنا چاہیے: مضمر اتار چڑھاؤ۔ پچھلے مہینے کی ٹانگ میں آپ کی بیچی گئی اگلی ٹانگ سے زیادہ اتار چڑھاؤ ہوتا ہے، لہذا آپ کے داخل ہونے کے بعد مضمر اتار چڑھاؤ میں تیزی سے کمی خیمے کو سکڑ سکتی ہے اور آپ کو نقصان پہنچا سکتی ہے یہاں تک کہ اگر NIFTY بالکل برتاؤ کرتا ہے۔ خیمہ صرف اسٹرائیک کے قریب ہی حقیقی ہے، اس لیے ایک کیلنڈر کسی معروف ایونٹ سے پہلے رکھا گیا ہے جو NIFTY کو بھیج سکتا ہے، ایک ناقص شرط ہے۔ پُرسکون حالات میں کیلنڈر کی تجارت کریں، نہ کہ طے شدہ جھٹکے میں۔</p>\n</div></div>\n<p>سینڈ باکس ٹریڈنگ میں شکل کی مشق کریں ( OpenAlgo میں تجزیہ کرنے والا موڈ) اور خیمہ کے بڑھتے اور گرتے ہوئے دیکھیں جب آپ اسٹرائیک اور ایکسپائرز کو دھکیلتے ہیں۔ کیلنڈر کے ساتھ آپ نے وقت کے ساتھ ساتھ سمت کی تجارت کرنا بھی سیکھ لیا ہے۔ اگلا ہم سیدھی لائن پر واپس آتے ہیں، مصنوعی مستقبل۔</p>\n<h2 id=\"key-takeaways\">اہم نکات</h2>\n<ul>\n<li>اے <strong>کیلنڈر پھیلاؤ</strong> قریب کے مہینے کے آپشن کو فروخت کرتا ہے اور اسی ہڑتال پر دور کا مہینہ خریدتا ہے، اس سے فائدہ اٹھاتا ہے۔ <strong>تیزی سے خرابی</strong> اگلی ٹانگ کے.</li>\n<li>ادائیگی ہے a <strong>خیمہ</strong> قریب ختم ہونے پر ہڑتال کی چوٹی، جہاں مردہ اگلی ٹانگ اور زندہ پچھلی ٹانگ سب سے دور ہیں۔</li>\n<li>دی <strong>کال کیلنڈر</strong> قیمت 13,130 روپے ہے، 14,480 روپے کی چوٹی پر ہے، اور 23,495 اور 24,634 پر بھی بریک، چوٹی پر 25 فیصد کے قریب مارجن پر واپسی ہے۔</li>\n<li>دی <strong>کیلنڈر لگائیں</strong> یہاں اسی شکل کا سب سے سستا راستہ ہے، 11,236 روپے کی چوٹی کے لیے 5,818 روپے ڈیبٹ اور رسک پر 1 سے 1.93 کا انعام؛ دی <strong>اخترن</strong> سب سے زیادہ 50 فیصد مشکلات کے لیے خیمہ کو چوڑا اور جھکایا جاتا ہے لیکن 15,161 روپے کی بدترین صورت۔</li>\n<li>کیلنڈر ہیں۔ <strong>طے شدہ خطرہ</strong> اور یہاں صرف ڈھانچے ہیں <strong>وقت کی خرابی میں مدد ملتی ہے</strong>، لیکن وہ مضمر اتار چڑھاؤ میں کمی کے بارے میں حساس ہیں اور ایک پرسکون، واقعہ سے پاک مہینہ چاہتے ہیں۔</li>\n</ul>\n","toc":[{"level":2,"text":"ون لائن آئیڈیا: قریب کو بیچیں، دور کی ملکیت کریں۔","id":"the-one-line-idea-sell-the-near-own-the-far"},{"level":2,"text":"کال کیلنڈر، روپیہ بہ روپیہ","id":"the-call-calendar-rupee-by-rupee"},{"level":2,"text":"تین نمبر، اور وہ کہاں سے آتے ہیں۔","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"قریب کی میعاد ختم ہونے پر نتائج پر چلنا","id":"walking-the-outcomes-at-the-near-expiry"},{"level":2,"text":"آپ کی مشکلات، مارجن، اور واپسی۔","id":"your-odds-margin-and-return"},{"level":2,"text":"وقت کی زوال پوری بات ہے۔","id":"time-decay-is-the-whole-point"},{"level":2,"text":"پوٹ کیلنڈر","id":"the-put-calendar"},{"level":2,"text":"اخترن کیلنڈر","id":"the-diagonal-calendar"},{"level":2,"text":"کیلنڈر کا انتخاب اور انتظام کرنا","id":"choosing-and-managing-a-calendar"},{"level":2,"text":"اہم نکات","id":"key-takeaways"}],"imgCount":3,"hasContent":true},"21":{"html":"<p>اختیارات کی ریاضی کا ایک خاموش ٹکڑا ہے جو ہر ابتدائی کو پہلی بار دیکھتے ہی حیران کر دیتا ہے۔ ایک خریدی ہوئی کال اور بیچا ہوا پوٹ، ایک ہی قیمت پر مارا جاتا ہے، ایسی چیز کو جوڑتا ہے جو بالکل بھی منحنی نہ ہو۔ وہ ایک سیدھی لکیر بناتے ہیں جو بالکل فیوچر پوزیشن کی طرح طلوع اور گرتی ہے۔ یہ تعلق، کہ آپشنز کو مستقبل میں جمع کیا جا سکتا ہے اور مستقبل کو آپشنز میں الگ کیا جا سکتا ہے، پورے موضوع میں سب سے زیادہ مفید خیالات میں سے ایک ہے۔ اس باب میں ہم نے ڈال دیا۔ <strong>طویل مصنوعی مستقبل</strong> اور <strong>مختصر مصنوعی مستقبل</strong> ساتھ ساتھ، پھر تعمیر کرنے کے لیے اسی بلڈنگ بلاک سوچ کا استعمال کریں۔ <strong>احاطہ کال</strong>، آمدنی کی تجارت جو آپ کے پاس پہلے سے موجود ہولڈنگ کے اوپر بیٹھتی ہے۔ تمام اعداد و شمار 26 جون 2026، اسپاٹ 24,056، ATM اسٹرائیک 24,050، لاٹ 65، 28 جولائی 2026 کو ختم ہونے والے حقیقی NIFTY آپشن ڈیٹا کا استعمال کرتے ہیں۔</p>\n<h2 id=\"the-one-line-idea\">ایک لائن کا خیال</h2>\n<p>اے <strong>مصنوعی مستقبل</strong> ایک ہی ہڑتال پر دو آپشنز سے دوبارہ تعمیر ہونے والا ایک طویل مستقبل ہے۔ کال خریدیں اور پٹ بیچیں اور آپ مستقبل کے تمام الٹا اور اس کے تمام نشیب و فراز کے مالک ہیں، جو ایک سیدھی ترچھی لکیر میں چپکے ہوئے ہیں۔ کال بیچیں اور پٹ خریدیں اور آپ نے آئینہ بنایا ہے، ایک مختصر مستقبل۔ نقطہ نظر وہی دو ٹوک دشاتمک شرط ہے جو مستقبل کا اظہار کرتا ہے، لیکن ان اختیارات سے جمع کیا گیا ہے جو آپ پہلے ہی سمجھتے ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک ہی ہڑتال پر ایک لمبی کال اور شارٹ پٹ ایک طویل مستقبل بناتے ہیں۔ ایک ہی ہڑتال پر ایک مختصر کال اور ایک لمبی پوٹ ایک مختصر مستقبل بناتی ہے۔ یہ اختیارات کے مرکز میں برابری کا رشتہ ہے: مستقبل صرف ایک کال ہے اور ایک ساتھ بولڈ کیا گیا ہے، اور تینوں میں سے کسی ایک کو دوسرے دو سے دوبارہ بنایا جا سکتا ہے۔ زیادہ پیچیدہ ڈھانچے کے اندر ان سیدھی لکیر کی شکلوں کو پہچاننا پڑھنے کی سب سے طاقتور مہارتوں میں سے ایک ہے جسے آپ تیار کر سکتے ہیں۔</p>\n</div></div>\n<h2 id=\"the-long-synthetic-future-rupee-by-rupee\">طویل مصنوعی مستقبل، روپیہ بہ روپیہ</h2>\n<p>آپ نے تیزی کی حکمت عملیوں کے درمیان مختصر طور پر اس شکل سے ملاقات کی۔ یہاں یہ ہے کہ یہ کس چیز سے بنی ہے، ایک خریدی ہوئی کال اور ایک فروخت کی گئی، دونوں پر پیسے کی ہڑتال پر۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>کال خریدیں۔</td>\n<td>24,050</td>\n<td>425.8 ادا کیا گیا۔</td>\n<td>27,677 روپے باہر</td>\n</tr>\n<tr>\n<td>2</td>\n<td>ڈال فروخت</td>\n<td>24,050</td>\n<td>295.1 موصول ہوا۔</td>\n<td>علاوہ 19,182 روپے میں</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>خالص ڈیبٹ</strong></td>\n<td><strong>تقریباً 8,496 روپے</strong></td>\n</tr>\n</tbody></table>\n<p>خریدی ہوئی کال آپ کو مستقبل کے تمام پہلوؤں کے حوالے کر دیتی ہے۔ بیچنے والے نے آپ کو مستقبل کے تمام منفی پہلوؤں میں ڈال دیا۔ انہیں ایک ساتھ چپکائیں اور منحنی خطوط ایک واحد اخترن لائن میں منسوخ ہو جائیں جو دونوں سمتوں میں نقطہ کے لیے NIFTY پوائنٹ کو ٹریک کرتی ہے۔ کال کی قیمت 425.8 ہے اور پوٹ آپ کو 295.1 ادا کرتا ہے، لہذا آپ فرق کے ساتھ، 130.7 پوائنٹس فی شیئر، جو کہ ایک ہے <strong>تقریباً 8,496 روپے کا خالص ڈیبٹ</strong> فی لاٹ</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-long-synthetic.png\" alt=\"NIFTY لمبا مصنوعی مستقبل، 24,050 کال خریدنا اور 24,050 کا پوٹ بیچنا۔ اورنج لائن ایک واحد سیدھی ترچھی ہے، جو 24,181 کے بریک ایون کے اوپر بغیر کسی حد کے بڑھ رہی ہے اور اس کے نیچے روپے کے بدلے روپیہ گر رہی ہے، بالکل ایک طویل مستقبل کی طرح۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY طویل مصنوعی مستقبل، 24,050 کال خریدنا اور 24,050 کا پوٹ بیچنا۔ اورنج لائن ایک واحد سیدھی ترچھی ہے، جو 24,181 کے بریک ایون کے اوپر بغیر کسی حد کے بڑھ رہی ہے اور اس کے نیچے روپے کے بدلے روپیہ گر رہی ہے، بالکل ایک طویل مستقبل کی طرح۔</figcaption></figure>\n<h2 id=\"the-three-numbers-and-where-they-come-from\">تین نمبر، اور وہ کہاں سے آتے ہیں۔</h2>\n<p><strong>Breakeven 24,181 ہے۔</strong> کسی بھی اختتامی قیمت پر، کال کی داخلی قدر مائنس دی پوٹ کی اندرونی قدر صرف NIFTY مائنس دی 24,050 سٹرائیک ہے۔ آپ نے اسے برقرار رکھنے کے لیے 130.7 پوائنٹس کی ادائیگی کی، اس لیے جب آپ NIFTY 24,050 جمع 130.7، جو کہ 24,181 ہے، کو صاف کر دیتے ہیں تو آپ منافع بخش ہو جاتے ہیں۔</p>\n<p><strong>زیادہ سے زیادہ منافع لامحدود ہے۔</strong> بریک ایون کے اوپر لائن ایک لمبے مستقبل کی طرح، بغیر کسی چھت کے نقطہ کے لیے نقطہ بڑھ جاتی ہے۔</p>\n<p><strong>زیادہ سے زیادہ نقصان 1,571,746 روپے ہے۔</strong> بریک ایون کے نیچے لائن روپے کے بدلے روپیہ گرتی ہے۔ فرش واقعی کوئی منزل نہیں ہے، یہ صرف اتنا ہے کہ NIFTY صفر سے نیچے نہیں گر سکتا، اور اگر یہ پورے راستے میں گرے تو نقصان تقریباً 1,571,746 روپے تک پہنچ جائے گا۔</p>\n<table>\n<thead>\n<tr>\n<th>نمبر</th>\n<th>یہ کیسے بنایا گیا ہے۔</th>\n<th>یہ تجارت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>بریک ایون</td>\n<td>سٹرائیک کے علاوہ پوائنٹس میں خالص ڈیبٹ</td>\n<td>24,050 جمع 130.7 برابر 24,181</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>نقطہ کے لئے نقطہ بڑھتا ہے، کوئی چھت نہیں</td>\n<td>لا محدود</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>مکمل زوال صفر پر، محدود لیکن بہت بڑا</td>\n<td>1,571,746 روپے</td>\n</tr>\n</tbody></table>\n<h2 id=\"walking-the-outcomes-at-expiry\">میعاد ختم ہونے پر نتائج پر چلنا</h2>\n<p>لمبے مصنوعی کو پانچ اختتامی قیمتوں پر طے کریں، فی لاٹ 65۔ خریدی گئی کال اس کی داخلی قیمت کے قابل ہے، فروخت شدہ پوٹ اس کی اندرونی قیمت کے قابل ہے، اور آخری کالم میں سیدھی لائن سادہ ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>NIFTY ختم ہونے پر</th>\n<th>24,050 کال آپ نے خریدی۔</th>\n<th>24,050 میں آپ نے فروخت کیا۔</th>\n<th>خالص منافع یا نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>22,000</td>\n<td>بیکار ختم</td>\n<td>آپ کے خلاف 2,050 کی قیمت</td>\n<td>مائنس 141,746 روپے</td>\n</tr>\n<tr>\n<td>24,050</td>\n<td>بیکار ختم</td>\n<td>بیکار ختم</td>\n<td>مائنس 8,496 روپے (ڈیبٹ)</td>\n</tr>\n<tr>\n<td>24,181</td>\n<td>مالیت 131</td>\n<td>بیکار ختم</td>\n<td>تقریباً 0 روپے (بریک ایون)</td>\n</tr>\n<tr>\n<td>25,000</td>\n<td>950 کی مالیت</td>\n<td>بیکار ختم</td>\n<td>علاوہ 53,255 روپے</td>\n</tr>\n<tr>\n<td>26,000</td>\n<td>مالیت 1,950</td>\n<td>بیکار ختم</td>\n<td>علاوہ 118,255 روپے</td>\n</tr>\n</tbody></table>\n<p>سیدھی لکیر سے آگے تشریح کرنے کے لیے کچھ نہیں ہے، اور یہی بات ہے۔ 24,181 سے اوپر آپ بغیر کسی حد کے پوائنٹ کے لیے پوائنٹ حاصل کرتے ہیں۔ اس کے نیچے آپ پوائنٹ کے بدلے پوائنٹ کھو دیتے ہیں، اور صفر کی طرف گہرا گرنا ہی 1,571,746 روپے کی بدترین صورت بنتا ہے۔ نیلی T+0 لائن تقریباً نارنجی لائن کے اوپر بیٹھتی ہے، کیونکہ مصنوعی مستقبل میں زوال کے لیے تقریباً کوئی وقت کی قدر نہیں ہوتی، اس لیے وقت بمشکل اس پوزیشن کو منتقل کرتا ہے۔ اس کا <strong>منافع کا امکان تقریباً 44 فیصد ہے۔</strong>، مارکیٹ NIFTY پر پڑھی گئی ہے جو 24,181 بریک ایون کو ایکسپائری کے ذریعے صاف کرتی ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>لمبا مصنوعی مستقبل بالکل ایک طویل NIFTY مستقبل کی طرح برتاؤ کرتا ہے، لہذا اس کا خطرہ دو طرفہ اور بہت بڑا ہے۔ زیادہ سے زیادہ نقصان تقریباً 1,571,746 روپے ہے اگر NIFTY صفر کی طرف گر جاتا ہے، فروخت شدہ پوٹ ایک ننگی چھوٹی ٹانگ ہے، اور ایکسچینج تقریباً 173,537 روپے کے بھاری مارجن کو روکتا ہے۔ اس ڈھانچے میں کہیں بھی حفاظتی فرش نہیں ہے۔ اس کے ساتھ اسی احترام کے ساتھ برتاؤ کریں جس طرح آپ فیوچر پوزیشن دیں گے، کبھی بھی نرم اختیارات کی تجارت کے طور پر نہیں۔</p>\n</div></div>\n<h2 id=\"the-short-synthetic-future\">مختصر مصنوعی مستقبل</h2>\n<p>دونوں ٹانگوں کو پلٹائیں اور آپ کو آئینے کی تصویر ملے گی۔ کال بیچیں، پوٹ خریدیں، اور آپ نے دو اختیارات سے ایک مختصر مستقبل بنایا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>ٹانگ</th>\n<th>ایکشن</th>\n<th>ہڑتال</th>\n<th>پریمیم فی شیئر</th>\n<th>کیش فلو فی لاٹ 65</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>کال فروخت کریں۔</td>\n<td>24,050</td>\n<td>425.8 موصول ہوا۔</td>\n<td>علاوہ 27,677 روپے میں</td>\n</tr>\n<tr>\n<td>2</td>\n<td>ڈال خریدیں</td>\n<td>24,050</td>\n<td>295.1 ادا کیا گیا۔</td>\n<td>19,182 روپے باہر</td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><strong>نیٹ کریڈٹ</strong></td>\n<td><strong>تقریباً 8,496 روپے میں</strong></td>\n</tr>\n</tbody></table>\n<table>\n<thead>\n<tr>\n<th>میٹرک</th>\n<th>قدر</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>زیادہ سے زیادہ منافع</td>\n<td>1,571,746 روپے</td>\n</tr>\n<tr>\n<td>زیادہ سے زیادہ نقصان</td>\n<td>لا محدود</td>\n</tr>\n<tr>\n<td>بریک ایون</td>\n<td>24,181</td>\n</tr>\n<tr>\n<td>منافع کا امکان</td>\n<td>تقریبا 56 فیصد</td>\n</tr>\n<tr>\n<td>انعام کا خطرہ</td>\n<td>NA</td>\n</tr>\n<tr>\n<td>نیٹ کریڈٹ</td>\n<td>تقریباً 8,496 روپے</td>\n</tr>\n<tr>\n<td>مارجن درکار ہے۔</td>\n<td>169,046 روپے</td>\n</tr>\n<tr>\n<td>اب کل P&amp;L</td>\n<td>تقریباً 0 روپے</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-short-synthetic.png\" alt=\"NIFTY مختصر مصنوعی مستقبل، 24,050 کال کی فروخت اور 24,050 کا پوٹ خریدنا۔ اورنج لائن ایک سیدھی ترچھی ہے جو 24,181 کے بریک ایون سے نیچے منافع میں گرتی ہے اور اس کے اوپر نقصان میں بڑھ رہی ہے، بالکل ایک مختصر مستقبل کی طرح جس میں نقصان کی کوئی حد نہیں ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>NIFTY مختصر مصنوعی مستقبل، 24,050 کال کی فروخت اور 24,050 کا پوٹ خریدنا۔ اورنج لائن ایک سیدھی ترچھی ہے جو 24,181 کے بریک ایون سے نیچے منافع میں گرتی ہے اور اس کے اوپر نقصان میں بڑھ رہی ہے، بالکل ایک مختصر مستقبل کی طرح جس میں نقصان کی کوئی حد نہیں ہے۔</figcaption></figure>\n<p>مختصر مصنوعی کو پڑھیں کیونکہ لمبا مصنوعی اوپر سے نیچے پلٹ جاتا ہے۔ 24,181 کے بریک ایون کے نیچے لائن منافع میں آتی ہے، جو نیچے کی طرف بڑی لیکن محدود ہے، کیونکہ NIFTY صفر سے نیچے نہیں جا سکتا، اس لیے زیادہ سے زیادہ منافع 1,571,746 روپے ہے۔ بریک ایون کے اوپر لائن بغیر کسی حد کے نقصان میں بڑھ جاتی ہے۔ لانگ سنتھیٹک کی طرح پانچ اختتامی قیمتوں کو چلائیں اور ہر خالص اعداد و شمار کے نشان کو صرف الٹ دیں: جہاں لمبا ورژن 22,000 میں 141,746 روپے کھو دیتا ہے، مختصر ورژن اسے حاصل کرتا ہے، اور جہاں طویل ورژن 26,000 پر 118,255 روپے حاصل کرتا ہے، مختصر ورژن اسے بغیر کسی حد کے کھو دیتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>مختصر مصنوعی مستقبل میں الٹا خطرہ ہے۔ فروخت شدہ کال ایک ننگی چھوٹی ٹانگ ہے، اور اگر NIFTY سخت ریلیز کرتا ہے تو نقصان بغیر کسی حد کے بڑھتا ہے، یہی وجہ ہے کہ بلڈر زیادہ سے زیادہ نقصان کو لامحدود کے طور پر پرنٹ کرتا ہے اور ایکسچینج مارجن کے تقریباً 169,046 روپے کو روکتا ہے۔ 8,496 روپے کا ایک چھوٹا سا کریڈٹ کسی بھی طرح سے اس خطرے کی عکاسی نہیں کرتا جو آپ لے رہے ہیں۔ یہ بھیس میں ایک مختصر مستقبل ہے اور اسے ایک کے طور پر منظم کیا جانا چاہئے۔</p>\n</div></div>\n<h2 id=\"the-covered-call\">ڈھکی ہوئی کال</h2>\n<p>کورڈ کال حکمت عملی بنانے والے میں کوئی ٹیمپلیٹ نہیں ہے، کیونکہ اس کی ٹانگوں میں سے ایک ایسی چیز ہے جسے آپ پہلے سے پکڑے ہوئے ہیں بجائے اس کے کہ آپ جو آپشن شامل کرتے ہیں۔ لیکن یہ ایک ہی حصوں کی سوچ سے بنایا گیا ہے، لہذا یہ یہاں سے تعلق رکھتا ہے. ایک طویل NIFTY پوزیشن پر فائز ایک تاجر کی تصویر بنائیں، مستقبل کے بارے میں بتائیں، جو ایک مستحکم، سائیڈ وے سے ہلکے سے اونچی مارکیٹ سے مطمئن ہے۔ اس ہولڈنگ سے آمدنی حاصل کرنے کے لیے، وہ <strong>موجودہ قیمت سے اوپر کال فروخت کریں۔</strong>یہاں 24,150 کال، اور 370.1 فی حصص کا پریمیم جیب میں ڈالیں، لاٹ کے لیے تقریباً 24,057 روپے۔</p>\n<p>دو ٹکڑے اس طرح کام کرتے ہیں۔</p>\n<ul>\n<li>دی <strong>طویل NIFTY مستقبل</strong> معمول کے مطابق پوائنٹ فار پوائنٹ ایکسپوژر دیتا ہے، جیسے جیسے NIFTY بڑھتا ہے اور گرتے ہی ہار جاتا ہے۔</li>\n<li>دی <strong>24,150 کال فروخت ہوئی۔</strong> فوری طور پر پریمیم لاتا ہے۔ جب تک NIFTY ایکسپائری کے ذریعے 24,150 سے نیچے ختم ہوجاتا ہے، وہ کال بیکار ختم ہوجاتی ہے اور پریمیم ہولڈنگ کے اوپر خالص آمدنی ہے۔</li>\n</ul>\n<p>نتیجہ ایک ایسی پوزیشن ہے جو ہر مہینے تھوڑا سا اضافی کماتا ہے، ایک واضح رعایت کے بدلے میں مارکیٹ پرسکون رہتی ہے: آپ کا اوپری حصہ محدود ہے۔ اگر NIFTY 24,150 سے آگے بڑھتا ہے، تو آپ کے مستقبل میں حاصل ہونے والے ہر ایک پوائنٹ سے اس پوائنٹ سے مماثلت ملتی ہے جو فروخت شدہ کال کے نقصان سے ہوتا ہے، اس لیے اسٹرائیک کے اوپر آپ کا منافع بڑھنا رک جاتا ہے۔ آپ کا بہترین معاملہ 24,150 کے علاوہ آپ کے جمع کردہ پریمیم تک منتقل کرنا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>کورڈ کال کی ادائیگی کو قریب سے دیکھیں اور آپ اسے پہچان لیں گے۔ ایک لمبا مستقبل اور ایک مختصر کال ایک شارٹ پٹ کے طور پر بالکل وہی جھکی ہوئی لکیر پیدا کرتی ہے: اوپر کی طرف محدود، محدود منافع اور نیچے کی طرف ایک لمبا، ڈھلوان نقصان۔ کورڈ کال ایک مصنوعی شارٹ پٹ ہے۔ یہ ایک بار پھر برابری کا آئیڈیا ہے، اور یہ بتاتا ہے کہ کورڈ کال انکم ٹریڈ کیوں ہے نہ کہ گروتھ ٹریڈ۔ آپ آج پریمیم کے بدلے اپنا الٹا بیچ رہے ہیں۔</p>\n</div></div>\n<p>کورڈ کال ایک ایسے سرمایہ کار کے لیے موزوں ہے جو خاموشی کے دوران ہولڈنگ کو برقرار رکھنا اور اس سے حاصل ہونے والی پیداوار کو نچوڑنا چاہتا ہے، نہ کہ کسی تاجر کے لیے جو بڑی ریلی کا پیچھا کر رہا ہو۔ پریمیم راستے میں ایک چھوٹا سا کشن بھی دیتا ہے، کیونکہ آپ کی جمع کردہ آمدنی کسی بھی زوال کے پہلے حصے کو پورا کرتی ہے۔ لیکن وہ کشن پتلا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ڈھکی ہوئی کال آپ کے منفی پہلو کی حفاظت نہیں کرتی ہے۔ اگر مارکیٹ گرتی ہے تو آپ کا طویل NIFTY مستقبل اب بھی بہت زیادہ کھو سکتا ہے، اور تمام فروخت شدہ کال آپ کو پہلے کشن کے طور پر چھوٹا پریمیم ہے۔ کسی ہولڈنگ پر آمدنی حاصل کرنے کے لیے کال بیچنا آپ دوسری صورت میں نہیں رکھنا چاہیں گے، ایک غلطی ہے، کیونکہ آپ نے برے کو تقریباً مکمل طور پر کھلا چھوڑتے ہوئے صرف اچھے نتائج کو محدود کر دیا ہے۔ کورڈ کال کو صرف اس پوزیشن پر استعمال کریں جس پر آپ واقعتاً خوشی محسوس کرتے ہیں، اور اسے حقیقی زوال کے لیے سائز دیں، نہ کہ اس سکون کے لیے جس کی آپ امید کر رہے ہیں۔</p>\n</div></div>\n<h2 id=\"three-ways-to-hold-a-directional-view\">دشاتمک نظریہ رکھنے کے تین طریقے</h2>\n<table>\n<thead>\n<tr>\n<th>پوزیشن</th>\n<th>سے بنایا گیا ہے۔</th>\n<th>شکل</th>\n<th>خطرہ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>طویل مصنوعی مستقبل</td>\n<td>لمبی کال، شارٹ پٹ</td>\n<td>سیدھی لائن اپ</td>\n<td>بڑا دو رخا، ننگا ڈال</td>\n</tr>\n<tr>\n<td>مختصر مصنوعی مستقبل</td>\n<td>مختصر کال، لمبی پوٹ</td>\n<td>سیدھی لائن نیچے</td>\n<td>لامحدود الٹا، ننگی کال</td>\n</tr>\n<tr>\n<td>احاطہ کال</td>\n<td>طویل ہولڈنگ، مختصر کال</td>\n<td>اوپر کی طرف، مکمل نیچے کی طرف</td>\n<td>ہولڈنگ پر مکمل منفی پہلو</td>\n</tr>\n</tbody></table>\n<p>ترکیبیں ایک سمتاتی نقطہ نظر کا خالص ترین اظہار ہیں، ایک سیدھی لکیر، لڑنے کے لیے کوئی وقت ضائع نہیں ہوتا، اور مستقبل کا مکمل خطرہ ہوتا ہے۔ ڈھکی ہوئی کال سب سے نرم ہے: یہ ایک مستحکم پریمیم کے بدلے اوپن اینڈڈ اپسائیڈ کو ترک کر دیتی ہے، اور یہ تب ہی سمجھ میں آتا ہے جب آپ پہلے سے ہی مالک ہوں اور بنیادی چیز چاہتے ہوں۔ تینوں میں سے کسی کی بھی وضاحت نہیں کی گئی ہے جس طرح سے پھیلاؤ ہوتا ہے، لہٰذا ایک ابتدائی کے لیے وہ پہلے کے ابواب کے پابند ڈھانچے سے آگے ایک واضح قدم رکھتے ہیں۔ حکمت عملی بنانے والے میں شارٹ اسٹریڈل کے ساتھ لمبا سینتھیٹک بنائیں اور دونوں بلاک کو ڈیڑھ لاکھ مارجن سے زیادہ اچھی طرح دیکھیں: سیدھی لائن مصنوعی مستقبل کے خطرے کے گرد شارٹ کٹ نہیں ہے، یہ وہ خطرہ ہے، جو دو اختیارات سے دوبارہ بنایا گیا ہے۔ حقیقی رقم کا ارتکاب کرنے سے پہلے سینڈ باکس ٹریڈنگ میں ان میں سے کسی کی مشق کریں ( OpenAlgo میں تجزیہ کار وضع)۔</p>\n<p>اب آپ نے دیکھا ہے کہ آپشنز فیوچر میں کیسے دوبارہ جمع ہوتے ہیں اور کس طرح فروخت شدہ کال ہولڈنگ کو انکم ٹریڈ میں بدل دیتی ہے۔ یہ حقیقی، فیوچر-گریڈ رسک کے ساتھ ڈھانچے ہیں، متعین خطرے کے اسپریڈز سے اسپیکٹرم کے مخالف سرے پر۔ آگے کے ابواب میں ہم پوزیشنز بنانے سے ان کا دفاع کرتے ہیں، اس سوال سے شروع کرتے ہیں جس کا ہر تاجر کو سامنا ہوتا ہے، جب کوئی تجارت آپ کے خلاف ہو تو آپ کیا کرتے ہیں۔</p>\n<h2 id=\"key-takeaways\">اہم نکات</h2>\n<ul>\n<li>اے <strong>مصنوعی مستقبل</strong> دو اختیارات سے مستقبل کی تعمیر نو کرتا ہے: a <strong>لمبی کال کے علاوہ شارٹ پٹ</strong> ایک طویل مستقبل ہے، a <strong>مختصر کال کے علاوہ ایک لمبی پوٹ</strong> ایک مختصر مستقبل ہے.</li>\n<li>دی <strong>طویل مصنوعی</strong> تقریباً 8,496 روپے کا خالص ڈیبٹ لاگت آتا ہے، یہاں تک کہ وقفے وقفے سے <strong>24,181</strong>، بغیر کسی حد کے بڑھتا ہے، اور اس کے نیچے 1,571,746 روپے کے نقصان کی طرف آتا ہے۔</li>\n<li>دی <strong>مختصر مصنوعی</strong> یہ اس کا آئینہ ہے، ایک چھوٹا سا کریڈٹ جس کا محدود حصہ 1,571,746 روپے کا بہترین کیس ہے اور ایک <strong>لامحدود</strong> ریلی میں نقصان</li>\n<li>دونوں لے جاتے ہیں۔ <strong>فیوچر گریڈ، دو طرفہ خطرہ</strong>1.6 لاکھ روپے سے زیادہ مارجن کو اچھی طرح سے روکیں، اور تقریباً کوئی وقت کی قدر نہیں رکھتے، اس لیے T+0 اور ایکسپائری لائنیں اوورلیپ ہو جاتی ہیں۔</li>\n<li>دی <strong>احاطہ کال</strong> ایک لمبی ہولڈنگ کے علاوہ فروخت ہونے والی زیادہ کال ہے: مستحکم پریمیم آمدنی، a <strong>الٹا بند</strong>، اور ایک اب بھی بڑا منفی پہلو، جو اسے ایک بناتا ہے۔ <strong>مصنوعی شارٹ پٹ</strong>.</li>\n<li>ان میں سے کوئی بھی خطرے سے دوچار نہیں ہے، اس لیے وہ ایک ابتدائی کے لیے اسپریڈز سے آگے ایک قدم پر بیٹھتے ہیں اور ایک حقیقی منفی اقدام کے لیے اس کا سائز ہونا چاہیے، اس پرسکون کے لیے کبھی نہیں جس کی آپ امید کرتے ہیں۔</li>\n</ul>\n","toc":[{"level":2,"text":"ایک لائن کا خیال","id":"the-one-line-idea"},{"level":2,"text":"طویل مصنوعی مستقبل، روپیہ بہ روپیہ","id":"the-long-synthetic-future-rupee-by-rupee"},{"level":2,"text":"تین نمبر، اور وہ کہاں سے آتے ہیں۔","id":"the-three-numbers-and-where-they-come-from"},{"level":2,"text":"میعاد ختم ہونے پر نتائج پر چلنا","id":"walking-the-outcomes-at-expiry"},{"level":2,"text":"مختصر مصنوعی مستقبل","id":"the-short-synthetic-future"},{"level":2,"text":"ڈھکی ہوئی کال","id":"the-covered-call"},{"level":2,"text":"دشاتمک نظریہ رکھنے کے تین طریقے","id":"three-ways-to-hold-a-directional-view"},{"level":2,"text":"اہم نکات","id":"key-takeaways"}],"imgCount":2,"hasContent":true},"22":{"html":"<p>اس کورس میں ہر حکمت عملی پر کچھ نہ کچھ لاگت آتی ہے۔ ڈیبٹ اسپریڈ آپ کے ادا کردہ پریمیم کی لاگت کرتا ہے۔ کریڈٹ کی حکمت عملی ایسا لگتا ہے جیسے یہ آپ کو ادائیگی کرتی ہے، پھر بھی یہ خاموشی سے پس منظر میں کسی بڑی چیز کا مطالبہ کرتی ہے: <strong>مارجن</strong>. گلا بیچیں، آئرن کنڈور چلائیں، یا مصنوعی میں فیوچر ٹانگ پکڑیں، اور جب تک پوزیشن کھلی ہے ایکسچینج رقم کی رقم کو روکتا ہے۔ ایک ابتدائی کے لیے یہ اکثر پورے موضوع کا سب سے بڑا تعجب ہوتا ہے۔ آپ نے 10,000 روپے کا کریڈٹ جمع کیا، تو آپ کے اکاؤنٹ میں اچانک ایک لاکھ سے زیادہ کیوں منجمد ہو گئے؟ یہ باب اس کا جواب دیتا ہے، اور پھر آپ کو وہ حصہ دکھاتا ہے جسے زیادہ تر نئے تاجر کبھی دریافت نہیں کرتے: آپ کو ہمیشہ نقد رقم کو منجمد کرنے کی ضرورت نہیں ہے۔ آپ ان چیزوں کو گروی رکھ سکتے ہیں جو آپ کے پاس پہلے سے ہیں۔</p>\n<h2 id=\"why-a-short-position-blocks-margin\">مختصر پوزیشن مارجن کو کیوں روکتی ہے۔</h2>\n<p>آپشن کا خریدار ایک پریمیم ادا کرتا ہے اور پھر ختم ہو جاتا ہے۔ زیادہ سے زیادہ جو وہ کھو سکتے ہیں وہ پہلے ہی ادا کر دیا جاتا ہے، لہذا ایکسچینج کو ان سے مزید سیکیورٹی کی ضرورت نہیں ہے۔ بیچنے والا اس کے برعکس ہے۔ وہ ایک چھوٹا پریمیم اکٹھا کرتے ہیں لیکن ایک بڑی، کبھی کبھی کھلی ذمہ داری قبول کرتے ہیں، اس لیے ایکسچینج ڈپازٹ کا مطالبہ کرتا ہے، <strong>مارجن</strong>, سیکورٹی کے طور پر کہ بیچنے والا اصل میں ادائیگی کر سکتا ہے اگر تجارت غلط ہو جائے. ہر فیوچر ٹانگ کا بھی یہی حال ہے۔</p>\n<p>یہ حاشیہ کوئی ایک صوابدیدی شخصیت نہیں ہے۔ اسے دو حصوں سے بنایا گیا ہے۔</p>\n<ul>\n<li><strong>SPAN مارجن</strong> بنیادی ہے. SPAN ایکسچینج کا رسک ماڈل ہے، اور یہ وہ رقم ہے جس کا حساب یہ آپ کی صحیح پوزیشن میں ایک دن کے بدترین اقدام کو پورا کرنے کے لیے کرتا ہے۔ ایک چھوٹا گلا، جو کسی بھی طرح سے کسی بڑی حرکت پر ہار سکتا ہے، ایک بڑا SPAN نمبر کھینچتا ہے۔ ایک متعین خطرے والے لوہے کا کنڈور، جہاں پر خریدے گئے پروں کے نقصان کو پورا کیا جاتا ہے، وہ بہت چھوٹا بناتا ہے۔</li>\n<li><strong>نمائش کا مارجن</strong> ایک اضافی بفر ہے جو ایکسچینج SPAN کے اوپر جوڑتا ہے، جو کہ ایک غیر معمولی پرتشدد دن کے لیے دوسرا کشن ہے۔</li>\n</ul>\n<p>دونوں کو شامل کریں اور آپ کے پاس ہے۔ <strong>کل مارجن درکار ہے۔</strong>، وہ رقم جو آرڈر کے گزرنے سے پہلے آپ کے اکاؤنٹ میں بلاک ہونا ضروری ہے اور آپ کے بند ہونے تک بلاک رہتی ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک مختصر یا فیوچر پوزیشن بلاک مارجن SPAN پلس ایکسپوزر کے برابر ہے۔ اس کا آپ کے جمع کردہ چھوٹے کریڈٹ سے کوئی لینا دینا نہیں ہے۔ یہ اس خطرے کی عکاسی کرتا ہے جو آپ اٹھا رہے ہیں، یہی وجہ ہے کہ ایک ننگا چھوٹا گلا اسی بنیادی کے متعین خطرے والے کنڈور سے کہیں زیادہ جڑتا ہے۔</p>\n</div></div>\n<p>OpenAlgo میں شامل ہے۔ <strong>مارجن کیلکولیٹر</strong> تو اس میں سے کوئی بھی اندازہ نہیں ہے۔ آپ اسے اپنی حکمت عملی کی ٹانگیں، ہر ایک کا پہلو، اور مقدار دیتے ہیں، اور یہ SPAN مارجن، نمائش کا مارجن، اور مطلوبہ کل واپس کرتا ہے۔ ملٹی ٹانگ آرڈر دینے سے پہلے اسے چیک کرنا آپ کو سیکنڈوں میں بتاتا ہے کہ آیا پوزیشن آپ کے اکاؤنٹ میں فٹ ہے یا نہیں، اور یہ متعین خطرے والے ڈھانچے کے بارے میں ایک خوشگوار حقیقت کو بھی ظاہر کرتا ہے: کیونکہ ایکسچینج آپ کے خریدے ہوئے پروں کو دیکھ سکتا ہے، اس لیے یہ آپ سے کنڈور یا تتلی کے لیے اس کے اندر بیٹھنے والے ننگے شارٹ کے مقابلے میں بہت کم مارجن وصول کرتا ہے۔ متعین خطرے کو روکنا سستا ہے، نہ صرف محفوظ۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>مارجن کیلکولیٹر کو پوری حکمت عملی پر چلائیں، ٹانگ بہ ٹانگ نہیں۔ ایکسچینج مشترکہ پوزیشن کو مارجن کرتا ہے، لہذا ایک ہیجڈ ڈھانچہ جیسے لوہے کے کنڈور کو اس کے حقیقی، محدود خطرے پر چارج کیا جاتا ہے۔ علیحدہ ٹانگوں کے طور پر اس کی قیمت کا تعین کرنا آپ کو درحقیقت ایک طرف رکھنے کی ضرورت کو بری طرح سے بڑھا دے گا۔</p>\n</div></div>\n<h2 id=\"the-cash-drag-problem\">کیش ڈریگ کا مسئلہ</h2>\n<p>یہاں عملی درد ہے۔ فرض کریں کہ انڈیکس پر ایک مختصر گلا گھونٹنے کے لیے تقریباً 1,50,000 روپے مارجن کی ضرورت ہے۔ اگر آپ کو 1,50,000 روپے پورے مہینے کے لیے بیکار کیش میں رکھنا پڑتے ہیں، تو وہ نقد آپ کو کچھ نہیں کماتا ہے جب تک کہ یہ سیکیورٹی کے طور پر موجود ہے۔ متعدد عہدوں پر چلنے والے ایک فعال تاجر کے لیے، لاکھوں روپے منجمد اور غیر پیداواری ہو سکتے ہیں۔ یعنی <strong>نقد گھسیٹیں</strong>، اور یہ ایک حقیقی قیمت ہے حالانکہ کوئی رقم ضائع نہیں ہوئی ہے۔</p>\n<p>سسٹم کے پاس سمجھدار جواب ہے۔ زیادہ تر تاجر پہلے سے ہی اثاثوں، حصص، فنڈز، بانڈز کے مالک ہیں، جو ڈیمیٹ اکاؤنٹ میں بیٹھنے کے علاوہ کچھ نہیں کر رہے ہیں۔ کیوں نہ ان اثاثوں کو بیکار نقدی کی بجائے سیکیورٹی کے طور پر کھڑا ہونے دیا جائے؟ بالکل وہی ہے جو عہد کرنے کی اجازت دیتا ہے۔</p>\n<h2 id=\"pledging-collateral-instead-of-cash\">نقدی کے بجائے ضمانت کا وعدہ کرنا</h2>\n<p>جب آپ <strong>عہد</strong> ایک سیکورٹی، آپ اپنے ڈپازٹری سے کہتے ہیں کہ اسے تجارت کے لیے ضمانت کے طور پر نشان زد کرے۔ اثاثہ کبھی بھی آپ کے ڈیمیٹ اکاؤنٹ کو نہیں چھوڑتا، آپ کو اب بھی اس کا منافع یا سود ملتا ہے، اور آپ اب بھی اس کے مالک ہیں۔ اسے صرف سیکورٹی کے طور پر جھنڈا لگایا جاتا ہے، اور بدلے میں اس کی قیمت آپ کے تجارتی مارجن میں شامل کر دی جاتی ہے۔ اس کے بعد آپ اس مارجن کو آپشنز بیچنے یا مساوی کیش پارک کیے بغیر فیوچر رکھنے کے لیے استعمال کر سکتے ہیں۔</p>\n<p>ایک کیچ ہے، اور یہ منصفانہ ہے۔ ایکسچینج آپ کو گروی رکھی ہوئی سیکیورٹی کی پوری قیمت نہیں دے گا، کیونکہ سیکیورٹی خود قیمت میں گر سکتی ہے۔ یہ لاگو ہوتا ہے a <strong>بال کٹوانے</strong>، مارکیٹ ویلیو میں رعایت، اور صرف بال کٹوانے کے بعد کی رقم مارجن کے طور پر شمار ہوتی ہے۔ ایک مستحکم، مائع اثاثہ ایک چھوٹا سا بال کٹ جاتا ہے. ایک غیر مستحکم اسٹاک کو ایک بڑا مل جاتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/diagram-collateral.png\" alt=\"گروی رکھنا آپ کے پاس پہلے سے موجود سیکیورٹی کو مارجن کے طور پر کھڑا کرنے دیتا ہے، ایکسچینج اس کی مارکیٹ ویلیو کو بال کٹوانے سے کم کرتا ہے، اور کم شدہ رقم قابل استعمال مارجن بن جاتی ہے، اس اصول کے ساتھ کہ کل مارجن کا تقریباً نصف اب بھی نقد یا نقد مساوی سے پورا ہونا چاہیے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>گروی رکھنا آپ کے پاس پہلے سے موجود سیکیورٹی کو مارجن کے طور پر کھڑا کرنے دیتا ہے، ایکسچینج اس کی مارکیٹ ویلیو کو بال کٹوانے سے کم کرتا ہے، اور کم شدہ رقم قابل استعمال مارجن بن جاتی ہے، اس اصول کے ساتھ کہ کل مارجن کا تقریباً نصف اب بھی نقد یا نقد مساوی سے پورا ہونا چاہیے۔</figcaption></figure>\n<p>ایک سادہ سی مثال اسے ٹھوس بناتی ہے۔ ایک بڑے اسٹاک کے 1,00,000 روپے گروی رکھیں اور شاید بیس سے پچیس فیصد بال کٹوانے کے بعد، آپ کو قابل استعمال مارجن کے تقریباً 75,000 سے 80,000 روپے مل سکتے ہیں۔ سرکاری بانڈ یا لیکویڈ فنڈ کے 1,00,000 روپے گروی رکھیں اور بال کٹوانے کی رقم چھوٹی ہے، لہذا آپ کو تقریباً 95،000 روپے یا اس سے زیادہ ملیں گے۔ ضمانت جتنا محفوظ ہے، اتنا ہی زیادہ مارجن دیتا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>بال کٹوانے کا فرق اس کے درمیان ہوتا ہے کہ سیکیورٹی کی کیا قیمت ہے اور اسے مارجن کے طور پر شمار کرنے کی کیا اجازت ہے۔ یہ تبادلے کو فروخت کیے جانے سے پہلے قیمت میں گرنے والے کولیٹرل سے بچاتا ہے۔ اثاثہ جتنا زیادہ مستحکم ہوگا، بالوں کا کٹنا اتنا ہی چھوٹا ہوگا، یہی وجہ ہے کہ G-Sec کسی ایک اسٹاک کی نسبت کولیٹرل کے طور پر مزید پھیلا ہوا ہے۔</p>\n</div></div>\n<h2 id=\"the-cash-component-rule\">نقد جزو کا اصول</h2>\n<p>گروی رکھی ہوئی سیکیورٹیز طاقتور ہوتی ہیں، لیکن وہ پورا کام نہیں کر سکتیں۔ تبادلے کا تقاضا ہے۔ <strong>آپ کے کل مارجن کا کم از کم نصف نقد یا نقد مساوی میں پورا کیا جائے۔</strong>، باقی کے ساتھ غیر نقد کولیٹرل جیسے اسٹاک اور ایکویٹی فنڈز میں اجازت دی جاتی ہے۔ یہ نقد جزو کا اصول ہے، اور یہ اس لیے موجود ہے کہ اگر کوئی پوزیشن آپ کے خلاف چلتی ہے، تو روزانہ کے نقصان کو پورا کرنے کے لیے حقیقی نقد رقم موجود ہے، نہ کہ صرف گروی رکھے ہوئے حصص جو کہ خود گر رہے ہیں۔</p>\n<p>نقد کے مساوی وہ قریب قریب نقدی اشیاء ہیں جو ایکسچینج اس مقصد کے لیے تقریباً نقدی کی طرح برتاؤ کرتی ہے، جس میں آسانی کے ساتھ کچھ ایسے اثاثے شامل ہوتے ہیں جو آپ گروی رکھ سکتے ہیں، جیسے کہ سرکاری سیکیورٹیز، خودمختار گولڈ بانڈز اور مائع فنڈز۔ لہذا ایک سمجھدار کولیٹرل مکس غیر نقد نصف کے لئے گروی رکھے ہوئے اسٹاک کی ایک پرت اور نقد کے مساوی نصف کے لئے مائع فنڈز یا G-Secs کی ایک تہہ ہوسکتی ہے۔ اگر آپ نان کیش کولیٹرل پر بہت زیادہ جھکاؤ رکھتے ہیں اور نقد رقم میں کمی کرتے ہیں، تو بروکر شارٹ فال پر سود وصول کرتا ہے، جو خاموشی سے آپ کے منافع کو کھا جاتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>کبھی بھی کسی پوزیشن کو مکمل طور پر گروی رکھے ہوئے اسٹاک کے ساتھ فنڈ نہ کریں۔ کم از کم نصف مارجن نقد یا نقد کے مساوی ہونا چاہیے، اور روزانہ مارک ٹو مارکیٹ نقصانات ہمیشہ نقد میں ڈیبٹ کیے جاتے ہیں۔ بغیر کیش بفر کے بغیر کیش کولیٹرل سے بھری ایک کتاب بالکل وہی اکاؤنٹ ہے جو تشدد والے دن جبری اخراج حاصل کرتا ہے۔</p>\n</div></div>\n<h2 id=\"what-counts-as-collateral-for-f-o\">جو F&amp;O کے لیے ضمانت کے طور پر شمار ہوتا ہے۔</h2>\n<p>اثاثوں کی فہرست جو آپ کو فیوچرز اور آپشنز کے لیے گروی رکھنے کی اجازت ہے، وسیع ہے، جو F&amp;O مارجن کو اتنا لچکدار بنانے کا حصہ ہے۔ F&amp;O کی نمائش کے لیے منظور شدہ ضمانت میں شامل ہیں:</p>\n<ul>\n<li><strong>خودمختار گولڈ بانڈز (SGBs)</strong></li>\n<li><strong>سرکاری سیکیورٹیز (G-Secs)</strong></li>\n<li><strong>میوچل فنڈز</strong></li>\n<li><strong>ETFs</strong></li>\n<li><strong>اسٹاکس</strong> (منظور شدہ، مائع والے)</li>\n<li><strong>REITs</strong> (رئیل اسٹیٹ انویسٹمنٹ ٹرسٹ)</li>\n<li><strong>دعوتیں</strong> (انفراسٹرکچر انویسٹمنٹ ٹرسٹ)</li>\n</ul>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/diagram-collateral-types.png\" alt=\"F&amp;O کے لیے ضامن کے طور پر قبول کیے گئے اثاثے وسیع ہیں، جن میں SGBs، G-Secs، میوچل فنڈز، ETFs، اسٹاکس، REITs اور InvITs شامل ہیں، جبکہ کیش مارکیٹ میں خریداری کے لیے مارجن ٹریڈنگ کی سہولت فی الحال صرف ETFs اور اسٹاکس کو قبول کرتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>F&amp;O کے لیے ضامن کے طور پر قبول کیے گئے اثاثے وسیع ہیں، جن میں SGBs، G-Secs، میوچل فنڈز، ETFs، اسٹاکس، REITs اور InvITs شامل ہیں، جبکہ کیش مارکیٹ میں خریداری کے لیے مارجن ٹریڈنگ کی سہولت فی الحال صرف ETFs اور اسٹاکس کو قبول کرتی ہے۔</figcaption></figure>\n<p>اس فہرست کو پڑھنے کا ایک مفید طریقہ بال کٹوانا ہے۔ سب سے اوپر حکومت کی حمایت یافتہ اور فنڈ کے آلات، SGBs، G-Secs اور مائع فنڈز، مستحکم ہیں اور اکثر چھوٹے بال کٹوانے کے ساتھ آپ کے نقد کے مساوی حصے میں شمار ہوتے ہیں۔ مارکیٹ کی قیمت والے آلات کم ہوتے ہیں، اسٹاک، REITs اور InvITs، بڑے بال کٹواتے ہیں اور بغیر نقدی کی طرف بیٹھ جاتے ہیں۔ دونوں کو ملانے سے آپ کل مارجن اور آپ کے پاس پہلے سے موجود اثاثوں سے نقد جزو کے اصول دونوں کو پورا کر سکتے ہیں۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>آپ ایک متعین خطرے والی پوزیشن چلانا چاہتے ہیں جس کے لیے تقریباً 1,50,000 روپے مارجن کی ضرورت ہے۔ اسے نقد میں منجمد کرنے کے بجائے، آپ تقریباً 1,00,000 روپے مائع فنڈ، جو کہ نقد کے برابر ہے اور اس کی پوری قیمت کے قریب، نقد نصف کو کور کرتے ہوئے گروی رکھتے ہیں، اور آپ تقریباً 1,00,000 روپے کا اسٹاک گروی رکھتے ہیں، جو بال کٹوانے کے بعد تقریباً 75,000 روپے کا غیر نقد مارجن کا اضافہ کرتا ہے۔ ان کے درمیان پوزیشن کو فنڈ دیا جاتا ہے، آپ کا نقد حصہ مطمئن ہے، اور آپ کے بیکار اثاثے آخر کار آپ کے لیے کام کر رہے ہیں۔</p>\n</div></div>\n<h2 id=\"a-different-list-mtf-collateral\">ایک مختلف فہرست: MTF کولیٹرل</h2>\n<p>یہ ایک پڑوسی اصول کو جاننے کے قابل ہے، کیونکہ ابتدائی اکثر دونوں کو الجھا دیتے ہیں۔ دی <strong>مارجن ٹریڈنگ کی سہولت ( MTF)</strong> ایف اینڈ او سے الگ چیز ہے۔ MTF آپ کو کیش مارکیٹ میں جزوی ادھار کی رقم سے حصص خریدنے دیتا ہے، اور اس کی اپنی، قابل قبول ضمانت کی ایک تنگ فہرست ہے۔ صرف MTF نمائش کے لیے <strong>ETFs اور اسٹاک</strong> فی الحال قبول کر رہے ہیں.</p>\n<p>لہذا ایک ہی اسٹاک کو کسی بھی دنیا میں گروی رکھا جا سکتا ہے، لیکن SGBs، G-Secs، میوچل فنڈز، REITs اور InvITs کا وسیع مینو جسے F&amp;O قبول کرتا ہے، آج تمام MTF پر نہیں ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>یہ معاملہ نہیں رہ سکتا۔ مارجن ٹریڈنگ کی سہولت پر ایک SEBI مشاورتی کاغذ نے تبدیلیوں کی تجویز پیش کی ہے، اور اگر اس کی دفعات کو ان کی موجودہ شکل میں منظور کیا جاتا ہے، تو MTF کے لیے قبول کردہ ضامن F&amp;O فہرست سے مماثل ہونے کے لیے وسیع ہو سکتا ہے، جس سے دونوں مؤثر طریقے سے ایک جیسے ہو جائیں گے۔ اس علاقے میں قواعد تیار ہوتے ہیں، لہذا درست فہرستوں کو مستقل قانون کے بجائے موجودہ عمل کے طور پر سمجھیں، اور عہد کرنے سے پہلے تازہ ترین پوزیشن کی تصدیق کریں۔</p>\n</div></div>\n<h2 id=\"the-practical-takeaway\">عملی راستہ</h2>\n<p>کولیٹرل ایک خاموش کارکردگی ہے جو ایک سوچ سمجھ کر آپشن ٹریڈر کو پیسے کو بیکار چھوڑنے والے سے الگ کرتی ہے۔ شارٹ یا فیوچر پوزیشن کا مارجن حقیقی ہے اور اسے SPAN پلس ایکسپوزر کے ذریعے سیٹ کیا گیا ہے، جسے OpenAlgo مارجن کیلکولیٹر آپ کو تجارت کرنے سے پہلے دکھائے گا۔ لیکن آپ کو اس مارجن کو منجمد نقدی کے ساتھ پورا کرنے کی ضرورت نہیں ہے۔ اپنے پاس پہلے سے موجود اثاثوں کو گروی رکھو، بال کٹوانے اور نقد جزو کے اصول کا احترام کریں، اور وہی سرمایہ آپ کے پورٹ فولیو اور آپ کی حکمت عملیوں کو ایک ساتھ مدد دے سکتا ہے۔ لاپرواہی سے استعمال کیا جاتا ہے، لیوریج اور پتلے کیش بفر یہ ہیں کہ اکاؤنٹس کیسے اڑا دیتے ہیں۔ ایک سمجھدار کولیٹرل مکس اور نقد نصف پر ایماندارانہ نظر کے ساتھ استعمال کیا جاتا ہے، مارجن ایک ایسا ٹول بن جاتا ہے جس کا انتظام آپ کو سرپرائز کرنے کے بجائے ہوتا ہے جو آپ کا انتظام کرتا ہے۔ اگلا باب خیال سے مشق کرنے کا عہد کرتا ہے، بال کٹوانے کی ریاضی کے ساتھ، اس سے زیادہ سے زیادہ فائدہ اٹھانے کے لیے دو ترکیبیں، اور احترام کے لیے مارجن کال رسک۔</p>\n","toc":[{"level":2,"text":"مختصر پوزیشن مارجن کو کیوں روکتی ہے۔","id":"why-a-short-position-blocks-margin"},{"level":2,"text":"کیش ڈریگ کا مسئلہ","id":"the-cash-drag-problem"},{"level":2,"text":"نقدی کے بجائے ضمانت کا وعدہ کرنا","id":"pledging-collateral-instead-of-cash"},{"level":2,"text":"نقد جزو کا اصول","id":"the-cash-component-rule"},{"level":2,"text":"جو F&O کے لیے ضمانت کے طور پر شمار ہوتا ہے۔","id":"what-counts-as-collateral-for-f-o"},{"level":2,"text":"ایک مختلف فہرست: MTF کولیٹرل","id":"a-different-list-mtf-collateral"},{"level":2,"text":"عملی راستہ","id":"the-practical-takeaway"}],"imgCount":2,"hasContent":true},"23":{"html":"<p>پچھلے باب میں آپ نے سیکھا کہ آپشنز بیچنا اور فیوچر بلاک مارجن رکھنا، اور یہ کہ آپ نقد منجمد کرنے کے بجائے اپنے پہلے سے موجود اثاثوں کو گروی رکھ کر اس مارجن کو پورا کر سکتے ہیں۔ یہ باب اس کو عملی بناتا ہے۔ عہد رکھنا ایک تاجر کے پاس سب سے زیادہ مفید اور غلط فہمی والے ٹولز میں سے ایک ہے۔ اچھی طرح سے استعمال کیا گیا ہے، یہ آپ کے طویل مدتی پورٹ فولیو کو ایک حصہ فروخت کیے بغیر خاموشی سے آپ کی تجارت کو فنڈ دینے دیتا ہے۔ لاپرواہی سے استعمال کیا جاتا ہے، یہ گرتی ہوئی مارکیٹ کو ان ہی ہولڈنگز کی زبردستی فروخت میں بدل سکتا ہے جسے آپ رکھنا چاہتے تھے۔ آئیے ہم اسے سمارٹ طریقے سے استعمال کرنا سیکھتے ہیں، بال کٹوانے کی ریاضی، پوشیدہ سود کی قیمت، دو حقیقی طور پر مفید چالیں، اور خطرے پر ایماندارانہ نظر۔</p>\n<h2 id=\"what-pledging-actually-does\">عہد کرنا دراصل کیا کرتا ہے۔</h2>\n<p>عہد یہ ہے کہ آپ اپنے بروکر سے کہہ رہے ہیں، یہاں، میرے حصص کو بطور تحفظ رکھو، اور بدلے میں مجھے تجارت کے لیے اضافی مارجن دیں۔ حصص کبھی بھی آپ کے ڈیمیٹ اکاؤنٹ کو نہیں چھوڑتے ہیں۔ آپ اب بھی ان کے مالک ہیں، آپ کو اب بھی ان کے منافع اور بونس ملتے ہیں، وہ صرف ضمانت کے طور پر نشان زد ہیں۔ بدلے میں، ان کی قیمت، جو کمی کے بعد ہم ایک لمحے میں ملیں گے، آپ کے تجارتی مارجن میں شامل کر دی جاتی ہے۔</p>\n<p>ایک سادہ تصویر۔ فرض کریں کہ آپ کے ڈیمیٹ اکاؤنٹ میں تقریباً 2,00,000 روپے مالیت کے شیئرز موجود ہیں۔ ٹریڈنگ فنڈز اکٹھا کرنے کے لیے انہیں بیچنے کے بجائے، آپ انہیں گروی رکھ کر استعمال کے قابل مارجن کے تقریباً 1,70,000 روپے وصول کرتے ہیں۔ یہ مارجن مزید حصص خریدنے، ایف اینڈ او پوزیشن، یا انٹرا ڈے ٹریڈ میں مدد کر سکتا ہے۔ آپ نے تازہ نقدی ڈالے بغیر اور جو کچھ آپ کے پاس ہے اسے فروخت کیے بغیر بڑھایا۔ یہی پوری اپیل ہے۔</p>\n<p>دو چیزیں سامنے جاننے کے قابل ہیں۔ سب سے پہلے، صرف منظور شدہ سیکیورٹیز کو گروی رکھا جاسکتا ہے، ہر اسٹاک اہل نہیں ہوتا ہے۔ حصص کے علاوہ آپ مائع ETFs، مائع فنڈز، ایکویٹی ETFs اور میوچل فنڈز بھی گروی رکھ سکتے ہیں۔ منظور شدہ فہرست آپ کے بروکر کے پلیٹ فارم اور ایکسچینج ویب سائٹ پر رہتی ہے۔ دوسرا، عہد کرنا رسمی کاموں سے خالی نہیں ہے، لیکن یہ جلدی ہے۔ آپ اس کی درخواست کرتے ہیں، اسے ڈپازٹری میں ایک تصدیقی قدم کے ساتھ منظور کرتے ہیں، اور مارجن عام طور پر اسی دن جمع ہوجاتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>جب آپ گروی رکھتے ہیں، تو اثاثہ آپ کا رہتا ہے اور آپ کے ڈیمیٹ اکاؤنٹ میں رہتا ہے، جس کو صرف ضمانت کے طور پر نشان زد کیا جاتا ہے۔ آپ ڈیویڈنڈ اور بونس اپنے پاس رکھتے ہیں اور آپ کسی بھی وقت بغیر کسی لاک اِن کے قرض اتار سکتے ہیں۔ گروی رکھنے سے آپ کو فروخت کیے بغیر تجارتی مارجن ملتا ہے، جو اس کا واحد سب سے بڑا فائدہ ہے۔</p>\n</div></div>\n<h2 id=\"the-haircut-decides-how-much-you-get\">بال کٹوانے سے فیصلہ ہوتا ہے کہ آپ کو کتنا ملتا ہے۔</h2>\n<p>آپ کو مارجن کے طور پر گروی رکھی گئی سیکیورٹی کی پوری مارکیٹ ویلیو کبھی نہیں ملتی ہے۔ تبادلہ لاگو ہوتا ہے a <strong>بال کٹوانے</strong>، مارکیٹ ویلیو میں فی صد کمی، اور بال کٹوانے کے بعد صرف وہ رقم جو قابل استعمال مارجن بن جاتی ہے۔ بال کٹوانے قرض دہندہ کے لیے خود قیمت میں کمی کے خلاف حفاظتی بفر ہے۔</p>\n<p>ایک مثال اسے ٹھوس بناتی ہے۔ 20 فیصد بال کٹوانے کے ساتھ 10,000 روپے کی سیکیورٹی گروی رکھیں، اور آپ کو قابل استعمال مارجن کے طور پر 8,000 روپے ملیں گے۔ دوسرے 2,000 روپے بفر کے طور پر واپس رکھے گئے ہیں۔ بال کٹوانے ہر اثاثے کے لیے یکساں نہیں ہوتے۔ مستحکم، مائع آلات میں چھوٹے بال کٹوانے ہوتے ہیں، جب کہ پرخطر، اتار چڑھاؤ والے اسٹاک میں بڑے ہوتے ہیں، کیونکہ ایک اتار چڑھاؤ والا اسٹاک بروکر کے فروخت کرنے سے پہلے مزید گر سکتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/diagram-haircut-ladder.png\" alt=\"بال کٹوانے سے یہ طے ہوتا ہے کہ ایک عہد آپ کو کتنا مارجن دیتا ہے: نقد ETFs میں تقریباً 6 فیصد کا چھوٹا ہیئر کٹ ہوتا ہے لہذا آپ کو مارجن کے طور پر تقریباً 94 فیصد، حکومت کے تعاون سے چلنے والے آلات تقریباً 10 فیصد، اور اتار چڑھاؤ والے اسٹاک ایک بڑے، متغیر بال کٹواتے ہیں تاکہ آپ کو نمایاں طور پر کم ملے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>بال کٹوانے سے یہ طے ہوتا ہے کہ ایک عہد آپ کو کتنا مارجن دیتا ہے: نقد ETFs میں تقریباً 6 فیصد کا چھوٹا ہیئر کٹ ہوتا ہے لہذا آپ کو مارجن کے طور پر تقریباً 94 فیصد، حکومت کے تعاون سے چلنے والے آلات تقریباً 10 فیصد، اور اتار چڑھاؤ والے اسٹاک ایک بڑے، متغیر بال کٹواتے ہیں تاکہ آپ کو نمایاں طور پر کم ملے۔</figcaption></figure>\n<p>لہذا آپ کو درحقیقت جو مارجن ملتا ہے اس کا انحصار صرف اثاثے کی قیمت پر نہیں ہوتا بلکہ اس کے بال کٹوانے پر ہوتا ہے، اور وہ بال کٹوانے وقت کے ساتھ بدل سکتے ہیں۔ ایک مستحکم بڑا اسٹاک 9 فیصد کے قریب بال کٹوا سکتا ہے، جب کہ ایک جمپیئر 18 فیصد یا اس سے زیادہ لے سکتا ہے، لہذا وہی 2,00,000 روپے ہولڈنگز آپ کو بہت مختلف مارجن دے سکتے ہیں اس پر منحصر ہے کہ یہ کون سا اسٹاک ہے۔</p>\n<h2 id=\"cash-collateral-versus-non-cash-collateral\">کیش کولیٹرل بمقابلہ غیر نقد ضمانت</h2>\n<p>گروی رکھے ہوئے اثاثے دو بالٹیوں میں آتے ہیں، اور فرق دونوں کے لیے اہمیت رکھتا ہے کہ آپ کتنا کر سکتے ہیں اور اس کی قیمت کیا ہے۔</p>\n<ul>\n<li><strong>نقد اور نقد کے مساوی ضمانت</strong>: مائع ETFs، مائع فنڈز، سرکاری سیکیورٹیز، خودمختار گولڈ بانڈز اور ٹریژری بل۔ نظام ان کا علاج تقریباً نقدی کی طرح کرتا ہے۔</li>\n<li><strong>غیر نقد یا ایکویٹی کولیٹرل</strong>: عام اسٹاک، ایکویٹی ETFs اور ایکویٹی میوچل فنڈز۔</li>\n</ul>\n<p>یہاں وہ اصول ہے جو ان کو جوڑتا ہے۔ جب آپ کم از کم F&amp;O کے لیے گروی مارجن استعمال کرتے ہیں۔ <strong>کل مارجن کا نصف نقد یا نقد مساوی میں پورا کیا جانا چاہیے۔</strong>، اور دوسرا نصف غیر نقد ہو سکتا ہے۔ یہ آخری باب کا وہی نقد جزو اصول ہے، اور گروی رکھنا وہ جگہ ہے جہاں اس کی قیمت نظر آتی ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>اگر آپ نقد نصف میں کمی کرتے ہیں اور اسے رات بھر کی پوزیشن کے لیے نان کیش کولیٹرل کے ساتھ فنڈ دیتے ہیں، تو ایکسچینج اس کمی پر سود وصول کرتا ہے، فی الحال تقریباً 0.035 فیصد فی دن، جو تقریباً 12.775 فیصد سالانہ ہے۔ بغیر نقدی کے گروی رکھے ہوئے اسٹاک پر مکمل طور پر جھکاؤ اور آپ ہر ایک دن جب پوزیشن کھلی ہے خاموشی سے سود ادا کر رہے ہیں۔</p>\n</div></div>\n<p>ایک فوری نمبر۔ کہتے ہیں کہ کسی پوزیشن کے لیے مارجن کے 1,00,000 روپے کی ضرورت ہے اور آپ کے پاس گروی رکھے ہوئے اسٹاک کے 1,00,000 روپے ہیں لیکن کوئی مائع ضمانت نہیں ہے۔ 50,000 روپے کی نقدی کی ضرورت نہیں ہے، اس لیے اسے آپ کے اسٹاکس سے فنڈ کیا جاتا ہے، اور اس 50,000 روپے کی کمی پر سود تقریباً 17.5 روپے یومیہ ہے۔ فی دن چھوٹا، لیکن یہ اس وقت تک چلتا ہے جب تک پوزیشن کھلی ہے، اور یہ آپ کی واپسی پر خالص ڈریگ ہے۔</p>\n<h2 id=\"trick-one-prefer-liquid-collateral\">ایک چال کریں، مائع کولیٹرل کو ترجیح دیں۔</h2>\n<p>پہلی ذہین عادت یہ ہے کہ آپ غیر مستحکم اسٹاک پر جھکنے کے بجائے جہاں کہیں بھی ہو سکے مائع، نقدی کے مساوی ضامن کو گروی رکھیں۔ اس کی دو واضح وجوہات ہیں۔</p>\n<p>سب سے پہلے سادہ کارکردگی ہے. مائع کولیٹرل کا بال چھوٹا ہوتا ہے، لہذا یہ آپ کو گروی رکھا ہوا فی روپیہ زیادہ مارجن دیتا ہے۔ کیش ETFs میں بال کٹوانے کا صرف 6 فیصد ہو سکتا ہے، جس سے آپ کو تقریباً 94 فیصد مارجن ملتا ہے۔ خودمختار گولڈ بانڈز، گورنمنٹ سیکیورٹیز، لیکویڈ فنڈز اور ٹریژری بل 10 فیصد بال کٹوانے کے ارد گرد بیٹھتے ہیں، جو تقریباً 90 فیصد دیتے ہیں۔ اسٹاک اور ایکویٹی فنڈز، ان کے بڑے اور متغیر بال کٹوانے کے ساتھ، آپ کو کم اور غیر یقینی رقم دیتے ہیں۔</p>\n<p>دوسری وجہ حفاظت ہے۔ جب آپ مستحکم نقد ضمانت کا عہد کرتے ہیں، تو اس کی قیمت بمشکل حرکت کرتی ہے، لہذا آپ کا مارجن برقرار رہتا ہے اور آپ کو کولیٹرل کی طرف سے مارجن کال کا سامنا نہیں ہوتا ہے۔ اس کے بجائے ایک غیر مستحکم اسٹاک گروی رکھو، اور اگر مارکیٹ گرتی ہے، تو آپ کے کولیٹرل کی قیمت بھی گر جاتی ہے۔ آپ کا مارجن سکڑتا ہے، اور آپ کا بروکر آپ سے ٹاپ اپ کرنے کے لیے کہہ سکتا ہے۔ 6 فیصد بال کٹوانے پر 1,00,000 روپے مائع آلے کا گروی رکھیں اور آپ کے پاس مستحکم مارجن 94,000 روپے ہے۔ 20 فیصد بال کٹوانے پر ایک غیر مستحکم اسٹاک کے 1,00,000 روپے گروی رکھیں اور آپ 80,000 روپے سے شروع کریں گے، لیکن اسٹاک میں 20 فیصد کمی سے اس کی قیمت 80,000 روپے تک گر جاتی ہے، اور اس کم قیمت پر بال کٹوانے سے آپ کو صرف 64,000 روپے رہ جاتے ہیں۔ یہ کمی کولیٹرل پر مارجن کال کو متحرک کر سکتی ہے جس کا آپ نے صرف وعدہ کیا تھا، یہاں تک کہ کبھی تجارت بھی نہیں کی۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اگر آپ کے پاس کوئی انتخاب ہے تو اپنے مارجن کے نصف کیش کے لیے مائع کولیٹرل گروی رکھیں اور اتار چڑھاؤ والے اسٹاک کو چھوٹے، غیر نقد ٹاپ اپ کے طور پر رکھیں۔ آپ کو زیادہ مارجن ملتا ہے، آپ کیش شارٹ فال کے سود کی ادائیگی سے گریز کرتے ہیں، اور آپ مارجن کال کو متحرک کرنے کے لیے آپ کے اپنے کولیٹرل کے خطرے کو دور کرتے ہیں۔</p>\n</div></div>\n<h2 id=\"trick-two-the-covered-call\">ٹرک ٹو، کورڈ کال</h2>\n<p>کیا ہوگا اگر آپ کا پورٹ فولیو تمام ایکویٹی ہے اور آپ کے پاس کوئی مائع آلات نہیں ہیں؟ آپ اب بھی a کے ذریعے کام کرنے کے لیے گروی رکھا ہوا اسٹاک رکھ سکتے ہیں۔ <strong>احاطہ کال</strong>جس حکمت عملی سے آپ پہلے ملے تھے۔ خیال یہ ہے کہ آپ ان حصص سے آمدنی حاصل کریں جو آپ کے پاس بہرحال ہیں۔</p>\n<p>فرض کریں کہ آپ 1,318 روپے کے قریب 500 RELIANCE شیئرز کے مالک ہیں، جس کی مالیت تقریباً 6,59,000 روپے ہے۔ آپ انہیں گروی رکھتے ہیں، اور تقریباً 9 فیصد بال کٹوانے کے بعد آپ کو تقریباً 6,00,000 روپے کا مارجن ملتا ہے۔ اس مارجن کے خلاف آپ ایک بہت زیادہ RELIANCE کال فروخت کرتے ہیں، 1360 سٹرائیک تقریباً 16 روپے فی شیئر کے حساب سے، جو آپ کے اکاؤنٹ میں تقریباً 8,000 روپے کا پریمیم ڈالتا ہے۔ اگر RELIANCE 1360 سے اوپر ختم ہوجاتا ہے، تو آپ کے حصص میں اضافہ ہوا ہے اور یہ فائدہ فروخت شدہ کال کو پورا کرتا ہے۔ اگر یہ 1360 سے نیچے ختم ہو جاتی ہے، تو کال بے کار ہو جاتی ہے اور آپ پریمیم کو صرف ان حصص پر آمدنی کے طور پر رکھتے ہیں جو آپ کے پاس تھے قطع نظر اس کے۔ اگرچہ کیش کمپوننٹ لاگت کو یاد رکھیں، چونکہ اگر F&amp;O مارجن کے پیچھے کوئی کیش ٹانگ نہیں ہے، تو شارٹ فال پر سود تب تک لاگو ہوتا ہے جب تک کہ شارٹ کال کھلی ہو۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>ایک کورڈ کال ایک تمام ایکویٹی پورٹ فولیو کو گروی رکھنے کے دوران کمانے کا قدرتی طریقہ ہے۔ آپ کوئی نئی دشاتمک شرط نہیں لے رہے ہیں، آپ اسٹرائیک کے اوپر اوپر کی طرف کرائے پر لے رہے ہیں جسے آپ بہرحال بیچ کر خوش ہوں گے، اور اس کے لیے پریمیم جمع کر رہے ہیں۔</p>\n</div></div>\n<h2 id=\"how-you-pledge-and-the-real-risk\">آپ کیسے عہد کرتے ہیں، اور اصل خطرہ</h2>\n<p>میکانکس سیدھے ہیں۔ اپنے بروکر کے پلیٹ فارم پر آپ اپنے ہولڈنگز پر جاتے ہیں، گروی رکھنے کے لیے اسٹاک اور مقدار کا انتخاب کرتے ہیں، اور درخواست جمع کراتے ہیں۔ ڈیپازٹری میں منظوری کے مرحلے کے بعد مارجن اسی دن جمع ہو جاتا ہے، عام طور پر چند منٹوں میں۔ غیر گروی رکھنا اسی راستے کی پیروی کرتا ہے اور مفت ہے، اور اگر آپ صرف گروی رکھے ہوئے اسٹاک کو فروخت کرتے ہیں تو یہ فروخت کے حصے کے طور پر خود بخود غیر گروی ہو جاتا ہے۔ عین مطابق اسکرینیں بروکر کے لحاظ سے مختلف ہوتی ہیں، لیکن شکل ہر جگہ ایک جیسی ہوتی ہے۔</p>\n<p>اب خطرہ، کیونکہ عہد کرنا دونوں طریقوں کو کاٹتا ہے۔ خطرہ مکمل طور پر عہد میں رہتا ہے۔ <strong>غیر مستحکم، غیر نقد</strong> ضمانت اور پھر اس کے خلاف تجارت۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/diagram-pledge-margincall.png\" alt=\"غیر مستحکم اسٹاک کو گروی رکھنے کا خطرہ: اگر اس کی قیمت گرتی ہے تو بال کٹوانے کو نئی کم قیمت پر لاگو کیا جاتا ہے، آپ کا قابل استعمال مارجن پوزیشن کی ضرورت سے نیچے گر جاتا ہے، بروکر مارجن کال جاری کرتا ہے، اور اگر آپ اسے فنڈ نہیں دے سکتے تو کمی کو پورا کرنے کے لیے گروی رکھے ہوئے حصص فروخت کیے جاتے ہیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>غیر مستحکم اسٹاک کو گروی رکھنے کا خطرہ: اگر اس کی قیمت گرتی ہے تو بال کٹوانے کو نئی کم قیمت پر لاگو کیا جاتا ہے، آپ کا قابل استعمال مارجن پوزیشن کی ضرورت سے نیچے گر جاتا ہے، بروکر مارجن کال جاری کرتا ہے، اور اگر آپ اسے فنڈ نہیں دے سکتے تو کمی کو پورا کرنے کے لیے گروی رکھے ہوئے حصص فروخت کیے جاتے ہیں۔</figcaption></figure>\n<p>ایک مثال کے ذریعے چلیں. آپ 2,00,000 روپے مالیت کے RELIANCE شیئرز گروی رکھتے ہیں اور، 9 فیصد بال کٹوانے کے بعد، تقریباً 1,82,000 روپے مارجن وصول کرتے ہیں، جسے آپ F&amp;O پوزیشن کے لیے استعمال کرتے ہیں۔ پھر RELIANCE 10 فیصد گرتا ہے، اس لیے آپ کا کولیٹرل اب 1,80,000 روپے کا ہے، اور اس پر 9 فیصد بال کٹوانے سے صرف 1,63,800 روپے کا مارجن رہ جاتا ہے۔ اب آپ کے پاس تقریباً 18,200 روپے کی کمی ہے۔ بروکر ایشو کرتا ہے۔ <strong>مارجن کال</strong>، آپ سے اس رقم کو نقد رقم میں شامل کرنے یا مزید ضمانت دینے کے لیے کہہ رہا ہے۔ اگر آپ ایسا نہیں کر سکتے ہیں، تو بروکر آپ کے گروی رکھے ہوئے کافی حصص بازار کی موجودہ قیمت پر فروخت کر دے گا تاکہ فرق کو پورا کیا جا سکے۔ یہ زبردستی فروخت حصص کو نقصان میں بند کر دیتی ہے اور آپ کی طویل مدتی ہولڈنگ کو سکڑ دیتی ہے۔ لہذا ایک برا دن آپ کو دو بار خرچ کر سکتا ہے، ایک بار تجارت پر اور ایک بار پورٹ فولیو پر جس کا مطلب آپ کو کبھی فروخت کرنا نہیں تھا۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>غیر مستحکم اسٹاک کو گروی رکھنا اور اس کے خلاف تجارت کرنا آپ کے خطرے کو دوگنا کردیتا ہے۔ گرتی ہوئی مارکیٹ آپ کی F&amp;O پوزیشن کو نقصان پہنچا سکتی ہے اور آپ کا گروی رکھا ہوا ضامن سکڑ سکتا ہے، اور اگر آپ نتیجے میں مارجن کو پورا نہیں کر سکتے تو بروکر آپ کے حصص کو خراب قیمت پر بیچ دیتا ہے۔ جبری فروخت گروی رکھنے کا اصل خطرہ ہے، بال کٹوانے کا نہیں۔</p>\n</div></div>\n<h2 id=\"so-should-you-pledge\">تو کیا آپ کو عہد کرنا چاہئے؟</h2>\n<p>عہد کرنا حقیقی طور پر طاقتور ہے، لیکن یہ ہر کسی یا ہر صورتحال کے لیے نہیں ہے۔ تین ایماندار ٹیسٹ اس کا فیصلہ کرتے ہیں۔</p>\n<ul>\n<li>گروی رکھنا آپ کو اضافی قوت خرید دیتا ہے، لیکن یہ آپ کے خطرے کو بھی بڑھاتا ہے۔ اگر آپ اسے سنبھالنے کے لیے تیار نہیں ہیں، تو اسے چھوڑ دینا بہتر ہے۔</li>\n<li>مختصر مدت کے مواقع کا تعاقب کرنے والے ایک فعال تاجر کے لیے، وعدہ کرنا ایک مفید ٹول ہے۔ ایک طویل مدتی سرمایہ کار کے لیے جو محض رکھنا چاہتا ہے، اس سے ایک خطرہ بڑھ جاتا ہے جس کی انہیں ضرورت نہیں ہے۔</li>\n<li>سخت سٹاپ نقصانات اور نظم و ضبط کے ساتھ پوزیشن کی سائزنگ کے ساتھ ہی وعدہ کرنا معنی رکھتا ہے۔ ان کے بغیر، یہ چھوٹی غلطیوں کو بڑی غلطیوں میں بدل دیتا ہے۔</li>\n</ul>\n<p>ایک واضح رسک پلان کے اندر استعمال کیا جاتا ہے، وعدہ کرنے سے آپ کے پہلے سے موجود اثاثوں سے لیکویڈیٹی کھل جاتی ہے اور آپ کے پورٹ فولیو اور آپ کی حکمت عملیوں کو ایک ہی وقت میں کام کرنے دیتا ہے۔ ایک کے بغیر استعمال کیا جاتا ہے، یہ خاموشی سے مارکیٹ کی معمول کی کمی کو آپ کے ہولڈنگز کے مستقل نقصان میں تبدیل کر سکتا ہے۔ فنڈنگ ​​سائیڈ کو اب سمجھ آنے کے بعد، اگلا باب اس طرف موڑتا ہے کہ جب آپ کا مارجن کم سے کم، مارجن پنالٹیز کی دنیا سے کم ہو جاتا ہے تو کیا ہوتا ہے۔</p>\n","toc":[{"level":2,"text":"عہد کرنا دراصل کیا کرتا ہے۔","id":"what-pledging-actually-does"},{"level":2,"text":"بال کٹوانے سے فیصلہ ہوتا ہے کہ آپ کو کتنا ملتا ہے۔","id":"the-haircut-decides-how-much-you-get"},{"level":2,"text":"کیش کولیٹرل بمقابلہ غیر نقد ضمانت","id":"cash-collateral-versus-non-cash-collateral"},{"level":2,"text":"ایک چال کریں، مائع کولیٹرل کو ترجیح دیں۔","id":"trick-one-prefer-liquid-collateral"},{"level":2,"text":"ٹرک ٹو، کورڈ کال","id":"trick-two-the-covered-call"},{"level":2,"text":"آپ کیسے عہد کرتے ہیں، اور اصل خطرہ","id":"how-you-pledge-and-the-real-risk"},{"level":2,"text":"تو کیا آپ کو عہد کرنا چاہئے؟","id":"so-should-you-pledge"}],"imgCount":2,"hasContent":true},"24":{"html":"<p>اب آپ جانتے ہیں کہ ایک پوزیشن کتنے مارجن کو روکتی ہے اور اسے گروی رکھ کر کیسے فنڈ کرنا ہے۔ حاشیہ کی کہانی کا آخری ٹکڑا وہ ہوتا ہے جب آپ مختصر ہوجاتے ہیں۔ ایکسچینج صرف ایک بار آپ کے مارجن کو چیک نہیں کرتا اور اسے بھول جاتا ہے۔ یہ دن بھر، بے ترتیب طور پر، بار بار چیک کرتا ہے، اور جب بھی آپ مطلوبہ کم از کم سے کم ہوتے ہیں تو یہ جرمانہ وصول کرتا ہے۔ یہ سمجھنا کہ یہ چیک کیسے کام کرتے ہیں، اور روزمرہ کے حالات جو ان کو متحرک کرتے ہیں، وہی ہے جو ایک تاجر کو الگ کرتا ہے جو اپنی واپسی کو ایسے شخص سے رکھتا ہے جو خاموشی سے جرمانے میں ان کا خون بہا دیتا ہے۔ یہ باب حاشیہ کے قواعد کے دائیں جانب رہنے کے بارے میں ہے۔</p>\n<h2 id=\"the-minimum-margin-you-must-always-hold\">کم از کم مارجن آپ کو ہمیشہ رکھنا چاہیے۔</h2>\n<p>چونکہ لیوریجڈ پوزیشن آپ کے اکاؤنٹ میں موجود نقدی سے زیادہ کھو سکتی ہے، اس لیے ریگولیٹرز آپ کے بروکر سے ایسی ہر تجارت پر کم از کم مارجن جمع کرنے کا مطالبہ کرتے ہیں، اور یہ کم از کم اختیاری نہیں ہے۔ رقم کی وضاحت ایکسچینج سے ہوتی ہے، بروکر نہیں۔</p>\n<ul>\n<li>کے لیے <strong>مساوات</strong>، کم از کم کہا جاتا ہے۔ <strong>VARپلس ELM</strong> (خطرے کی قیمت کے علاوہ انتہائی نقصان کا مارجن)۔</li>\n<li>کے لیے <strong>ایف اینڈ او</strong>، یہ ہے <strong>SPAN علاوہ نمائش</strong> آپ پہلے ہی جانتے ہیں۔</li>\n</ul>\n<p>چونکہ چوٹی مارجن کے اصول آئے ہیں، یہ کم از کم پوری صنعت میں یکساں ہے۔ ایک بروکر سیلنگ پوائنٹ کے طور پر مزید انٹرا ڈے لیوریج کی پیشکش نہیں کر سکتا۔ آپ جو بھی تجارت کرتے ہیں، وہی کم از کم مارجن لاگو ہوتا ہے، اور آپ سے توقع کی جاتی ہے کہ یہ آپ کے اکاؤنٹ میں موجود ہوگا۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>کم از کم مارجن ایکسچینج کے ذریعہ مقرر کیا جاتا ہے اور ہر جگہ ایک جیسا ہوتا ہے۔ F&amp;O کے لیے یہSPANپلس ایکسپوژر ہے، ایکویٹی کے لیے یہVARپلس ELM ہے۔ آپ کو کم از کم یہ رقم کسی بھی لیوریجڈ پوزیشن کے خلاف رکھنی چاہیے، اور بروکر کے لیے آپ کو کم رکھنے کی اجازت دینے کا کوئی قانونی طریقہ نہیں ہے۔</p>\n</div></div>\n<h2 id=\"peak-margin-the-random-checks\">چوٹی مارجن، بے ترتیب چیک</h2>\n<p>یہ وہ حصہ ہے جو زیادہ تر ابتدائیوں کو حیران کر دیتا ہے۔ ایکسچینج نہ صرف دن کے اختتام پر آپ کے مارجن کو چیک کرتا ہے۔ چوٹی مارجن سسٹم کے تحت، کلیئرنگ کارپوریشن لیتا ہے۔ <strong>متعدد بے ترتیب سنیپ شاٹس</strong> تجارتی دن کے دوران ہر تاجر کی پوزیشن اور مارجن کے علاوہ دن کے اختتام پر ایک چیک۔ آپ نہیں جانتے کہ انٹرا ڈے اسنیپ شاٹس کب گریں گے، اور ایکسچینج کی طرف سے درست تعداد ہمیشہ کے لیے طے کرنے کی بجائے سیٹ کی جاتی ہے۔</p>\n<p>ان میں سے ہر ایک لمحے پر، آپ کے اکاؤنٹ میں مکمل مطلوبہ مارجن ہونا ضروری ہے۔ اگر آپ ایک سنیپ شاٹ میں بھی مختصر ہیں، تو اس وقت کی کمی ریکارڈ کی جاتی ہے، چاہے آپ کے پاس باقی دن کے لیے کافی مارجن ہو یا نہ ہو۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/diagram-margin-snapshots.png\" alt=\"کلیئرنگ کارپوریشن دن بھر میں کئی بے ترتیب لمحات میں آپ کے مارجن کو چیک کرتی ہے اور ساتھ ہی دن کے آخر میں بھی چیک کرتی ہے، اور ان میں سے کسی ایک پر بھی مطلوبہ مارجن کم ہونا ایک کمی ریکارڈ کرتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>کلیئرنگ کارپوریشن دن بھر میں کئی بے ترتیب لمحات میں آپ کے مارجن کو چیک کرتی ہے اور ساتھ ہی دن کے آخر میں بھی چیک کرتی ہے، اور ان میں سے کسی ایک پر بھی مطلوبہ مارجن کم ہونا ایک کمی ریکارڈ کرتا ہے۔</figcaption></figure>\n<p>یہی وجہ ہے کہ ایک تاجر صرف بند ہونے سے پہلے اوپر نہیں جا سکتا اور یہ فرض نہیں کر سکتا کہ وہ محفوظ ہیں۔ بے ترتیب اسنیپ شاٹس کا مطلب ہے کہ کمی سے بچنے کا واحد قابل اعتماد طریقہ یہ ہے کہ پورے دن پورے مارجن کو برقرار رکھا جائے، نہ صرف آسان لمحات پر۔</p>\n<h2 id=\"the-penalty-slabs\">جرمانے کے سلیب</h2>\n<p>جب کوئی کمی پائی جاتی ہے، کسی بھی سنیپ شاٹ پر یا دن کے اختتام پر، اس رقم پر جرمانہ وصول کیا جاتا ہے جس سے آپ کم تھے۔ نرخ درج ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>دن میں کمی</th>\n<th>کمی پر جرمانہ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ایک لاکھ روپے سے کم</td>\n<td>0.5 فیصد</td>\n</tr>\n<tr>\n<td>ایک لاکھ روپے یا اس سے زیادہ</td>\n<td>1 فیصد</td>\n</tr>\n<tr>\n<td>ایک مہینے میں تین بار سے زیادہ</td>\n<td>5 فیصد تک</td>\n</tr>\n</tbody></table>\n<p>لہذا 50,000 روپے کی کمی پر 250 روپے کا جرمانہ ہوتا ہے، جبکہ 2,00,000 روپے کی کمی پر 2,000 روپے کا جرمانہ ہوتا ہے۔ بار بار کم ہونا، ایک مہینے میں تین بار سے زیادہ، اور شرح 5 فیصد تک بڑھ سکتی ہے۔ یہ جرمانے ایکسچینج کے ذریعے جمع کیے جاتے ہیں اور بنیادی تصفیہ گارنٹی فنڈ میں جمع کیے جاتے ہیں۔ یہ آپ کے بروکر کی ایجاد کردہ فیس نہیں ہیں، یہ ایک ریگولیٹری چارج ہیں، اور وہ سیدھے آپ کے ریٹرن سے نکلتے ہیں۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>آپ کی پوری پوزیشن پر نہیں، شارٹ فال پر مارجن کا جرمانہ لگایا جاتا ہے، لیکن اس میں تیزی سے اضافہ ہوتا ہے۔ بار بار ہونے والی چھوٹی چھوٹی خامیاں خاموشی سے ٹریڈنگ اکاؤنٹ کو ختم کر دیتی ہیں، اور ایک مہینے میں تین مثالیں عبور کرنے سے شرح بڑھ جاتی ہے۔ سب سے سستا جرمانہ وہ ہے جسے آپ ہمیشہ مارجن بفر رکھ کر متحرک نہیں کرتے ہیں۔</p>\n</div></div>\n<h2 id=\"upfront-versus-non-upfront-shortfalls\">اپ فرنٹ بمقابلہ غیر پیشگی کمی</h2>\n<p>تمام کمیوں کے ساتھ ایک جیسا سلوک نہیں کیا جاتا ہے، اور فرق یہ فیصلہ کرتا ہے کہ کون ادائیگی کرتا ہے۔</p>\n<ul>\n<li>ایک <strong>پیشگی کمی</strong> آپ کے پاس اس وقت کافی مارجن نہیں ہے جس وقت آپ کسی پوزیشن میں داخل ہوتے ہیں، یا مطلوبہ مارجن آپ کے پہلے سے موجود ہونے کے بعد اس سے بڑھ جاتا ہے۔ دوسرا پہلو یہ ہے کہ بروکرز آپ کو بغیر کسی پیشگی مارجن کے تجارت میں داخل ہونے نہیں دیں گے۔</li>\n<li>اے <strong>غیر پیشگی کمی</strong> ایک مارجن ہے جو آپ کے داخل ہونے کے بعد واجب الادا ہو جاتا ہے۔ سب سے واضح مثال فیوچر پوزیشن پر مارک ٹو مارکیٹ نقصان ہے، جہاں آپ کے پاس اگلے دن تک، ٹی پلس ون، فنڈز لانے کے لیے ہے۔ ایکسپائری ویک ڈیلیوری مارجن اور اسٹاک ڈیریویٹیوز پر دیگر ایڈہاک مارجن بھی یہاں آتے ہیں۔ غیر پیشگی جرمانے آپ کو بھیجے جا سکتے ہیں۔</li>\n</ul>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>عملی طور پر یہ یاد رکھنا نہیں ہے کہ جرمانہ کس بالٹی میں پڑتا ہے، بلکہ یہ سمجھنا ہے کہ مارجن کی کمی سے بچنا ہمیشہ آپ کا مسئلہ ہوتا ہے۔ چاہے بروکر جرمانہ برداشت کرے یا اسے پاس کرے، کمی کا مطلب ہے کہ آپ کی پوزیشنیں کم ہیں اور آپ کے لیے بند ہونے کا خطرہ ہے۔</p>\n</div></div>\n<h2 id=\"the-everyday-situations-that-trip-traders\">روزمرہ کے حالات جو تاجروں کو ٹرپ کرتے ہیں۔</h2>\n<p>جرمانے شاذ و نادر ہی لاپرواہی سے زیادہ فائدہ اٹھانے کا نتیجہ ہوتے ہیں۔ وہ عام طور پر عام حالات سے آتے ہیں جہاں آپ کے پہلے سے تجارت میں ہونے کے بعد مطلوبہ مارجن خاموشی سے بڑھ جاتا ہے۔ تین جاننے کے قابل ہیں۔</p>\n<ul>\n<li><strong>آپ کے خلاف آگے بڑھنے والا ایک مختصر آپشن۔</strong> جب آپ کوئی آپشن بیچتے ہیں، تو فیوچر کی طرح روزانہ مارک ٹو مارکیٹ سیٹلمنٹ نہیں ہوتی ہے۔ اس کے بجائے، جیسے جیسے پوزیشن آپ کے خلاف جاتی ہے، مطلوبہ مارجن آسانی سے بڑھ جاتا ہے۔ اگر آپ کے پاس اضافی مارجن نہیں ہے، تو اسے پیشگی شارٹ فال سمجھا جاتا ہے۔ یہی وجہ ہے کہ ایک مختصر فروخت کنندہ کو ہمیشہ فالتو مارجن رکھنا چاہیے، نہ کہ صرف پہلے دن کی ضرورت کی رقم۔</li>\n<li><strong>ہیج ٹانگ کو بند کرنا۔</strong> ایک ہیجڈ پوزیشن کو ننگے مقام کے مقابلے میں بہت کم مارجن کی ضرورت ہوتی ہے، کیونکہ ایکسچینج دیکھ سکتا ہے کہ خطرہ محدود ہے۔ خریدے گئے پوٹ کے ذریعے محفوظ فیوچر پوزیشن کی تصویر بنائیں، جس کو مل کر صرف ایک چھوٹے مارجن کی ضرورت ہو سکتی ہے۔ پٹ کو بند کریں اور فیوچر پوزیشن اچانک برہنہ ہو جائے، تو اس کا مارجن فوری طور پر واپس اوپر آجاتا ہے۔ اگر آپ کے پاس اتنی بڑی رقم نہیں ہے، تو آپ کو فوری طور پر ہیج ختم ہونے کی کمی ہے۔</li>\n<li><strong>اتار چڑھاؤ میں ایک چھلانگ۔</strong> جب مارکیٹیں اتار چڑھاؤ کا شکار ہو جاتی ہیں، تو ایکسچینج پورے بورڈ میں SPAN اور نمائش کے مارجن کو بڑھا سکتا ہے۔ ایک ایسی پوزیشن جو کل مکمل طور پر حاشیہ پر تھی آج آپ کے اپنے کسی عمل کے بغیر مختصر ہوسکتی ہے۔</li>\n</ul>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>کسی حکمت عملی کے خطرے کو کم کرنے والی ٹانگ کو ہمیشہ آخری ہٹائیں، پہلے کبھی نہیں۔ اگر آپ خطرناک ٹانگ سے پہلے حفاظتی ٹانگ کو بند کر کے آئرن کنڈور یا مستقبل کے محفوظ مستقبل کو کھولتے ہیں تو جو باقی رہ جاتا ہے اس پر مارجن بڑھ جاتا ہے اور آپ دونوں آرڈرز کے درمیان فرق میں کمی کا شکار ہو سکتے ہیں۔ سب سے پہلے ننگے خطرے کو بند کرو، تحفظ آخری.</p>\n</div></div>\n<h2 id=\"staying-penalty-free\">جرمانہ سے پاک رہنا</h2>\n<p>اس میں سے کسی سے بھی بچنا مشکل نہیں ہے، بس کمرے چھوڑنے کی عادت پڑتی ہے۔ جو تاجر کبھی جرمانہ ادا نہیں کرتے وہ صرف وہی ہوتے ہیں جو کبھی بھی اپنے مارجن کے آخری روپے تک تجارت نہیں کرتے۔</p>\n<ul>\n<li>رکھنا a <strong>مارجن بفر</strong>. تجارت کرنے سے پہلے OpenAlgo مارجن کیلکولیٹر چلائیں اور اس بات کی تصدیق کریں کہ آپ ضرورت سے زیادہ آرام سے رکھتے ہیں، لہذا انٹرا ڈے اضافہ آپ کو شارٹ فال میں نہیں ڈالتا۔</li>\n<li>ٹی پلس ون ڈیڈ لائن سے پہلے اگلے دن تک فنڈ فیوچر مارک ٹو مارکیٹ نقصانات۔</li>\n<li>جب آپ مختصر اختیارات رکھتے ہیں، تو بڑھتے ہوئے مارجن کو دیکھیں جیسے ہی پوزیشن آپ کے خلاف جاتی ہے، اور اس کے لیے اضافی فنڈز رکھیں۔</li>\n<li>محفوظ ترتیب میں متعدد ٹانگوں کی حکمت عملیوں کو کھولیں، برہنہ ٹانگ پہلے، ہیج آخری۔</li>\n</ul>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>مارجن جرمانے تقریباً مکمل طور پر قابل گریز ہیں۔ وہ تجارت کے لیے سزا نہیں ہیں، یہ ان کے مارجنڈ ہونے کی قیمت ہیں جب بے ترتیب چیکوں میں سے کوئی ایک لینڈ کرتا ہے۔ ایک بفر رکھیں، وقت پر مستقبل کے نقصانات کو فنڈ کریں، اور ہیجز کو صحیح ترتیب میں کھولیں، اور آپ ان سے کبھی نہیں مل پائیں گے۔</p>\n</div></div>\n<p>اب آپ ہر طرف سے مارجن کو سمجھتے ہیں، یہ کیا ہے، اسے ضمانت اور وعدہ کے ذریعے کیسے فنڈ کرنا ہے، اور جرمانے سے کیسے پاک رہنا ہے۔ یہ اس کورس میں ہر حکمت عملی کے پیچھے عملی مشینری کو مکمل کرتا ہے۔ آخری باب میں ہم میکانکس سے پیچھے ہٹتے ہیں اور اس سوال کا جواب دیتے ہیں کہ یہ سب کچھ اس کے لیے تھا، ایک حقیقی منظر اور ایک حقیقی اکاؤنٹ کے ساتھ، آپ اصل میں کون سی حکمت عملی کا انتخاب کرتے ہیں، اور اس کے آن ہونے کے بعد آپ اس کا انتظام کیسے کرتے ہیں۔</p>\n","toc":[{"level":2,"text":"کم از کم مارجن آپ کو ہمیشہ رکھنا چاہیے۔","id":"the-minimum-margin-you-must-always-hold"},{"level":2,"text":"چوٹی مارجن، بے ترتیب چیک","id":"peak-margin-the-random-checks"},{"level":2,"text":"جرمانے کے سلیب","id":"the-penalty-slabs"},{"level":2,"text":"اپ فرنٹ بمقابلہ غیر پیشگی کمی","id":"upfront-versus-non-upfront-shortfalls"},{"level":2,"text":"روزمرہ کے حالات جو تاجروں کو ٹرپ کرتے ہیں۔","id":"the-everyday-situations-that-trip-traders"},{"level":2,"text":"جرمانہ سے پاک رہنا","id":"staying-penalty-free"}],"imgCount":1,"hasContent":true},"25":{"html":"<p>اب تک اس کورس میں ہر حکمت عملی ایک ایسی چیز رہی ہے جسے آپ نے رکھا ہے اور اسے ختم ہونے تک روک رکھا ہے۔ آپ نے ایک شکل کا انتخاب کیا، جب آپ داخل ہوئے تو آپ کو اپنے زیادہ سے زیادہ نفع اور نقصان کا علم تھا، اور آپ نے انتظار کیا۔ لیکن حقیقی بازار شاذ و نادر ہی بیٹھتے ہیں جب آپ انتظار کرتے ہیں۔ ایک مختصر گلا جو پیر کو آرام سے پیسے سے باہر تھا، جمعرات تک اس کی ایک ہڑتال کے خلاف دباؤ ڈال سکتا ہے۔ ایک بیل پوٹ اسپریڈ انڈیکس کو اپنی فروخت شدہ ہڑتال کی طرف بڑھتے ہوئے دیکھ سکتا ہے۔ جب ایسا ہوتا ہے تو آپ کے پاس پکڑنے اور گھبرانے کے علاوہ تیسرا انتخاب ہوتا ہے: آپ کر سکتے ہیں۔ <strong>ایڈجسٹ کریں</strong>. ایڈجسٹ کرنے کا مطلب ہے پوزیشن کو تبدیل کرنا جب یہ کھلا ہو، اس کا دفاع کرنا، اس کا وقت خریدنا، یا اسے نئے منظر پر دوبارہ مرکوز کرنا۔ یہ باب بنیادی ایڈجسٹمنٹ کی چالوں کو سکھاتا ہے اور اتنا ہی اہم ہے کہ انہیں کب استعمال نہ کیا جائے۔ یہاں کوئی نیا نمبر نہیں، صرف ایک بار لائیو ہونے کے بعد تجارت کو منظم کرنے کا ہنر۔</p>\n<h2 id=\"why-adjust-at-all\">بالکل ایڈجسٹ کیوں؟</h2>\n<p>کسی پوزیشن کو چھونے کی صرف تین دیانتدار وجوہات ہیں جو پہلے سے موجود ہے۔</p>\n<ul>\n<li><strong>نقصان کو کسی چھوٹی یا زیادہ تعریف میں کاٹنا۔</strong> ایک آزمائشی چھوٹی ٹانگ کو متعین خطرے کے پھیلاؤ میں تبدیل کیا جا سکتا ہے، اس لیے بھاگنے والا نقصان محدود ہو جاتا ہے۔</li>\n<li><strong>وقت خریدنے کے لیے۔</strong> اگر آپ کا نظریہ اب بھی درست ہے لیکن اقدام ابھی تک نہیں ہوا ہے، تو آپ تجارت کو بعد میں ایکسپائری میں دھکیل سکتے ہیں اور اسے کام کرنے کے لیے مزید گنجائش دے سکتے ہیں۔</li>\n<li><strong>ایک نئے منظر پر دوبارہ مرکز کرنے کے لیے۔</strong> اگر NIFTY منتقل ہو گیا ہے اور اس پر آپ کا پڑھنا واقعی بدل گیا ہے، تو آپ نئی قیمت کے ارد گرد بیٹھنے کے لیے ڈھانچے کو تبدیل کر سکتے ہیں۔</li>\n</ul>\n<p>غور کریں کہ اس فہرست میں کیا نہیں ہے: اپنے غلط ہونے کا اعتراف کرنے سے بچنے کے لیے ایڈجسٹ کرنا، یا نقصان کو واپس لینے کی امید میں نیا خطرہ شامل کرنا۔ یہ دو طریقے ہیں ایڈجسٹمنٹ اکاؤنٹس کو تباہ کر دیتے ہیں۔ نیچے کی ہر حرکت صرف اس صورت میں مفید ہے جب یہ تین حقیقی وجوہات میں سے ایک کو پورا کرے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایڈجسٹمنٹ جادو صاف کرنے والا نہیں ہے۔ آپ کی ہر تبدیلی کی اپنی لاگت ہوتی ہے، اس کا اپنا نیا خطرہ ہوتا ہے، اور مسدود مارجن پر اس کا اپنا اثر ہوتا ہے۔ ایک اچھی ایڈجسٹمنٹ کا مقصد آپ کے ایماندار موجودہ نقطہ نظر کے مطابق آپ کی پوزیشن کو بہتر بنانا ہے، نہ کہ نقصان اٹھانے سے انکار کرنا۔ اگر آپ کو ایڈجسٹ کرنے کی واحد وجہ یہ ہے کہ آپ کھونے والی تجارت کو بند کرنے کا متحمل نہیں ہوسکتے ہیں، تو صحیح اقدام تقریباً ہمیشہ اسے بند کرنا ہوتا ہے۔</p>\n</div></div>\n<h2 id=\"rolling-out-in-time\">وقت میں رول آؤٹ</h2>\n<p>پہلا اقدام ہے۔ <strong>رول آؤٹ</strong>اور یہ سب سے نرم ہے۔ آپ ایکسپائری کے قریب ٹانگ یا پوری پوزیشن کو بند کرتے ہیں اور بعد میں ایکسپائری میں اسی ڈھانچے کو دوبارہ کھولتے ہیں۔ چونکہ مزید تاریخ والے آپشنز میں زیادہ وقت ہوتا ہے، اس لیے ان کو بیچنے سے عام طور پر اس سے زیادہ کریڈٹ ملتا ہے جتنا آپ نے قریبی کو واپس خریدنے میں خرچ کیا تھا، اس لیے ایک رول آؤٹ اکثر مزید خالص کریڈٹ کے لیے کیا جا سکتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-short-strangle.png\" alt=\"فروخت شدہ 23,950 پوٹ اور 24,150 کال فروخت کے ساتھ ایک NIFTY مختصر گلا جب انڈیکس ان حملوں میں سے کسی ایک کی طرف بڑھتا ہے، تو پورے ڈھانچے کو بعد میں ایکسپائری تک لے جانے سے وقت لگتا ہے اور عام طور پر اضافی کریڈٹ اکٹھا ہوتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>فروخت شدہ 23,950 پوٹ اور 24,150 کال فروخت کے ساتھ ایک NIFTY مختصر گلا جب انڈیکس ان حملوں میں سے کسی ایک کی طرف بڑھتا ہے، تو پورے ڈھانچے کو بعد میں ایکسپائری تک لے جانے سے وقت لگتا ہے اور عام طور پر اضافی کریڈٹ اکٹھا ہوتا ہے۔</figcaption></figure>\n<p>اوپر مختصر گلا گھونٹ لیں۔ فرض کریں کہ NIFTY نے دو ہفتے بہتے ہوئے گزارے ہیں اور اب پریمیم کے زوال میں بہت کم وقت کے ساتھ اوپری ہڑتال پر جھک رہا ہے۔ رول آؤٹ کرنے کا مطلب ہے کہ قریب کے دونوں ٹانگوں کو واپس خریدنا اور اگلی میعاد میں وہی گلا بیچنا۔ آپ مارکیٹ کو رینج میں دوبارہ آباد ہونے کے لیے تجارت کو ایک اور مہینہ دیتے ہیں، اور آپ عام طور پر استحقاق کے لیے مزید پریمیم جمع کرتے ہیں۔ آپ جس خطرے کے خلاف وقت خرید رہے ہیں وہ ختم نہیں ہوتا، لیکن آپ نے نقصان میں مجبور ہونے سے صرف اس وجہ سے انکار کر دیا کہ کیلنڈر ختم ہو گیا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>وقت میں ایک مختصر پوزیشن کو باہر نکالنا کھلے خطرے کو زیادہ دیر تک زندہ رکھتا ہے۔ مختصر گلا گھونٹنے کے اوپر اس کے نقصان پر اب بھی کوئی حد نہیں ہے اور ایک منزل صرف صفر پر ہے، اور اسے بعد میں ختم ہونے میں دھکیلنے کا مطلب ہے کہ آپ کو ایک اضافی مہینے تک اس خطرے کا سامنا ہے۔ صرف اس وقت رول آؤٹ کریں جب آپ کا نظریہ کہ NIFTY رینج میں رہتا ہے حقیقی طور پر برقرار ہے، کبھی بھی کسی نقصان میں تاخیر کرنے کے اضطراری طور پر نہیں جو مارکیٹ آپ کو بتا رہی ہے کہ حقیقت ہے۔</p>\n</div></div>\n<h3 id=\"rolling-a-strike-up-or-down\">اسٹرائیک کو اوپر یا نیچے رول کرنا</h3>\n<p>دوسرا اقدام وہی ایکسپائری رکھتا ہے لیکن <strong>آزمائشی ہڑتال کو قیمت سے دور لے جاتا ہے۔</strong>. اگر NIFTY آپ کی فروخت کردہ 24,150 کال کے خلاف زور دے رہا ہے، تو آپ اس کال کو واپس خرید سکتے ہیں اور ایک اعلی ہڑتال پر ایک نئی کال فروخت کر سکتے ہیں، ایک یا دو قدم آگے بڑھیں۔ آزمائشی ٹانگ اب عمل سے آگے ہے، لہذا یہ کم فوری دباؤ میں ہے۔</p>\n<p>یہ سانس لینے کا کمرہ خریدتا ہے، لیکن یہ شاذ و نادر ہی مفت ہے۔ اسٹرائیک کو بیچنے سے جو پیسے سے آگے ہے اس سے کم پریمیم لاتا ہے جو آپ نے واپس خریدا ہے، اس لیے اسٹرائیک کو اوپر یا نیچے کرنے سے عام طور پر آپ کے اصل کریڈٹ کا کچھ حصہ خرچ ہوتا ہے، اور اگر آپ محتاط نہیں ہیں تو اس سے پوزیشن کا خطرہ بڑھ سکتا ہے۔ اس کے بارے میں سوچنے کا ایماندار طریقہ: آپ اپنی دفاعی لائن کو قیمت سے مزید آگے بڑھانے کے لیے، واپس دیئے گئے کریڈٹ میں تھوڑا سا ادا کر رہے ہیں۔ جب آپ ایسا کرتے ہیں تو، ایک وقت میں ایک طرف تبدیل کریں اور دوسرے کو چھونے سے پہلے پوری ادائیگی کو دوبارہ پڑھیں۔ غیر ٹیسٹ شدہ کال کو جگہ پر چھوڑتے ہوئے جانچ شدہ کال کو اوپر منتقل کرنا اکثر ایک گلا گھونٹنے کو اچھی طرح سے دوبارہ مرکز بناتا ہے، جب کہ دونوں کو ایک ساتھ منتقل کرنا، جلدی میں، یہ ہے کہ کس طرح ایک پرسکون دفاعی ایڈجسٹمنٹ خاموشی سے بالکل نئی، بڑی پوزیشن میں بدل جاتی ہے جس کا آپ نے کبھی انعقاد نہیں کرنا تھا۔</p>\n<h2 id=\"reshaping-the-structure\">ڈھانچے کو نئی شکل دینا</h2>\n<p>چالوں کا تیسرا خاندان خود تجارت کی شکل بدلتا ہے، عام طور پر کھلے خطرے کو متعین خطرے میں تبدیل کرنے کے لیے۔</p>\n<ul>\n<li><strong>پھیلاؤ کو وسیع کریں۔</strong> ایک بیل پوٹ اسپریڈ جس کا تجربہ کیا جا رہا ہے اسے سٹرائیکس کے نچلے جوڑے تک لایا جا سکتا ہے، جس سے انڈیکس کو اسپریڈ کے مکمل طور پر پیسے میں آنے سے پہلے گرنے کی مزید گنجائش مل جاتی ہے۔ ڈھانچہ پوری طرح متعین خطرہ رہتا ہے۔</li>\n<li><strong>آئرن کنڈور بنانے کے لیے مخالف سمت شامل کریں۔</strong> اگر آپ ایک ہی کریڈٹ اسپریڈ چلا رہے ہیں اور ایک طرف مارکیٹ آپ کے حق میں چلی گئی ہے، تو آپ دوسری طرف بھی اسپریڈ بیچ سکتے ہیں۔ بیل پوٹ اسپریڈ پلس بیئر کال اسپریڈ ایک آئرن کنڈور ہے، اور دوسرا اسپریڈ شامل کرنے سے زیادہ کریڈٹ ملتا ہے اور آپ کے منافع بخش زون کو وسیع کیا جاتا ہے۔ یہ صرف اس صورت میں کریں جب نئی طرف حقیقی طور پر قیمت سے بہت دور ہو، اس لیے آپ اس خطرے کے لیے پریمیم جمع کر رہے ہیں جو آپ کو لینے میں آسانی ہو، نہ کہ آپ کی نمائش کو دگنا کرنا۔</li>\n</ul>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/strat-bull-put-spread.png\" alt=\"ایک NIFTY بیل پوٹ اسپریڈ، 24,050 کا پوٹ بیچ رہا ہے اور 23,950 کا پوٹ خرید رہا ہے۔ اگر NIFTY فروخت ہونے والی ہڑتال سے دور ہو جاتا ہے، تو مارکیٹ کے اوپر پھیلے ہوئے ایک بیئر کال کو شامل کرنے سے اس واحد اسپریڈ کو اضافی کریڈٹ کے لیے مکمل آئرن کنڈور میں تبدیل کر دیا جاتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>ایک NIFTY بیل پوٹ اسپریڈ، 24,050 کا پوٹ بیچ رہا ہے اور 23,950 کا پوٹ خرید رہا ہے۔ اگر NIFTY فروخت کی گئی ہڑتال سے دور ہو جاتا ہے، تو مارکیٹ کے اوپر پھیلے ہوئے ایک بیئر کال کو شامل کرنے سے اس واحد اسپریڈ کو اضافی کریڈٹ کے لیے مکمل آئرن کنڈور میں تبدیل کر دیا جاتا ہے۔</figcaption></figure>\n<p>ان سب کے ذریعے چلنے والا دھاگہ یہ ہے کہ آپ اسے برقرار رکھنے یا بحال کرنے کی کوشش کر رہے ہیں، <strong>خطرے کی وضاحت</strong>. پھیلاؤ کو چوڑا کرنا اسے پابند رکھتا ہے۔ اسپریڈ کو لوہے کے کنڈور میں تبدیل کرنے سے دونوں اطراف بندھے رہتے ہیں۔ یہ وہ ایڈجسٹمنٹ ہیں جو ایک ابتدائی طور پر محفوظ طریقے سے کر سکتا ہے، کیونکہ بدترین کیس ہر قدم پر ایک معلوم نمبر رہتا ہے۔</p>\n<h2 id=\"capping-a-runaway-short\">ایک بھگوڑے مختصر کیپنگ</h2>\n<p>سب سے اہم دفاعی اقدام کھلے خطرے کو بند میں تبدیل کرنا ہے۔ اگر آپ کی ننگی ٹانگ چھوٹی ہے، فروخت شدہ کال یا فروخت شدہ پوٹ بغیر کسی تحفظ کے، اور مارکیٹ اس کے خلاف چل رہی ہے، تو آپ کر سکتے ہیں۔ <strong>نقصان کو پورا کرنے کے لیے مزید ایک لمبی ٹانگ ڈالیں۔</strong>. اپنی فروخت شدہ کال کے اوپر ایک کال خریدیں، یا آپ کے فروخت کردہ پوٹ کے نیچے ایک پوٹ، اور نیکڈ شارٹ ایک معروف زیادہ سے زیادہ نقصان کے ساتھ ایک کریڈٹ اسپریڈ بن جاتا ہے۔</p>\n<p>یہ ایک ایڈجسٹمنٹ ہے جو حقیقی طور پر خطرے کو محض منتقل کرنے کے بجائے کم کرتی ہے۔ آپ حفاظتی ونگ خریدنے کے لیے اپنا کچھ کریڈٹ واپس دیتے ہیں، لیکن اس کے بدلے میں لامحدود دم ختم ہو جاتا ہے، اس کی جگہ ایک متعین نمبر لے لیتا ہے جس سے آپ واقعی زندہ رہ سکتے ہیں۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>حفاظتی ونگ خرید کر بھاگنے والے کو مختصر کرنا درست اقدام ہے۔ اضافی پریمیم اکٹھا کرنے اور اپنے نقصان کو کم کرنے کے لیے مزید ننگی چھوٹی ٹانگیں شامل کرنا غلط ہے، اور یہ سب سے عام طریقہ ہے کہ ابتدائی افراد کے لیے قابل انتظام نقصان کو اکاؤنٹ ختم ہونے والے میں بدل دیا جائے۔ قاعدہ آسان ہے: ایڈجسٹمنٹ آپ کے خطرے کو کم کر سکتی ہے یا اسے مستحکم رکھ سکتی ہے، لیکن اسے کبھی بھی ایسی پوزیشن کے کھلے عام خطرے میں اضافہ نہیں کرنا چاہیے جو پہلے ہی کھو رہی ہے۔ ہارنے والے کو بچانے کے لیے خطرہ نہ ڈالیں۔</p>\n</div></div>\n<h2 id=\"adjusting-honestly-in-openalgo\">OpenAlgo میں ایمانداری سے ایڈجسٹ کرنا</h2>\n<p>OpenAlgo کا اسٹریٹجی بلڈر آپ کو ایک روپیہ کرنے سے پہلے ان میں سے ہر ایک کو ماڈل بنانے دیتا ہے، تاکہ آپ یہ دیکھ سکیں کہ ایڈجسٹمنٹ آپ کے نو نمبروں کے ساتھ کیا کرتی ہے۔ ورک فلو جان بوجھ کر ایماندار ہے۔</p>\n<ul>\n<li><strong>بند ٹانگ کو باہر نکلنے کی قیمت کے ساتھ نشان زد کریں۔</strong> جب آپ ٹیسٹ شدہ شارٹ واپس خریدتے ہیں یا قریب مہینے کی ٹانگ کو بند کرتے ہیں، تو اسے بند کرنے کے لیے آپ نے جو قیمت ادا کی تھی اسے ریکارڈ کریں۔ یہ اس ٹانگ پر حاصل شدہ فائدہ یا نقصان کو بند کر دیتا ہے۔</li>\n<li><strong>نئی ٹانگ شامل کریں۔</strong> رولڈ اسٹرائیک کو بیچیں، بعد میں ختم ہونے والے کو کھولیں، یا حفاظتی ونگ کو ڈھانچے میں تازہ ٹانگ کے طور پر خریدیں۔</li>\n<li><strong>میٹرکس اور مارجن کو دوبارہ چیک کریں۔</strong> نیا زیادہ سے زیادہ منافع، نیا زیادہ سے زیادہ نقصان، نئے بریک ایونز، اور سب سے بڑھ کر نئے مارجن کی ضرورت کو پڑھیں۔ ایک ایڈجسٹمنٹ جو آپ کے خطرے کو ٹھیک کرتی ہے لیکن آپ کے مسدود مارجن کو دگنا کر دیتی ہے جو آپ کے اکاؤنٹ میں نہیں ہو سکتی۔</li>\n</ul>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>ہر بار مارجن کو دوبارہ چیک کرنے کی وجہ یہ ہے کہ ایڈجسٹمنٹ اکثر اسے تیزی سے تبدیل کرتی ہے۔ حفاظتی ونگ کے ساتھ ننگے شارٹ کو کیپ کرنا عام طور پر مارجن کو کم کرتا ہے، کیونکہ ایکسچینج اب کھلی ذمہ داری کے بجائے ایک متعین خطرے کے پھیلاؤ کو دیکھتا ہے۔ وقت میں شارٹ آؤٹ کرنا، یا دوسرا شارٹ سائیڈ شامل کرنا، عام طور پر اسے بڑھاتا ہے۔ ایڈجسٹ کرنے کے آرڈر دینے سے پہلے ہمیشہ اس بات کی تصدیق کریں کہ نیا مارجن آپ کے اکاؤنٹ میں آرام سے فٹ بیٹھتا ہے، اور پہلے سینڈ باکس ٹریڈنگ میں پوری ترتیب کی مشق کریں۔</p>\n</div></div>\n<h2 id=\"adjust-or-simply-exit\">ایڈجسٹ کریں یا صرف باہر نکلیں۔</h2>\n<p>سب سے مشکل فیصلہ یہ جاننا ہے کہ کب تجارت کا دفاع کرنا ہے اور کب اسے بند کرنا ہے اور آگے بڑھنا ہے۔ سب سے صاف امتحان ایک سوال پوچھنا ہے: <strong>کیا مقالہ اب بھی درست ہے؟</strong></p>\n<ul>\n<li>اگر آپ کی تجارت کی اصل وجہ اب بھی برقرار ہے، تو آپ کے خلاف اقدام صرف شور ہے، اور پوزیشن اب بھی متعین خطرہ ہے یا اسے بنایا جا سکتا ہے، پھر <strong>ایڈجسٹ کریں</strong>. آپ کسی نہ کسی پیچ کے ذریعے اچھی تجارت کا انتظام کر رہے ہیں۔</li>\n<li>اگر آپ نے جو وجہ درج کی ہے وہ ٹوٹ گئی ہے، تو مارکیٹ نے واضح طور پر آپ کے خلاف ایک سمت کا انتخاب کیا ہے، یا تجارت کا دفاع کرنے کا مطلب یہ ہوگا کہ آپ اس خطرے کو شامل کریں جو آپ برداشت نہیں کر سکتے، پھر <strong>باہر نکلنا</strong>. چھوٹے ہونے پر نقصان اٹھائیں اور اگلے سیٹ اپ کے لیے اپنا سرمایہ رکھیں۔</li>\n</ul>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>دو آزمائشی مختصر گلا گھونٹنا، دو مختلف جوابات۔ سب سے پہلے، NIFTY پتلی، سمت کے بغیر ٹریڈنگ پر آپ کی کال اسٹرائیک کی طرف گھوم رہا ہے، آپ کا نظریہ کہ یہ حد تک رہتا ہے برقرار ہے، اور آپ کے پاس کافی مارجن ہے: آزمائشی کال کو اوپر اور باہر رول کریں، تھوڑا سا مزید کریڈٹ جمع کریں، اور اسے جگہ دیں۔ دوسرے میں، ایک مضبوط رجحان قائم ہوا ہے، NIFTY نے یقین کے ساتھ آپ کی ہڑتال کو صاف طور پر توڑ دیا ہے، اور دفاع کرنے کا واحد طریقہ یہ ہے کہ آگے بڑھتے رہیں: دفاع کے لیے کچھ بھی نہیں ہے۔ اسے بند کریں، طے شدہ نقصان کو قبول کریں، اور رجحان کے خلاف تجارت بند کریں۔</p>\n</div></div>\n<p>اچھی طرح سے ایڈجسٹ کرنا ایک ایسے تاجر کو الگ کرتا ہے جو ایک برا مہینہ زندہ رہتا ہے اور جو نہیں کرتا ہے۔ اپنی تین دیانتدار وجوہات پر قائم رہیں، ہر اقدام کو متعین خطرے کے اندر رکھیں، ہر بار مارجن کو دوبارہ چیک کریں، اور اس پوزیشن میں کبھی بھی خطرہ شامل نہ کریں جو پہلے ہی کھو رہی ہے۔ اس نظم و ضبط کے ساتھ، اس کورس کی حکمت عملی نہ صرف وہ شکلیں بن جاتی ہیں جنہیں آپ پہنتے ہیں، بلکہ وہ تجارتیں جن کو آپ چلا سکتے ہیں۔</p>\n","toc":[{"level":2,"text":"بالکل ایڈجسٹ کیوں؟","id":"why-adjust-at-all"},{"level":2,"text":"وقت میں رول آؤٹ","id":"rolling-out-in-time"},{"level":3,"text":"اسٹرائیک کو اوپر یا نیچے رول کرنا","id":"rolling-a-strike-up-or-down"},{"level":2,"text":"ڈھانچے کو نئی شکل دینا","id":"reshaping-the-structure"},{"level":2,"text":"ایک بھگوڑے مختصر کیپنگ","id":"capping-a-runaway-short"},{"level":2,"text":"OpenAlgo میں ایمانداری سے ایڈجسٹ کرنا","id":"adjusting-honestly-in-openalgo"},{"level":2,"text":"ایڈجسٹ کریں یا صرف باہر نکلیں۔","id":"adjust-or-simply-exit"}],"imgCount":2,"hasContent":true},"26":{"html":"<p>ادائیگی کا چارٹ آپ کو بتاتا ہے کہ تجارت کہاں ختم ہوتی ہے۔ یہ آپ کو یہ نہیں بتاتا ہے کہ تجارت وہاں کے راستے میں کیسا محسوس کرے گی، چاہے وہ کسی پرسکون دن فائدہ اٹھائے یا خون بہے، یا اگر بازار کا موڈ بدل جائے تو اس کا کیا ہوتا ہے۔ اس کے لیے آپ کو مزید دو لینز کی ضرورت ہے۔ سب سے پہلے کا سیٹ ہے۔ <strong>خالص یونانی</strong>, چھوٹی تعداد جو بیان کرتی ہے کہ آپ کی پوزیشن ایک دن سے دوسرے دن تک کیسے سانس لیتی ہے۔ دوسرا ہے <strong>اتار چڑھاؤ کا نظام</strong>, سادہ لیکن طاقتور سوال کہ آیا ابھی اختیارات مہنگے ہیں یا ان کے اپنے ماضی کے نسبت سستے ہیں۔ یہ باب حکمت عملی کے انتخاب میں تجزیاتی پل ہے۔ ایک بار جب آپ کسی پوزیشن کے نیٹ یونانی کو پڑھ سکتے ہیں اور موجودہ مضمر اتار چڑھاؤ کو اس کی اپنی تاریخ پر رکھ سکتے ہیں، تو صحیح ڈھانچہ اندازہ ہونا بند کر دیتا ہے اور فیصلہ ہونا شروع کر دیتا ہے۔</p>\n<h2 id=\"a-position-is-the-sum-of-its-legs\">پوزیشن اس کی ٹانگوں کا مجموعہ ہے۔</h2>\n<p>ہر کثیر ٹانگ حکمت عملی جو آپ سے ملی ہے وہ واحد اختیارات سے تیار کی گئی ہے، اور ہر ایک آپشن کی اپنی یونانی ہے۔ خوبصورت، آسان بنانے والی حقیقت یہ ہے کہ یونانی اس میں اضافہ کرتے ہیں۔ یہ جاننے کے لیے کہ پوری پوزیشن کیا کرتی ہے، آپ ہر ٹانگ کے نشان کا احترام کرتے ہوئے ہر ٹانگ میں وہی یونانی شامل کریں۔ ایک خریدی ہوئی ٹانگ اس کی یونانی شامل کرتی ہے۔ ایک بیچی ہوئی ٹانگ اسے گھٹا دیتی ہے۔ چار اہم ہیں ڈیلٹا، گاما، تھیٹا اور ویگا۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/diagram-position-greeks.png\" alt=\"ملٹی ٹانگ پوزیشن کے چار نیٹ یونانی، ہر ایک ٹانگ پر ایک ہی یونانی کو جوڑ کر تشکیل دیا جاتا ہے: نیٹ ڈیلٹا سمتی جھکاؤ ہے، نیٹ گاما یہ ہے کہ جھکاؤ کتنی تیزی سے بدلتا ہے، نیٹ تھیٹا ہے روپے کے وقت کے زوال کی کمائی یا لاگت ہر روز، اور نیٹ ویگا یہ ہے کہ اگر تقلید اتار چڑھاؤ بڑھتا ہے تو پوزیشن کتنا فائدہ یا کھوتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ملٹی ٹانگ پوزیشن کے چار نیٹ یونانی، ہر ایک ٹانگ پر ایک ہی یونانی کو جوڑ کر تشکیل دیا جاتا ہے: نیٹ ڈیلٹا سمتی جھکاؤ ہے، نیٹ گاما یہ ہے کہ جھکاؤ کتنی تیزی سے بدلتا ہے، نیٹ تھیٹا ہے روپے کے وقت کے زوال کی کمائی یا لاگت ہر روز، اور نیٹ ویگا یہ ہے کہ اگر تقلید اتار چڑھاؤ بڑھتا ہے تو پوزیشن کتنا فائدہ یا کھوتی ہے۔</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>حکمت عملی صرف اس کی ٹانگوں کا مجموعہ ہے، اور اسی طرح اس کے یونانی بھی ہیں۔ ٹانگیں شامل کریں اور آپ کو پوزیشن کا نیٹ ڈیلٹا، نیٹ گاما، نیٹ تھیٹا اور نیٹ ویگا ملے گا۔ وہ چار نمبر آپ کو وہ سب کچھ بتاتے ہیں جو جامد ادائیگی کا چارٹ چھوڑ دیتا ہے: یہ کس طرف جھکتا ہے، کتنی تیزی سے یہ جھکاؤ بدلتا ہے، آیا وقت آپ کو ادائیگی کر رہا ہے یا آپ سے معاوضہ لے رہا ہے، اور آیا آپ مضمر اتار چڑھاؤ میں تبدیلی کے لیے یا اس کے خلاف شرط لگا رہے ہیں۔</p>\n</div></div>\n<h2 id=\"reading-the-four-net-greeks\">چار نیٹ یونانی پڑھنا</h2>\n<p>ہمارے اینکر پر ٹھوس تجارت کریں: 24,056 کے قریب NIFTY اسپاٹ، 24,050 پر پیسے کی ہڑتال، 28 جولائی 2026 کی میعاد تقریباً 32 دن ختم، لاٹ سائز 65۔ 24,050 کال بیچیں اور 24,050 آپ کے پاس ہیں اور <strong>مختصر straddle</strong>46,858 روپے فی لاٹ کا کریڈٹ جمع کرنا۔ اس کے چار نیٹ یونانیوں کو ایک وقت میں چلائیں، کیونکہ وہ تقریباً ہر پریمیم سیلنگ پوزیشن کو بیان کرتے ہیں جسے آپ کبھی بھی چلائیں گے۔</p>\n<p><strong>نیٹ ڈیلٹا</strong> دشاتمک نمائش ہے، NIFTY میں ایک نکاتی اقدام سے پوزیشن کو کتنا فائدہ یا نقصان ہوتا ہے۔ شارٹ کال میں منفی ڈیلٹا ہوتا ہے، شارٹ پٹ میں مثبت ڈیلٹا ہوتا ہے، اور پیسے پر وہ تقریباً منسوخ کر دیتے ہیں۔ مختصر straddle لہذا ہے <strong>ڈیلٹا نیوٹرل کے قریب</strong>: اوپر یا نیچے کی ایک چھوٹی سی ہلچل آپ کے نفع اور نقصان کو بمشکل منتقل کرتی ہے۔ اس کے برعکس ایک بیل کال پھیلنا واضح طور پر مثبت خالص ڈیلٹا کو ظاہر کرے گا، کیونکہ یہ چاہتا ہے کہ انڈیکس بڑھے۔ صاف لفظوں میں نیٹ ڈیلٹا سوال ہے، میں کس طرف جھک رہا ہوں، اور کتنا۔</p>\n<p><strong>نیٹ گاما</strong> یہ ہے کہ ڈیلٹا کتنی تیزی سے بدلتا ہے جیسا کہ NIFTY حرکت کرتا ہے۔ مختصر straddle ہے <strong>مختصر گاما</strong>، یعنی اس کا ڈیلٹا اس کے خلاف ہو جاتا ہے: جیسے جیسے انڈیکس بڑھتا ہے پوزیشن مختصر ہوتی جاتی ہے، جیسے جیسے گرتی ہے پوزیشن لمبی ہوتی جاتی ہے، اس لیے ہر حرکت آخری سے کچھ زیادہ تکلیف دیتی ہے۔ مختصر گاما وہ قیمت ہے جو ہر پریمیم بیچنے والا ایک مستحکم آمدنی کے لیے ادا کرتا ہے۔ طویل اختیارات اس کے برعکس ہیں، طویل گاما، جہاں حرکتیں آپ کو زیادہ سے زیادہ مدد کرتی ہیں۔</p>\n<p><strong>نیٹ تھیٹا</strong> کیا وہ روپیہ ہے جو وقت آپ کے ہاتھ میں آتا ہے یا آپ سے ہر روز لیتا ہے، باقی سب کچھ رک جاتا ہے۔ مختصر straddle ہے <strong>مثبت تھیٹا</strong>: آپ خالص فروخت کنندہ ہیں، اس لیے ہر گزرتا دن آپ کے مختصر اختیارات کو ختم کرتا ہے اور یہ کٹاؤ آپ کی آمدنی ہے۔ ایک خالص خریدار، جیسے لمبا سٹرڈل، منفی تھیٹا رکھتا ہے اور وہ ہر روز کرایہ ادا کرتا ہے۔ تھیٹا صاف لفظوں میں یہ ہے کہ گھڑی میری دوست ہے یا دشمن؟</p>\n<p><strong>نیٹ ویگا</strong> مضمر اتار چڑھاؤ میں تبدیلی کی نمائش ہے، اگر مارکیٹ کی متوقع حد وسیع یا تنگ ہو جاتی ہے تو فائدہ یا نقصان۔ مختصر straddle ہے <strong>مختصر ویگا</strong>: اگر مضمر اتار چڑھاؤ گر جاتا ہے تو، آپ کے بیچے گئے اختیارات سستے ہو جاتے ہیں اور آپ کو فائدہ ہوتا ہے۔ اگر اس میں اضافہ ہوتا ہے، تو وہ زیادہ مہنگے ہو جاتے ہیں اور آپ ہار جاتے ہیں، یہاں تک کہ NIFTY کے ایک پوائنٹ کو منتقل کرنے سے پہلے۔ ویگا صاف لفظوں میں ہے، کیا میں خوف بیچ رہا ہوں یا اسے خرید رہا ہوں۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>NIFTY پر ایک مختصر اسٹریڈل اور چار ٹانگوں والا کریڈٹ آئرن کنڈور ایک ہی یونانی دستخط کا اشتراک کرتے ہیں: ڈیلٹا نیوٹرل کے قریب، مختصر گاما، مثبت تھیٹا، شارٹ ویگا۔ یہ ایک جملہ پوری کہانی بیان کرتا ہے۔ وہ وقت کے زوال اور پرسکون ہونے سے آہستہ آہستہ پیسہ کماتے ہیں، اگر انڈیکس بڑی حرکت کرتا ہے یا اگر مضمر اتار چڑھاؤ چھلانگ لگاتا ہے تو وہ کھو جاتے ہیں، اور انہیں اس بات کی زیادہ پرواہ نہیں ہوتی کہ کون سی سمت بڑھتا ہے جب تک کہ یہ بہت دور نہیں جاتا۔</p>\n</div></div>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>یہاں ایک تدریسی مثال کے طور پر استعمال کیا گیا مختصر اسٹریڈل ایک نقصان اٹھاتا ہے جس میں اوپر کی طرف کوئی چھت نہیں ہوتی ہے اور نیچے کی طرف بہت بڑا لیکن محدود نقصان ہوتا ہے، اس کے 46,858 روپے کے کریڈٹ کے ارد گرد 23,329 اور 24,771 پر breakevens ہوتے ہیں۔ اس کا مثبت تھیٹا اور شارٹ ویگا پرکشش ہیں، لیکن لامحدود خطرہ حقیقی ہے۔ ایک ابتدائی شخص جو ایک ہی شارٹ گاما، شارٹ ویگا، مثبت تھیٹا پروفائل چاہتا ہے اسے ایک متعین خطرے والے ڈھانچے کے ساتھ اس کا اظہار کرنا چاہیے جیسے کہ کریڈٹ آئرن کنڈور (زیادہ سے زیادہ منافع 5,616 روپے، زیادہ سے زیادہ نقصان کی حد 884 روپے)، جو بدترین کیس کو ایک معروف نمبر رکھتا ہے۔</p>\n</div></div>\n<h2 id=\"implied-volatility-is-a-regime-not-a-number\">مضمر اتار چڑھاؤ ایک نظام ہے، نمبر نہیں۔</h2>\n<p>نیٹ ویگا صرف اس صورت میں اہمیت رکھتا ہے جب آپ کو معلوم ہو کہ مضمر اتار چڑھاؤ کس راستے پر جانے کا امکان ہے، اور یہ ایسی چیز نہیں ہے جسے آپ ایک اقتباس سے پڑھتے ہیں۔ NIFTY پر آج کی ایٹ-دی-منی مضمر اتار چڑھاؤ تقریباً 12.7 فیصد ہے، لیکن 12.7 اپنے طور پر بے معنی ہے۔ صحیح سوال ہمیشہ ہوتا ہے، کس کے مقابلے میں زیادہ یا کم؟ مضمر اتار چڑھاؤ ہے a <strong>حکومت</strong>، اور آپ اس کی اپنی حالیہ تاریخ کے خلاف فیصلہ کرتے ہیں۔</p>\n<p>دو آسان اقدامات اسے اس تاریخ پر رکھتے ہیں۔ <strong>IV درجہ</strong> پوچھتا ہے کہ موجودہ مضمر اتار چڑھاؤ پچھلے سال کے دوران اس کی سب سے کم اور سب سے زیادہ پڑھنے کے درمیان کہاں ہے، اس حد کے فیصد کے طور پر۔ اگر گزشتہ سال 10 سے 22 فیصد تک چلا اور آج 12.7 ہے، تو درجہ کم ہے، کیونکہ 12.7 بینڈ کے نیچے کے قریب بیٹھتا ہے۔ <strong>IV پرسنٹائل</strong> تھوڑا سا مختلف سوال پوچھتا ہے: پچھلے سال کے دنوں کے کس حصے پر آج کے مقابلے میں اتار چڑھاؤ کم تھا۔ 20 کے فیصد کا مطلب ہے کہ یہ پانچ میں سے صرف ایک دن سستا تھا، اس لیے آج کا دن پرسکون ہے۔ رینک حد کی انتہاؤں کی پرواہ کرتا ہے، فیصد اس بات کی پرواہ کرتا ہے کہ آپ یہاں کتنی بار آئے ہیں، اور وہ مل کر آپ کو بتاتے ہیں کہ ابھی پریمیم امیر ہے یا سستا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/diagram-iv-rank.png\" alt=\"مضمر اتار چڑھاؤ کو اس کی اپنی بارہ ماہ کی تاریخ کے خلاف پرکھا گیا: IV درجہ کی پیمائش کرتا ہے جہاں آج سال کی کم اور اعلی کے درمیان بیٹھا ہے، جب کہ IV پرسنٹائل ان دنوں کے حصے کی پیمائش کرتا ہے جو آج سے زیادہ پرسکون تھے، لہذا 12.7 فیصد کی وہی خام تعداد اس کے اوپری رینج کے نچلے حصے کے قریب سستی کے طور پر پڑھتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>مضمر اتار چڑھاؤ کو اس کی اپنی بارہ ماہ کی تاریخ کے خلاف سمجھا جاتا ہے: IV درجہ کی پیمائش کرتا ہے جہاں آج سال کی کم اور زیادہ کے درمیان ہے، جب کہ IV پرسنٹائل ان دنوں کے حصے کی پیمائش کرتا ہے جو آج سے زیادہ پرسکون تھے، لہذا 12.7 فیصد کی وہی خام تعداد اس کے اوپری رینج کے نیچے کے قریب سستی اور امیر کے قریب پڑھتی ہے۔</figcaption></figure>\n<p>انڈیکس کی سطح پر آپ کو خود اس کی گنتی کرنے کی بھی ضرورت نہیں ہے۔ <strong>انڈیا VIX</strong> پوری آپشن چین سے ماخوذ NIFTY کی متوقع تیس دن کی اتار چڑھاؤ پر مارکیٹ کا شائع شدہ مطالعہ ہے۔ ایک کم اور گرتا ہوا انڈیا VIX کا کہنا ہے کہ آپشن مارکیٹ قیمتوں کا تعین کر رہی ہے، یہ وہ ماحول ہے جہاں فروخت پریمیم خاموشی سے ختم ہو جاتی ہے۔ ایک اعلیٰ اور ابھرتا ہوا انڈیا VIX کا کہنا ہے کہ خوف کی قیمت لگائی جا رہی ہے، پریمیم چربی والے ہیں، اور انہیں بیچنا زیادہ فائدہ مند اور زیادہ خطرناک ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>کسی بھی اتار چڑھاؤ کی تجارت کرنے سے پہلے، IV درجہ، IV پرسنٹائل اور انڈیا VIX کو ایک ساتھ دیکھیں۔ وہ ایک سوال کا جواب دیتے ہیں جو یہ فیصلہ کرتا ہے کہ آیا آپ کو بیچنے والا ہونا چاہیے یا اختیارات کا خریدار: کیا مضمر اتار چڑھاؤ مہنگا ہے یا اپنے ماضی کی نسبت سستا؟ جب آپ کریڈٹ اور ڈیبٹ ڈھانچے کے درمیان انتخاب کر رہے ہوتے ہیں تو وہ واحد پڑھنا سمت کے بارے میں کسی بھی نقطہ نظر سے زیادہ قابل قدر ہے۔</p>\n</div></div>\n<h2 id=\"the-skew-puts-cost-more-than-equidistant-calls\">سکیو: مساوی کالوں سے زیادہ لاگت آتی ہے۔</h2>\n<p>مضمر اتار چڑھاؤ ایک ہی ختم ہونے پر ہونے والی ہڑتالوں میں بھی یکساں نہیں ہے۔ انڈیکس کے اختیارات پر منفی پہلو تقریباً ہمیشہ اوپر کی نسبت زیادہ مضمر اتار چڑھاؤ پر تجارت کرتا ہے۔ رقم کے نیچے دیے گئے فاصلہ میں اس کے اوپر اسی فاصلے پر کال کے مقابلے میں زیادہ مضبوط اتار چڑھاؤ ہوتا ہے۔ یہ جھکاؤ ہے <strong>اتار چڑھاؤ کی ترچھی۔</strong>، اور یہ اس لیے موجود ہے کیونکہ مارکیٹیں بڑھنے سے زیادہ تیزی سے گرتی ہیں: سرمایہ کار منفی تحفظ کے لیے ادائیگی کرتے ہیں، اور یہ مسلسل مانگ کم ہڑتالوں کے مضمر اتار چڑھاؤ کو اٹھاتی ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/diagram-vol-skew.png\" alt=\"انڈیکس کے اتار چڑھاؤ کی ترچھی: ایک ہی میعاد ختم ہونے پر ہڑتال کے خلاف مضمر اتار چڑھاؤ کی منصوبہ بندی کرنا نیچے کی طرف ڈھلوان لائن پیدا کرتا ہے، جس میں بائیں جانب پیسے کے بغیر دائیں طرف کی رقم سے باہر کی کالوں کے مقابلے میں زیادہ مضمر اتار چڑھاؤ ہوتا ہے، کیونکہ منفی تحفظ کی مانگ مسلسل ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>انڈیکس کے اتار چڑھاؤ کی ترچھی: ایک ہی میعاد ختم ہونے پر ہڑتال کے خلاف مضمر اتار چڑھاؤ کی منصوبہ بندی کرنا نیچے کی طرف ڈھلوان لائن پیدا کرتا ہے، جس میں بائیں جانب پیسے کے بغیر دائیں طرف کی رقم سے باہر کی کالوں کے مقابلے میں زیادہ مضمر اتار چڑھاؤ ہوتا ہے، کیونکہ منفی تحفظ کی مانگ مسلسل ہے۔</figcaption></figure>\n<p>جب آپ اسٹرائیک کو چنتے ہیں تو اسکیو اہمیت رکھتا ہے۔ جب آپ NIFTY پر پھیلے ہوئے آئرن کنڈور یا بیل پوٹ کے پوٹ سائیڈ کو فروخت کرتے ہیں، تو آپ اس سے زیادہ نیچے والے اتار چڑھاؤ میں فروخت کر رہے ہیں، اس لیے پوٹ ونگ کال ونگ کے مقابلے میں جگہ سے اسی فاصلے کے لیے زیادہ پریمیم لاتا ہے۔ اس کا مطلب یہ بھی ہے کہ سڈول نظر آنے والا ڈھانچہ شاذ و نادر ہی نیچے سے ہم آہنگ ہوتا ہے: نیچے والے حملوں کی قیمت اوپر والے سے زیادہ خوف کے لیے ہوتی ہے۔ سکیو کو پڑھنا آپ کو یہ سمجھنے سے روکتا ہے کہ رینج ٹریڈ کے دونوں اطراف ایک ہی شرط ہیں۔</p>\n<h2 id=\"the-term-structure-near-against-far\">اصطلاح کا ڈھانچہ: قریب سے دور</h2>\n<p>دوسری جہت وقت ہے۔ مضمر اتار چڑھاؤ نہ صرف ہڑتالوں میں بلکہ ایکسپائریوں میں بھی مختلف ہوتا ہے۔ قریب قریب 28 جولائی 2026 کی میعاد کا 25 اگست 2026 کی میعاد ختم ہونے سے موازنہ کرنے سے آپ کو <strong>اصطلاح کی ساخت</strong>. پُرسکون بازاروں میں یہ آہستہ سے اوپر کی طرف ڈھلتی ہے، دور کا مہینہ قریب کے مہینے کے مقابلے میں قدرے زیادہ مضمر اتار چڑھاؤ کا حامل ہوتا ہے، کیونکہ طویل افق پر مزید کچھ ہو سکتا ہے۔ وہ اوپر کی شکل عام حالت ہے۔</p>\n<p>ایک <strong>الٹا</strong> اصطلاحی ڈھانچہ، جہاں قریب کا مہینہ دور سے زیادہ مہنگا ہے، ایک انتباہ ہے۔ یہ عام طور پر کسی معروف واقعہ جیسے کہ نتیجہ یا پالیسی فیصلے سے پہلے ظاہر ہوتا ہے، جب مارکیٹ کو بہت جلد حرکت کے پھٹنے اور پھر پرسکون ہونے کی توقع ہوتی ہے۔ وکر کی شکل معلومات ہے: ایک اوپر کی اصطلاح کا ڈھانچہ کہتا ہے کہ قریب کی میعاد نسبتاً سستی ہے، ایک الٹا کہتا ہے کہ قریب کی ایکسپائری ایونٹ کے پریمیم سے بھری ہوئی ہے جو واقعہ کے گزر جانے کے بعد گر جائے گی۔</p>\n<p>یہ بالکل وہی ہے جو a <strong>کیلنڈر</strong> تجارت فصل کے لیے بنائی گئی ہے۔ 28 جولائی کے قریب کے آپشن کو بیچیں اور اسی سٹرائیک پر 25 اگست کا دور کا آپشن خریدیں، اور آپ قریب کی تاریخ کے اتار چڑھاؤ کو مختصر کرتے ہیں اور دور کی تاریخ کے اتار چڑھاؤ کو طویل کرتے ہیں، اگر قریب کی ٹانگ دور کی ٹانگ سے زیادہ تیزی سے زوال پذیر ہوتی ہے، جو کہ ایک اوپر کی مدت کی ساخت اور مستحکم جگہ کی فراہمی ہے۔</p>\n<h2 id=\"matching-the-structure-to-the-regime\">ڈھانچے کو حکومت سے ملانا</h2>\n<p>اب دونوں لینز ملتے ہیں۔ اپنی پوزیشن کا نیٹ ویگا پڑھیں، پھر حکومت کو پڑھیں، اور یقینی بنائیں کہ وہ متفق ہیں۔</p>\n<ul>\n<li>جب مضمر اتار چڑھاؤ ہوتا ہے۔ <strong>اعلی</strong> (امیر IV درجہ، بلند بھارت VIX)، پریمیم مہنگا ہے، لہذا احسان کریں <strong>فروخت</strong> یہ کریڈٹ اسپریڈز، کریڈٹ آئرن کنڈور، اور شارٹ اسٹریڈلز یا گلا گھونٹنا سب کچھ ہیں۔ <strong>مختصر ویگا</strong>: وہ جیت جاتے ہیں اگر مضمر اتار چڑھاؤ معمول کی طرف آتا ہے، جو امیر حکومتیں کرتی ہیں۔ ابتدائیوں کے لیے، اس متعین خطرے کو رکھیں، برہنہ اسٹریڈل کے بجائے آئرن کنڈور۔</li>\n<li>جب مضمر اتار چڑھاؤ ہوتا ہے۔ <strong>کم</strong> (سستا IV درجہ، پرسکون ہندوستان VIX)، پریمیم سستا ہے، لہذا احسان کریں <strong>خریدنا</strong> یہ ڈیبٹ اسپریڈز اور طویل اختیارات ہیں۔ <strong>لمبی ویگا</strong>: وہ جیت جاتے ہیں اگر تقلید اتار چڑھاؤ کم بنیاد سے بڑھتا ہے، اور جب اختیارات اپنے لیے سستے ہوتے ہیں تو ان کی قیمت بہت کم ہوتی ہے۔</li>\n<li>جب کنارہ اس کی سطح کے بجائے منحنی شکل میں ہو تو a کا استعمال کریں۔ <strong>کیلنڈر</strong> تجارت کرنے کے لئے <strong>اصطلاح کی ساخت</strong>, قیمتی قریب کی تاریخ کے اتار چڑھاؤ کو فروخت کرنا اور سستی دور کی اتار چڑھاؤ کا مالک ہونا۔</li>\n</ul>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>زیادہ بیچنا اور کم خریدنا ایک ابتدائی تعصب ہے، کوئی اصول نہیں۔ اعلی مضمر اتار چڑھاؤ صرف تب ہی فروخت ہونے کے قابل ہے جب مضمر اقدام اس اقدام کے خلاف حقیقی طور پر بھرپور ہو جس کے آپ حقیقت میں احساس ہونے کی توقع رکھتے ہیں، اور زیادہ پڑھنا اکثر سامنے آنے والے حقیقی واقعے کی عکاسی کرتا ہے۔ کمائی کے نتیجے یا پالیسی ڈے میں فروخت کرنا آپ کو ایک موٹا پریمیم اور اسی تجارت پر ایک ظالمانہ فرق دے سکتا ہے۔ اس لیے ایک ایونٹ چیک کے ساتھ پڑھے گئے نظام کو جوڑیں، خطرے کی وضاحت رکھیں، اور کبھی بھی پریمیم فروخت نہ کریں کیونکہ نمبر زیادہ ہے۔</p>\n</div></div>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>جو اصول اسے آپس میں جوڑتا ہے وہ حکومت کے خلاف آپ کے نیٹ ویگا کی علامت ہے۔ شارٹ ویگا جیت جاتی ہے اگر مضمر اتار چڑھاؤ گرتا ہے، لہذا اس کا تعلق اعلی IV حکومتوں میں ہے۔ لانگ ویگا جیت جاتی ہے اگر مضمر اتار چڑھاؤ بڑھتا ہے، تو اس کا تعلق کم IV حکومتوں میں ہے۔ جب مضمر اتار چڑھاؤ پہلے سے ہی سستا ہو تو شارٹ ویگا ٹریڈ لگانا، یا لانگ ویگا ٹریڈ اس وقت کرنا جب یہ پہلے سے مہنگا ہو، حکومت سے لڑنا ہے، اور حکومت عام طور پر جیت جاتی ہے۔</p>\n</div></div>\n<h2 id=\"the-practical-takeaway\">عملی راستہ</h2>\n<p>یونانی اور اتار چڑھاؤ کا نظام علمی سجاوٹ نہیں ہے۔ یہ پرواز سے پہلے کی جانچ ہے جو اس کورس کے باقی حصوں کو ان فیصلوں میں بدل دیتی ہے جن کا آپ دفاع کر سکتے ہیں۔ نظم و ضبط مختصر ہے اور یہ کبھی تبدیل نہیں ہوتا ہے۔</p>\n<ul>\n<li>ٹانگیں شامل کریں اور خالص یونانی پڑھیں۔ اپنے نیٹ ڈیلٹا کو جانیں (آپ کس طرف جھکتے ہیں)، نیٹ گاما (کتنی تیزی سے یہ جھکاؤ بدلتا ہے)، نیٹ تھیٹا (چاہے وقت آپ کو ادائیگی کرتا ہے) اور نیٹ ویگا (چاہے آپ اتار چڑھاؤ بیچ رہے ہوں یا خرید رہے ہوں)۔</li>\n<li>ویگا سائن سے فیصلہ کریں کہ پوزیشن بیچنے والا ہے یا اتار چڑھاؤ کا خریدار، اور اسے کبھی بھی حادثہ نہ ہونے دیں۔</li>\n<li>موجودہ مضمر اتار چڑھاؤ کو اس کی اپنی تاریخ پر IV درجہ، IV پرسنٹائل اور انڈیا VIX کے ساتھ رکھیں، تاکہ آپ کو معلوم ہو کہ پریمیم امیر ہے یا سستا۔</li>\n<li>اسٹرائیکس کا انتخاب کرنے سے پہلے سکیو کو چیک کریں اور میعاد ختم ہونے کا انتخاب کرنے سے پہلے اصطلاح کا ڈھانچہ۔</li>\n<li>اسے صرف اس وقت لگائیں جب حکومت آپ کے ساتھ ہو: جب مضمر اتار چڑھاؤ زیادہ ہو تو پریمیم فروخت کریں، جب یہ کم ہو تو اسے خریدیں، اور کیلنڈر کی تجارت کریں جب کنارے منحنی ہو۔ اس عادت کے ساتھ، آخری باب میں آپ جس حکمت عملی کا انتخاب کرتے ہیں وہ پہلے ہی اس مارکیٹ میں فٹ ہو جائے گی جس میں آپ اصل میں ہیں۔</li>\n</ul>\n","toc":[{"level":2,"text":"پوزیشن اس کی ٹانگوں کا مجموعہ ہے۔","id":"a-position-is-the-sum-of-its-legs"},{"level":2,"text":"چار نیٹ یونانی پڑھنا","id":"reading-the-four-net-greeks"},{"level":2,"text":"مضمر اتار چڑھاؤ ایک نظام ہے، نمبر نہیں۔","id":"implied-volatility-is-a-regime-not-a-number"},{"level":2,"text":"سکیو: مساوی کالوں سے زیادہ لاگت آتی ہے۔","id":"the-skew-puts-cost-more-than-equidistant-calls"},{"level":2,"text":"اصطلاح کا ڈھانچہ: قریب سے دور","id":"the-term-structure-near-against-far"},{"level":2,"text":"ڈھانچے کو حکومت سے ملانا","id":"matching-the-structure-to-the-regime"},{"level":2,"text":"عملی راستہ","id":"the-practical-takeaway"}],"imgCount":3,"hasContent":true},"27":{"html":"<p>آپ نے اس پورے کورس کو میٹنگ کی حکمت عملیوں کو ایک وقت میں صرف کیا ہے، ہر ایک کو اس کی ادائیگی کی شکل اور اس کے تین نمبروں سے سیکھنا ہے۔ اب وہ حصہ آتا ہے جو فیصلہ کرتا ہے کہ آیا اس میں سے کوئی بھی آپ کو پیسہ کماتا ہے: اس لمحے کے لیے صحیح کا انتخاب کرنا اور ایک بار اس کے آن ہونے کے بعد اس کا انتظام کرنا۔ حکمت عملی صرف ایک ٹول ہے، اور بہترین ٹول وہ ہے جو کام اور آپ کے اکاؤنٹ کے سائز کے مطابق ہو۔ یہ اختتامی باب ہر چیز کو ایک ساتھ کھینچتا ہے۔ یہ آپ کے بازار کے نظارے کو ایک سمجھدار ڈھانچے کے ساتھ نقشہ بناتا ہے، یہ بتاتا ہے کہ آپ کو متعین خطرے سے کیوں شروع کرنا چاہیے، یہ بتاتا ہے کہ پوزیشن کو کس طرح سائز کرنا ہے تاکہ ایک خراب تجارت آپ کی تجارت کو ختم نہ کر سکے، اور منافع لینے، ایڈجسٹ کرنے، اور دور چلنے کے لیے واضح اصول وضع کرتا ہے۔ ہم ایک چیک لسٹ کے ساتھ ختم کرتے ہیں جو آپ ہر تجارت سے پہلے چلا سکتے ہیں۔</p>\n<h2 id=\"start-with-your-view-then-pick-the-shape\">اپنے نقطہ نظر سے شروع کریں، پھر شکل منتخب کریں۔</h2>\n<p>اس کورس میں ہر حکمت عملی اس بارے میں مختلف رائے کا جواب دیتی ہے کہ NIFTY آگے کہاں جاتا ہے۔ لہذا پہلا سوال یہ نہیں ہے کہ کون سی حکمت عملی ہے، یہ وہی ہے جو آپ کے خیال میں واقعتاً ہو گا۔ کیا آپ تیز، مندی کا شکار ہیں، پرسکون ہونے کی توقع کر رہے ہیں، یا کسی بھی سمت میں کسی بڑے اقدام کے لیے تیار ہیں؟ ایک بار جب یہ ایماندار اور مخصوص ہو جائے تو ڈھانچہ تقریباً خود کو چن لیتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/options-strategies/images/diagram-strategy-by-view.png\" alt=\"ویو ٹو سٹریٹیجی سلیکٹر: تیزی، مندی، غیرجانبدار، اور بڑے موو آراء ہر نقشے کو متعین خطرے والے ڈھانچے کے لیے جو ان میں فٹ بیٹھتا ہے، اس لیے آپ اس شکل کا انتخاب کرتے ہیں جو کہ آپ کو درحقیقت NIFTY کے کرنے کی توقع کے مطابق ہو۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ویو ٹو سٹریٹیجی سلیکٹر: تیزی، مندی، غیرجانبدار، اور بڑے موو آراء ہر نقشے کو متعین خطرے والے ڈھانچے کے لیے جو ان میں فٹ بیٹھتا ہے، اس لیے آپ اس شکل کا انتخاب کرتے ہیں جو اس سے مماثل ہو جس کی آپ اصل میں NIFTY کی توقع کرتے ہیں۔</figcaption></figure>\n<p>یہاں ایک ٹیبل جیسا ہی خیال ہے، پورے کورس سے حقیقی NIFTY نمبرز استعمال کرتے ہوئے (اسپاٹ 24,056، لاٹ 65، 28 جولائی 2026 ایکسپائری) تاکہ آپ تینوں نمبروں کا ساتھ ساتھ موازنہ کر سکیں۔</p>\n<table>\n<thead>\n<tr>\n<th>آپ کا نظریہ</th>\n<th>سمجھدار ڈھانچہ</th>\n<th>Breakeven(s)</th>\n<th>زیادہ سے زیادہ منافع</th>\n<th>زیادہ سے زیادہ نقصان</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ہلکی تیزی</td>\n<td>بیل کال پھیل گئی۔</td>\n<td>24,106</td>\n<td>2,876 روپے</td>\n<td>3,624 روپے</td>\n</tr>\n<tr>\n<td>بلش، کریڈٹ چاہتے ہیں۔</td>\n<td>بیل ڈال پھیل گیا</td>\n<td>24,011</td>\n<td>2,506 روپے</td>\n<td>3,994 روپے</td>\n</tr>\n<tr>\n<td>ہلکا سا مندی والا</td>\n<td>ریچھ پھیل گیا</td>\n<td>24,011</td>\n<td>3,994 روپے</td>\n<td>2,506 روپے</td>\n</tr>\n<tr>\n<td>بیئرش، کریڈٹ چاہتے ہیں۔</td>\n<td>ریچھ کی کال پھیل گئی۔</td>\n<td>24,106</td>\n<td>3,624 روپے</td>\n<td>2,876 روپے</td>\n</tr>\n<tr>\n<td>غیر جانبدار، ایک رینج رکھتا ہے۔</td>\n<td>لانگ آئرن کنڈور (بلڈر، رینج ورژن)</td>\n<td>23,864 اور 24,236</td>\n<td>5,616 روپے</td>\n<td>884 روپے</td>\n</tr>\n<tr>\n<td>غیر جانبدار، ہڑتال کو پن کرتا ہے۔</td>\n<td>لوہے کی لمبی مکھی (بلڈر، پن ورژن)</td>\n<td>23,956 اور 24,148</td>\n<td>6,130 روپے</td>\n<td>370 روپے</td>\n</tr>\n<tr>\n<td>بڑا اقدام، کسی بھی طرح سے</td>\n<td>لمبا سٹرڈل</td>\n<td>23,329 اور 24,771</td>\n<td>لا محدود</td>\n<td>46,858 روپے</td>\n</tr>\n<tr>\n<td>بڑا اقدام، سستا</td>\n<td>لمبا گلا گھونٹنا</td>\n<td>23,323 اور 24,777</td>\n<td>لا محدود</td>\n<td>40,729 روپے</td>\n</tr>\n</tbody></table>\n<p>اس ٹیبل کو ایک مینو کے طور پر پڑھیں، درجہ بندی کے نہیں۔ ایک بیل کال اسپریڈ لوہے کے کنڈور سے بہتر نہیں ہے۔ وہ مختلف خیالات کا جواب دیتے ہیں. نظم و ضبط یہ ہے کہ آپ اپنی ایماندارانہ رائے کو قطار کا انتخاب کرنے دیں، بجائے اس کے کہ آپ اپنی پسند کی حکمت عملی کا انتخاب کریں اور پھر اسے درست ثابت کرنے کے لیے کوئی نظریہ ایجاد کریں۔ یہ بھی یاد رکھیں کہ منافع کا امکان، جسے آپ بلڈر پینل سے پڑھ سکتے ہیں، انتخاب کا حصہ ہے: سخت سٹرائیکس کے ساتھ ایک اعلی کریڈٹ آئرن کنڈور وسیع تر سے کم جیتتا ہے، لہذا اپنی اسٹرائیکس کو ان مشکلات پر سیٹ کریں جو آپ اصل میں چاہتے ہیں۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>نام دینے کا ایک نوٹ۔ بلڈر ان دو غیر جانبدار ڈھانچے کو لانگ آئرن کونڈور اور لانگ آئرن فلائی کا لیبل لگاتا ہے۔ اس کے کنونشن میں وہ رینج کے پابند، کریڈٹ طرز کے ورژن ہیں: آپ کو اس وقت فائدہ ہوتا ہے جب NIFTY پنکھوں (کنڈور) کے اندر رہتا ہے یا سنٹر اسٹرائیک (مکھی) کو پن کرتا ہے، اور خریدی گئی بیرونی ٹانگیں نقصان کو پورا کرتی ہیں، یہی وجہ ہے کہ ٹیبل میں ایک چھوٹے سے زیادہ سے زیادہ نقصان اور زیادہ سے زیادہ منافع دکھایا گیا ہے۔ دوسرے پلیٹ فارمز کبھی کبھی لمبے اور چھوٹے لیبلز کو الٹے طریقے سے جوڑ دیتے ہیں، اس لیے کبھی بھی اکیلے نام پر بھروسہ نہ کریں۔ تجارت کرنے سے پہلے ادائیگی کی شکل اور بلڈر پینل سے منافع کا امکان پڑھیں۔</p>\n</div></div>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>فیصلوں کی ترتیب اہمیت رکھتی ہے۔ پہلے NIFTY پر ایک واضح، مخصوص نظریہ بنائیں۔ پھر اس ڈھانچے کا انتخاب کریں جس کی ادائیگی کی شکل اس عین مطابق منظر کو انعام دیتی ہے۔ سب سے پہلے حکمت عملی کا انتخاب کرنا اور اسے فٹ کرنے کے لیے اپنے نقطہ نظر کو موڑنا یہ سب سے عام طریقہ ہے کہ تاجر بالکل اچھی ساخت پر پیسہ کھو دیتے ہیں۔</p>\n</div></div>\n<h2 id=\"defined-risk-first-always\">پہلے خطرے کی وضاحت، ہمیشہ</h2>\n<p>اگر آپ کو اس پورے کورس میں سے ایک اصول یاد ہے تو اسے بنائیں۔ جب تک آپ تجربہ کار نہ ہوں، تجارت کریں۔ <strong>طے شدہ خطرہ</strong> ڈھانچے، وہ جن کا زیادہ سے زیادہ نقصان ایک مقررہ، معلوم نمبر ہے جو آپ کے داخل ہونے سے پہلے چارٹ پر چھپا ہوا ہے۔</p>\n<p>میز پر واپس دیکھو. بیل کال اسپریڈ کا خطرہ 3,624 روپے ہے اور ایک روپیہ زیادہ نہیں۔ آئرن کنڈور کی قیمت 884 روپے ہے، آئرن فلائی صرف 370 روپے ہے۔ آپ اپنی زیادہ سے زیادہ کھو سکتے ہیں، لیکن آپ کبھی بھی سرپرائز نہیں کھو سکتے۔</p>\n<p>اس کورس کے ڈھانچے کے ساتھ انتباہات کے ساتھ جھنڈا لگائیں: شارٹ اسٹریڈل اور شارٹ اسٹرینگل، کال اور پوٹ ریشو اسپریڈز، لمبا اور مختصر مصنوعی مستقبل، جیڈ لیزرڈ کے اندر شارٹ پوٹ۔ ان میں سے ہر ایک ایک رکھتا ہے۔ <strong>غیر متعینہ یا لامحدود نقصان</strong> کم از کم ایک طرف، اور مماثل مارجن، اکثر ایک انڈیکس لاٹ کے لیے ڈیڑھ لاکھ سے زیادہ۔ وہ اچھی ادائیگی کر سکتے ہیں اور تجربہ کار تاجر ان کا استعمال کرتے ہیں، لیکن NIFTY میں ایک پرتشدد اقدام آپ کے جمع کیے گئے پریمیم سے کئی گنا زیادہ خرچ کر سکتا ہے۔ یہ وہ جگہ نہیں ہے جہاں آپ کو سیکھنا چاہئے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>لامحدود یا کھلے نقصان کے ساتھ حکمت عملی، شارٹ اسٹریڈلز اور گلا گھونٹنا، ایک ننگی ٹانگ کے ساتھ تناسب پھیلانا، مصنوعی فیوچر، اور ننگے شارٹ پوٹس، آپ کے جمع کردہ اور ایک ہی سیشن میں ٹریڈنگ اکاؤنٹس کو ختم کرنے سے کہیں زیادہ کھو سکتے ہیں۔ ماسٹر ڈیفائنڈ رسک ڈھانچے، جہاں آپ ان کے قریب کہیں بھی جانے سے پہلے چارٹ پر بدترین کیس پرنٹ کیا جاتا ہے۔</p>\n</div></div>\n<p>خطرے سے متعلق معاملات کی وضاحت کی ایک دوسری وجہ ہے: یہ آپ کو صحیح سائز دینے دیتا ہے، کیونکہ آپ کو پہلے سے ہی خراب ترین صورت حال معلوم ہوتی ہے۔ اگر آپ نہیں جانتے کہ اس میں کتنا نقصان ہو سکتا ہے تو آپ کسی پوزیشن کو سمجھداری سے سائز نہیں کر سکتے، اور غیر متعینہ خطرے والی تجارتیں اس نمبر کو آپ سے چھپا دیتی ہیں۔</p>\n<h2 id=\"size-every-position-to-survive\">زندہ رہنے کے لئے ہر پوزیشن کا سائز بنائیں</h2>\n<p>ناکام ہونے کا تیز ترین طریقہ غلط حکمت عملیوں کا انتخاب نہیں کرنا ہے۔ یہ ایک تجارت پر بہت زیادہ لگا رہا ہے اور آپ کے کنارے کے کام کرنے کا وقت آنے سے پہلے ہی ختم ہو رہا ہے۔ پوزیشن کا سائز بقا ہے۔</p>\n<p>پیشہ ور افراد جو سادہ اصول استعمال کرتے ہیں وہ یہ ہے کہ اکثر کسی ایک تجارت پر آپ کے اکاؤنٹ کا صرف ایک چھوٹا سا ٹکڑا خطرے میں ڈالنا ہے۔ <strong>ایک سے دو فیصد.</strong> متعین خطرے کے ساتھ یہ آسان ریاضی ہے، کیونکہ آپ کا زیادہ سے زیادہ نقصان معلوم ہوتا ہے۔</p>\n<ul>\n<li>فرض کریں کہ آپ کا اکاؤنٹ 5,00,000 روپے ہے اور آپ خطرے کو دو فیصد تک محدود کرتے ہیں، جو کہ 10,000 روپے فی تجارت ہے۔</li>\n<li>ایک بیل کال اسپریڈ ایک لاٹ کے لیے 3,624 روپے کا خطرہ ہے۔ یہ آپ کی 10,000 روپے کی حد کے تحت آرام سے فٹ بیٹھتا ہے، اور یہاں تک کہ دو لاٹ، 7,248 روپے کے خطرے میں، پھر بھی اس کے اندر ہوں گے۔</li>\n<li>لمبا سٹرڈل ایک لاٹ کے لیے 46,858 روپے کا خطرہ ہے۔ یہ آپ کی 10,000 روپے کی حد سے تقریباً پانچ گنا ہے، اس لیے ایک لاٹ پہلے ہی بہت بڑا ہے اور آپ اسے چھوڑ دیتے ہیں یا کسی سستے ڈھانچے کا انتظار کرتے ہیں جو فٹ بیٹھتا ہے۔</li>\n</ul>\n<p>نقطہ صحیح فیصد نہیں ہے۔ یہ یہ ہے کہ آپ کا سائز آپ کے زیادہ سے زیادہ نقصان سے بہتا ہے، نہ کہ آپ کتنے اعتماد سے محسوس کرتے ہیں۔ اعتماد سب سے بدترین ممکنہ سائزنگ ان پٹ ہے، کیونکہ آپ ان تجارتوں سے پہلے ہی زیادہ پر اعتماد محسوس کرتے ہیں جو سب سے زیادہ نقصان پہنچاتے ہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اپنے نقصان کی حد سے پیچھے کی طرف کام کریں۔ اس روپے کی رقم کا فیصلہ کریں جو آپ تجارت پر کھونا چاہتے ہیں، پھر اپنی لاٹ کی تعداد حاصل کرنے کے لیے حکمت عملی کے زیادہ سے زیادہ نقصان کو فی لاٹ سے تقسیم کریں۔ اگر جواب ایک لاٹ سے کم ہے، تو تجارت آپ کے اکاؤنٹ کے لیے بہت بڑی ہے اور آپ اسے چھوڑ دیتے ہیں۔ یہ ایک عادت زیادہ تر اکاؤنٹ ختم کرنے والی غلطیوں کو روکتی ہے۔</p>\n</div></div>\n<h2 id=\"manage-the-trade-profit-adjust-exit\">تجارت کا انتظام کریں: منافع، ایڈجسٹ، باہر نکلیں۔</h2>\n<p>جب آپ اسے کھولتے ہیں تو پوزیشن ختم نہیں ہوتی ہے۔ داخل ہونے سے پہلے اپنے انتظامی اصولوں کا فیصلہ کریں، جب آپ پرسکون ہوں، کیونکہ ایک بار جب پیسہ حرکت میں آتا ہے تو آپ کا فیصلہ خراب ہوجاتا ہے۔</p>\n<p><strong>منافع کب لینا ہے۔</strong> جیتنے کے لیے آپ کو کریڈٹ ٹریڈ کی میعاد ختم ہونے کی ضرورت نہیں ہے۔ بہت سے تاجر ایک مقررہ خطرے والے کریڈٹ ڈھانچے کو بند کر دیتے ہیں جب اس نے اپنے زیادہ سے زیادہ منافع کا ایک بڑا حصہ حاصل کر لیا ہوتا ہے، اکثر آدھے سے تین چوتھائی تک، بجائے اس کے کہ الٹ پھیر کا سامنا کرتے ہوئے آخری روپے کو نچوڑا جائے۔ اچھا منافع جلد لینے سے آپ کا سرمایہ آزاد ہو جاتا ہے اور اس خطرے کو دور کرتا ہے جس کی آپ کو مزید ضرورت نہیں ہے۔ ڈیبٹ اسپریڈ کے لیے، وہی خیال لاگو ہوتا ہے: اگر آپ کی مطلوبہ حرکت زیادہ تر ہو چکی ہے اور پوزیشن ختم ہونے سے پہلے اس کے زیادہ سے زیادہ منافع کے قریب ہے، تو اسے بند کرنا جیت میں بند ہو جاتا ہے۔</p>\n<p><strong>کب ایڈجسٹ کرنا ہے۔</strong> ایڈجسٹ کرنے کا مطلب ہے کہ آپ کے خلاف حرکت کرنے والی تجارت کو ٹھیک کرنے کے لیے ٹانگیں بدلنا، ایڈجسٹمنٹ کے باب کا موضوع، مثال کے طور پر مزید کریڈٹ لینے کے لیے آئرن کنڈور کے بغیر جانچے گئے سائیڈ کو قریب کرنا، یا دھمکی آمیز مختصر ہڑتال کو مزید دور منتقل کرنا۔ ایڈجسٹ کرنا ایک حقیقی ہنر ہے، لیکن یہ وہ جگہ بھی ہے جہاں تاجر برے کے بعد اچھا پیسہ پھینک کر مصیبت میں پڑ جاتے ہیں۔ ہوشیار مرمت پر سادہ انتظام کو ترجیح دیں۔ ایک ایڈجسٹمنٹ جو ہارنے والے کو بچانے کے لیے خطرے میں اضافہ کرتی ہے اکثر اس متعین نقصان کو قبول کرنے سے زیادہ بدتر ہوتی ہے جس کے لیے آپ نے سائن اپ کیا تھا۔</p>\n<p><strong>کب باہر نکلنا ہے۔</strong> تجارت کی وجہ ختم ہونے پر، جب آپ کا نظریہ بدل گیا ہو، یا جب پوزیشن آپ کے پہلے سے طے شدہ نقصان کی سطح پر آجائے تو باہر نکلیں۔ متعین خطرے کے ساتھ آپ کے پاس ہمیشہ یہ اختیار ہوتا ہے کہ آپ کچھ نہ کریں اور بدترین صورت حال کو ختم ہونے دیں، کیونکہ یہ محدود ہے، لیکن سرمائے کو محفوظ رکھنے کے لیے جلد سے جلد باہر نکلنا عام طور پر تجارت کو اس کے مکمل نقصان کو دیکھنے سے زیادہ دانشمندی ہے۔ نقصان اٹھانے سے بچنے کے لیے اپنے خطرے کو کبھی بھی وسیع نہ کریں۔ اس طرح ایک چھوٹا متعین نقصان غیر متعینہ نقصان میں بدل جاتا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>داخل ہونے سے پہلے اپنے باہر نکلنے کا فیصلہ کریں۔ منافع کی سطح لکھیں جہاں آپ بند ہوں گے، نقصان کی سطح جہاں آپ رکیں گے، اور اس تاریخ سے قطع نظر کہ آپ باہر جائیں گے۔ سکون میں بنایا گیا منصوبہ ہر بار گھبراہٹ میں کیے گئے فیصلے کو مات دیتا ہے۔</p>\n</div></div>\n<h2 id=\"your-pre-trade-checklist\">آپ کی پری ٹریڈ چیک لسٹ</h2>\n<p>کوئی بھی حکمت عملی ترتیب دینے سے پہلے اس فہرست کو چلائیں۔ اگر آپ ہر سطر کا جواب نہیں دے سکتے تو تجارت تیار نہیں ہے۔</p>\n<ul>\n<li><strong>دیکھیں۔</strong> کیا میں ایک سادہ جملے میں بتا سکتا ہوں کہ میں کیا کرنے کی توقع رکھتا ہوں اور تقریباً کب تک؟</li>\n<li><strong>شکل</strong> کیا اس ڈھانچے کی ادائیگی حقیقت میں اس منظر کو بدلہ دیتی ہے، اور کیا میں نے اس کے چارٹ کو دیکھا ہے؟</li>\n<li><strong>تین نمبر۔</strong> کیا میں داخل ہونے سے پہلے بریک ایون، زیادہ سے زیادہ منافع، اور زیادہ سے زیادہ نقصان جانتا ہوں؟</li>\n<li><strong>مشکلات</strong> کیا میں نے نفع کے امکان کی جانچ کی ہے، اور کیا انعام اس کا جواز رکھتا ہے؟</li>\n<li><strong>متعین خطرہ۔</strong> کیا میرا بدترین کیس بند اور جانا جاتا ہے؟ اگر نہیں، تو کیا میں واقعی ایک کھلے نقصان اور اس کے بڑے مارجن کو سمجھتا اور قبول کرتا ہوں؟</li>\n<li><strong>سائز</strong> کیا میری لاٹوں کی تعداد میرے نقصان کی حد سے آتی ہے، جو میرے اکاؤنٹ کے ایک چھوٹے سے ٹکڑے کو خطرے میں رکھتے ہوئے؟</li>\n<li><strong>باہر نکلتا ہے۔</strong> کیا میں نے یہ لکھا ہے کہ میں کہاں منافع لیتا ہوں، کہاں میں نقصان کم کرتا ہوں، اور میں باہر جانے کی تاریخ؟</li>\n<li><strong>ریہرسل۔</strong> کیا میں نے اسے حکمت عملی بنانے والے میں بنایا ہے اور، اگر یہ میرے لیے نیا ہے، تو اسے پہلے سینڈ باکس ٹریڈنگ میں چلائیں (Analyzer mode in OpenAlgo)؟</li>\n</ul>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>جو تاجر سب سے زیادہ چالاک حکمت عملیوں کے ساتھ شاذ و نادر ہی ہوتے ہیں۔ یہ وہی ہیں جو ایک سادہ ڈھانچے کو ایک واضح نقطہ نظر سے میل کھاتے ہیں، اپنے خطرے کی وضاحت کرتے ہیں، کھوتے ہوئے سلسلے کو زندہ رہنے کے لیے سائز اتنا چھوٹا رکھتے ہیں، اور اپنے باہر نکلنے کے منصوبے پر عمل کرتے ہیں۔ اس کورس کا ہر ٹول اس ڈسپلن کے اندر کام کرتا ہے اور اس میں سے کوئی بھی اس کے بغیر کام نہیں کرتا۔</p>\n</div></div>\n<p>یہ منی ایچر میں پورا ہنر ہے۔ اب آپ نام شدہ ڈھانچے کو جانتے ہیں، کسی بھی ادائیگی کو اس کی شکل اور اس کے نو نمبروں کے حساب سے کیسے پڑھنا ہے، اور اس کے خطرے کے لیے ایماندارانہ احترام کے ساتھ تجارت کا انتخاب، سائز اور انتظام کیسے کیا جائے۔ متعین خطرے والے ڈھانچے سے شروع کرتے رہیں، اپنے سائز کو چھوٹا رکھیں، اور حقیقی رقم کی لائن پر آنے سے پہلے حکمت عملی بنانے والے میں مشق کرتے رہیں۔ حکمت عملی ہمیشہ موجود رہے گی۔ اپنے سرمائے کی حفاظت کرنا تاکہ آپ اگلے سال بھی تجارت کر رہے ہوں وہ حصہ ہے جو انہیں اہمیت دیتا ہے۔</p>\n","toc":[{"level":2,"text":"اپنے نقطہ نظر سے شروع کریں، پھر شکل منتخب کریں۔","id":"start-with-your-view-then-pick-the-shape"},{"level":2,"text":"پہلے خطرے کی وضاحت، ہمیشہ","id":"defined-risk-first-always"},{"level":2,"text":"زندہ رہنے کے لئے ہر پوزیشن کا سائز بنائیں","id":"size-every-position-to-survive"},{"level":2,"text":"تجارت کا انتظام کریں: منافع، ایڈجسٹ، باہر نکلیں۔","id":"manage-the-trade-profit-adjust-exit"},{"level":2,"text":"آپ کی پری ٹریڈ چیک لسٹ","id":"your-pre-trade-checklist"}],"imgCount":1,"hasContent":true}}
